let QDB = {};
function _hh_initQDB(){
  // 1) تحميل سريع من localStorage (للظهور الفوري)
  QDB = _loadQDB();

  //  ضمان أسئلة الشركاء (أجيال + بيرف آب + طموح): تُحقن دائماً في QDB
  //   مهما كان ترتيب تحميل questions.js أو حالة الكاش · مصدر موثوق مضمّن
  try{
    if(typeof _HH_PARTNER_QUESTIONS === 'object' && _HH_PARTNER_QUESTIONS){
      for(var _pc in _HH_PARTNER_QUESTIONS){
        if(!Array.isArray(QDB[_pc]) || QDB[_pc].length === 0){
          QDB[_pc] = JSON.parse(JSON.stringify(_HH_PARTNER_QUESTIONS[_pc]));
        }
      }
    }
  }catch(_e){ console.warn('partner qs inject:', _e); }
  
  // تحميل المجموعات المخصصة من localStorage أولاً (يجب قبل الفئات)
  try{
    const customGroups = JSON.parse(localStorage.getItem('hh_custom_groups') || '{}');
    Object.keys(customGroups).forEach(groupId => {
      const meta = customGroups[groupId];
      if(typeof CAT_GROUPS !== 'undefined'){
        // التحقق من عدم وجود المجموعة مسبقاً
        if(!CAT_GROUPS.some(g => g.id === groupId)){
          CAT_GROUPS.push({
            id: groupId,
            label: meta.label,
            icon: `<svg viewBox="0 0 100 100" width="36" height="36" xmlns="http://www.w3.org/2000/svg"><rect width="100" height="100" rx="14" fill="${meta.color||'#8A1538'}"/><text x="50" y="62" text-anchor="middle" font-size="40" font-family="Cairo,Arial" fill="#fff" font-weight="900">${meta.label.charAt(0)}</text></svg>`,
            cats: []
          });
        }
        // إضافة للمستوى "العامة"
        if(typeof CAT_LEVELS !== 'undefined'){
          const generalLevel = CAT_LEVELS.find(l => l.id === 'general');
          if(generalLevel && !generalLevel.groupIds.includes(groupId)){
            generalLevel.groupIds.push(groupId);
          }
        }
      }
    });
  }catch(e){ console.warn('تعذر تحميل المجموعات المخصصة:', e); }
  
  // تحميل الفئات المخصصة (التي أنشأها الأدمن) من localStorage
  try{
    const customCats = JSON.parse(localStorage.getItem('hh_custom_cats') || '{}');
    Object.keys(customCats).forEach(catName => {
      const meta = customCats[catName];
      // تسجيل في CAT_INFO إن لم تكن موجودة
      if(typeof CAT_INFO !== 'undefined' && !CAT_INFO[catName]){
        CAT_INFO[catName] = {
          emoji: meta.emoji || '',
          label: catName,
          color: meta.color || '#8A1538',
          bg: meta.bg || '#F7EBEE' };
      }
      // إضافة للمجموعة المختارة
      if(typeof CAT_GROUPS !== 'undefined' && meta.groupId){
        const grp = CAT_GROUPS.find(g => g.id === meta.groupId);
        if(grp && Array.isArray(grp.cats) && !grp.cats.includes(catName)){
          grp.cats.push(catName);
        }
      }
      // إضافة لـ QDB إن لم تكن موجودة
      if(!QDB[catName]) QDB[catName] = [];
    });
  }catch(e){ console.warn('تعذر تحميل الفئات المخصصة:', e); }
  
  // إعادة رسم ذكية متعددة المحاولات لضمان تحميل ملفات JS الخارجية (defer)
  // الـ defer scripts (الخرائط/الأعلام/العواصم/الأساطير) قد تتأخر على الأجهزة البطيئة
  // نتحقق دورياً حتى تكتمل الفئات بدل محاولة واحدة بتوقيت ثابت
  (function _hh_retryBuild(){
    var attempts = 0;
    var maxAttempts = 25; // حتى ~5 ثوانٍ كحد أقصى
    var timer = setInterval(function(){
      attempts++;
      QDB = _loadQDB();
      //  إعادة حقن أسئلة الشركاء بعد كل إعادة بناء (وإلا تُمحى)
      try{
        if(typeof _HH_PARTNER_QUESTIONS === 'object' && _HH_PARTNER_QUESTIONS){
          for(var _pc2 in _HH_PARTNER_QUESTIONS){
            if(!Array.isArray(QDB[_pc2]) || QDB[_pc2].length === 0){
              QDB[_pc2] = JSON.parse(JSON.stringify(_HH_PARTNER_QUESTIONS[_pc2]));
            }
          }
        }
      }catch(_e2){}
      if(typeof buildCatSelect === 'function'){
        try{ buildCatSelect(); }catch(e){}
      }
      // نتوقف عندما تُحمّل فئات الجغرافيا الأساسية (أعلام/عواصم) أو نبلغ الحد
      var geoReady = (typeof QDB_ORIGINAL !== 'undefined') &&
                     QDB_ORIGINAL['أعلام الدول'] && QDB_ORIGINAL['عواصم الدول'];
      if(geoReady || attempts >= maxAttempts){
        clearInterval(timer);
      }
    }, 200);
  })();
  
  // 2) محاولة تحميل من Firestore بعد قليل (لجلب أحدث التعديلات من الإدارة)
  // ننتظر لحظة لتهيأ Firebase
  setTimeout(async ()=>{
    try{
      if(typeof loadQDBFromCloud === 'function' && typeof db !== 'undefined' && db){
        const updated = await loadQDBFromCloud();
        // جلب طبقة تعديلات الفئات الخارجية (الخرائط/الأعلام/...) من السحابة
        if(typeof _hhLoadExtOverridesFromCloud === 'function'){
          try{ await _hhLoadExtOverridesFromCloud(); }catch(e){ console.warn('ext ov init load skipped:', e); }
        }
        if(updated){
          // إعادة تحميل الواجهة إن كنا في شاشة فيها أسئلة
          if(typeof loadAdminCatQuestions === 'function'){
            const catSelect = document.getElementById('aq-cat-select');
            if(catSelect && catSelect.value){
              loadAdminCatQuestions();
            }
          }
          // إعادة رسم قائمة الفئات (لتحديث عدادات الأسئلة)
          // هذا يحل مشكلة ظهور "0 سؤال" قبل اكتمال تحميل البيانات
          if(typeof buildCatSelect === 'function'){
            try{ buildCatSelect(); }catch(e){ console.warn('buildCatSelect refresh skipped:', e); }
          }
        }
        
        //  ربط لحظي: أي تعديل في Firestore يصل لكل المستخدمين فوراً
        try{
          if(window._qdbLiveUnsub) window._qdbLiveUnsub();
          window._qdbLiveUnsub = db.collection('admin_qdb').onSnapshot((snap) => {
            // نتجاهل التحديث الأول (لأنه فقط القراءة الأولية)
            if(!window._qdbLiveInitialized){
              window._qdbLiveInitialized = true;
              return;
            }
            // أي تعديل من Firestore → نعيد التحميل
            console.log('تحديث الأسئلة من السحابة...');
            Promise.resolve(typeof _hhLoadExtOverridesFromCloud==='function' ? _hhLoadExtOverridesFromCloud() : null).then(()=> loadQDBFromCloud().then(updated => {
              if(updated){
                if(typeof buildCatSelect === 'function'){
                  try{ buildCatSelect(); }catch(e){}
                }
                // إن كان المستخدم في شاشة الإدارة، تحديث القائمة
                if(typeof loadAdminCatQuestions === 'function'){
                  const catSelect = document.getElementById('aq-cat-select');
                  if(catSelect && catSelect.value){
                    loadAdminCatQuestions();
                  }
                }
                // إشعار خفيف (للمستخدمين غير الأدمن)
                if(typeof isAdminUser === 'function' && !isAdminUser(currentUser)){
                  if(typeof toast === 'function') toast('تم تحديث الأسئلة', 'info');
                }
              }
            }));
          }, (err) => {
            console.warn('QDB live listener error:', err);
          });
        }catch(e){ console.warn('تعذر تفعيل التحديث اللحظي:', e); }
        
        // استرجاع المجموعات المخصصة من السحابة + ربط لحظي
        try{
          if(window._groupsLiveUnsub) window._groupsLiveUnsub();
          window._groupsLiveUnsub = db.collection('platform_settings').doc('custom_groups').onSnapshot((snap) => {
            if(!snap.exists) return;
            const cloudGroups = snap.data() || {};
            let changed = false;
            Object.keys(cloudGroups).forEach(groupId => {
              const meta = cloudGroups[groupId];
              if(!meta || !meta.label) return;
              // إضافة للـ CAT_GROUPS إن لم تكن موجودة
              if(typeof CAT_GROUPS !== 'undefined' && !CAT_GROUPS.some(g => g.id === groupId)){
                CAT_GROUPS.push({
                  id: groupId,
                  label: meta.label,
                  icon: `<svg viewBox="0 0 100 100" width="36" height="36" xmlns="http://www.w3.org/2000/svg"><rect width="100" height="100" rx="14" fill="${meta.color||'#8A1538'}"/><text x="50" y="62" text-anchor="middle" font-size="40" font-family="Cairo,Arial" fill="#fff" font-weight="900">${meta.label.charAt(0)}</text></svg>`,
                  cats: []
                });
                changed = true;
              }
              // إضافة لمستوى "العامة"
              if(typeof CAT_LEVELS !== 'undefined'){
                const gen = CAT_LEVELS.find(l => l.id === 'general');
                if(gen && !gen.groupIds.includes(groupId)){
                  gen.groupIds.push(groupId);
                  changed = true;
                }
              }
              // حفظ محلي أيضاً
              try{
                const lc = JSON.parse(localStorage.getItem('hh_custom_groups') || '{}');
                lc[groupId] = { label: meta.label, color: meta.color };
                localStorage.setItem('hh_custom_groups', JSON.stringify(lc));
              }catch(e){}
            });
            if(changed && typeof buildCatSelect === 'function'){
              try{ buildCatSelect(); }catch(e){}
            }
          }, (err) => {
            console.warn('Groups live listener error:', err);
          });
        }catch(e){ console.warn('تعذر تفعيل تحديث المجموعات:', e); }
      }
      // تحميل صور الفئات السحابية
      if(typeof loadCatImagesFromCloud === 'function'){
        await loadCatImagesFromCloud();
        // إعادة رسم اللوحة إن كانت مفتوحة بعد تحميل الصور
        if(document.getElementById('screen-board') && document.getElementById('screen-board').classList.contains('active') && typeof G !== 'undefined' && G.selectedCats && G.selectedCats.length){
          if(typeof buildBoard==='function') buildBoard();
          if(typeof updateBoardUI==='function') updateBoardUI();
        }
      }
      // تحميل تخصيصات الأدمن (ألوان/إخفاء/مخصّصة) · تصل لكل المستخدمين
      if(typeof loadCustomizationsFromCloud === 'function'){
        await loadCustomizationsFromCloud();
        if(typeof buildCatSelect === 'function' && document.getElementById('screen-setup') && document.getElementById('screen-setup').classList.contains('active')){
          buildCatSelect();
        }
      }
      // تحميل صور المؤثرين السحابية
      if(typeof loadInfluencerImagesFromCloud === 'function'){
        await loadInfluencerImagesFromCloud();
      }
    }catch(e){ console.warn('cloud load skipped:', e); }
  }, 1500);
}
if(document.readyState === 'loading'){
  document.addEventListener('DOMContentLoaded', _hh_initQDB);
}else{
  _hh_initQDB();
}

