// ═══ إدارة إنجازات الطالب (localStorage) ═══
function _loadAchievements(){
  try{
    return JSON.parse(localStorage.getItem('hh_achievements') || '{}');
  }catch(e){ return {}; }
}

function _saveAchievements(data){
  try{
    localStorage.setItem('hh_achievements', JSON.stringify(data));
  }catch(e){}
}

function getUserStats(){
  const raw = _loadAchievements();
  return {
    earnedBadges: raw.earnedBadges || [],
    earnedSkills: raw.earnedSkills || [],
    totalActivities: raw.totalActivities || 0,
    quizzesTaken: raw.quizzesTaken || 0,
    quizzesAbove90: raw.quizzesAbove90 || 0,
    bestQuizScore: raw.bestQuizScore || 0,
    maxStreak: raw.maxStreak || 0,
    categoryMastery: raw.categoryMastery || {},
    masteriesCount: raw.masteriesCount || 0,
    flashcardsViewed: raw.flashcardsViewed || 0,
    gamesPlayed: raw.gamesPlayed || 0,
    legendPlays: raw.legendPlays || 0,
    servicesUsed: raw.servicesUsed || [],
    badgesEarned: (raw.earnedBadges||[]).length,
    lastEarnedBadge: raw.lastEarnedBadge || null,
    lastUpdatedAt: raw.lastUpdatedAt || null
  };
}

function updateUserStats(updates){
  const current = _loadAchievements();
  const merged = {...current, ...updates, lastUpdatedAt: Date.now()};
  _saveAchievements(merged);
  // فحص الشارات الجديدة
  checkAndAwardBadges();
}

/**
 * فحص كل الشارات ومنح الجديد منها
 */
function checkAndAwardBadges(){
  const stats = getUserStats();
  const earned = new Set(stats.earnedBadges);
  const newlyEarned = [];

  for(const [id, badge] of Object.entries(BADGES)){
    if(earned.has(id)) continue;
    try{
      if(badge.condition(stats)){
        earned.add(id);
        newlyEarned.push({id, ...badge});
      }
    }catch(e){ console.warn('Badge check error:', id, e); }
  }

  if(newlyEarned.length > 0){
    const raw = _loadAchievements();
    raw.earnedBadges = Array.from(earned);
    raw.lastEarnedBadge = newlyEarned[newlyEarned.length-1];
    _saveAchievements(raw);

    // عرض إشعار الشارة الجديدة
    newlyEarned.forEach((badge, i) => {
      setTimeout(() => showBadgeUnlockModal(badge), i * 1500);
    });
  }
}

/**
 * تسجيل نشاط (للتتبع العام)
 */
function trackActivity(type, data = {}){
  const stats = _loadAchievements();
  stats.totalActivities = (stats.totalActivities||0) + 1;

  // تتبع الخدمات المستخدمة
  const services = new Set(stats.servicesUsed || []);
  services.add(type);
  stats.servicesUsed = Array.from(services);

  // تتبعات خاصة حسب النوع
  if(type === 'quiz' && data.score != null){
    stats.quizzesTaken = (stats.quizzesTaken||0) + 1;
    if(data.score >= 90) stats.quizzesAbove90 = (stats.quizzesAbove90||0) + 1;
    if(data.score > (stats.bestQuizScore||0)) stats.bestQuizScore = data.score;
  }
  if(type === 'game'){
    stats.gamesPlayed = (stats.gamesPlayed||0) + 1;
    if(data.isLegend) stats.legendPlays = (stats.legendPlays||0) + 1;
  }
  if(type === 'flashcard_viewed'){
    stats.flashcardsViewed = (stats.flashcardsViewed||0) + 1;
  }
  if(type === 'streak_update' && data.streak != null){
    if(data.streak > (stats.maxStreak||0)) stats.maxStreak = data.streak;
  }

  _saveAchievements(stats);
  checkAndAwardBadges();
}
