// ═══════════════════════════════════════════════════════════════════
// buildCatSelect v2 · تابات أفقية + شبكة بطاقات مسطحة
// محفوظ: نفس .cat-btn، نفس toggleCat، نفس dataset.cat، نفس updateCatHint
// ═══════════════════════════════════════════════════════════════════

// آخر تاب نشط · محفوظ في localStorage
let _msActiveTab = (function(){
  try{
    let v = localStorage.getItem('ms_active_tab') || 'prep';
    // alias للقيم القديمة قبل توحيد المرحلة الإعدادية
    if(v === 'grade7' || v === 'grade8' || v === 'grade9') v = 'prep';
    return v;
  }catch(e){ return 'prep'; }
})();

// التاب الفرعي النشط لكل تاب رئيسي يحتوي subTabs (مثل prep)
// null = لم يُختر بعد، يُعرض رسالة الاختيار
let _msActiveSubTab = (function(){
  try{
    // عند فتح الصفحة، إن كان التاب الحالي يحتوي subTabs، نستعيد آخر اختيار
    const lvl = (typeof CAT_LEVELS !== 'undefined') ? CAT_LEVELS.find(l => l.id === _msActiveTab) : null;
    if(lvl && lvl.subTabs && lvl.subTabs.length){
      const saved = localStorage.getItem('ms_active_subtab_' + _msActiveTab);
      if(saved && lvl.subTabs.find(s => s.id === saved)) return saved;
    }
  }catch(e){}
  return null;
})();

//  دالة موحّدة: تضمن وجود أسئلة الشركاء (أجيال+بيرف آب+طموح) في QDB
//   تُستدعى من كل نقطة تقرأ QDB لئلا تظهر الفئات فارغة أو «يتم التحضير»
function _hhEnsurePartnerQs(){
  try{
    if(typeof _HH_PARTNER_QUESTIONS === 'object' && _HH_PARTNER_QUESTIONS && typeof QDB === 'object'){
      for(var _pcE in _HH_PARTNER_QUESTIONS){
        if(!Array.isArray(QDB[_pcE]) || QDB[_pcE].length === 0){
          QDB[_pcE] = JSON.parse(JSON.stringify(_HH_PARTNER_QUESTIONS[_pcE]));
        }
      }
    }
  }catch(_e){}
}

function buildCatSelect(){
  //  ضمان أسئلة الشركاء قبل بناء التابات (وإلا تظهر «يتم التحضير»)
  if(typeof _hhEnsurePartnerQs === 'function') _hhEnsurePartnerQs();
  // نمسح الفئات المحفوظة لنبدأ نظيف في كل جلسة إعداد
  localStorage.removeItem('hh_saved_cats');

  // إظهار زر تحرير الصور للأدمن فقط
  try{
    const editBtn = document.getElementById('cat-edit-mode-btn');
    if(editBtn){
      editBtn.style.display = isAdminUser(currentUser) ? 'inline-flex' : 'none';
    }
  }catch(e){}

  // تحديث فئة الأسئلة المخصصة في CAT_GROUPS
  const customGroup=CAT_GROUPS.find(g=>g.id==='custom');
  if(customGroup){
    let custom={};
    try{ custom=JSON.parse(localStorage.getItem('hh_custom_q')||'{}'); }catch(e){ custom={}; }
    customGroup.cats=Object.keys(custom);
  }
  const container=document.getElementById('cat-select');
  if(!container)return;
  container.innerHTML='';

  // ─────── 1. التابات الأفقية ───────
  const tabsWrap = document.createElement('div');
  tabsWrap.className = 'ms-tabs-wrap';
  const tabsBar = document.createElement('div');
  tabsBar.className = 'ms-tabs';
  tabsBar.id = 'ms-tabs-bar';

  // تاب "الكل" + تابات لكل مستوى (مع استبعاد الفارغة)
  const tabs = [];

  // عداد إجمالي عبر كل المستويات
  let totalQs = 0;
  CAT_LEVELS.forEach(level => {
    level.groupIds.forEach(gid => {
      const g = CAT_GROUPS.find(x => x.id === gid);
      if(!g) return;
      g.cats.forEach(c => { totalQs += (QDB[c]||[]).length; });
    });
  });
  if(totalQs > 0){
    tabs.push({ id:'all', label:'الكل', count: totalQs, icon:'all', status:'available' });
  }

  CAT_LEVELS.forEach(level => {
    let levelQs = 0, levelCatsCount = 0;
    level.groupIds.forEach(gid => {
      const g = CAT_GROUPS.find(x => x.id === gid);
      if(!g) return;
      levelCatsCount += g.cats.length;
      g.cats.forEach(c => { levelQs += (QDB[c]||[]).length; });
    });
    // نعرض التاب حتى لو فارغ (للحالة 'soon' و 'mine' الفارغة)
    // إيموجي فقط للأساطير حالياً (الباقي SVG inline)
    let tabIcon = level.id;
    tabs.push({
      id: level.id,
      label: level.label,
      count: levelQs,
      icon: tabIcon,
      status: level.status
    });
  });

  // التحقق أن التاب النشط موجود (وإلا ارجع لأول تاب)
  if(!tabs.some(t => t.id === _msActiveTab)){
    _msActiveTab = tabs[0] ? tabs[0].id : 'all';
  }

  // أيقونات SVG أنيقة لكل تاب
  const tabIcons = {
    'all':     '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/></svg>',
    'schools': '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 10v6M2 10l10-5 10 5-10 5z"/><path d="M6 12v5c3 3 9 3 12 0v-5"/></svg>',
    'general': '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="2" y1="12" x2="22" y2="12"/><path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"/></svg>',
    'competitions': '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M6 9H4.5a2.5 2.5 0 0 1 0-5H6"/><path d="M18 9h1.5a2.5 2.5 0 0 0 0-5H18"/><path d="M4 22h16"/><path d="M10 14.66V17c0 .55-.47.98-.97 1.21C7.85 18.75 7 20.24 7 22"/><path d="M14 14.66V17c0 .55.47.98.97 1.21C16.15 18.75 17 20.24 17 22"/><path d="M18 2H6v7a6 6 0 0 0 12 0V2Z"/></svg>',
    'partners': '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M11 17l-1.5 1.5a2.1 2.1 0 0 1-3-3L8 14"/><path d="M14 7l2-2a3 3 0 0 1 4.5 4L17 12.5a2.2 2.2 0 0 1-3.2 0L13 11.7"/><path d="M2.5 9.5L7 5a3 3 0 0 1 4.3.2l3.9 4a2 2 0 0 1-2.9 2.8L10.5 10"/><path d="M13.5 15.5l-2 2a2.1 2.1 0 0 1-3-3"/></svg>',
    'legends': '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M3 18l2-11 5 5 2-8 2 8 5-5 2 11z"/><path d="M4 21h16"/></svg>',
    'islamic': '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M17.5 15a7.5 7.5 0 1 1-5-13 6 6 0 0 0 5 13z"/><path d="M17 3l.9 2.1L20 6l-2.1.9L17 9l-.9-2.1L14 6l2.1-.9z"/></svg>' };

  const tabTheme = {
    all:          ['#8A1538','#5E0E26','#F7ECEF'],
    schools:      ['#1F4E79','#12304d','#E9EEF8'],
    general:      ['#3D6B53','#274a38','#EBF2EE'],
    partners:     ['#b5801f','#8A6D2E','#FDF3DD'],
    competitions: ['#B8924A','#8A6D2E','#FBF3E1'],
    legends:      ['#5E0E26','#3D0918','#F5E9EE'],
    islamic:      ['#2C5340','#1c3a2b','#E9F1EC']
  };

  tabs.forEach(tab => {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'ms-tab' + (tab.id === _msActiveTab ? ' active' : '');
    btn.dataset.tabId = tab.id;
    const th = tabTheme[tab.id] || tabTheme.all;
    btn.style.setProperty('--ta',  th[0]);
    btn.style.setProperty('--tad', th[1]);
    btn.style.setProperty('--tas', th[2]);
    const countHtml = tab.count > 0 ? `<span class="ms-tab-count">${tab.count}</span>` : '';
    const iconSvg = tabIcons[tab.icon] || '';
    const iconHtml = iconSvg ? `<span class="ms-tab-icon">${iconSvg}</span>` : '';
    btn.innerHTML = `${iconHtml}<span class="ms-tab-name">${tab.label}</span>${countHtml}`;
    btn.onclick = () => msSwitchTab(tab.id);
    tabsBar.appendChild(btn);
  });

  container.appendChild(tabsWrap);

  // زر البحث السريع (يفتح حقل بحث يفلتر الفئات)
  const searchWrap = document.createElement('div');
  searchWrap.className = 'ms-search-wrap';
  searchWrap.id = 'ms-search-wrap';
  searchWrap.innerHTML = `
    <button type="button" class="ms-search-btn" id="ms-search-btn" aria-label="بحث في الفئات" title="بحث">
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><circle cx="11" cy="11" r="7"/><path d="M21 21l-4.3-4.3"/></svg>
    </button>
    <input type="search" class="ms-search-input" id="ms-search-input" placeholder="ابحث عن فئة..." autocomplete="off">
    <button type="button" class="ms-search-clear" id="ms-search-clear" aria-label="مسح البحث" title="إغلاق">
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
    </button> `;
  container.appendChild(searchWrap);

  // منطق البحث
  setTimeout(() => {
    const sBtn = document.getElementById('ms-search-btn');
    const sInput = document.getElementById('ms-search-input');
    const sClear = document.getElementById('ms-search-clear');
    if(!sBtn || !sInput || !sClear) return;

    sBtn.onclick = () => {
      searchWrap.classList.add('active');
      sInput.focus();
    };
    sClear.onclick = () => {
      sInput.value = '';
      searchWrap.classList.remove('active');
      applyCatSearch('');
    };
    sInput.oninput = () => applyCatSearch(sInput.value);
    sInput.onkeydown = (e) => {
      if(e.key === 'Escape') sClear.click();
    };
  }, 50);

  // زر السهم اليمين (للسابق - في RTL يكون لليمين)
  const arrowRight = document.createElement('button');
  arrowRight.type = 'button';
  arrowRight.className = 'ms-tabs-arrow right';
  arrowRight.id = 'ms-tabs-arrow-right';
  arrowRight.setAttribute('aria-label','التاب السابق');
  arrowRight.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="9 18 15 12 9 6"/></svg>';
  arrowRight.onclick = () => msPrevTab();
  tabsWrap.appendChild(arrowRight);

  tabsWrap.appendChild(tabsBar);

  // زر السهم اليسار (للتالي - في RTL يكون لليسار)
  const arrowLeft = document.createElement('button');
  arrowLeft.type = 'button';
  arrowLeft.className = 'ms-tabs-arrow left';
  arrowLeft.id = 'ms-tabs-arrow-left';
  arrowLeft.setAttribute('aria-label','التاب التالي');
  arrowLeft.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="15 18 9 12 15 6"/></svg>';
  arrowLeft.onclick = () => msNextTab();
  tabsWrap.appendChild(arrowLeft);

  // ─────── 2. حاوية الشبكة ───────
  const gridWrap = document.createElement('div');
  gridWrap.className = 'ms-cat-grid';
  gridWrap.id = 'ms-cat-grid';
  container.appendChild(gridWrap);

  // ─────── 3. ملء الشبكة بالتاب النشط ───────
  msRenderTabContent(_msActiveTab);

  // تحديث حالة الأسهم بعد البناء الأولي
  setTimeout(() => {
    _msUpdateTabsArrows();
  }, 50);

  updateCatHint();
}

/**
 * تطبيق فلتر البحث على بطاقات الفئات
 */
function applyCatSearch(query){
  const q = (query || '').trim().toLowerCase();
  const grid = document.getElementById('ms-cat-grid');
  if(!grid) return;

  const btns = grid.querySelectorAll('.cat-btn');
  const headers = grid.querySelectorAll('.ms-group-header');

  if(!q){
    // إعادة كل شيء طبيعي
    btns.forEach(b => b.style.display = '');
    headers.forEach(h => h.style.display = '');
    return;
  }

  // فلترة البطاقات حسب الاسم
  btns.forEach(b => {
    const lbl = b.querySelector('.ci-lbl');
    const name = lbl ? lbl.textContent.toLowerCase() : '';
    b.style.display = name.includes(q) ? '' : 'none';
  });

  // إخفاء عناوين المجموعات (لأن البحث يكسر التجميع)
  headers.forEach(h => h.style.display = 'none');
}

/**
 * تبديل التاب النشط
 */
function msSwitchTab(tabId){
  // معالجة "قريباً" · تنبيه فقط
  const level = CAT_LEVELS.find(l => l.id === tabId);
  if(level && level.status === 'soon'){
    if(typeof toast === 'function') toast(' ' + level.label + ' · قريباً بإذن الله', 'info');
    return;
  }

  _msActiveTab = tabId;
  try{ localStorage.setItem('ms_active_tab', tabId); }catch(e){}

  // إعادة ضبط التاب الفرعي عند تغيير التاب الرئيسي
  // (إن كان للتاب الجديد subTabs، نسترجع آخر اختيار من localStorage)
  if(level && level.subTabs && level.subTabs.length){
    try{
      const saved = localStorage.getItem('ms_active_subtab_' + tabId);
      const validSaved = saved && level.subTabs.find(s => s.id === saved);
      _msActiveSubTab = validSaved ? saved : null;
    }catch(e){ _msActiveSubTab = null; }
  } else {
    _msActiveSubTab = null;
  }

  // تحديث مظهر التابات
  let activeBtn = null;
  document.querySelectorAll('.ms-tab').forEach(t => {
    const isActive = t.dataset.tabId === tabId;
    t.classList.toggle('active', isActive);
    if(isActive) activeBtn = t;
  });

  // تمرير سلس ليتوسط التاب النشط في الشاشة
  if(activeBtn && activeBtn.scrollIntoView){
    try{
      activeBtn.scrollIntoView({ behavior:'smooth', block:'nearest', inline:'center' });
    }catch(e){}
  }

  // إعادة تعيين تركيز الفئات + تحديث الأسهم
  _msFocusedCatIdx = -1;
  setTimeout(() => {
    _msUpdateTabsArrows();
  }, 50);

  // إعادة بناء الشبكة
  msRenderTabContent(tabId);
}

// اختيار تاب فرعي (مثل الصف داخل المرحلة الإعدادية)
function msSelectSubTab(parentTabId, subTabId){
  const level = CAT_LEVELS.find(l => l.id === parentTabId);
  if(!level || !level.subTabs) return;
  const sub = level.subTabs.find(s => s.id === subTabId);
  if(!sub) return;

  _msActiveSubTab = subTabId;
  try{ localStorage.setItem('ms_active_subtab_' + parentTabId, subTabId); }catch(e){}

  // تحديث مظهر التابات الفرعية
  document.querySelectorAll('.ms-subtab').forEach(t => {
    t.classList.toggle('active', t.dataset.grade === subTabId);
  });

  // إعادة بناء الشبكة بناءً على الصف المختار
  msRenderTabContent(parentTabId);
}
window.msSelectSubTab = msSelectSubTab;
function _msGetAvailableTabs(){
  const tabs = [];
  // تاب الكل (إن وُجد)
  const allBtn = document.querySelector('.ms-tab[data-tab-id="all"]');
  if(allBtn) tabs.push('all');
  // باقي التابات (نتجاوز "soon")
  CAT_LEVELS.forEach(level => {
    if(level.status === 'soon') return;
    if(document.querySelector('.ms-tab[data-tab-id="'+level.id+'"]')){
      tabs.push(level.id);
    }
  });
  return tabs;
}

/**
 * التاب السابق (في RTL = اليمين بصرياً، لكن الترتيب الذهني يميناً ← يساراً)
 */
function msPrevTab(){
  const tabs = _msGetAvailableTabs();
  const idx = tabs.indexOf(_msActiveTab);
  if(idx > 0) msSwitchTab(tabs[idx - 1]);
}

/**
 * التاب التالي
 */
function msNextTab(){
  const tabs = _msGetAvailableTabs();
  const idx = tabs.indexOf(_msActiveTab);
  if(idx >= 0 && idx < tabs.length - 1) msSwitchTab(tabs[idx + 1]);
}

/**
 * تحديث حالة أسهم التابات (تعطيل عند الأطراف)
 */
function _msUpdateTabsArrows(){
  const tabs = _msGetAvailableTabs();
  const idx = tabs.indexOf(_msActiveTab);
  const arrowR = document.getElementById('ms-tabs-arrow-right');
  const arrowL = document.getElementById('ms-tabs-arrow-left');
  if(arrowR) arrowR.disabled = (idx <= 0);
  if(arrowL) arrowL.disabled = (idx < 0 || idx >= tabs.length - 1);
}

/**
 * التنقل داخل الفئات في التاب الحالي
 */
let _msFocusedCatIdx = -1;
function _msGetVisibleCats(){
  const grid = document.getElementById('ms-cat-grid');
  if(!grid) return [];
  return Array.from(grid.querySelectorAll('.cat-btn:not(.cat-hidden-by-admin)'));
}
function msPrevCat(){
  const cats = _msGetVisibleCats();
  if(!cats.length) return;
  if(_msFocusedCatIdx <= 0) _msFocusedCatIdx = 0;
  else _msFocusedCatIdx--;
  _msHighlightCat(cats);
}
function msNextCat(){
  const cats = _msGetVisibleCats();
  if(!cats.length) return;
  if(_msFocusedCatIdx >= cats.length - 1) _msFocusedCatIdx = cats.length - 1;
  else _msFocusedCatIdx++;
  _msHighlightCat(cats);
}
function _msHighlightCat(cats){
  const target = cats[_msFocusedCatIdx];
  if(!target) return;
  // إزالة التركيز السابق
  document.querySelectorAll('.cat-btn.cat-focused').forEach(c => c.classList.remove('cat-focused'));
  target.classList.add('cat-focused');
  target.scrollIntoView({ behavior:'smooth', block:'center', inline:'center' });
  setTimeout(() => target.classList.remove('cat-focused'), 1200);
  _msUpdateCatsNav();
}
function _msUpdateCatsNav(){
  const cats = _msGetVisibleCats();
  const navInfo = document.getElementById('ms-cats-nav-info');
  const btnPrev = document.getElementById('ms-cats-nav-prev');
  const btnNext = document.getElementById('ms-cats-nav-next');
  if(!navInfo) return;
  if(!cats.length){
    navInfo.innerHTML = '<div>لا توجد فئات</div>';
    if(btnPrev) btnPrev.disabled = true;
    if(btnNext) btnNext.disabled = true;
    return;
  }
  const idx = _msFocusedCatIdx >= 0 && _msFocusedCatIdx < cats.length ? _msFocusedCatIdx : 0;
  const cat = cats[idx];
  const lbl = cat.querySelector('.ci-lbl');
  navInfo.innerHTML = '<div>' + (lbl ? lbl.textContent : 'فئة') + '</div>' +
    '<div class="ms-cats-nav-info-sub">' + (idx+1) + ' من ' + cats.length + '</div>';
  if(btnPrev) btnPrev.disabled = (idx <= 0);
  if(btnNext) btnNext.disabled = (idx >= cats.length - 1);
}

/**
 * ملء الشبكة بفئات التاب المختار
 * "الكل" = كل الفئات من كل المستويات (عدا الفارغة)
 * "tabId" = فئات هذا المستوى فقط
 */
function msRenderTabContent(tabId){
  //  ضمان أسئلة الشركاء قبل بناء محتوى التاب (وإلا تظهر «يتم التحضير»)
  if(typeof _hhEnsurePartnerQs === 'function') _hhEnsurePartnerQs();
  const grid = document.getElementById('ms-cat-grid');
  if(!grid) return;
  grid.innerHTML = '';

  // ─── إن كان التاب يحتوي subTabs، نعرضها قبل الفئات ───
  const currentLevel = CAT_LEVELS.find(l => l.id === tabId);
  let activeSubTab = null;

  // إزالة شريط التابات الفرعية القديم إن وُجد
  const oldSubBar = document.getElementById('ms-subtabs-bar');
  if(oldSubBar) oldSubBar.remove();

  if(currentLevel && currentLevel.subTabs && currentLevel.subTabs.length){
    // بناء شريط التابات الفرعية وحقنه قبل الشبكة
    const subBar = document.createElement('div');
    subBar.id = 'ms-subtabs-bar';
    subBar.className = 'ms-subtabs-wrap';
    subBar.innerHTML = `
      <div class="ms-subtabs-label">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M22 10v6M2 10l10-5 10 5-10 5z"/><path d="M6 12v5c3 3 9 3 12 0v-5"/></svg> الصف:
      </div>
      <div class="ms-subtabs"> ${currentLevel.subTabs.map(st => `
          <button type="button"
            class="ms-subtab${_msActiveSubTab === st.id ? ' active' : ''}${st.status === 'soon' ? ' soon' : ''}"
            data-grade="${st.id}"
            onclick="msSelectSubTab('${tabId}','${st.id}')"
          >${st.label}</button> `).join('')}
      </div> `;
    grid.parentNode.insertBefore(subBar, grid);

    // البحث عن التاب الفرعي المحدد
    activeSubTab = currentLevel.subTabs.find(st => st.id === _msActiveSubTab);

    // إن لم يُحدد صف بعد → أظهر رسالة "اختر صفاً"
    if(!activeSubTab){
      grid.innerHTML = `
        <div class="ms-prep-prompt">
          <div class="ms-prep-prompt-icon">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
              <path d="M14 5l7 7-7 7"/>
              <path d="M3 12h18"/>
            </svg>
          </div>
          <div class="ms-prep-prompt-title">اختر صفاً للبدء</div>
          <div class="ms-prep-prompt-sub">حدد الصف من الأعلى لعرض فئاته (السابع أو الثامن أو التاسع)</div>
        </div> `;
      return;
    }

    // إن كان الصف "قريباً" → أظهر رسالة قريباً
    if(activeSubTab.status === 'soon'){
      grid.innerHTML = `
        <div class="ms-prep-prompt">
          <div class="ms-prep-prompt-icon" style="background:linear-gradient(135deg,#5a3a8e,#3d2557);">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
              <circle cx="12" cy="12" r="10"/>
              <polyline points="12 6 12 12 16 14"/>
            </svg>
          </div>
          <div class="ms-prep-prompt-title">${activeSubTab.label} · قريباً بإذن الله</div>
          <div class="ms-prep-prompt-sub">منهج هذا الصف قيد الإعداد، ترقب التحديثات القادمة</div>
        </div> `;
      return;
    }
  }

  // ─── جمع الفئات مع تذكر مجموعتها (للفصل بعناوين داخل التاب) ───
  // البنية: [{groupId, group, cats:[...]}]
  const groupedSections = [];
  const seenCats = new Set();

  function addCatsFromGroup(g){
    if(!g) return;
    // إخفاء مجموعة «طموح» عن الجمهور العام · تظهر للمدير فقط
    if(g.id === 'tomoh'){
      const _isAdm = (typeof isAdminUser === 'function') && isAdminUser(currentUser);
      if(!_isAdm) return;
    }
    const filteredCats = g.cats.filter(c => !seenCats.has(c));
    // المجموعات "قريباً" تُعرَض حتى لو فارغة (تظهر فقط الترويسة بحالة قريباً)
    if(filteredCats.length === 0 && !g.soonNote) return;
    filteredCats.forEach(c => seenCats.add(c));
    groupedSections.push({
      groupId: g.id,
      group: g,
      cats: filteredCats,
      isSoon: !!g.soonNote
    });
  }

  if(tabId === 'all'){
    CAT_LEVELS.forEach(level => {
      if(level.status === 'soon') return;
      level.groupIds.forEach(gid => {
        const g = CAT_GROUPS.find(x => x.id === gid);
        if(g) addCatsFromGroup(g);
      });
    });
  } else {
    const level = CAT_LEVELS.find(l => l.id === tabId);
    if(!level) return;
    if(level.status === 'soon'){
      grid.innerHTML = '<div class="ms-empty-tab"> ' + level.label + ' · قريباً بإذن الله</div>';
      return;
    }
    // إن كان التاب يحوي subTab نشطاً، نأخذ groupIds منه فقط
    const activeIds = (activeSubTab ? activeSubTab.groupIds : level.groupIds);
    activeIds.forEach(gid => {
      const g = CAT_GROUPS.find(x => x.id === gid);
      if(g) addCatsFromGroup(g);
    });
  }

  // ألوان مميزة لكل مجموعة (لون شريط العنوان + الأيقونة)
  const groupAccents = {
    social6: '#8A1538',
    grade5_soon: '#1E3A5F',
    social7: '#8A1538',
    science7: '#1E3A5F',
    social8: '#A67C4A',
    grade9_soon: '#5a3a8e',
    legends: '#8A6D2E',
    islamic: '#3D6B53',
    lang: '#993556',
    qatar: '#8A1538',
    sport: '#0f6e56',
    geography: '#1E3A5F',
    custom: '#3D4A7A' };

  // تنبيه النخبة (يظهر مرة واحدة فوق الشبكة في تاب الأساطير)
  const totalCatsToShow = groupedSections.reduce((sum, s) => sum + s.cats.length, 0);
  if(tabId === 'elite' && totalCatsToShow > 0){
    const isGuest = !currentUser;
    const loginPrompt = isGuest
      ? '<div class="ln-guest-cta"><svg width="14" height="14" viewBox="0 0 24 24" fill="#D4BC85" style="margin-left:4px;vertical-align:-2px;"><path d="M12 2l3 7h7l-5.5 4.5L18 22l-6-4-6 4 1.5-8.5L2 9h7z"/></svg> <strong>مجاني للجميع!</strong> سجل دخولك لفتح المنطقة الأسطورية</div>' : '';
    const noticeEl = document.createElement('div');
    noticeEl.className = 'legends-notice legends-notice-top';
    noticeEl.style.gridColumn = '1/-1';
    noticeEl.innerHTML = '<div class="ln-title">تنبيه · منطقة النخبة</div><div class="ln-body">الفئات الأسطورية <strong>استثنائية</strong> · أسئلتها متدرجة الصعوبة (<span class="ln-600">600</span> / <span class="ln-800">800</span> / <span class="ln-1000">1000</span>) وصممت لتحدي الخبراء والمتبحرين.</div><div class="ln-warn">لا يخوضها إلا الأقوياء جداً</div>'+loginPrompt;
    grid.appendChild(noticeEl);
  }

  // حالة فارغة
  if(totalCatsToShow === 0){
    if(tabId === 'mine'){
      const empty = document.createElement('div');
      empty.className = 'ms-empty-tab';
      empty.innerHTML = '<div style="margin-bottom:10px;">لم تنشئ أسئلة بعد</div><button onclick="showScreen(\'screen-custom-q\')" style="background:linear-gradient(135deg,#3D4A7A,#2C3358);color:#fff;border:none;padding:8px 16px;border-radius:9px;font-family:Cairo,sans-serif;font-weight:900;font-size:.78rem;cursor:pointer;">أنشئ أسئلتك الآن</button>';
      grid.appendChild(empty);
    } else {
      grid.innerHTML += '<div class="ms-empty-tab">لا توجد فئات في هذا القسم</div>';
    }
    return;
  }

  // مولّد ألوان عشوائي ثابت (نفس البطاقة → نفس اللون دائماً)
  const _hh_paletteFor = (catName) => {
    let hash = 0;
    for(let i = 0; i < catName.length; i++){
      hash = ((hash << 5) - hash) + catName.charCodeAt(i);
      hash |= 0;
    }
    return 'p' + ((Math.abs(hash) % 10) + 1);
  };

  // ─── عرض كل مجموعة بعنوان فاصل + بطاقاتها ───
  // إذا كانت هناك أكثر من مجموعة في هذا التاب، نعرض العناوين الفاصلة
  const showHeaders = groupedSections.length > 1;

  // ─── حالة الطي: نقرأ من localStorage أو نطبق الافتراضي (كل الأقسام مطوية) ───
  // المفتاح خاص بكل تاب
  const collapseKey = 'ms_collapsed_'+tabId;
  let collapsedGroups = new Set();
  try{
    const saved = JSON.parse(localStorage.getItem(collapseKey) || 'null');
    if(Array.isArray(saved)){
      collapsedGroups = new Set(saved);
    } else if(showHeaders){
      // افتراضي: كل الأقسام مطوية · يفتحها المستخدم بضغطة
      groupedSections.forEach(s => collapsedGroups.add(s.groupId));
    }
  }catch(e){}

  groupedSections.forEach((section, sectionIdx) => {
    const isCollapsed = collapsedGroups.has(section.groupId);

    if(showHeaders){
      // عداد فئات + أسئلة لهذه المجموعة
      let groupQs = 0;
      section.cats.forEach(c => { groupQs += (QDB[c]||[]).length; });
      const accent = groupAccents[section.groupId] || '#B8924A';

      const header = document.createElement('div');
      header.className = 'ms-group-header' + (section.isSoon ? ' ms-group-header-soon' : '') + (isCollapsed ? ' collapsed' : '');
      header.dataset.groupId = section.groupId;
      header.style.setProperty('--mgh-accent', accent);
      const subText = section.isSoon
        ? (section.group.soonNote || 'قريباً')
        : (groupQs > 0 
            ? (section.cats.length + ' فئات')
            : 'يتم التحضير…');
      const countBadge = section.isSoon
        ? '<div class="ms-group-header-count" style="background:rgba(90,58,142,.15);color:#5a3a8e;border-color:#5a3a8e;">قريباً</div>' : (groupQs > 0 
            ? '<div class="ms-group-header-count">' + groupQs + '</div>' : '<div class="ms-group-header-count" style="background:rgba(184,146,74,.12);color:#8A6D2E;border-color:#B8924A;font-size:.65rem;">⏳</div>');
      // سهم الطي (لا يظهر على مجموعات soon لأنها فارغة)
      const chevron = section.isSoon ? '' :
        '<div class="ms-group-header-chevron" aria-label="طي/فتح">' +
          '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"/></svg>' +
        '</div>';
      header.innerHTML =
        chevron +
        '<div class="ms-group-header-icon">' + (section.group.icon || '') + '</div>' +
        '<div class="ms-group-header-info">' +
          '<div class="ms-group-header-title">' + section.group.label + '</div>' +
          '<div class="ms-group-header-sub">' + subText + '</div>' +
        '</div>' +
        countBadge;
      // ضغطة الرأس تطوي/تفتح القسم (إن لم تكن soon)
      if(!section.isSoon){
        header.addEventListener('click', () => {
          const gid = section.groupId;
          const isNowCollapsed = header.classList.toggle('collapsed');
          // تحديث localStorage
          let curSet = new Set();
          try{ curSet = new Set(JSON.parse(localStorage.getItem(collapseKey)||'[]')); }catch(e){}
          if(isNowCollapsed){ curSet.add(gid); } else { curSet.delete(gid); }
          try{ localStorage.setItem(collapseKey, JSON.stringify([...curSet])); }catch(e){}
          // إظهار/إخفاء بطاقات المجموعة
          const cards = grid.querySelectorAll('.cat-btn[data-group="'+gid+'"]');
          cards.forEach(c => c.classList.toggle('ms-grouped-hidden', isNowCollapsed));
        });
      }
      grid.appendChild(header);
    }

    section.cats.forEach(cat => {
      const ci = CAT_INFO[cat];
      if(!ci) return;

      // احترام حالة "مخفية"
      const isAdminLocal = (typeof isAdminUser === 'function') && isAdminUser(currentUser);
      const isHiddenByAdmin = _hh_isCatHidden(cat);
      if(isHiddenByAdmin && !isAdminLocal) return;

      const d = document.createElement('div');
      const isExclusive = ci.exclusive === true;
      const isLocked = isExclusive && !window._hasExclusiveAccess;
      // ربط البطاقة بمجموعتها (للطي)
      d.dataset.group = section.groupId;
      // إخفاء البطاقة إن كانت المجموعة مطوية وما يظهر الترويسة
      if(showHeaders && isCollapsed) d.classList.add('ms-grouped-hidden');
      // استرجاع حالة التحديد من الذاكرة (يسمح باختيار من تابات متعددة)
      let _savedActiveCats = [];
      try{ _savedActiveCats = JSON.parse(localStorage.getItem('hh_saved_cats')||'[]'); }catch(e){}
      const isPreSelected = Array.isArray(_savedActiveCats) && _savedActiveCats.indexOf(cat) !== -1;
      d.className = 'cat-btn' + (isLocked ? ' locked' : '') + (isHiddenByAdmin ? ' cat-hidden-by-admin' : '') + (isPreSelected ? ' active' : '');
      d.dataset.cat = cat;
      if(isLocked) d.dataset.locked = '1';

      // تطبيق اللون المخصص للأدمن (إن وجد) كخلفية متدرجة
      const customColor = _hh_getCatCustomColor(cat);
      const _isPartnerCat = (cat.indexOf('بيرف آب')!==-1 || cat.indexOf('طموح')!==-1 || cat.indexOf('قنوان')!==-1);
      if(customColor){
        d.style.background = 'linear-gradient(135deg,'+customColor+' 0%,'+_hh_darken(customColor,.25)+' 100%)';
      } else if(_isPartnerCat && ci.img && ci.color){
        // فئات الشركاء فقط: خلفية بيضاء كاملة للشعار + شريط اسم ملوّن أسفل (الخيار ①)
        d.style.background = '#fff';
        d.dataset.logoColor = ci.color;
        d.classList.add('cat-btn-logo');
      } else {
        // لون عشوائي ثابت من اللوحات الـ 10
        d.dataset.palette = _hh_paletteFor(cat);
      }

      const savedCatImg = localStorage.getItem('cat_img_'+cat);
      var iconHtml;
      if(_isPartnerCat && CAT_SVG[cat]){
        // شعار الشريك كـ SVG نصي (يظهر للجميع دائماً)
        iconHtml = '<div class="ci-svg ci-svg-logo">'+CAT_SVG[cat]+'</div>';
      } else if(savedCatImg){
        iconHtml = '<div class="ci-img"><img src="'+savedCatImg+'" alt="'+ci.label+'" loading="lazy"></div>';
      } else if(typeof CAT_SVG !== 'undefined' && CAT_SVG && CAT_SVG[cat]){
        iconHtml = '<div class="ci-svg">'+CAT_SVG[cat]+'</div>';
      } else if(ci.img){
        iconHtml = '<div class="ci-img"><img src="'+ci.img+'" alt="'+ci.label+'" loading="lazy"></div>';
      } else {
        // Fallback ذكي: استخدام أول كلمتين (إذا أمكن) أو أول حرفين بدلاً من حرف واحد
        const label = (ci.label || cat).trim();
        const words = label.split(/\s+/).filter(w => w.length > 0);
        let displayText = '';
        if(words.length >= 2){
          // كلمتين: نأخذ الحرف الأول من أول كلمة + الحرف الأول من ثاني كلمة
          displayText = words[0].charAt(0) + words[1].charAt(0);
        } else if(label.length >= 2){
          // كلمة واحدة: أول حرفين
          displayText = label.substring(0, 2);
        } else {
          displayText = label;
        }
        const bgColor = customColor || ci.color || '#8A1538';
        const fontSize = displayText.length > 1 ? '1.8rem' : '2.5rem';
        iconHtml = '<div class="ci-svg" style="background:linear-gradient(135deg,'+bgColor+' 0%,#5E0E26 100%);"><div style="font-family:Cairo;font-weight:900;font-size:'+fontSize+';color:#e8c968;margin-bottom:14px;letter-spacing:-2px;">'+displayText+'</div></div>';
      }

      // عداد الأسئلة على البطاقة (الجديد)
      const qCount = (QDB[cat]||[]).length;
      const qCountHtml = qCount > 0 ? '<div class="ms-cat-qcount">'+qCount+'</div>' : '';

      const safeCat = cat.replace(/'/g,"\\'");
      const editBtn = '<button class="cat-edit-btn" onclick="event.stopPropagation();openCatImageEditor(\''+safeCat+'\')" title="تغيير الصورة"><svg viewBox="0 0 24 24"><path d="M3 17.25V21h3.75L17.81 9.94l-3.75-3.75L3 17.25zM20.71 7.04c.39-.39.39-1.02 0-1.41l-2.34-2.34c-.39-.39-1.02-.39-1.41 0l-1.83 1.83 3.75 3.75 1.83-1.83z"/></svg></button>';

      // أزرار الأدمن السريعة (إخفاء/لون/حذف)
      const hideIcon = isHiddenByAdmin
        ? '<svg viewBox="0 0 24 24"><path d="M12 4.5C7 4.5 2.73 7.61 1 12c1.73 4.39 6 7.5 11 7.5s9.27-3.11 11-7.5c-1.73-4.39-6-7.5-11-7.5zM12 17a5 5 0 1 1 0-10 5 5 0 0 1 0 10zm0-8a3 3 0 1 0 0 6 3 3 0 0 0 0-6z"/></svg>' : '<svg viewBox="0 0 24 24"><path d="M12 7c2.76 0 5 2.24 5 5 0 .65-.13 1.26-.36 1.83l2.92 2.92c1.51-1.26 2.7-2.89 3.43-4.75-1.73-4.39-6-7.5-11-7.5-1.4 0-2.74.25-3.98.7l2.16 2.16C10.74 7.13 11.35 7 12 7zM2 4.27l2.28 2.28.46.46C3.08 8.3 1.78 10.02 1 12c1.73 4.39 6 7.5 11 7.5 1.55 0 3.03-.3 4.38-.84l.42.42L19.73 22 21 20.73 3.27 3 2 4.27zM7.53 9.8l1.55 1.55c-.05.21-.08.43-.08.65 0 1.66 1.34 3 3 3 .22 0 .44-.03.65-.08l1.55 1.55c-.67.33-1.41.53-2.2.53-2.76 0-5-2.24-5-5 0-.79.2-1.53.53-2.2zm4.31-.78l3.15 3.15.02-.16c0-1.66-1.34-3-3-3l-.17.01z"/></svg>';
      const hideTitle = isHiddenByAdmin ? 'إظهار الفئة' : 'إخفاء الفئة';
      const adminTools = '<div class="cat-admin-tools" onclick="event.stopPropagation();">' + '<button class="cat-admin-btn cab-hide" onclick="event.stopPropagation();toggleCatHidden(\''+safeCat+'\')" title="'+hideTitle+'">'+hideIcon+'</button>' + '<button class="cat-admin-btn cab-color" onclick="event.stopPropagation();openCatColorModal(\''+safeCat+'\')" title="تغيير اللون"><svg viewBox="0 0 24 24"><path d="M12 3a9 9 0 0 0 0 18c.83 0 1.5-.67 1.5-1.5 0-.39-.15-.74-.39-1.01-.23-.26-.38-.61-.38-.99 0-.83.67-1.5 1.5-1.5H16c2.76 0 5-2.24 5-5 0-4.42-4.03-8-9-8zm-5.5 9c-.83 0-1.5-.67-1.5-1.5S5.67 9 6.5 9 8 9.67 8 10.5 7.33 12 6.5 12zm3-4C8.67 8 8 7.33 8 6.5S8.67 5 9.5 5s1.5.67 1.5 1.5S10.33 8 9.5 8zm5 0c-.83 0-1.5-.67-1.5-1.5S13.67 5 14.5 5s1.5.67 1.5 1.5S15.33 8 14.5 8zm3 4c-.83 0-1.5-.67-1.5-1.5S16.67 9 17.5 9s1.5.67 1.5 1.5-.67 1.5-1.5 1.5z"/></svg></button>' + '<button class="cat-admin-btn cab-delete" onclick="event.stopPropagation();deleteCatPermanent(\''+safeCat+'\')" title="حذف الفئة"><svg viewBox="0 0 24 24"><path d="M6 19c0 1.1.9 2 2 2h8c1.1 0 2-.9 2-2V7H6v12zM19 4h-3.5l-1-1h-5l-1 1H5v2h14V4z"/></svg></button>' + '</div>';

      const _lblStyle = (ci.img && ci.color)
        ? ' style="background:linear-gradient(135deg,'+ci.color+' 0%,'+_hh_darken(ci.color,.3)+' 100%);color:#fff;"' : '';
      d.innerHTML = qCountHtml + iconHtml + editBtn + adminTools + '<div class="ci-lbl"'+_lblStyle+'>'+ci.label+'</div>';
      d.onclick = () => toggleCat(d);
      grid.appendChild(d);
    });
  });
}

window.msSwitchTab = msSwitchTab;
window.msRenderTabContent = msRenderTabContent;
window.msPrevTab = msPrevTab;
window.msNextTab = msNextTab;
window.msPrevCat = msPrevCat;
window.msNextCat = msNextCat;


/** طي/فتح مستوى */
function hh_toggleLevel(lid){
  const level = CAT_LEVELS.find(l => l.id === lid);
  if(!level) return;
  // أغلق غيره وافتح هذا
  CAT_LEVELS.forEach(l => {
    const wrap = document.querySelector('.hh-level[data-lid="'+l.id+'"]');
    if(!wrap) return;
    if(l.id === lid){
      wrap.classList.toggle('hh-open');
    } else {
      wrap.classList.remove('hh-open');
      // أغلق المجموعات داخله
      l.groupIds.forEach(gid => {
        const sub = document.getElementById('sub-'+gid);
        const btn = document.querySelector('[data-gid="'+gid+'"]');
        if(sub) sub.classList.remove('open');
        if(btn) btn.classList.remove('active');
      });
    }
  });
}

/** بحث ذكي في الشجرة كلها */
function hh_searchCatsTree(query){
  const q = (query||'').trim().toLowerCase();
  // عند مسح البحث · أعد كل شيء كما كان
  if(!q){
    document.querySelectorAll('.hh-level').forEach(el => el.style.display = '');
    document.querySelectorAll('.cat-group-btn').forEach(el => el.style.display = '');
    document.querySelectorAll('.cat-btn').forEach(el => el.style.display = '');
    return;
  }
  // مر على كل الفئات وحدد ما يطابق
  CAT_LEVELS.forEach(level => {
    const levelEl = document.querySelector('.hh-level[data-lid="'+level.id+'"]');
    if(!levelEl) return;
    let levelHasMatch = false;
    const levelMatchesByText = level.label.toLowerCase().includes(q) || level.desc.toLowerCase().includes(q);
    level.groupIds.forEach(gid => {
      const group = CAT_GROUPS.find(g => g.id === gid);
      if(!group) return;
      const groupBtn = document.querySelector('[data-gid="'+gid+'"]');
      const sub = document.getElementById('sub-'+gid);
      const groupMatchesByText = group.label.toLowerCase().includes(q);
      let groupHasMatch = groupMatchesByText;
      // فحص الفئات داخل المجموعة
      if(sub){
        sub.querySelectorAll('.cat-btn').forEach(catEl => {
          const catName = catEl.dataset.cat || '';
          const ci = CAT_INFO[catName] || {};
          const matches = catName.toLowerCase().includes(q) || (ci.label||'').toLowerCase().includes(q);
          catEl.style.display = (matches || groupMatchesByText || levelMatchesByText) ? '' : 'none';
          if(matches) groupHasMatch = true;
        });
        // افتح المجموعة إن طابقت
        if(groupHasMatch || levelMatchesByText){
          sub.classList.add('open');
          if(groupBtn) groupBtn.classList.add('active');
        }
      }
      // إخفاء/إظهار زر المجموعة
      if(groupBtn) groupBtn.style.display = (groupHasMatch || levelMatchesByText) ? '' : 'none';
      if(groupHasMatch) levelHasMatch = true;
    });
    // إخفاء/إظهار المستوى
    levelEl.style.display = (levelHasMatch || levelMatchesByText) ? '' : 'none';
    // افتح المستوى إن طابق
    if(levelHasMatch || levelMatchesByText) levelEl.classList.add('hh-open');
  });
}
window.hh_toggleLevel = hh_toggleLevel;
window.hh_searchCatsTree = hh_searchCatsTree;

function toggleGroup(gid){
  // إغلاق الباقين وفتح المختار
  CAT_GROUPS.forEach(g=>{
    const btn=document.querySelector('[data-gid="'+g.id+'"]');
    const sub=document.getElementById('sub-'+g.id);
    if(g.id===gid){
      const isOpen=sub.classList.contains('open');
      sub.classList.toggle('open',!isOpen);
      btn.classList.toggle('active',!isOpen);
    }else{
      sub.classList.remove('open');
      if(btn)btn.classList.remove('active');
    }
  });
}

function updateCatHint(){
  // مصدر الحقيقة: localStorage (يشمل فئات من تابات غير ظاهرة)
  let savedCats = [];
  try{ savedCats = JSON.parse(localStorage.getItem('hh_saved_cats')||'[]'); }catch(e){ savedCats = []; }
  if(!Array.isArray(savedCats)) savedCats = [];
  const n = savedCats.length;

  // ─── العداد الجديد (ms-cats-counter في عنوان قسم الفئات) ───
  const counter=document.getElementById('selected-counter');
  if(counter){
    if(n === 0){
      counter.classList.remove('visible');
      counter.textContent = '0';
    } else {
      counter.classList.add('visible');
      counter.classList.remove('warn');
      counter.textContent = n + ' مختارة';
      // نفس قواعد القديم: 2-6 = جاهز، >6 = تحذير
      if(n > 6){
        counter.classList.add('warn');
      }
    }
  }

  // ─── الشريط القديم selected-tags (مخفي بصرياً، محفوظ للتوافق) ───
  const tagsEl=document.getElementById('selected-tags');
  if(tagsEl){
    if(n===0){
      tagsEl.innerHTML='<span class="empty-hint">اختر من 2 إلى 6 فئات</span>';
    }else{
      tagsEl.innerHTML=savedCats.map(cat=>{
        const ci=CAT_INFO[cat]||{};
        return `<div class="selected-tag">
          <span>${ci.emoji||''}</span>
          <span>${ci.label||cat}</span>
          <span class="remove-tag" onclick="removeCat('${cat}')">✕</span>
        </div>`;
      }).join('');
    }
  }
}

function removeCat(cat){
  // احذف من localStorage (يعمل حتى لو الفئة في تاب آخر غير ظاهر)
  let savedCats = [];
  try{ savedCats = JSON.parse(localStorage.getItem('hh_saved_cats')||'[]'); }catch(e){ savedCats = []; }
  if(!Array.isArray(savedCats)) savedCats = [];
  const idx = savedCats.indexOf(cat);
  if(idx !== -1){
    savedCats.splice(idx, 1);
    localStorage.setItem('hh_saved_cats', JSON.stringify(savedCats));
  }
  // أزل التحديد البصري إن كانت البطاقة ظاهرة في التاب الحالي
  const btn = document.querySelector('.cat-btn[data-cat="'+cat+'"]');
  if(btn) btn.classList.remove('active');
  updateCatHint();
  if(typeof setupActionUpdate === 'function') setupActionUpdate();
}

