/** قراءة قائمة الفئات المخفية */
function _hh_getHiddenCats(){
  try{ return JSON.parse(localStorage.getItem('hh_hidden_cats')||'[]'); }
  catch(e){ return []; }
}
/** هل الفئة مخفية؟ */
function _hh_isCatHidden(cat){
  return _hh_getHiddenCats().indexOf(cat) !== -1;
}
/** قراءة لون الفئة المخصص */
function _hh_getCatCustomColor(cat){
  try{
    const map = JSON.parse(localStorage.getItem('hh_cat_colors')||'{}');
    return map[cat] || null;
  }catch(e){ return null; }
}
/** تغميق لون hex بنسبة معينة (0-1) */
function _hh_darken(hex,amt){
  try{
    const h = hex.replace('#','');
    const r = parseInt(h.substr(0,2),16);
    const g = parseInt(h.substr(2,2),16);
    const b = parseInt(h.substr(4,2),16);
    const f = 1 - amt;
    const dr = Math.max(0,Math.round(r*f));
    const dg = Math.max(0,Math.round(g*f));
    const db = Math.max(0,Math.round(b*f));
    return '#'+[dr,dg,db].map(x=>x.toString(16).padStart(2,'0')).join('');
  }catch(e){ return hex; }
}

/** إخفاء/إظهار فئة (الأدمن فقط) */
function toggleCatHidden(cat){
  if(!isAdminUser(currentUser)){
    toast('فقط المدير','error'); return;
  }
  const list = _hh_getHiddenCats();
  const idx = list.indexOf(cat);
  if(idx === -1){
    list.push(cat);
    toast('تم إخفاء الفئة عن الزوار','info');
  } else {
    list.splice(idx,1);
    toast('تم إظهار الفئة','success');
  }
  localStorage.setItem('hh_hidden_cats', JSON.stringify(list));
  // مزامنة سحابية فورية · تصل لكل المستخدمين
  if(typeof _hh_saveCustomizationsToCloud === 'function') _hh_saveCustomizationsToCloud();
  // إعادة بناء قائمة الفئات لتعكس التغيير
  if(typeof buildCatSelect === 'function') buildCatSelect();
}

/** تغيير لون الفئة (الأدمن فقط) */
function changeCatColor(cat, color){
  if(!isAdminUser(currentUser)){
    toast('فقط المدير','error'); return;
  }
  if(!color || !/^#[0-9a-f]{6}$/i.test(color)){
    toast('لون غير صالح','error'); return;
  }
  let map = {};
  try{ map = JSON.parse(localStorage.getItem('hh_cat_colors')||'{}'); }catch(e){ map = {}; }
  map[cat] = color;
  localStorage.setItem('hh_cat_colors', JSON.stringify(map));
  if(typeof _hh_saveCustomizationsToCloud === 'function') _hh_saveCustomizationsToCloud();
  toast('تم تغيير لون الفئة','success');
  if(typeof buildCatSelect === 'function') buildCatSelect();
}

/** إعادة تعيين لون الفئة للون الافتراضي */
function resetCatColor(cat){
  if(!isAdminUser(currentUser)){ toast('فقط المدير','error'); return; }
  let map = {};
  try{ map = JSON.parse(localStorage.getItem('hh_cat_colors')||'{}'); }catch(e){ map = {}; }
  if(map[cat]){
    delete map[cat];
    localStorage.setItem('hh_cat_colors', JSON.stringify(map));
    if(typeof _hh_saveCustomizationsToCloud === 'function') _hh_saveCustomizationsToCloud();
    toast('تم استعادة اللون الافتراضي','info');
    if(typeof buildCatSelect === 'function') buildCatSelect();
  }
}

/**
 * حذف فئة نهائيا (الأدمن فقط) · مع تأكيد قوي.
 * • للفئات المخصصة (custom): يحذف نهائيا من localStorage و QDB.
 * • للفئات الأساسية: يحول الحذف إلى "إخفاء" (لأن الحذف الكامل قد يكسر بنية اللعبة).
 */
function deleteCatPermanent(cat){
  if(!isAdminUser(currentUser)){
    toast('فقط المدير','error'); return;
  }
  const ci = CAT_INFO[cat];
  if(!ci){ toast('الفئة غير موجودة','error'); return; }

  // هل هي فئة مخصصة؟
  let isCustom = false;
  try{
    const custom = JSON.parse(localStorage.getItem('hh_custom_q')||'{}');
    isCustom = !!custom[cat];
  }catch(e){}

  if(isCustom){
    if(!confirm('حذف فئة "'+ci.label+'" نهائيا مع كل أسئلتها؟ لا يمكن التراجع.')) return;
    if(typeof deleteCQCat === 'function'){
      deleteCQCat(cat);
    } else {
      // fallback
      const custom = JSON.parse(localStorage.getItem('hh_custom_q')||'{}');
      delete custom[cat];
      localStorage.setItem('hh_custom_q', JSON.stringify(custom));
      delete QDB[cat]; delete CAT_INFO[cat];
    }
    if(typeof buildCatSelect === 'function') buildCatSelect();
    return;
  }

  // فئة أساسية → نحول إلى إخفاء (مع شرح واضح)
  const list = _hh_getHiddenCats();
  if(list.indexOf(cat) !== -1){
    if(!confirm('فئة "'+ci.label+'" مخفية بالفعل. هل تريد إعادة إظهارها؟')) return;
    toggleCatHidden(cat);
    return;
  }
  if(!confirm('فئة "'+ci.label+'" أساسية ولا يمكن حذفها نهائيا (تحوي أسئلة المنهج). سنخفيها من جميع الزوار. متابعة؟')) return;
  toggleCatHidden(cat);
}
// ═══════════════════════════════════════════════════════════════════

function toggleCat(el){
  // منع النقر على الفئات المقفلة (للزوار غير المسجلين)
  if(el.dataset.locked === '1' || el.classList.contains('locked')){
    const catName = el.dataset.cat || 'هذه الفئة';
    if(!currentUser){
      toast('سجل دخولك لفتح فئة ' + catName + ' · مجاني للجميع!', 'warn');
    } else {
      toast('فئة ' + catName + ' تحتاج تصريح خاص من الإدارة', 'warn');
    }
    return;
  }

  // نقرأ القائمة الكاملة من الذاكرة (تشمل فئات من تابات أخرى غير ظاهرة)
  let savedCats = [];
  try{ savedCats = JSON.parse(localStorage.getItem('hh_saved_cats')||'[]'); }catch(e){ savedCats = []; }
  if(!Array.isArray(savedCats)) savedCats = [];

  const cat = el.dataset.cat;
  const idx = savedCats.indexOf(cat);
  const isCurrentlyActive = idx !== -1;

  //  فئات المسابقات الخاصة: تُلعب منفردة (لوحة 4 مستويات)
  const _isCompCat = (typeof _HH_COMP_CATS !== 'undefined') && _HH_COMP_CATS.has(cat);
  const _hasCompSelected = (typeof _HH_COMP_CATS !== 'undefined') && savedCats.some(c => _HH_COMP_CATS.has(c));

  if(isCurrentlyActive){
    // إلغاء التحديد
    if(savedCats.length <= 1){toast('يجب اختيار فئة واحدة على الأقل','error');return;}
    savedCats.splice(idx, 1);
    el.classList.remove('active');
  }else if(_isCompCat){
    // اختيار مسابقة: تُلغى بقية الفئات وتُختار المسابقة وحدها
    savedCats = [cat];
    document.querySelectorAll('.cat-btn.active').forEach(b => { if(b !== el) b.classList.remove('active'); });
    el.classList.add('active');
    toast('مسابقة خاصة · تُلعب منفردة بلوحة مخصصة','info');
  }else{
    // إضافة فئة عادية: إن كانت مسابقة مختارة سابقاً نزيلها أولاً
    if(_hasCompSelected){
      savedCats = savedCats.filter(c => !_HH_COMP_CATS.has(c));
      document.querySelectorAll('.cat-btn.active').forEach(b => {
        if(_HH_COMP_CATS.has(b.dataset.cat)) b.classList.remove('active');
      });
    }
    if(savedCats.length >= 6){toast('الحد الأقصى 6 فئات','error');return;}
    savedCats.push(cat);
    el.classList.add('active');
  }
  localStorage.setItem('hh_saved_cats', JSON.stringify(savedCats));
  updateCatHint();
  // تحديث شريط "ابدأ اللعبة" فوراً بعد كل اختيار
  if(typeof setupActionUpdate === 'function') setupActionUpdate();
}

let G={teams:[],scores:[],turn:0,answered:false,timer:null,timerSec:0,timerTotal:0,curQ:null,curKey:'',boardData:{},selectedCats:[]};
let teamCount=2;
let timerMult=1; // معامل ضرب وقت المؤقت

function setTimerMult(m){
  timerMult=m;
  ['half','normal','double'].forEach(k=>{
    const b=document.getElementById('topt-'+k);
    if(b)b.classList.remove('active');
  });
  const map={0.5:'half',1:'normal',2:'double'};
  const b=document.getElementById('topt-'+map[m]);
  if(b)b.classList.add('active');
}

function setTeamCount(n){
  teamCount=n;
  // تحديث أزرار التبويب
  [2,3,4,5,6,7,8].forEach(i=>{
    const btn=document.getElementById('nt-'+i);
    if(btn)btn.classList.toggle('active',i===n);
  });
  buildTeamsUI();
}

// ────────────────────────────────────────────────
// توليد اسم لعبة تلقائي ذكي
// ────────────────────────────────────────────────
function autoGameName(){
  const input=document.getElementById('game-name');
  if(!input)return;
  // بيانات ذكية للاسم
  const today=new Date();
  const weekdays=['الأحد','الإثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت'];
  const dayName=weekdays[today.getDay()];
  const dayNum=today.getDate();

  // اسم المعلم من الحساب
  let teacherName='';
  try{
    const displayName = currentUser?.displayName || '';
    if(displayName){
      // أخذ أول كلمتين (عادة الاسم الأول + الأب)
      const parts = displayName.trim().split(/\s+/);
      teacherName = parts.slice(0,2).join(' ');
    }
  }catch(e){}

  // اسم الفصل من الفصل المنشأ للمعلم (إن وجد)
  let className='';
  try{
    // نحاول أولا من localStorage (آخر فصل استخدمه)
    className = localStorage.getItem('hh_last_class_name') || '';
  }catch(e){}

  // الفئات المختارة حاليا (إن وجدت)
  const activeCats=[...document.querySelectorAll('.cat-btn.active')].map(b=>{
    const k=b.dataset.cat;
    return CAT_INFO[k]?.label||k;
  });

  // بناء الاقتراح الذكي حسب الأولوية
  let suggestion='';
  if(className && teacherName){
    // أفضل صيغة: "فصل السابع-أ · الأحد 23"
    suggestion = 'فصل '+className+' · '+dayName+' '+dayNum;
  } else if(teacherName){
    suggestion = 'حصة '+teacherName+' · '+dayName+' '+dayNum;
  } else if(activeCats.length>0){
    suggestion = activeCats[0]+' · '+dayName+' '+dayNum;
  } else {
    suggestion = 'حصة '+dayName+' '+dayNum;
  }
  input.value=suggestion;
}

// ────────────────────────────────────────────────
// اقتراح تلقائي لأسماء الفرق (ذكي)
// ────────────────────────────────────────────────
function autoSuggestTeamNames(){
  // يعمل فقط إذا الحقول فارغة (ما نكتب فوق شي كتبه المستخدم)
  for(let i=0;i<teamCount;i++){
    const el=document.getElementById('tm-'+i);
    if(el && !el.value.trim()){
      const defaults=['الفريق 1','الفريق 2','الفريق 3','الفريق 4','الفريق 5','الفريق 6'];
      el.value=defaults[i]||('الفريق '+(i+1));
    }
  }
}

// ────────────────────────────────────────────────
// تعبئة أسماء الفرق الافتراضية (الألوان) · زر يدوي
// ────────────────────────────────────────────────
function autoTeamNames(){
  const defaults=['الفريق 1','الفريق 2','الفريق 3','الفريق 4','الفريق 5','الفريق 6'];
  for(let i=0;i<teamCount;i++){
    const el=document.getElementById('tm-'+i);
    if(el)el.value=defaults[i]||('الفريق '+(i+1));
  }
  saveTeamNames();
  toast('تم استعادة الأسماء الافتراضية','success');
}

function buildTeamsUI(){
  const names=['الفريق 1','الفريق 2','الفريق 3','الفريق 4','الفريق 5','الفريق 6'];
  let saved=[];
  try{ saved=JSON.parse(localStorage.getItem('hh_team_names')||'[]'); }catch(e){ saved=[]; }
  const c=document.getElementById('teams-container');
  if(!c)return;
  c.innerHTML='';
  // صنف ديناميكي حسب عدد الفرق للتحكم بالتوزيع
  c.classList.remove('teams-count-2','teams-count-3','teams-count-4','teams-count-5','teams-count-6');
  c.classList.add('teams-count-'+teamCount);
  for(let i=0;i<teamCount;i++){
    const val=saved[i]||names[i]||('الفريق '+(i+1));
    const div=document.createElement('div');
    div.className='team-entry';
    // بناء آمن بدون innerHTML - يمنع XSS
    const lbl=document.createElement('label');
    lbl.textContent='الفريق '+(i+1);
    const inp=document.createElement('input');
    inp.type='text';
    inp.id='tm-'+i;
    inp.value=val; // آمن: value يعامل كـ string
    inp.maxLength=8;
    inp.addEventListener('input',saveTeamNames);
    div.appendChild(lbl);
    div.appendChild(inp);
    c.appendChild(div);
  }
}

function saveTeamNames(){
  const names=[];
  for(let i=0;i<teamCount;i++){
    const el=document.getElementById('tm-'+i);
    if(el)names.push((el.value||'').trim().slice(0,8)||'الفريق '+(i+1));
  }
  try{ localStorage.setItem('hh_team_names',JSON.stringify(names)); }catch(e){}
}
let PU={teams:[],armed:null};
function resetPU(){
  PU={teams:G.teams.map(()=>({hafra:1,dagf:1,eskot:1,twoans:1,fakh:1})),armed:null};
  G.trapTarget=null;G.trapBy=null;
}

function startGame(overrideTeams, overrideCats, overrideName){
  // حراسة: التأكد من اختيار الدور قبل أي لعبة جديدة
  if(!overrideTeams && !_currentUserRole){
    // محاولة استرجاع الدور من localStorage أولا (تجنب false positive)
    try{
      const saved = localStorage.getItem('hh_user_role');
      if(saved && ['teacher','student','other','guest'].includes(saved)){
        _currentUserRole = saved;
      }
    }catch(e){}
  }
  //  الزائر (غير المسجل) يلعب مباشرة كـ "زائر" بدون أي مودال
  if(!overrideTeams && !_currentUserRole && !currentUser){
    _currentUserRole = 'guest';
    try{ localStorage.setItem('hh_user_role','guest'); }catch(e){}
  }
  // المستخدم المسجل: نطلب التصنيف لمرة واحدة فقط
  if(!overrideTeams && !_currentUserRole){
    window._hhResumeStartAfterRole = true;
    showRoleModal({force:true});
    return;
  }
  let cats, teams, gameName;
  // إذا جاءت معاملات (إعادة اللعب من السجل) نستخدمها مباشرة
  if(overrideTeams && overrideCats){
    cats = overrideCats;
    teams = overrideTeams;
    gameName = overrideName || 'إعادة لعبة';
  } else {
    // نقرأ من localStorage (يشمل فئات من تابات متعددة)
    try{ cats = JSON.parse(localStorage.getItem('hh_saved_cats')||'[]'); }catch(e){ cats = []; }
    if(!Array.isArray(cats)) cats = [];
    const err=document.getElementById('setup-err');
    //  فئة مسابقة منفردة: يُسمح ببدئها وحدها
    const _compSoloStart = (cats.length === 1) && (typeof _HH_COMP_CATS !== 'undefined') && _HH_COMP_CATS.has(cats[0]);
    if(cats.length<2 && !_compSoloStart){
      if(err){
        err.innerHTML='<span style="color:#c0392b;font-weight:900;">يجب اختيار فئتين على الأقل</span>';
        err.scrollIntoView({behavior:'smooth',block:'center'});
      }
      if(typeof toast==='function') toast('اختر فئتين على الأقل لبدء اللعبة', 'warn');
      return;
    }
    if(cats.length>6){
      if(err){
        err.innerHTML='<span style="color:#c0392b;font-weight:900;">الحد الأقصى 6 فئات</span>';
      }
      if(typeof toast==='function') toast('الحد الأقصى 6 فئات في اللعبة الواحدة', 'warn');
      return;
    }
    
    // فحص: نتأكد أن كل فئة فيها أسئلة كافية (سؤالان من كل مستوى)
    const emptyCats = [];
    cats.forEach(cat => {
      const all = QDB[cat] || [];
      if(all.length < 6){
        emptyCats.push({ name: cat, count: all.length });
      }
    });
    
    if(emptyCats.length > 0){
      const names = emptyCats.map(c => `"${c.name}" (${c.count} سؤال)`).join('، ');
      const msg = `الفئات التالية لا تحتوي على أسئلة كافية:\n${names}\n\nكل فئة تحتاج 6 أسئلة على الأقل (2 سهل + 2 متوسط + 2 صعب).\n\nهل تريد البدء بهذه الفئات على أي حال؟ (ستظهر فارغة)`;
      
      if(!confirm(msg)){
        if(err) err.innerHTML='<span style="color:#c0392b;font-weight:900;">أضف أسئلة للفئات الفارغة أو احذفها من الاختيار</span>';
        if(typeof toast==='function') toast('بعض الفئات فارغة', 'warn');
        return;
      }
    }
    
    err.textContent='';
    const gameNameEl=document.getElementById('game-name');
    gameName=gameNameEl?gameNameEl.value.trim():'';
    // لو اسم اللعبة فارغ، ولد واحد تلقائيا بدل الرفض
    if(!gameName){
      const today=new Date();
      const weekdays=['الأحد','الإثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت'];
      const months=['يناير','فبراير','مارس','أبريل','مايو','يونيو','يوليو','أغسطس','سبتمبر','أكتوبر','نوفمبر','ديسمبر'];
      const firstCat=cats[0]?(CAT_INFO[cats[0]]?.label||cats[0]):'حصة';
      gameName=firstCat+' · '+weekdays[today.getDay()]+' '+today.getDate()+' '+months[today.getMonth()];
      if(gameNameEl)gameNameEl.value=gameName;
    }
    teams=[];
    for(let i=0;i<teamCount;i++){
      const el=document.getElementById('tm-'+i);
      teams.push(el?el.value.trim()||('الفريق '+(i+1)):('الفريق '+(i+1)));
    }
  }
  try{ if(typeof hhLogActivity==='function') hhLogActivity('game_start', (cats||[]).join('+').slice(0,60)); }catch(_lg){}
  G={teams,scores:teams.map(()=>0),turn:0,answered:false,timer:null,timerSec:0,timerTotal:0,curQ:null,curKey:'',boardData:{},selectedCats:cats,gameName,startTime:Date.now(),sessionLog:[]};
  // ═══ حفظ اللعبة فور البدء (تبقى في السجل حتى لو انسحب اللاعب) ═══
  try{ G.gameLocalId = 'g'+Date.now()+'_'+Math.random().toString(36).slice(2,7); hhSaveGameStart(); }catch(_gs){}
  // عداد وقت اللعبة
  clearInterval(window._gameElapsedTimer);
  window._gameElapsedTimer=setInterval(()=>{
    const el=document.getElementById('game-elapsed');
    if(!el)return;
    const s=Math.floor((Date.now()-G.startTime)/1000);
    el.textContent='⏱ '+Math.floor(s/60)+':'+(s%60<10?'0':'')+s%60;
  },1000);
  resetPU();
  //  وضع المسابقة الخاصة: فئة واحدة بلوحة 4 مستويات × 8 أسئلة
  G.isComp = (cats.length === 1) && (typeof _HH_COMP_CATS !== 'undefined') && _HH_COMP_CATS.has(cats[0]);
  G.compKind = G.isComp ? (((typeof _HH_WAFA_CAT !== 'undefined' && cats[0] === _HH_WAFA_CAT) || (typeof _HH_CHAR_COMPS !== 'undefined' && _HH_CHAR_COMPS[cats[0]])) ? 'wafa' : 'quran') : '';
  // قائمة الفئات الأسطورية · تستخدم المجموعة العالمية المعرفة قرب CAT_PALETTES
  cats.forEach(cat=>{
    G.boardData[cat]={};
    if(G.isComp){
      if(G.compKind==='wafa'){
        // لوحات الشخصية: ترتيب مجمّع بالفئات الفرعية
        // الوضع الموسع الذكي: إن اتسع البنك لثلاثة أسئلة لكل مستوى في كل فئة فرعية (بنوك 48+)
        // تُعرض اللوحة 3×3 = 36 خلية تلقائياً؛ وإلا سؤالان لكل مستوى = 24 كالمعتاد
        const _allQ=(QDB[cat]||[]);
        const _tiers=(typeof _HH_CHAR_COMPS!=='undefined' && _HH_CHAR_COMPS[cat] && Array.isArray(_HH_CHAR_COMPS[cat].tiers)) ? _HH_CHAR_COMPS[cat].tiers : ['easy','med','hard'];
        G.wafaTiers=_tiers;
        const _subKeys=[...new Set(_allQ.map(q=>(q.sub!==undefined)?q.sub:0))].sort((a,b)=>a-b);
        const _rich=_subKeys.length>0 && _tiers.every(d=> _subKeys.every(k=> _allQ.filter(q=>q.diff===d && ((q.sub!==undefined)?q.sub:0)===k).length>=3));
        const perSub=_rich?3:2;
        G.wafaPerSub=perSub;
        _tiers.forEach(diff=>{
          const all=_allQ.filter(q=>q.diff===diff);
          const bySub={};
          all.forEach(q=>{ const k=(q.sub!==undefined)?q.sub:0; (bySub[k]=bySub[k]||[]).push(q); });
          const keys=Object.keys(bySub).sort((a,b)=>a-b);
          const cap=Math.max(1,keys.length)*perSub;
          if(all.length<=cap){
            // بنك مطابق تماماً: ترتيب ثابت محفوظ (توافق مسابقات 24 القائمة)
            const picked=[]; keys.forEach(k=>{ picked.push(...bySub[k].slice(0,perSub)); });
            G.boardData[cat][diff]=picked.length?picked:all.slice(0,cap);
          } else {
            // بنك موسع: سحب طازج متوازن بلا تكرار عبر اللعبات
            const picked=[]; keys.forEach(k=>{ picked.push(...hhPickFresh(cat+'::'+diff+'::s'+k, bySub[k], perSub)); });
            G.boardData[cat][diff]=picked;
          }
        });
        return;
      }
      // مسابقة القرآن: 8 أسئلة عشوائية من كل مستوى (200/400/600/800)
      ['easy','med','hard','elite'].forEach(diff=>{
        const pool=(QDB[cat]||[]).filter(q=>q.diff===diff);
        G.boardData[cat][diff]=hhPickFresh(cat+'::'+diff, pool, 8);
      });
      return;
    }
    // الأساطير: نأخذ سؤالين من كل مستوى (easy=600, med=800, hard=1000)
    // الفئات العادية والأساطير: انتقاء طازج بلا تكرار عبر اللعبات
    ['easy','med','hard'].forEach(diff=>{
      const pool=(QDB[cat]||[]).filter(q=>q.diff===diff);
      G.boardData[cat][diff]=hhPickFresh(cat+'::'+diff, pool, 2);
    });
  });
  showScreen('screen-board');
  // إخفاء أي مقترح ترويجي ظاهر عند دخول اللعب
  try{ var _sb=document.getElementById('hh-season-banner'); if(_sb) _sb.style.display='none'; }catch(e){}
  window.scrollTo(0,0);
  document.getElementById('screen-board').scrollTop=0;
  updateBoardUI();
  
  // تتبع الإنجازات
  if(window.hhTrackActivity){
    hhTrackActivity('game_played');
    if(G.teams && G.teams.length >= 6) hhTrackActivity('six_teams');
  }
  // نبني بعد frame واحد لضمان أن topBar استقر في الـ DOM
  requestAnimationFrame(()=>{
    requestAnimationFrame(()=>{
      setTimeout(()=>{
      // تأخير مزدوج لضمان استقرار DOM وأبعاد دقيقة
      requestAnimationFrame(()=>{ requestAnimationFrame(()=>{ buildBoard(); }); });
      // fallback متكرر حتى يظهر اللوح
      let _fbCount = 0;
      const _fbInterval = setInterval(()=>{
        const grid = document.getElementById('board-grid');
        if(grid && grid.children.length === 0 && G.selectedCats.length > 0){
          buildBoard();
          _fbCount++;
          if(_fbCount >= 5) clearInterval(_fbInterval);
        } else {
          clearInterval(_fbInterval);
        }
      }, 300);
      // observer يعيد البناء لو تغير حجم الشاشة (دوران، zoom)
      if(window._boardResizeObs) window._boardResizeObs.disconnect();
      window._boardResizeObs = new ResizeObserver(()=>{ 
        if(G.selectedCats.length){ 
          clearTimeout(window._resizeBuildTimer);
          window._resizeBuildTimer = setTimeout(()=>buildBoard(), 80);
        } 
      });
      const tb=document.getElementById('board-top-bar');
      if(tb) window._boardResizeObs.observe(tb);
      const bb=document.getElementById('board-bottom-bar');
      if(bb) window._boardResizeObs.observe(bb);
      const gridObs=document.getElementById('board-grid');
      if(gridObs) window._boardResizeObs.observe(gridObs);
      }, 400);
    });
  });
}

// ═══ ذاكرة الأسئلة المطروحة: منع التكرار عبر اللعبات ═══
var _HH_SEEN_KEY = 'hh_seen_v1';
var _HH_SEEN_CLOUD = null;      // نسخة الذاكرة السحابية بعد التحميل
var _HH_SEEN_CLOUD_LOADED = false;
var _hhSeenSaveTimer = null;
function _hhQHash(q){
  var s = (q && q.q) ? String(q.q) : '';
  var h = 5381;
  for(var i=0;i<s.length;i++){ h = ((h<<5)+h+s.charCodeAt(i))|0; }
  return 'q'+(h>>>0).toString(36);
}
// تحميل الذاكرة السحابية مرة واحدة عند تسجيل الدخول (يدمجها مع المحلي)
async function _hhSeenCloudLoad(){
  if(_HH_SEEN_CLOUD_LOADED) return;
  try{
    if(typeof OFFLINE_MODE!=='undefined' && OFFLINE_MODE) return;
    if(typeof currentUser==='undefined' || !currentUser || typeof db==='undefined' || !db) return;
    var d = await db.collection('user_seen_questions').doc(currentUser.uid).get();
    _HH_SEEN_CLOUD = (d.exists && d.data().map) ? d.data().map : {};
    _HH_SEEN_CLOUD_LOADED = true;
    // دمج: المحلي (من جلسات كزائر) يُرفع للسحابة أول مرة
    var local = {}; try{ local = JSON.parse(localStorage.getItem(_HH_SEEN_KEY)||'{}')||{}; }catch(e){}
    var merged = _hhSeenMerge(_HH_SEEN_CLOUD, local);
    _HH_SEEN_CLOUD = merged;
    try{ localStorage.setItem(_HH_SEEN_KEY, JSON.stringify(merged)); }catch(e){}
    _hhSeenCloudSaveDebounced();
  }catch(e){}
}
function _hhSeenMerge(a, b){
  var out = JSON.parse(JSON.stringify(a||{}));
  Object.keys(b||{}).forEach(function(cat){
    out[cat] = out[cat] || {};
    Object.keys(b[cat]).forEach(function(h){
      // نحتفظ بأقدم وقت طرح (الأدق للدورة)
      if(!out[cat][h] || b[cat][h] < out[cat][h]) out[cat][h] = b[cat][h];
    });
  });
  return out;
}
function _hhSeenCloudSaveDebounced(){
  if(_hhSeenSaveTimer) clearTimeout(_hhSeenSaveTimer);
  _hhSeenSaveTimer = setTimeout(function(){
    try{
      if(typeof OFFLINE_MODE!=='undefined' && OFFLINE_MODE) return;
      if(typeof currentUser==='undefined' || !currentUser || typeof db==='undefined' || !db) return;
      if(!_HH_SEEN_CLOUD) return;
      db.collection('user_seen_questions').doc(currentUser.uid).set({
        map: _HH_SEEN_CLOUD,
        updatedAt: firebase.firestore.FieldValue.serverTimestamp()
      }, {merge:true});
    }catch(e){}
  }, 1500);  // تجميع الكتابات لتقليل الاستدعاءات
}
function _hhSeenLoad(){
  // السحابة إن حُمّلت (حساب مسجّل)، وإلا المحلي (زائر/دون اتصال)
  if(_HH_SEEN_CLOUD_LOADED && _HH_SEEN_CLOUD) return _HH_SEEN_CLOUD;
  try{ return JSON.parse(localStorage.getItem(_HH_SEEN_KEY)||'{}')||{}; }catch(e){ return {}; }
}
function _hhSeenSave(m){
  // محلي دائماً (فوري وآمن)
  try{ localStorage.setItem(_HH_SEEN_KEY, JSON.stringify(m)); }catch(e){}
  // وسحابي إن كان الحساب مسجّلاً
  if(_HH_SEEN_CLOUD_LOADED){ _HH_SEEN_CLOUD = m; _hhSeenCloudSaveDebounced(); }
}
// وسم سؤال بأنه طُرح فعلاً (يستدعى عند فتح السؤال)
function hhMarkSeen(cat, q){
  try{
    var m=_hhSeenLoad();
    (m[cat]=m[cat]||{})[_hhQHash(q)]=Date.now();
    _hhSeenSave(m);
  }catch(e){}
}
// انتقاء طازج: غير المطروح أولاً، ثم الأقدم طرحاً؛ وإن اكتملت الدورة صُفّرت ذاكرة الفئة
function hhPickFresh(cat, pool, count){
  if(!pool || !pool.length) return [];
  var m=_hhSeenLoad(), seen=m[cat]||{};
  var freshQ=[], old=[];
  pool.forEach(function(q){
    var h=_hhQHash(q);
    if(seen[h]) old.push({q:q, t:seen[h]}); else freshQ.push(q);
  });
  // اكتملت الدورة على هذه المجموعة؟ صفّر وابدأ من جديد
  if(freshQ.length===0 && old.length>0){
    delete m[cat]; _hhSeenSave(m);
    freshQ=pool.slice(); old=[];
  }
  var picked=shuffle(freshQ.slice()).slice(0, count);
  if(picked.length<count && old.length){
    old.sort(function(a,b){ return a.t-b.t; }); // الأقدم طرحاً أولاً
    picked=picked.concat(old.map(function(x){return x.q;}).slice(0, count-picked.length));
  }
  return picked;
}

function buildBoard(){
  const wrap = document.getElementById('board-grid');
  if(!wrap) return;
  wrap.innerHTML = '';
  const n = G.selectedCats.length;
  if(!n) return;

  //  لوحات المسابقات الخاصة
  if(G.isComp){
    if(G.compKind==='wafa'){ buildWafaBoard(wrap); } else { buildCompBoard(wrap); }
    return;
  }

  const isMobile   = window.innerWidth < 700;
  const isLandscape= window.innerWidth > window.innerHeight;
  const vw = window.innerWidth;
  const vh = window.innerHeight;

  // ── قياس top-bar الفعلي ──
  const tbEl = document.getElementById('board-top-bar');
  const tbH  = tbEl ? Math.ceil(tbEl.getBoundingClientRect().height) : (isMobile ? 46 : 58);

  // ── قياس bottom-bar (شريط الفرق) لخصمه من المساحة ──
  const bbEl = document.getElementById('board-bottom-bar');
  const bbH  = bbEl ? Math.ceil(bbEl.getBoundingClientRect().height) : (isMobile ? 48 : 56);

  // ── المساحة الحقيقية: نستخدم getBoundingClientRect للـboard-grid مباشرة ──
  // (الآن top-bar و bottom-bar داخل flex، فـboard-grid يأخذ المساحة الصحيحة تلقائياً)
  const gridEl = document.getElementById('board-grid');
  let totalH;
  if(gridEl){
    const rect = gridEl.getBoundingClientRect();
    if(rect.height > 100){
      totalH = Math.floor(rect.height - 6); // -6 للأمان
    } else {
      // fallback: نحسب نظرياً
      totalH = Math.floor(vh - tbH - bbH - 8);
    }
  } else {
    totalH = Math.floor(vh - tbH - bbH - 8);
  }

  // ── توزيع الفئات ──
  let perRow, chunks;
  if(n >= 5){
    const r1 = Math.ceil(n/2), r2 = Math.floor(n/2);
    chunks  = [G.selectedCats.slice(0,r1), G.selectedCats.slice(r1)];
    perRow  = r1;
  } else if(n === 4){
    perRow = 2; chunks = [G.selectedCats.slice(0,2), G.selectedCats.slice(2,4)];
  } else if(n === 3){
    perRow = 3; chunks = [G.selectedCats];
  } else {
    perRow = 2; chunks = [G.selectedCats.slice(0,1), G.selectedCats.slice(1,2)];
  }
  const nRows  = chunks.length;

  // ── أبعاد دقيقة ──
  const rowGap   = isMobile ? 3 : 5;
  const catGap   = isMobile ? 2 : 4;
  const cellGap  = isMobile ? 2 : 3;
  const pad      = isMobile ? 2 : 3;

  const availH   = totalH - pad*2 - rowGap*(nRows-1);
  const rowH     = Math.floor(availH / nRows);

  // label: ارتفاع ثابت يدعم سطرين
  const labelBarH= isMobile ? (isLandscape ? 22 : 30) : 34;
  const usableH  = rowH - labelBarH - cellGap*4;
  const cellH    = Math.max(16, Math.floor(usableH / 3));

  // عرض اللوحة الفعلي (محدود بـ max-width:1200px) لا عرض النافذة الكامل
  // هذا يمنع تجاوز الخلايا لحدود اللوحة وقصّها عند الأطراف على الشاشات العريضة
  let boardW = vw;
  try{
    const gw = gridEl ? gridEl.getBoundingClientRect().width : 0;
    if(gw > 50) boardW = Math.floor(gw);
  }catch(e){}
  // ملء كامل العرض: أُلغي سقف 1200px حتى تكتمل الأطراف

  const catW     = Math.floor((boardW - pad*2 - catGap*(perRow-1)) / perRow);
  // توازن بين عمود الفئة والأرقام حسب الحالة:
  // - جوال + 6 فئات (3 في الصف): الفئة ~40% حتى الأرقام تكون 30% لكل عمود
  // - جوال + 4 فئات (2 في الصف): الفئة ~42%
  // - ديسكتوب: 50%
  let centerWRatio, minCenterW, maxCenterW;
  if(isMobile){
    if(perRow >= 3){
      // 3 فئات أفقيا · نقلل الفئة لإفساح للأرقام
      centerWRatio = 0.40;
      minCenterW = 55;
      maxCenterW = 75;
    } else {
      // 2 فئات أفقيا · مساحة كافية للجميع
      centerWRatio = 0.42;
      minCenterW = 75;
      maxCenterW = 110;
    }
  } else {
    centerWRatio = 0.50;
    minCenterW = 100;
    maxCenterW = 180;
  }
  const centerW  = Math.max(minCenterW, Math.min(maxCenterW, Math.floor(catW * centerWRatio)));

  // الأرقام: خط مناسب للحجم الفعلي للخلية
  const ptsSize  = isMobile
    ? Math.max(0.95, Math.min(1.55, cellH / 30))
    : Math.max(0.80, Math.min(1.35, cellH / 24));
  // اسم الفئة: يتكيف مع عرض عمود الفئة
  const lblSize  = isMobile
    ? Math.max(0.74, Math.min(0.92, centerW / 78))
    : Math.max(0.68, Math.min(0.90, centerW / 180));
  const emojiS   = Math.max(0.9,  Math.min(2.6,  cellH  * 0.07));

  // ── CSS ديناميكي ──
  let style = document.getElementById('board-dynamic-style');
  if(!style){ style = document.createElement('style'); style.id='board-dynamic-style'; document.head.appendChild(style); }
  style.textContent = `
    #board-grid{ overflow:hidden; padding:0; height:100%; }
    .board-rows-wrap{
      display:flex; flex-direction:column;
      gap:${rowGap}px; width:100%;
      max-width:none; margin-inline:auto;
      height:${totalH}px;
      padding:${pad}px;
      box-sizing:border-box; overflow:hidden;
    }
    .board-cat-group{
      display:flex; flex-direction:row;
      gap:${catGap}px;
      height:${rowH}px;
      flex-shrink:0; overflow:hidden;
    }
    .cat-row{
      display:grid;
      grid-template-columns:1fr ${centerW}px 1fr;
      gap:${cellGap}px; align-items:start;
      flex:1; min-width:0;
    }
    .cat-col{
      display:flex; flex-direction:column;
      gap:${cellGap}px; justify-content:flex-start;
    }
    .qcell{ height:${cellH}px; flex-shrink:0; }
    .qcell .qpts{ font-size:${ptsSize}rem; }
    /* الفئة: الصورة + الاسم = بالضبط مجموع ارتفاع الأرقام الثلاثة */
    .cat-center{
      height:${cellH * 3 + cellGap * 2}px;
      align-self:start;
      margin:0 !important;
    }
    .cat-center .cc-img-wrap{
      height:${cellH * 3 + cellGap * 2 - labelBarH}px;
      max-height:${cellH * 3 + cellGap * 2 - labelBarH}px;
      flex:none;
      overflow:hidden;
    }
    .cat-center .cc-label-bar{
      font-size:${lblSize}rem !important;
      white-space:normal !important;
      word-break:break-word !important;
      line-height:1.15 !important;
      padding:2px 3px !important;
      height:${labelBarH}px !important;
      max-height:${labelBarH}px !important;
      flex:none !important;
      display:flex !important;
      align-items:center !important;
      justify-content:center !important;
      text-align:center !important;
      border-radius:0 0 12px 12px !important;
      overflow:hidden !important;
    }
    .cat-center .cc-img-wrap .cc-emoji{ font-size:${emojiS}rem; }
  `;

  // ── بناء اللوح ──
  const outerWrap = document.createElement('div');
  outerWrap.className = 'board-rows-wrap';

  chunks.forEach(rowCats => {
    // تعبئة لو الصف ناقص
    const filled = [...rowCats];
    while(filled.length < perRow) filled.push(null);

    const groupWrap = document.createElement('div');
    groupWrap.className = 'board-cat-group';

    filled.forEach(cat => {
      if(!cat){
        const ph = document.createElement('div');
        ph.style.cssText = 'visibility:hidden;flex:1;min-width:0;';
        groupWrap.appendChild(ph);
        return;
      }
      const ci       = CAT_INFO[cat] || {emoji:'<svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M21 5c-1.11-.35-2.33-.5-3.5-.5-1.95 0-4.05.4-5.5 1.5-1.45-1.1-3.55-1.5-5.5-1.5S2.45 4.9 1 6v14.65c0 .25.25.5.5.5.1 0 .15-.05.25-.05C3.1 20.45 5.05 20 6.5 20c1.95 0 4.05.4 5.5 1.5 1.35-.85 3.8-1.5 5.5-1.5 1.65 0 3.35.3 4.75 1.05.1.05.15.05.25.05.25 0 .5-.25.5-.5V6c-.6-.45-1.25-.75-2-1z"/></svg>', label:cat, color:'#8A1538', bg:'#e8f2ec'};
      const globalIdx= G.selectedCats.indexOf(cat);

      const isLegendCat = (typeof _LEGENDARY_CATS_SET !== 'undefined')
        ? _LEGENDARY_CATS_SET.has(cat)
        : (cat === 'الأساطير' || cat.startsWith('أساطير'));
      const left3=[], right3=[];
      ['easy','med','hard'].forEach(diff=>{
        const qs = G.boardData[cat]?.[diff] || [];
        left3.push(qs[0] ? {diff, q:qs[0], key:cat+'__'+diff+'__0', catIdx:globalIdx, isLegend:isLegendCat} : null);
        right3.push(qs[1] ? {diff, q:qs[1], key:cat+'__'+diff+'__1', catIdx:globalIdx, isLegend:isLegendCat} : null);
      });

      const row = document.createElement('div');
      row.className = 'cat-row';

      const leftCol = document.createElement('div');
      leftCol.className = 'cat-col';
      for(let i=0;i<3;i++) leftCol.appendChild(left3[i] ? makeQCell({...left3[i],side:'left'}) : makePH(cellH));
      row.appendChild(leftCol);

      // الأساطير: palette ذهبية ثابتة موحدة لطابع راق متناسق
      // الفئات العادية: palette حسب الترتيب
      const _cp = isLegendCat
        ? CAT_PALETTE_LEGENDARY   // الذهبي الفخم · ثابت لكل فئات الأساطير
        : CAT_PALETTES[globalIdx % CAT_PALETTES.length];
      const center = document.createElement('div');
      center.className = 'cat-center';
      const _isPartnerCat = (cat.indexOf('بيرف آب')!==-1 || cat.indexOf('طموح')!==-1 || cat.indexOf('قنوان')!==-1);
      if(_isPartnerCat && ci.img){
        // الخيار ①: خلفية بيضاء كاملة + الشعار يملأ + شريط اسم ملوّن
        center.style.cssText = `background:#fff;border:2.5px solid ${ci.color||_cp[9]};box-shadow:0 4px 0 ${_cp[10]};`;
        center.classList.add('cat-center-logo');
      } else {
        center.style.cssText = `background:${_cp[8]};border:2.5px solid ${_cp[9]};box-shadow:0 4px 0 ${_cp[10]};`;
      }

      const imgWrap = document.createElement('div');
      imgWrap.className = 'cc-img-wrap';
      //  حقن خلفية متدرجة بلون الفئة في الأيقونات الأسطورية لإزالة التنافر البني الموحد
      if(isLegendCat){
        // خلفية متدرجة بنية داكنة + توهج ذهبي حول الأيقونة (المعيار الذهبي)
        imgWrap.style.background = 'radial-gradient(circle at 50% 35%, #5E0E26 0%, #3D0918 70%, #1a0e05 100%)';
        imgWrap.style.borderRadius = '12px';
        imgWrap.style.boxShadow = 'inset 0 0 0 2px rgba(212,188,133,.55), 0 0 16px rgba(184,146,74,.25)';
      }
      const savedImg = localStorage.getItem('cat_img_'+cat);
      if(_isPartnerCat && CAT_SVG[cat]){
        // شعار الشريك كـ SVG نصي (يظهر للجميع دائماً · لا يعتمد على صور خارجية)
        imgWrap.style.background = '#fff';
        imgWrap.innerHTML = CAT_SVG[cat];
      } else if(savedImg){
        imgWrap.innerHTML = `<img src="${savedImg}" alt="${ci.label}" style="width:100%;height:100%;object-fit:contain;">`;
      } else if(CAT_SVG[cat]){
        imgWrap.innerHTML = CAT_SVG[cat];
      } else if(ci.img){
        imgWrap.innerHTML = `<img src="${ci.img}" alt="${ci.label}" style="width:100%;height:100%;object-fit:contain;padding:6px;box-sizing:border-box;">`;
      } else if(ci.emoji && ci.emoji.trim()){
        imgWrap.innerHTML = `<span class="cc-emoji">${ci.emoji}</span>`;
      } else {
        // Fallback احترافي: SVG بالحرف الأول من اسم الفئة (بدون إيموجي)
        const firstChar = (ci.label || cat || '?').charAt(0);
        const accentColor = ci.color || '#8A1538';
        imgWrap.innerHTML = `
          <svg viewBox="0 0 100 100" width="100%" height="100%" xmlns="http://www.w3.org/2000/svg" style="max-width:88%;max-height:88%;">
            <defs>
              <linearGradient id="catgrad_${cat.replace(/[^a-zA-Z0-9]/g,'')}" x1="0%" y1="0%" x2="100%" y2="100%">
                <stop offset="0%" stop-color="${accentColor}" stop-opacity="0.95"/>
                <stop offset="100%" stop-color="${accentColor}" stop-opacity="0.7"/>
              </linearGradient>
            </defs>
            <rect x="6" y="6" width="88" height="88" rx="18" fill="url(#catgrad_${cat.replace(/[^a-zA-Z0-9]/g,'')})" stroke="#B8924A" stroke-width="2.5"/>
            <text x="50" y="68" text-anchor="middle" font-size="52" font-family="'Cairo','Tajawal',sans-serif" fill="#fff" font-weight="900" style="letter-spacing:-2px;">${firstChar}</text>
          </svg> `;
      }
      center.appendChild(imgWrap);

      const labelBar = document.createElement('div');
      labelBar.className = 'cc-label-bar';
      if(_isPartnerCat && ci.color){
        labelBar.style.cssText = `background:${ci.color};border-radius:0 0 10px 10px;color:#fff;`;
      } else {
        labelBar.style.cssText = `background:${_cp[6]};border-radius:0 0 10px 10px;`;
      }
      labelBar.textContent = ci.label;
      center.appendChild(labelBar);
      row.appendChild(center);

      const rightCol = document.createElement('div');
      rightCol.className = 'cat-col';
      for(let i=0;i<3;i++) rightCol.appendChild(right3[i] ? makeQCell({...right3[i],side:'right'}) : makePH(cellH));
      row.appendChild(rightCol);

      groupWrap.appendChild(row);
    });
    outerWrap.appendChild(groupWrap);
  });
  wrap.appendChild(outerWrap);
}
// ═══════════════════════════════════════════════════════════════════
//  لوحة المسابقات الخاصة · 4 مستويات (200/400/600/800) × 8 أسئلة
//    تحافظ على نفس عقد اللعب: cell_{cat__diff__i} + openQ + used
// ═══════════════════════════════════════════════════════════════════
const COMP_LEVELS = [
  {diff:'easy',  pts:200, label:'سهل',   bg:'#EBF2EE', border:'#3D6B53', text:'#2C5340'},
  {diff:'med',   pts:400, label:'متوسط', bg:'#FDF3DD', border:'#b5801f', text:'#7a5410'},
  {diff:'hard',  pts:600, label:'صعب',   bg:'#FDE8E8', border:'#c0392b', text:'#8b1a10'},
  {diff:'elite', pts:800, label:'نخبة',  bg:'linear-gradient(135deg,#3D0918,#5E0E26)', border:'#B8924A', text:'#D4BC85'}
];

// ═══════════════════════════════════════════════════════════════════
//  مسابقة مركز أجيال التربوي · لوحة شعار المركز وسط أربع فئات
// ═══════════════════════════════════════════════════════════════════
var _HH_AJYALC_CAT = 'مسابقة مركز أجيال التربوي';
_HH_PARTNER_QUESTIONS[_HH_AJYALC_CAT] = [{"diff": "easy", "q": "ما الرياضة التراثية التي يمارسها القطريون بالصقور؟", "a": "الصقارة (الصيد بالصقور)", "sub": 0}, {"diff": "easy", "q": "ما البطولة القارية التي توّج بها العنابي عامي 2019 و2023؟", "a": "بطولة كأس آسيا", "sub": 0}, {"diff": "med", "q": "ما النادي القطري الملقب بـ«الملك»؟", "a": "نادي الريان", "sub": 0}, {"diff": "med", "q": "من هدّاف المنتخب القطري التاريخي الملقب بـ«المعلم»؟", "a": "منصور مفتاح", "sub": 0}, {"diff": "hard", "q": "ما أقدم نادٍ رياضي تأسس في قطر؟", "a": "النادي الأهلي (عام 1950)", "sub": 0}, {"diff": "hard", "q": "في أي عام استضافت الدوحة دورة الألعاب الآسيوية؟", "a": "عام 2006", "sub": 0}, {"diff": "easy", "q": "ما الناقل الجوي الوطني لدولة قطر؟", "a": "الخطوط الجوية القطرية", "sub": 1}, {"diff": "easy", "q": "ما وسيلة النقل الحديثة التي تربط أنحاء الدوحة بثلاثة خطوط؟", "a": "مترو الدوحة", "sub": 1}, {"diff": "med", "q": "ما الوزارة القطرية المسؤولة عن رعاية الفنون والتراث والمهرجانات؟", "a": "وزارة الثقافة", "sub": 1}, {"diff": "med", "q": "في أي منطقة بالدوحة يقع مبنى مكتبة قطر الوطنية؟", "a": "المدينة التعليمية", "sub": 1}, {"diff": "hard", "q": "في أي عام تأسست جامعة قطر؟", "a": "عام 1977", "sub": 1}, {"diff": "hard", "q": "ما «البِشت» في اللباس القطري؟", "a": "عباءة رجالية تُلبس فوق الثوب في المناسبات", "sub": 1}, {"diff": "easy", "q": "في أي قارة تقع دولة قطر؟", "a": "قارة آسيا", "sub": 2}, {"diff": "easy", "q": "ما المسطح المائي الذي يحيط بقطر من ثلاث جهات؟", "a": "الخليج العربي", "sub": 2}, {"diff": "med", "q": "ما المدينة الساحلية شمال الدوحة التي سُمّيت على خورها البحري وميناء صيدها العريق؟", "a": "مدينة الخور", "sub": 2}, {"diff": "med", "q": "ما المدينة الصناعية جنوب قطر المرتبطة بتصدير النفط؟", "a": "مدينة مسيعيد", "sub": 2}, {"diff": "hard", "q": "ما البلدة القطرية الشهيرة بمحمية أشجار القرم (المانغروف)؟", "a": "الذخيرة", "sub": 2}, {"diff": "hard", "q": "ما المنطقة الجنوبية التي يلتقي فيها البحر بالكثبان الرملية؟", "a": "خور العديد (البحر الداخلي)", "sub": 2}, {"diff": "easy", "q": "ما المشروب الساخن بالحليب والهيل الرائج في المجالس القطرية؟", "a": "شاي الكرك", "sub": 3}, {"diff": "easy", "q": "ما الحيوان الملقب بـ«سفينة الصحراء» في الموروث القطري؟", "a": "الجمل", "sub": 3}, {"diff": "med", "q": "ما الفعالية التراثية المصاحبة لاحتفالات اليوم الوطني في أم صلال؟", "a": "درب الساعي", "sub": 3}, {"diff": "med", "q": "كم درهماً في الريال القطري الواحد؟", "a": "100 درهم", "sub": 3}, {"diff": "hard", "q": "ما الاسم القديم الذي عُرفت به مدينة الدوحة؟", "a": "البِدع", "sub": 3}, {"diff": "hard", "q": "من مؤلف كلمات النشيد الوطني القطري «قسماً»؟", "a": "الشيخ مبارك بن سيف آل ثاني", "sub": 3}];
_HH_COMP_CATS.add(_HH_AJYALC_CAT);
var _HH_CHAR_COMPS = _HH_CHAR_COMPS || {};
_HH_CHAR_COMPS[_HH_AJYALC_CAT] = {
  get img(){ return (typeof _HH_IMG_QANWAN!=='undefined') ? _HH_IMG_QANWAN : ''; },
  name1:'برنامج قنوان',
  name2:'',
  frameBg:'#ffffff',
  subs:[
    {label:'الرياضي',    c:'#3D6B53', bg:'#EBF2EE'},
    {label:'الثقافي',    c:'#b5801f', bg:'#FDF3DD'},
    {label:'الاستكشافي', c:'#c0392b', bg:'#FDE8E8'},
    {label:'الترفيهي',   c:'#5E0E26', bg:'#F7ECEF'}
  ]
};
try{
  var _hhAjycSeed = JSON.parse(JSON.stringify(_HH_PARTNER_QUESTIONS[_HH_AJYALC_CAT]));
  if(typeof window !== 'undefined' && window.QDB_ORIGINAL){ window.QDB_ORIGINAL[_HH_AJYALC_CAT] = _hhAjycSeed; }
  if(typeof QDB_ORIGINAL === 'object' && QDB_ORIGINAL && QDB_ORIGINAL !== window.QDB_ORIGINAL){ QDB_ORIGINAL[_HH_AJYALC_CAT] = _hhAjycSeed; }
}catch(_e){}

// ═══════════════════════════════════════════════════════════════════
//  مسابقة اليوم الأمني · مركز أجيال التربوي
// ═══════════════════════════════════════════════════════════════════
