// ═══ تخصيصات الأدمن للمسابقات (اسم المسابقة، الشخصية، الصورة، الفئات الفرعية، الأسئلة) ═══
var _HH_COMP_DEFAULTS = null;
function _hhSnapshotCompDefaults(){
  if(_HH_COMP_DEFAULTS) return;
  try{
    _HH_COMP_DEFAULTS = {
      wafa:{ label:_HH_WAFA_LABEL_DEFAULT, name1:_HH_WAFA_NAME1, name2:_HH_WAFA_NAME2, img:_HH_WAFA_IMG,
             subs:_HH_WAFA_SUBS.map(x=>x.label),
             questions: JSON.parse(JSON.stringify(_HH_PARTNER_QUESTIONS[_HH_WAFA_CAT]||[])) },
      quran:{ label:_HH_AJYAL_QURAN_COMP_CAT,
             questions: JSON.parse(JSON.stringify(_HH_PARTNER_QUESTIONS[_HH_AJYAL_QURAN_COMP_CAT]||[])) },
      chars:{}
    };
    // كل لوحات الشخصية من السجل المعمم (عدا الوفاء المغطاة أعلاه)
    try{
      if(typeof _HH_CHAR_COMPS!=='undefined'){
        Object.keys(_HH_CHAR_COMPS).forEach(function(cat){
          if(typeof _HH_WAFA_CAT!=='undefined' && cat===_HH_WAFA_CAT) return;
          var cc=_HH_CHAR_COMPS[cat];
          _HH_COMP_DEFAULTS.chars[cat]={
            label:(typeof CAT_INFO!=='undefined'&&CAT_INFO[cat]&&CAT_INFO[cat].label)||cat,
            name1:cc.name1||'', name2:cc.name2||'',
            subs:(cc.subs||[]).map(function(x){return x.label;}),
            questions: JSON.parse(JSON.stringify(_HH_PARTNER_QUESTIONS[cat]||[]))
          };
        });
      }
    }catch(_e2){}
  }catch(_e){}
}
// تجاوزات لوحات الشخصية (صورة/أسماء/فئات) · تُقرأ في buildWafaBoard
var _HH_COMP_OVR = {};
function _hhApplyCompConfig(){
  _hhSnapshotCompDefaults();
  var cfg=null; try{ cfg=JSON.parse(localStorage.getItem('hh_comp_config')||'null'); }catch(_e){}
  var eff = cfg||{}; var w=eff.wafa||{}, q=eff.quran||{};
  var d=_HH_COMP_DEFAULTS||{wafa:{},quran:{}};
  try{
    _HH_WAFA_NAME1 = w.name1 || d.wafa.name1;
    _HH_WAFA_NAME2 = w.name2 || d.wafa.name2;
    _HH_WAFA_NAME  = _HH_WAFA_NAME1+' '+_HH_WAFA_NAME2;
    _HH_WAFA_IMG   = (w.img && String(w.img).indexOf('data:image')===0) ? w.img : d.wafa.img;
    for(var i=0;i<4;i++){ _HH_WAFA_SUBS[i].label = (Array.isArray(w.subs)&&w.subs[i]) ? w.subs[i] : d.wafa.subs[i]; }
    var wq = (Array.isArray(w.questions)&&w.questions.length===24) ? w.questions : d.wafa.questions;
    var qq = (Array.isArray(q.questions)&&q.questions.length) ? q.questions : d.quran.questions;
    _HH_PARTNER_QUESTIONS[_HH_WAFA_CAT] = JSON.parse(JSON.stringify(wq));
    _HH_PARTNER_QUESTIONS[_HH_AJYAL_QURAN_COMP_CAT] = JSON.parse(JSON.stringify(qq));
    try{ if(typeof window!=='undefined'&&window.QDB_ORIGINAL){ window.QDB_ORIGINAL[_HH_WAFA_CAT]=JSON.parse(JSON.stringify(wq)); window.QDB_ORIGINAL[_HH_AJYAL_QURAN_COMP_CAT]=JSON.parse(JSON.stringify(qq)); } }catch(_e){}
    try{ if(typeof QDB!=='undefined'&&QDB){ QDB[_HH_WAFA_CAT]=JSON.parse(JSON.stringify(wq)); QDB[_HH_AJYAL_QURAN_COMP_CAT]=JSON.parse(JSON.stringify(qq)); } }catch(_e){}
    try{ if(typeof CAT_INFO!=='undefined'){
      if(CAT_INFO[_HH_WAFA_CAT]) CAT_INFO[_HH_WAFA_CAT].label = w.label || d.wafa.label;
      if(CAT_INFO[_HH_AJYAL_QURAN_COMP_CAT]) CAT_INFO[_HH_AJYAL_QURAN_COMP_CAT].label = q.label || d.quran.label;
    } }catch(_e){}
  }catch(_e){}
  // لوحات الشخصية الأخرى من السجل المعمم
  try{
    _HH_COMP_OVR = {};
    var chars=(cfg&&cfg.chars)||{};
    var dch=(d&&d.chars)||{};
    if(typeof _HH_CHAR_COMPS!=='undefined'){
      Object.keys(_HH_CHAR_COMPS).forEach(function(cat){
        if(typeof _HH_WAFA_CAT!=='undefined' && cat===_HH_WAFA_CAT) return;
        var c=chars[cat]||{}; var dd=dch[cat]||{};
        // الأسئلة: نقبل التخصيص إذا طابق حجم الأصل (حماية من التلف)
        var qs=(Array.isArray(c.questions)&&dd.questions&&c.questions.length===dd.questions.length)?c.questions:dd.questions;
        if(qs){
          _HH_PARTNER_QUESTIONS[cat]=JSON.parse(JSON.stringify(qs));
          try{ if(typeof window!=='undefined'&&window.QDB_ORIGINAL) window.QDB_ORIGINAL[cat]=JSON.parse(JSON.stringify(qs)); }catch(_a){}
          try{ if(typeof QDB!=='undefined'&&QDB) QDB[cat]=JSON.parse(JSON.stringify(qs)); }catch(_b){}
        }
        try{ if(typeof CAT_INFO!=='undefined'&&CAT_INFO[cat]) CAT_INFO[cat].label=c.label||dd.label||CAT_INFO[cat].label; }catch(_c){}
        var ovr={};
        if(c.name1) ovr.name1=c.name1;
        if(c.name2!==undefined&&c.name2!==null&&c.name2!=='') ovr.name2=c.name2;
        if(c.img&&String(c.img).indexOf('data:image')===0) ovr.img=c.img;
        if(Array.isArray(c.subs)&&c.subs.some(function(x){return x;})) ovr.subs=c.subs;
        if(Object.keys(ovr).length) _HH_COMP_OVR[cat]=ovr;
      });
    }
  }catch(_e3){}
}
_hhApplyCompConfig();

// ═══════════════════════════════════════════════════════════════════
//  لوحة «يوم الوفاء» · 4 فئات فرعية حول صورة الشخصية كاملةً
//    نفس عقد اللعب: cell_{cat__diff__i} + openQ + used
// ═══════════════════════════════════════════════════════════════════
function buildWafaBoard(wrap){
  const cat = G.selectedCats[0];
  // تكوين اللوحة: يوم الوفاء بإعداداتها القابلة للتخصيص، أو أي لوحة شخصية من السجل
  const _cc = (typeof _HH_CHAR_COMPS !== 'undefined' && _HH_CHAR_COMPS[cat]) || null;
  const _isWafaSelf = (typeof _HH_WAFA_CAT !== 'undefined' && cat === _HH_WAFA_CAT);
  const _ov = (typeof _HH_COMP_OVR!=='undefined' && _HH_COMP_OVR[cat]) || {};
  const CC_IMG  = _isWafaSelf ? _HH_WAFA_IMG   : (_ov.img   || (_cc ? _cc.img   : ''));
  const CC_N1   = _isWafaSelf ? _HH_WAFA_NAME1 : (_ov.name1 || (_cc ? _cc.name1 : ''));
  const CC_N2   = _isWafaSelf ? _HH_WAFA_NAME2 : ((_ov.name2!==undefined) ? _ov.name2 : (_cc ? _cc.name2 : ''));
  const CC_SUBS = _isWafaSelf ? _HH_WAFA_SUBS  : ((_cc ? _cc.subs : []).map((sb,i)=> (_ov.subs&&_ov.subs[i]) ? Object.assign({},sb,{label:_ov.subs[i]}) : sb));
  const CC_FBG  = (!_isWafaSelf && _cc && _cc.frameBg) ? _cc.frameBg : '#baaf9d';
  const CC_COMPACT = (!_isWafaSelf && _cc && _cc.compact===true);
  const CC_ORN     = (!_isWafaSelf && _cc && _cc.plateOrn===true);
  const isMobile    = window.innerWidth < 700;
  const isLandscape = window.innerWidth > window.innerHeight;
  const vh = window.innerHeight;

  const tbEl = document.getElementById('board-top-bar');
  const tbH  = tbEl ? Math.ceil(tbEl.getBoundingClientRect().height) : (isMobile ? 46 : 58);
  const bbEl = document.getElementById('board-bottom-bar');
  const bbH  = bbEl ? Math.ceil(bbEl.getBoundingClientRect().height) : (isMobile ? 48 : 56);
  let totalH;
  const rect = wrap.getBoundingClientRect();
  if(rect.height > 100){ totalH = Math.floor(rect.height - 6); }
  else { totalH = Math.floor(vh - tbH - bbH - 8); }

  const pad     = isMobile ? 4 : 8;
  const gap     = isMobile ? 5 : 10;
  const headerH = isMobile ? (isLandscape ? 30 : 36) : 50;
  const stacked = isMobile && !isLandscape; // جوال عمودي: أعمدة متراصة

  // مقاس الإطار المربع: أصغر بُعدَي العمود الأوسط حتى تملأه الصورة المربعة تماماً بلا فراغ
  const centerW   = stacked ? Math.min(CC_COMPACT?150:170, Math.floor(window.innerWidth*0.34))
                            : (CC_COMPACT ? Math.max(180, Math.min(Math.floor(window.innerWidth*0.17), 280))
                                          : Math.max(240, Math.min(Math.floor(window.innerWidth*0.27), 420)));
  const nameH     = isMobile ? 60 : 80; // ارتفاع لوحة الاسم بسطرَي خط أميري
  const topShift  = stacked ? 0 : (isMobile ? 10 : 22); // إنزال الصورة قليلاً
  const stageH    = totalH - pad*2 - headerH - gap;
  const frameSide = stacked ? centerW : Math.max(150, Math.min(centerW, stageH - nameH - gap - topShift));

  let style = document.getElementById('wafa-board-dynamic-style');
  if(!style){ style = document.createElement('style'); style.id='wafa-board-dynamic-style'; document.head.appendChild(style); }
  style.textContent = `
    #board-grid{ overflow:hidden; padding:0; height:100%; }
    .wafa-wrap{ display:flex; flex-direction:column; gap:${gap}px; width:100%;
      max-width:1560px; margin-inline:auto;
      height:${totalH}px; padding:${pad}px; box-sizing:border-box; overflow:${stacked?'auto':'hidden'}; }
    .wafa-header{ height:${headerH}px; flex-shrink:0; display:flex; align-items:center; justify-content:center;
      background:linear-gradient(135deg,#3D0918,#5E0E26); border:2px solid #B8924A; border-radius:14px;
      box-shadow:0 3px 0 #8A6D2E, 0 0 18px rgba(184,146,74,.25);
      font-family:'Amiri','Cairo',serif; font-weight:700; color:#D4BC85;
      font-size:${isMobile ? '1rem' : '1.55rem'}; padding:0 12px; text-align:center; letter-spacing:.2px; }
    .wafa-stage{ flex:1; min-height:0; display:flex; flex-direction:${stacked?'column':'row'}; gap:${gap}px; }
    .wafa-side{ flex:1; min-width:0; display:flex; flex-direction:column; gap:${gap}px; }
    .wafa-cat{ flex:1; min-height:0; display:flex; flex-direction:column; border-radius:14px; overflow:hidden;
      border:2.5px solid var(--wc); background:#fff; box-shadow:0 3px 0 var(--wc); }
    .wafa-cat .wname{ background:var(--wc); color:#fff; font-weight:900; text-align:center;
      padding:${isMobile?'3px':((G.wafaPerSub||2)===3?'3px':'5px')}; font-size:${isMobile?'.8rem':((G.wafaPerSub||2)===3?'.92rem':'1rem')}; font-family:Cairo,sans-serif; flex-shrink:0; }
    .wafa-cells{ flex:1; min-height:0; display:grid; grid-template-columns:repeat(${(G.wafaTiers||['easy','med','hard']).length},1fr);
      grid-template-rows:repeat(${(typeof G!=='undefined'&&G.wafaPerSub)||2},1fr);
      gap:${isMobile?4:((G.wafaPerSub||2)===3?5:7)}px; padding:${isMobile?5:((G.wafaPerSub||2)===3?6:8)}px; }
    .wafa-cells .qcell{ display:flex; align-items:center; justify-content:center; cursor:pointer; user-select:none;
      border:2px solid var(--wc); border-radius:${(G.wafaPerSub||2)===3?9:11}px; background:var(--wbg); min-height:${isMobile?30:0}px;
      box-shadow:inset 0 -2px 0 rgba(61,9,24,.06);
      transition:transform .13s ease, box-shadow .13s ease; }
    .wafa-cells .qcell:not(.used):hover{ transform:translateY(-2px);
      box-shadow:0 6px 16px rgba(61,9,24,.14), inset 0 -2px 0 rgba(61,9,24,.06); }
    .wafa-cells .qcell:not(.used):active{ transform:translateY(0); }
    .wafa-cells .qcell .qpts{ font-weight:900; font-family:Cairo,sans-serif; color:var(--wc);
      font-size:${isMobile?'.85rem':((G.wafaTiers||[]).length===4?'.95rem':((G.wafaPerSub||2)===3?'1rem':'1.15rem'))}; }
    .wafa-cells .qcell.elite{ background:linear-gradient(140deg,#3A2B10,#151007); border-color:#B8924A; position:relative; }
    .wafa-cells .qcell.elite .qpts{ color:#EAD9B0; }
    .wafa-cells .qcell.elite::after{ content:'★'; position:absolute; top:2px; left:6px; font-size:.55rem; color:#B8924A; }
    .wafa-center{ width:${stacked?'100%':centerW+'px'}; flex-shrink:0;
      display:flex; flex-direction:${stacked?'row':'column'}; align-items:center;
      justify-content:${stacked?'center':'flex-start'}; padding-top:${stacked?0:topShift}px; gap:${gap}px;
      ${stacked?'order:-1;':''} }
    .wafa-frame{ width:${frameSide}px; height:${frameSide}px; flex-shrink:0;
      border-radius:22px; background:${CC_FBG}; border:4px solid #B8924A;
      box-shadow:0 0 0 3px #8A1538, 0 12px 34px rgba(61,9,24,.4);
      display:flex; align-items:center; justify-content:center; overflow:hidden; }
    .wafa-frame img{ width:100%; height:100%; object-fit:cover; display:block; }
    .wafa-name .wn1{ font-size:${isMobile?'1.02rem':'clamp(1rem, 1.55vw, 1.35rem)'}; line-height:1.5; white-space:nowrap; }
    .wafa-name{ max-width:100%; box-sizing:border-box; overflow:hidden; }
    .wafa-name .wn2{ font-size:${isMobile?'.75rem':'clamp(.82rem, 1.45vw, 1.05rem)'}; white-space:nowrap; line-height:1.7; }
    .wafa-name{ ${stacked?'flex:1;':''} background:linear-gradient(135deg,#3D0918,#5E0E26); border:2px solid #B8924A;
      color:#D4BC85; font-family:'Amiri','Cairo',serif; font-weight:700; text-align:center; line-height:1.6;
      padding:${isMobile?'6px 10px':'8px 16px'}; border-radius:12px; box-shadow:0 3px 0 #8A6D2E;
      font-size:${isMobile?'.85rem':'1.12rem'}; }
    ${CC_ORN?`
    .wafa-name{ position:relative; padding-inline:${isMobile?'22px':'28px'}; box-shadow:0 0 0 2px #8A1538, 0 3px 0 #8A6D2E; }
    .wafa-name::before,.wafa-name::after{ content:'\u2756'; position:absolute; top:50%; transform:translateY(-50%); color:#B8924A; font-size:${isMobile?'.6rem':'.75rem'}; }
    .wafa-name::before{ right:8px; } .wafa-name::after{ left:8px; }
    .wafa-name .wn1{ font-weight:900; font-family:Cairo,sans-serif; }`:''}
  `;

  const outer=document.createElement('div'); outer.className='wafa-wrap';
  const header=document.createElement('div'); header.className='wafa-header';
  header.textContent = (CAT_INFO[cat] && CAT_INFO[cat].label) || cat;
  outer.appendChild(header);

  const stage=document.createElement('div'); stage.className='wafa-stage';

  const mkSubBlock=(si)=>{
    const sub=CC_SUBS[si];
    const box=document.createElement('div'); box.className='wafa-cat';
    box.style.setProperty('--wc',sub.c); box.style.setProperty('--wbg',sub.bg);
    const nm=document.createElement('div'); nm.className='wname'; nm.textContent=sub.label;
    if(sub.c2){ nm.style.background='linear-gradient(135deg,'+sub.c+','+sub.c2+')'; }
    box.appendChild(nm);
    const cells=document.createElement('div'); cells.className='wafa-cells';
    // الأعمدة: 200/400/600 · والصفوف بعدد أسئلة المستوى (2 قياسياً، 3 في الوضع الموسع)
    const _per=G.wafaPerSub||2;
    const _tiers=G.wafaTiers||['easy','med','hard'];
    const _order=[];
    for(let k=0;k<_per;k++){ _tiers.forEach(diff=>_order.push([diff,k])); }
    _order.forEach(([diff,k])=>{
      const idx=si*_per+k;
      const q=(G.boardData[cat] && G.boardData[cat][diff] && G.boardData[cat][diff][idx])||null;
      const el=document.createElement('div');
      if(!q){ el.className='qcell used'; cells.appendChild(el); return; }
      const key=cat+'__'+diff+'__'+idx;
      el.id='cell_'+key; el.className='qcell '+diff;
      el.innerHTML='<div class="qpts">'+DIFF_MAP[diff].pts+'</div>';
      el.addEventListener('click',()=>{
        if(el.classList.contains('used')) return;
        el.classList.add('popping'); setTimeout(()=>el.classList.remove('popping'),300);
        openQ(q,diff,key,false);
      });
      cells.appendChild(el);
    });
    box.appendChild(cells);
    return box;
  };

  const sideR=document.createElement('div'); sideR.className='wafa-side';
  sideR.appendChild(mkSubBlock(0)); sideR.appendChild(mkSubBlock(1));
  const center=document.createElement('div'); center.className='wafa-center';
  const frame=document.createElement('div'); frame.className='wafa-frame';
  const img=document.createElement('img'); img.src=CC_IMG; img.alt=(CC_N1+' '+CC_N2); frame.appendChild(img);
  const nameEl=document.createElement('div'); nameEl.className='wafa-name';
  nameEl.innerHTML='<div class="wn1">'+esc(CC_N1)+'</div>'+(CC_N2?('<div class="wn2">'+esc(CC_N2)+'</div>'):'');
  nameEl.setAttribute('aria-label',CC_N1+' '+CC_N2);
  center.appendChild(frame); center.appendChild(nameEl);
  const sideL=document.createElement('div'); sideL.className='wafa-side';
  sideL.appendChild(mkSubBlock(2)); sideL.appendChild(mkSubBlock(3));

  stage.appendChild(sideR); stage.appendChild(center); stage.appendChild(sideL);
  outer.appendChild(stage);
  wrap.appendChild(outer);

  // ضمانة عدم القصّ: إن تجاوزت لوحة الاسم حدود اللوحة (اختلاف خطوط/مقاسات) نُصغّر الإطار بمقدار التجاوز
  if(!stacked){
    requestAnimationFrame(()=>{ try{
      const stR=stage.getBoundingClientRect(), nmR=nameEl.getBoundingClientRect();
      const over=Math.ceil(nmR.bottom-(stR.bottom-2));
      if(over>0){
        const side=Math.max(140, frameSide-over);
        frame.style.width=side+'px'; frame.style.height=side+'px';
      }
    }catch(_e){} });
  }
}

function buildCompBoard(wrap){
  const cat = G.selectedCats[0];
  const ci  = CAT_INFO[cat] || {label:cat, color:'#8A1538', bg:'#F8F3E6'};
  const isMobile    = window.innerWidth < 700;
  const isLandscape = window.innerWidth > window.innerHeight;
  const vh = window.innerHeight;

  // ── المساحة الحقيقية (نفس منطق buildBoard) ──
  const tbEl = document.getElementById('board-top-bar');
  const tbH  = tbEl ? Math.ceil(tbEl.getBoundingClientRect().height) : (isMobile ? 46 : 58);
  const bbEl = document.getElementById('board-bottom-bar');
  const bbH  = bbEl ? Math.ceil(bbEl.getBoundingClientRect().height) : (isMobile ? 48 : 56);
  let totalH;
  const rect = wrap.getBoundingClientRect();
  if(rect.height > 100){ totalH = Math.floor(rect.height - 6); }
  else { totalH = Math.floor(vh - tbH - bbH - 8); }

  // ── أبعاد ──
  const pad     = isMobile ? 3 : 6;
  const rowGap  = isMobile ? 4 : 8;
  const cellGap = isMobile ? 3 : 6;
  const headerH = isMobile ? (isLandscape ? 30 : 38) : 48;
  // الجوال عمودي: 4 أعمدة × سطرين لكل مستوى، وإلا 8 أعمدة × سطر واحد
  const twoLines = isMobile && !isLandscape;
  const cols = twoLines ? 4 : 8;
  const availH = totalH - pad*2 - headerH - rowGap*4;
  const rowH   = Math.floor(availH / 4);
  const cellH  = twoLines ? Math.max(18, Math.floor((rowH - cellGap) / 2)) : Math.max(20, rowH);
  const badgeW = isMobile ? 58 : 96;
  const ptsSize = Math.max(0.9, Math.min(1.6, cellH / (isMobile ? 26 : 30)));

  // ── CSS ديناميكي ──
  let style = document.getElementById('comp-board-dynamic-style');
  if(!style){ style = document.createElement('style'); style.id='comp-board-dynamic-style'; document.head.appendChild(style); }
  style.textContent = `
    #board-grid{ overflow:hidden; padding:0; height:100%; }
    .comp-board-wrap{
      display:flex; flex-direction:column; gap:${rowGap}px;
      width:100%; max-width:none; margin-inline:auto;
      height:${totalH}px; padding:${pad}px; box-sizing:border-box; overflow:hidden;
    }
    .comp-board-header{
      height:${headerH}px; flex-shrink:0;
      display:flex; align-items:center; justify-content:center; gap:10px;
      background:linear-gradient(135deg,#3D0918,#5E0E26);
      border:2px solid #B8924A; border-radius:14px;
      box-shadow:0 3px 0 #8A6D2E, 0 0 18px rgba(184,146,74,.25);
      font-family:Cairo,sans-serif; font-weight:900; color:#D4BC85;
      font-size:${isMobile ? '.82rem' : '1.05rem'};
      padding:0 10px; text-align:center;
    }
    .comp-level-row{
      display:flex; flex-direction:row; gap:${cellGap}px;
      height:${rowH}px; flex-shrink:0; overflow:hidden;
    }
    .comp-level-badge{
      width:${badgeW}px; flex-shrink:0; border-radius:12px;
      display:flex; flex-direction:column; align-items:center; justify-content:center;
      font-family:Cairo,sans-serif; font-weight:900; line-height:1.15;
    }
    .comp-level-badge .clb-pts{ font-size:${isMobile ? '.95rem' : '1.25rem'}; font-variant-numeric:tabular-nums; }
    .comp-level-badge .clb-lbl{ font-size:${isMobile ? '.62rem' : '.78rem'}; opacity:.9; }
    .comp-cells{
      flex:1; min-width:0;
      display:grid; grid-template-columns:repeat(${cols},1fr);
      gap:${cellGap}px; align-content:stretch;
    }
    .comp-cells .qcell{
      height:${cellH}px; display:flex; align-items:center; justify-content:center;
      cursor:pointer; user-select:none;
    }
    .comp-cells .qcell .qpts{ font-size:${ptsSize}rem; font-weight:900; font-family:Cairo,sans-serif; }
  `;

  // ── البناء ──
  const outer = document.createElement('div');
  outer.className = 'comp-board-wrap';

  const header = document.createElement('div');
  header.className = 'comp-board-header';
  header.innerHTML = `<svg width="${isMobile?18:24}" height="${isMobile?18:24}" viewBox="0 0 24 24" fill="none" stroke="#D4BC85" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M6 9H4.5a2.5 2.5 0 0 1 0-5H6"/><path d="M18 9h1.5a2.5 2.5 0 0 0 0-5H18"/><path d="M4 22h16"/><path d="M10 14.66V17c0 .55-.47.98-.97 1.21C7.85 18.75 7 20.24 7 22"/><path d="M14 14.66V17c0 .55.47.98.97 1.21C16.15 18.75 17 20.24 17 22"/><path d="M18 2H6v7a6 6 0 0 0 12 0V2Z"/></svg><span>${esc(ci.label || cat)}</span>`;
  outer.appendChild(header);

  COMP_LEVELS.forEach(lvl => {
    const row = document.createElement('div');
    row.className = 'comp-level-row';

    const badge = document.createElement('div');
    badge.className = 'comp-level-badge';
    badge.style.cssText = `background:${lvl.bg};border:2.5px solid ${lvl.border};box-shadow:0 3px 0 ${lvl.border};color:${lvl.text};`;
    badge.innerHTML = `<span class="clb-pts">${lvl.pts}</span><span class="clb-lbl">${lvl.label}</span>`;
    row.appendChild(badge);

    const cellsWrap = document.createElement('div');
    cellsWrap.className = 'comp-cells';
    const qs = (G.boardData[cat] && G.boardData[cat][lvl.diff]) || [];
    for(let i=0;i<8;i++){
      if(qs[i]){
        cellsWrap.appendChild(makeCompCell(lvl, qs[i], cat+'__'+lvl.diff+'__'+i));
      }else{
        const ph = document.createElement('div');
        ph.className = 'qcell used';
        ph.style.cssText = 'border-radius:14px;background:#e8ecf0;border:2px dashed #c8ced4;';
        cellsWrap.appendChild(ph);
      }
    }
    row.appendChild(cellsWrap);
    outer.appendChild(row);
  });

  wrap.appendChild(outer);
}

function makeCompCell(lvl, q, key){
  const el = document.createElement('div');
  el.id = 'cell_' + key;
  el.className = 'qcell ' + lvl.diff;
  el.style.cssText = `border:2.5px solid ${lvl.border};background:${lvl.bg};border-radius:14px;box-shadow:0 2px 0 ${lvl.border};`;
  el.innerHTML = `<div class="qpts" style="color:${lvl.text}">${lvl.pts}</div>`;
  el.addEventListener('click', () => {
    if(el.classList.contains('used')) return;
    el.classList.add('popping');
    setTimeout(()=>el.classList.remove('popping'),300);
    openQ(q, lvl.diff, key, false);
  });
  return el;
}

function makeQCell({diff,q,key,catIdx=0,side='left',isLegend=false}){
  const d=DIFF_MAP[diff];
  // الأساطير: palette ذهبية ثابتة موحدة · متناسقة مع الأيقونة
  const p = isLegend
    ? CAT_PALETTE_LEGENDARY
    : CAT_PALETTES[catIdx % CAT_PALETTES.length];
  const el=document.createElement('div');
  el.id='cell_'+key;
  // في الأساطير: التفاوت المتدرج 600/800/1000
  // easy → 600 (نخبوي معروف) | med → 800 (يحتاج تخصص) | hard → 1000 (أسطوري)
  const legendPtsMap = {easy:600, med:800, hard:1000};
  const shownPts = isLegend ? legendPtsMap[diff] : d.pts;
  el.className='qcell '+diff;
  const r=side==='left'?'6px 20px 20px 6px':'20px 6px 6px 20px';
  if(diff==='easy'){
    el.style.cssText=`border:2px solid ${p[1]};background:${p[0]};border-radius:${r};box-shadow:0 2px 0 ${p[1]};`;
    el.innerHTML=`<div class="qpts" style="color:${p[2]}">${shownPts}</div>`;
  }else if(diff==='med'){
    el.style.cssText=`border:2px solid ${p[4]};background:${p[3]};border-radius:${r};box-shadow:0 2px 0 ${p[4]};`;
    el.innerHTML=`<div class="qpts" style="color:${p[5]}">${shownPts}</div>`;
  }else{
    el.style.cssText=`border:2px solid ${p[7]};background:${p[6]};border-radius:${r};box-shadow:0 2px 0 ${p[7]};`;
    el.innerHTML=`<div class="qpts" style="color:#fff">${shownPts}</div>`;
  }
  el.addEventListener('click',()=>{
    if(el.classList.contains('used'))return;
    el.classList.add('popping');
    setTimeout(()=>el.classList.remove('popping'),300);
    openQ(q,diff,key,isLegend);
  });
  return el;
}
function makePH(h){
  const p=document.createElement('div');
  p.style.cssText='height:'+h+'px;border-radius:50px;background:#e8ecf0;opacity:.4;';
  return p;
}

function adjustScore(i, dir){
  G.scores[i]=(G.scores[i]||0)+(dir*50);
  updateBoardUI();
  toast(esc(G.teams[i])+' '+(dir>0?'▲ +50':'▼ -50')+' نقطة','info');
}

function updateBoardUI(){
  const row=document.getElementById('b-scores-row');
  if(row){
    row.innerHTML='';
    // صنف ديناميكي حسب عدد الفرق للتوزيع المتساوي
    row.classList.remove('teams-2','teams-3','teams-4','teams-5','teams-6','teams-7','teams-8');
    row.classList.add('teams-'+G.teams.length);
    G.teams.forEach((t,i)=>{
      const isActive=G.turn===i;
      // بطاقة الفريق الكبيرة
      const card=document.createElement('div');
      card.className='team-score-card' + (isActive?' active':'');

      // زر +
      const btnPlus=document.createElement('button');
      btnPlus.className='score-btn plus';
      btnPlus.textContent='+';
      btnPlus.title='+ 50 نقطة';
      btnPlus.onclick=()=>adjustScore(i,1);

      // اسم الفريق
      const name=document.createElement('div');
      name.className='team-name';
      name.textContent=t;

      // النقاط
      const score=document.createElement('div');
      score.className='team-score';
      score.textContent=G.scores[i];

      // زر -
      const btnMinus=document.createElement('button');
      btnMinus.className='score-btn minus';
      btnMinus.textContent='−';
      btnMinus.title='- 50 نقطة';
      btnMinus.onclick=()=>adjustScore(i,-1);

      // الترتيب: − [نقاط] [اسم] +
      card.appendChild(btnMinus);
      card.appendChild(score);
      card.appendChild(name);
      card.appendChild(btnPlus);
      row.appendChild(card);
    });
  }
  const tb=document.getElementById('turn-badge');
  if(tb){
    const name=esc(G.teams[G.turn]||'');
    const gameName=esc(G.gameName||'');
    tb.innerHTML=
      '<div style="height:3px;background:rgba(255,255,255,.25);width:100%;"></div>'+
      '<div style="display:flex;align-items:stretch;flex:1;">'+
        '<div style="flex:1;padding:5px 12px;border-left:1px solid rgba(255,255,255,.15);display:flex;flex-direction:column;justify-content:center;gap:2px;background:rgba(255,255,255,.06);">'+
          '<span style="font-size:.56rem;color:rgba(255,255,255,.45);font-family:Cairo,sans-serif;letter-spacing:.8px;">اسم اللعبة</span>'+
          '<span style="font-size:.84rem;font-weight:900;color:#fff;font-family:Cairo,sans-serif;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100px;">'+gameName+'</span>'+
        '</div>'+
        '<div onclick="hhSwitchTurn()" title="انقر لتبديل الدور (للحكم)" style="flex:1;padding:5px 12px;display:flex;flex-direction:column;justify-content:center;gap:2px;cursor:pointer;">'+
          '<span style="font-size:.56rem;color:rgba(255,255,255,.45);font-family:Cairo,sans-serif;letter-spacing:.8px;">دور <svg width="9" height="9" viewBox="0 0 24 24" fill="none" stroke="#D4BC85" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:middle;"><path d="M8 3L4 7l4 4"/><path d="M4 7h16"/><path d="M16 21l4-4-4-4"/><path d="M20 17H4"/></svg></span>'+
          '<span style="font-size:.84rem;font-weight:900;color:#fff;font-family:Cairo,sans-serif;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100px;">'+name+'</span>'+
        '</div>'+
      '</div>';
  }
  const nameEl=document.getElementById('board-game-name');
  if(nameEl)nameEl.textContent=G.gameName||'';
  updatePUDisplay();
}

// تبديل الدور بقرار الحكم: نقرة على خانة الدور
function hhSwitchTurn(){
  if(!G || !G.teams || G.teams.length<2) return;
  if(document.getElementById('q-modal').classList.contains('open')){
    if(typeof toast==='function') toast('أغلق السؤال أولاً ثم بدّل الدور','warn');
    return;
  }
  G.turn=(G.turn+1)%G.teams.length;
  updateBoardUI();
  if(typeof toast==='function') toast('الدور الآن: '+G.teams[G.turn],'info');
}

function updatePUDisplay(){
  const teamPU=PU.teams[G.turn]||{hafra:1,dagf:1,eskot:1,twoans:1,fakh:1};
  const modalOpen=document.getElementById('q-modal').classList.contains('open');
  ['hafra','dagf','eskot','twoans','fakh'].forEach(type=>{
    const used=teamPU[type]<=0;
    const armed=PU.armed===type;
    // حفرة وضاعف: قبل السؤال فقط · منع وجوابين: بعد السؤال فقط
    const afterOnly=(type==='eskot'||type==='twoans'||type==='fakh');
    const wrongTime=afterOnly?(!modalOpen):(modalOpen);
    ['pu-','qm-'].forEach(pre=>{
      const btnId = pre + (type==='twoans' ? 'twoans' : type);
      const b=document.getElementById(btnId);if(!b)return;
      b.disabled=used||wrongTime;
      b.classList.toggle('used-pu',used);
      b.classList.toggle('armed',armed);
      const badge=document.getElementById(btnId+'-badge');
      if(badge){
        const count=Math.max(0,teamPU[type]);
        badge.textContent=count;
        badge.style.display=used?'none':'flex';
      }
      b.style.opacity=(used)?'0.2':(wrongTime?'0.35':'1');
      b.style.cursor=(used||wrongTime)?'not-allowed':'pointer';
    });
  });
}

function armPU(type){
  const teamPU=PU.teams[G.turn];
  if(!teamPU||teamPU[type]<=0)return;
  const modalOpen=document.getElementById('q-modal').classList.contains('open');
  // حفرة وضاعف: قبل السؤال فقط
  if((type==='hafra'||type==='dagf')&&modalOpen){
    toast('حفرة وضاعف تستخدمان قبل فتح السؤال','warn');return;
  }
  // منع وجوابين والفخ: بعد السؤال فقط
  if((type==='eskot'||type==='twoans'||type==='fakh')&&!modalOpen){
    toast((type==='fakh'?'الفخ':(type==='eskot'?'منع':'جوابين'))+' تستخدم بعد فتح السؤال','warn');return;
  }
  //  الفخ: تفعيل فوري · إجبار الفريق التالي على الإجابة (مرة واحدة للفريق في اللعبة)
  if(type==='fakh'){
    if(G.trapTarget!==null){ toast('الفخ مستخدم في هذا السؤال','warn'); return; }
    if(G.answered){ toast('حُسم السؤال · لا فخ بعد التحكيم','warn'); return; }
    const n=G.teams.length;
    const target=(G.turn+1)%n;
    G.trapBy=G.turn; G.trapTarget=target;
    teamPU.fakh--;
    const banner=document.getElementById('qm-trap-banner');
    if(banner){
      banner.innerHTML=' <b>فخ!</b> السؤال الآن على فريق «'+esc(G.teams[target])+'» · إن أجاب صحيحاً يكسب النقاط، وإن أخطأ تُخصم منه!';
      banner.style.display='block';
    }
    playSound('wrong');
    if(navigator.vibrate) navigator.vibrate([60,40,60]);
    toast(' فخ من «'+esc(G.teams[G.turn])+'» · الإجابة على «'+esc(G.teams[target])+'»','info');
    updatePUDisplay();
    return;
  }
  PU.armed=PU.armed===type?null:type;
  updatePUDisplay();
  if(PU.armed)toast({hafra:' حفرة مسلحة!',dagf:'ضاعف مسلح!',eskot:' منع جاهز!',twoans:' جوابين جاهزة!',fakh:' الفخ!'}[type],'info');
}

function openQ(q,diff,key,isLegend){
  G.curQ=q;G.curKey=key;G.answered=false;
  G.ansRevealed=false;
  // وسم السؤال مطروحاً (لمنظومة منع التكرار)
  try{ hhMarkSeen(key.split('__')[0]+'::'+diff, q); }catch(e){}
  G.curIsLegend = !!isLegend;
  G.curLegendDiff = isLegend ? diff : null;
  const d=DIFF_MAP[diff];const ci=CAT_INFO[key.split('__')[0]]||{};
  // في الأساطير: العرض يكون بمستويات "نخبوي 600 / متقدم 800 / أسطوري 1000"
  const legendLabels = {easy:'نخبوي', med:'متقدم', hard:'أسطوري'};
  document.getElementById('qm-diff').textContent = isLegend ? legendLabels[diff] : d.label;
  document.getElementById('qm-diff').className='qm-badge '+diff;
  document.getElementById('qm-cat').textContent=ci.label||'';
  // أيقونة الفئة في الـ modal
  const catIcon=document.getElementById('qm-cat-icon');
  if(catIcon){
    const savedCatImg=localStorage.getItem('cat_img_'+key.split('__')[0]);
    if(savedCatImg){
      catIcon.innerHTML='<img src="'+savedCatImg+'" alt="أيقونة الفئة" style="width:32px;height:32px;object-fit:contain;">';
    } else if(CAT_SVG[key.split('__')[0]]){
      catIcon.style.background=ci.bg||'#e8f2ec';
      catIcon.innerHTML=CAT_SVG[key.split('__')[0]];
      catIcon.querySelector('svg').setAttribute('width','32');
      catIcon.querySelector('svg').setAttribute('height','32');
    } else {
      catIcon.innerHTML='<span style="font-size:1.4rem;">'+(ci.emoji||'<svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M21 5c-1.11-.35-2.33-.5-3.5-.5-1.95 0-4.05.4-5.5 1.5-1.45-1.1-3.55-1.5-5.5-1.5S2.45 4.9 1 6v14.65c0 .25.25.5.5.5.1 0 .15-.05.25-.05C3.1 20.45 5.05 20 6.5 20c1.95 0 4.05.4 5.5 1.5 1.35-.85 3.8-1.5 5.5-1.5 1.65 0 3.35.3 4.75 1.05.1.05.15.05.25.05.25 0 .5-.25.5-.5V6c-.6-.45-1.25-.75-2-1z"/></svg>')+'</span>';
    }
  }
  const legendPtsMap = {easy:600, med:800, hard:1000};
  const shownPts = isLegend ? legendPtsMap[diff] : d.pts;
  document.getElementById('qm-pts').textContent=shownPts+' نقطة';
  document.getElementById('qm-text').textContent=q.q;
  const cw=document.getElementById('qm-correct-wrap');
  if(cw){ cw.style.display='none'; const f=document.getElementById('qm-correct-form'); if(f) f.style.display='none';
    const n=document.getElementById('qm-correct-note'); if(n) n.value='';
    const e2=document.getElementById('qm-correct-err'); if(e2) e2.textContent='';
    const bb=document.getElementById('qm-correct-btn'); if(bb){ bb.style.display=''; bb.disabled=false; bb.textContent='✎ صوّب · أبلغ عن خطأ في السؤال أو الجواب'; bb.style.textDecoration='underline dotted'; bb.style.color='#8A6D2E'; } }
  // أسئلة الخيارات المتعددة · لا تظهر تلقائياً؛ وسيلة مساعدة بيد المتحكم
  const optsEl=document.getElementById('qm-opts');
  const optsTrig=document.getElementById('qm-opts-trigger');
  if(optsEl){ optsEl.innerHTML=''; optsEl.style.display='none'; optsEl.classList.remove('locked'); }
  if(optsTrig){ optsTrig.style.display=(Array.isArray(q.opts)&&q.opts.length>=2)?'flex':'none'; optsTrig.disabled=false; }
  const imgEl=document.getElementById('qm-img');
  if(imgEl){if(q.img){imgEl.src=q.img;imgEl.style.display='block';}else{imgEl.style.display='none';imgEl.src='';}}
  const revBtn=document.getElementById('reveal-btn');
  const ansBox=document.getElementById('answer-box');
  const judge=document.getElementById('team-judge');
  revBtn.textContent='الجواب';revBtn.className='answer-reveal-btn';revBtn.disabled=false;
  ansBox.textContent='';ansBox.className='answer-box';
  judge.style.display='none';
  // الأزرار تبنى ديناميكيا في revealAnswer
  document.getElementById('qm-actions').style.display='none';
  // إخفاء التلميح (سيظهر بعد الحكم)
  const hintEl=document.getElementById('judge-hint');
  if(hintEl) hintEl.style.display='none';
  // إعادة ضبط: إظهار المؤقت والمساعدات لسؤال جديد
  const qmBox=document.querySelector('#q-modal .qm-box');
  if(qmBox){ qmBox.classList.remove('revealed'); qmBox.scrollTop=0; }
  updatePUDisplay();
  const _qm=document.getElementById('q-modal');if(_qm.parentNode!==document.body)document.body.appendChild(_qm);_qm.classList.add('open');
  updatePUDisplay();
  startTimer(d.time,diff);
}

function hhToggleFullscreen(){
  try{
    if(document.fullscreenElement){ document.exitFullscreen(); }
    else{ document.documentElement.requestFullscreen(); }
  }catch(e){}
}
function hhBlackout(on){
  const el=document.getElementById('hh-blackout');
  if(!el) return;
  const show = (on===undefined)? el.style.display==='none' : on;
  el.style.display = show ? 'block' : 'none';
}
function hhToggleShortcutsHelp(){
  const el=document.getElementById('hh-kbd-help');
  if(!el) return;
  el.style.display = (el.style.display==='none'||!el.style.display) ? 'flex' : 'none';
}
function hhToggleTimerPause(){
  if(typeof G==='undefined' || !G.timer) return;
  G.timerPaused = !G.timerPaused;
  const tw=document.querySelector('.timer-wrap');
  if(tw) tw.classList.toggle('timer-paused', G.timerPaused);
  if(typeof toast==='function') toast(G.timerPaused?'⏸ المؤقت متوقف':'▶ المؤقت مستأنف', 'info');
}
document.addEventListener('keydown', function(e){
  // طبقة التعتيم: أي زر يخرج منها
  const bo=document.getElementById('hh-blackout');
  if(bo && bo.style.display!=='none'){ e.preventDefault(); hhBlackout(false); return; }
  // لا اختصارات أثناء الكتابة
  const t=e.target;
  if(t && (t.tagName==='INPUT'||t.tagName==='TEXTAREA'||t.tagName==='SELECT'||t.isContentEditable)) return;
  // فعالة في شاشة اللوحة فقط
  const board=document.getElementById('screen-board');
  if(!board || !board.classList.contains('active')) return;
  const modalOpen = (d=>d && getComputedStyle(d).display!=='none')(document.getElementById('q-modal'));
  switch(e.code){
    case 'KeyF': e.preventDefault(); hhToggleFullscreen(); break;
    case 'KeyB': e.preventDefault(); hhBlackout(true); break;
    case 'KeyT': e.preventDefault(); if(modalOpen) hhToggleTimerPause(); break;
    case 'KeyQ': if(modalOpen){ e.preventDefault(); try{ closeModal(); }catch(_){} } break;
    case 'KeyX': if(modalOpen){ e.preventDefault(); try{ closeModal(); toast&&toast('تم تجاوز السؤال','info'); }catch(_){} } break;
    case 'KeyE':
      if(modalOpen){
        e.preventDefault();
        const cw=document.getElementById('qm-correct-wrap');
        const revealed = cw && cw.style.display!=='none';
        if(!revealed){ try{ revealAnswer(); }catch(_){} }
        else { try{ hhOpenCorrection(); }catch(_){} }
      }
      break;
  }
});

// ═══════════════════════════════════════════════════════════════════
//  نظام الإشعارات · شكر وتقدير من الإدارة للمستخدمين
// ═══════════════════════════════════════════════════════════════════
async function hhSendUserNotification(toUid, toEmail, toName, title, body){
  if(typeof firebase==='undefined' || !firebase.firestore) throw new Error('لا اتصال بالسحابة');
  await firebase.firestore().collection('user_notifications').add({
    toUid: toUid||null, toEmail: (toEmail||'').toLowerCase()||null, toName: toName||'',
    title: String(title||'').slice(0,120), body: String(body||'').slice(0,800),
    from:'إدارة المُلهِم', read:false,
    createdAt: firebase.firestore.FieldValue.serverTimestamp()
  });
}
function hhOpenThanksComposer(reportId){
  const r=(window._allReports||[]).find(x=>String(x.id)===String(reportId));
  if(!r){ toast('تعذر إيجاد البلاغ','error'); return; }
  const toName=r.reporterName||(r.user&&(r.user.displayName||(r.user.email||'').split('@')[0]))||'صديق المنصة';
  const old=document.getElementById('hh-thanks-overlay'); if(old) old.remove();
  const ov=document.createElement('div'); ov.id='hh-thanks-overlay';
  ov.style.cssText='position:fixed;inset:0;background:rgba(30,6,15,.55);backdrop-filter:blur(4px);z-index:999995;display:flex;align-items:center;justify-content:center;padding:18px;';
  ov.onclick=ev=>{ if(ev.target===ov) ov.remove(); };
  const defTitle=' شكر وتقدير من إدارة المُلهِم';
  const defBody='أخي الكريم '+toName+'،\nشكراً جزيلاً على تصويبك الدقيق · بمثل حرصك تزداد المنصة جودةً وموثوقية. تم اعتماد ملاحظتك وستجد أثرها قريباً.\nمع خالص التقدير ';
  ov.innerHTML='<div style="background:#fff;border:2px solid #B8924A;border-radius:18px;max-width:460px;width:100%;overflow:hidden;font-family:Cairo,Tajawal,sans-serif;" onclick="event.stopPropagation()">' +'<div style="background:linear-gradient(135deg,#8A1538,#5E0E26);color:#fff;padding:13px 18px;font-weight:900;font-size:.95rem;"> إرسال شكر وتقدير إلى: '+esc(toName)+'</div>' +'<div style="padding:16px 18px;">' +'<div style="font-weight:800;font-size:.76rem;color:#5E0E26;margin-bottom:5px;">العنوان</div>' +'<input id="th-title" type="text" value="'+defTitle+'" style="width:100%;border:1.5px solid #E3D9C6;border-radius:10px;padding:9px 12px;font-family:Cairo;font-size:.84rem;box-sizing:border-box;margin-bottom:10px;">' +'<div style="font-weight:800;font-size:.76rem;color:#5E0E26;margin-bottom:5px;">نص الرسالة</div>' +'<textarea id="th-body" rows="5" style="width:100%;border:1.5px solid #E3D9C6;border-radius:10px;padding:10px 12px;font-family:Cairo;font-size:.85rem;line-height:1.9;resize:vertical;box-sizing:border-box;">'+defBody+'</textarea>' +'<div style="display:flex;gap:9px;margin-top:11px;">' +'<button id="th-send" style="background:linear-gradient(135deg,#3D6B53,#2a4d3a);color:#fff;border:none;border-radius:10px;padding:10px 24px;font-weight:900;font-size:.84rem;cursor:pointer;">إرسال الشكر</button>' +'<button onclick="document.getElementById(\'hh-thanks-overlay\').remove()" style="background:#F3F0F1;color:#666;border:none;border-radius:10px;padding:10px 16px;font-weight:900;font-size:.84rem;cursor:pointer;">إلغاء</button>' +'</div></div></div>';
  document.body.appendChild(ov);
  document.getElementById('th-send').onclick=async function(){
    this.disabled=true; this.textContent='جار الإرسال...';
    try{
      await hhSendUserNotification(r.user&&r.user.uid, r.user&&r.user.email, toName,
        document.getElementById('th-title').value, document.getElementById('th-body').value);
      toast(' وصل الشكر إلى '+toName,'success');
      ov.remove();
    }catch(err){ toast('تعذر الإرسال: '+(err.message||err),'error'); this.disabled=false; this.textContent='إرسال الشكر'; }
  };
}

// ── جرس المستخدم ──
let _hhNotifs=[];
async function hhLoadNotifications(){
  try{
    if(typeof firebase==='undefined'||!firebase.firestore||typeof currentUser==='undefined'||!currentUser) return;
    const db=firebase.firestore(); const col=db.collection('user_notifications');
    const seen={}; const out=[];
    const pull=async q=>{ const snap=await q.limit(30).get(); snap.forEach(d=>{ if(!seen[d.id]){ seen[d.id]=1; out.push(Object.assign({id:d.id}, d.data())); } }); };
    if(currentUser.uid) await pull(col.where('toUid','==',currentUser.uid));
    if(currentUser.email) await pull(col.where('toEmail','==',currentUser.email.toLowerCase()));
    out.sort((a,b)=>{ const ta=a.createdAt&&a.createdAt.seconds||0, tb=b.createdAt&&b.createdAt.seconds||0; return tb-ta; });
    _hhNotifs=out;
    hhUpdateNotifBadge();
  }catch(e){ console.warn('notifs:',e); }
}
function hhUpdateNotifBadge(){
  const badge=document.getElementById('hh-notif-badge'); if(!badge) return;
  const unread=_hhNotifs.filter(n=>!n.read).length;
  badge.textContent=unread>9?'9+':unread;
  badge.style.display=unread>0?'flex':'none';
}
function hhToggleNotifPanel(){
  const panel=document.getElementById('hh-notif-panel'); if(!panel) return;
  const opening=panel.style.display==='none'||!panel.style.display;
  panel.style.display=opening?'block':'none';
  if(!opening) return;
  const list=document.getElementById('hh-notif-list');
  if(!_hhNotifs.length){
    list.innerHTML='<div style="text-align:center;color:#999;font-family:Cairo;font-weight:700;font-size:.82rem;padding:22px 10px;">لا إشعارات بعد </div>';
  } else {
    list.innerHTML=_hhNotifs.map(n=>{
      const d=n.createdAt&&n.createdAt.seconds?new Date(n.createdAt.seconds*1000).toLocaleDateString('ar-QA',{day:'numeric',month:'long'}):'';
      return '<div style="background:'+(n.read?'#fff':'#FBF6EA')+';border:1.5px solid '+(n.read?'#eee':'#E3D9C6')+';border-radius:12px;padding:11px 13px;margin-bottom:8px;">' +'<div style="display:flex;justify-content:space-between;gap:8px;align-items:center;margin-bottom:4px;">' +'<div style="font-family:Cairo;font-weight:900;font-size:.82rem;color:#5E0E26;">'+esc(n.title||'')+'</div>' +(d?'<div style="font-size:.66rem;color:#aaa;font-family:Cairo;white-space:nowrap;">'+d+'</div>':'')
        +'</div>' +'<div style="font-family:Cairo;font-weight:700;font-size:.78rem;color:#555;line-height:1.9;white-space:pre-wrap;">'+esc(n.body||'')+'</div>' +'<div style="font-size:.66rem;color:#B8924A;font-family:Cairo;font-weight:800;margin-top:5px;">· '+esc(n.from||'إدارة المُلهِم')+'</div>' +'</div>';
    }).join('');
  }
  // تعليم الكل مقروءاً
  try{
    if(typeof firebase!=='undefined'&&firebase.firestore){
      const db=firebase.firestore();
      _hhNotifs.filter(n=>!n.read&&n.id).forEach(n=>{ db.collection('user_notifications').doc(n.id).update({read:true}).catch(()=>{}); n.read=true; });
      setTimeout(hhUpdateNotifBadge,300);
    }
  }catch(e){}
}

function hhOpenCorrection(){
  const f=document.getElementById('qm-correct-form'); const b=document.getElementById('qm-correct-btn');
  if(f) f.style.display='block'; if(b) b.style.display='none';
  const nm=document.getElementById('qm-correct-name');
  if(nm && !nm.value && typeof currentUser!=='undefined' && currentUser){
    nm.value = currentUser.displayName || (currentUser.email||'').split('@')[0] || '';
  }
  const n=document.getElementById('qm-correct-note'); if(n) setTimeout(()=>n.focus(),50);
}
function hhCloseCorrection(){
  const f=document.getElementById('qm-correct-form'); const b=document.getElementById('qm-correct-btn');
  if(f) f.style.display='none'; if(b) b.style.display='';
  const n=document.getElementById('qm-correct-note'); if(n) n.blur();
  if(document.activeElement && document.activeElement.blur) document.activeElement.blur();
}
async function hhSubmitCorrection(){
  const noteEl=document.getElementById('qm-correct-note');
  const errEl=document.getElementById('qm-correct-err');
  const note=(noteEl&&noteEl.value||'').trim();
  if(note.length<5){ if(errEl) errEl.textContent='اكتب وصف الخطأ أو التصويب (5 أحرف على الأقل)'; return; }
  const btn=document.getElementById('qm-correct-send');
  if(btn){ btn.disabled=true; btn.textContent='جار الإرسال...'; }
  try{
    const q=G.curQ||{};
    const userInfo=(typeof currentUser!=='undefined'&&currentUser)?{uid:currentUser.uid||null,email:currentUser.email||null,displayName:currentUser.displayName||null}:{anonymous:true};
    const data={
      type:'question_correction',
      description:note,
      qCat: q._cat || q.cat || ((G.selectedCats||[]).join('، ')) || '',
      qText: q.q || '',
      qAnswer: q.a || '',
      qDiff: q.diff || '',
      reporterName: ((document.getElementById('qm-correct-name')||{}).value||'').trim().slice(0,60),
      user: userInfo,
      userAgent: navigator.userAgent.substring(0,200),
      url: window.location.pathname,
      createdAt:(typeof firebase!=='undefined'&&firebase.firestore)?firebase.firestore.FieldValue.serverTimestamp():new Date().toISOString(),
      status:'new' };
    if(typeof firebase!=='undefined'&&firebase.firestore){
      await firebase.firestore().collection('problem_reports').add(data);
      if(typeof toast==='function') toast('شكراً! وصل تصويبك وسيُراجع','success');
    } else {
      const local=JSON.parse(localStorage.getItem('hh_problem_reports')||'[]');
      local.push({...data,_localId:Date.now()});
      localStorage.setItem('hh_problem_reports',JSON.stringify(local));
      if(typeof toast==='function') toast('حُفظ التصويب محلياً','info');
    }
    hhCloseCorrection();
    const b2=document.getElementById('qm-correct-btn');
    if(b2){ b2.textContent='✓ وصل تصويبك · شكراً لحرصك'; b2.disabled=true; b2.style.textDecoration='none'; b2.style.color='#3D6B53'; }
  }catch(e){
    if(errEl) errEl.textContent='تعذر الإرسال · حاول مرة أخرى';
  }finally{
    if(btn){ btn.disabled=false; btn.textContent='إرسال التصويب'; }
  }
}

function hhShowMcqOptions(){
  const q=G.curQ;
  const optsEl=document.getElementById('qm-opts');
  const optsTrig=document.getElementById('qm-opts-trigger');
  if(!q || !Array.isArray(q.opts) || q.opts.length<2 || !optsEl) return;
  optsEl.innerHTML='';
  const letters=['أ','ب','ج','د','هـ','و'];
  const shuffled=q.opts.slice().sort(()=>Math.random()-0.5);
  shuffled.forEach((op,oi)=>{
    const btn=document.createElement('button');
    btn.type='button'; btn.className='qm-opt'; btn.dataset.val=op;
    btn.innerHTML='<span class="qo-letter">'+letters[oi]+'</span><span class="qo-text"></span>';
    btn.querySelector('.qo-text').textContent=op;
    btn.onclick=function(){
      if(optsEl.classList.contains('locked')) return;
      optsEl.querySelectorAll('.qm-opt').forEach(b=>b.classList.remove('picked'));
      btn.classList.add('picked');
    };
    optsEl.appendChild(btn);
  });
  optsEl.style.display='grid';
  if(optsTrig) optsTrig.style.display='none';
  if(window.hhSoundClick) try{hhSoundClick();}catch(e){}
}

// رجوع آمن: يغلق السؤال دون احتسابه · للاختيار الخاطئ
function hhQCancel(){
  if(G.ansRevealed){
    if(typeof toast==='function') toast('لا رجوع بعد كشف الجواب','warn');
    return;
  }
  clearInterval(G.timer);
  // إعادة فخ الخصم إن كان مفعلاً على هذا السؤال
  try{
    if(G.trapBy!=null && G.teams && G.teams[G.trapBy]){
      PU.teams[G.trapBy].trap=(PU.teams[G.trapBy].trap||0)+1;
    }
  }catch(e){}
  G.trapTarget=null; G.trapBy=null;
  var tb=document.getElementById('qm-trap-banner'); if(tb){tb.style.display='none';tb.innerHTML='';}
  var tw=document.querySelector('.timer-wrap'); if(tw) tw.classList.remove('time-expired');
  G.timeExpired=false;
  G.curQ=null; G.curKey='';
  document.getElementById('q-modal').classList.remove('open');
  if(typeof updatePUDisplay==='function') updatePUDisplay();
  if(typeof toast==='function') toast('رجعت دون احتساب السؤال · الخلية ما زالت متاحة','info');
}

function revealAnswer(){
  G.ansRevealed=true;
  clearInterval(G.timer);
  clearInterval(window._gameElapsedTimer);
  // صوت الكشف
  if(window.hhSoundReveal) hhSoundReveal();
  // إخفاء المؤقت وصف المساعدات بعد الكشف · توفير مساحة
  const qmBox=document.querySelector('#q-modal .qm-box');
  if(qmBox) qmBox.classList.add('revealed');
  const revBtn=document.getElementById('reveal-btn');
  const ansBox=document.getElementById('answer-box');
  const judge=document.getElementById('team-judge');
  revBtn.textContent='تم الكشف عن الجواب';revBtn.className='answer-reveal-btn revealed';revBtn.disabled=true;
  ansBox.textContent=G.curQ.a;ansBox.className='answer-box show';
  // تمييز الخيارات بعد الكشف
  const optsTrig2=document.getElementById('qm-opts-trigger');
  if(optsTrig2) optsTrig2.style.display='none';
  const cw2=document.getElementById('qm-correct-wrap');
  if(cw2) cw2.style.display='block';
  const optsEl2=document.getElementById('qm-opts');
  if(optsEl2 && optsEl2.style.display!=='none'){
    optsEl2.classList.add('locked');
    optsEl2.querySelectorAll('.qm-opt').forEach(b=>{
      if(b.dataset.val===G.curQ.a){ b.classList.add('correct'); }
      else if(b.classList.contains('picked')){ b.classList.add('wrong'); }
    });
  }
  // بناء أزرار الفرق · اختيار متعدد
  const judgeGrid=document.getElementById('judge-grid');
  judgeGrid.innerHTML='';
  // ملاحظة جوابين إن مفعلة
  if(PU.armed==='twoans'){
    const twoNote=document.createElement('div');
    twoNote.style.cssText='width:100%;text-align:center;background:linear-gradient(135deg,#EBF2EE,#FAFAF8);border:1.5px solid #3D6B53;border-radius:10px;padding:8px 12px;margin-bottom:8px;font-family:Cairo,sans-serif;font-weight:900;color:#3D6B53;font-size:.82rem;';
    twoNote.innerHTML=' <strong>جوابين مفعلة</strong> · الفريق <strong>'+(G.teams[G.turn]||'')+'</strong> له حق تقديم إجابتين، إن صحت إحداهما اعتبر الفريق فائزا';
    judgeGrid.appendChild(twoNote);
  }
  // تعليمة
  const hint=document.createElement('div');
  hint.style.cssText='width:100%;text-align:center;font-size:.75rem;color:#888;margin-bottom:6px;font-family:Tajawal,sans-serif;';
  hint.textContent='اضغط على كل فريق أجاب صح (يمكن اختيار أكثر من فريق)';
  judgeGrid.appendChild(hint);
  // أزرار الفرق
  G.teams.forEach((t,i)=>{
    const btn=document.createElement('button');
    btn.className='judge-btn';
    btn.dataset.idx=i;
    btn.dataset.selected='0';
    btn.textContent=t;
    btn.onclick=()=>{
      const sel=btn.dataset.selected==='1';
      btn.dataset.selected=sel?'0':'1';
      btn.classList.toggle('correct-team',!sel);
      btn.innerHTML=(sel?'':' <svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-2 15l-5-5 1.41-1.41L10 14.17l7.59-7.59L19 8l-9 9z"/></svg> ')+t;
    };
    judgeGrid.appendChild(btn);
  });
  // صف الأزرار: تأكيد النتيجة + لا أحد + التالي (الأخير معطل حتى يتم الحكم)
  const actionsRow=document.getElementById('judge-actions');
  actionsRow.innerHTML='';
  const confirmBtn=document.createElement('button');
  confirmBtn.className='j-btn j-btn-confirm';
  confirmBtn.innerHTML='<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg> تأكيد النتيجة';
  confirmBtn.onclick=()=>{
    const winners=[...judgeGrid.querySelectorAll('.judge-btn[data-selected="1"]')].map(b=>parseInt(b.dataset.idx));
    judgeAnswer(winners.length>0?winners:'none');
  };
  const noneBtn=document.createElement('button');
  noneBtn.className='j-btn j-btn-none';
  noneBtn.innerHTML='<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg> لا أحد';
  noneBtn.onclick=()=>judgeAnswer('none');
  const nextBtn=document.createElement('button');
  nextBtn.className='j-btn j-btn-next';
  nextBtn.id='judge-next-btn';
  nextBtn.innerHTML='<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg> التالي';
  nextBtn.onclick=()=>closeModal();
  actionsRow.appendChild(confirmBtn);
  actionsRow.appendChild(noneBtn);
  actionsRow.appendChild(nextBtn);
  judge.style.display='block';
  if(PU.armed){const teamPU=PU.teams[G.turn];if(teamPU)teamPU[PU.armed]--;updatePUDisplay();}
}

function judgeAnswer(winners){
  G.answered=true;
  //  تسجيل الجلسة (للبحث التربوي)
  try{
    const _q=G.curQ||{};
    const _wi=(winners==='none'||!winners||winners.length===0)?[]:(Array.isArray(winners)?winners:[parseInt(winners)]);
    // استخراج تسمية الفئة الفرعية (لوحات المسابقات)
    let _subLbl='';
    try{
      if(typeof _q.sub==='number'){
        const _mainCat=_q._cat||G.selectedCats[0]||'';
        let _subs=null;
        if(typeof _HH_CHAR_COMPS!=='undefined'&&_HH_CHAR_COMPS[_mainCat]){
          const _ov=(typeof _HH_COMP_OVR!=='undefined'&&_HH_COMP_OVR[_mainCat])||{};
          _subs=_HH_CHAR_COMPS[_mainCat].subs||null;
          if(_ov.subs&&_ov.subs[_q.sub]) _subLbl=_ov.subs[_q.sub];
        }
        if(!_subLbl&&typeof _HH_WAFA_CAT!=='undefined'&&_mainCat===_HH_WAFA_CAT&&typeof _HH_WAFA_SUBS!=='undefined') _subs=_HH_WAFA_SUBS;
        if(!_subLbl&&_subs&&_subs[_q.sub]) _subLbl=_subs[_q.sub].label||'';
      }
    }catch(_sl){}
    G.sessionLog=G.sessionLog||[];
    G.sessionLog.push({
      n: G.sessionLog.length+1,
      q: _q.q||'', a: _q.a||'', diff: _q.diff||'',
      cat: (_q._cat||(_q.sub!==undefined?(G.selectedCats[0]||''):'')||G.selectedCats.join('+')),
      subCat: _subLbl,
      note: '',
      correct: _wi.length>0,
      winners: _wi.map(i=>G.teams[i]||('ف'+(i+1))),
      team: G.teams[G.turn]||('ف'+(G.turn+1)),
      ts: Math.round((Date.now()-G.startTime)/1000)
    });
  }catch(_se){}
  const diffKey=G.curKey.split('__')[1];
  const realD=DIFF_MAP[diffKey]||{pts:200};
  // الأساطير: نقاط متدرجة 600/800/1000 حسب المستوى
  const legendPtsMap = {easy:600, med:800, hard:1000};
  const pts = G.curIsLegend ? legendPtsMap[diffKey] : realD.pts;
  const armed=PU.armed;PU.armed=null;
  const finalPts=armed==='dagf'?pts*2:pts;
  // هل انتهى الوقت قبل الإجابة؟ (نستخدمه لتحويل النقاط إلى خصم)
  const timeExpired = G.timeExpired===true;
  document.querySelectorAll('.judge-btn').forEach(b=>b.disabled=true);
  if(winners==='none'||!winners||winners.length===0){
    playSound('wrong');
    if(navigator.vibrate) navigator.vibrate([100,50,100]);
    if(G.trapTarget!==null){
      G.scores[G.trapTarget]=(G.scores[G.trapTarget]||0)-pts;
      toast(' وقع «'+esc(G.teams[G.trapTarget])+'» في الفخ! خصم '+pts+' نقطة','error');
    }else if(timeExpired){
      toast('انتهى الوقت! لا أحد أجاب صح','warning');
    }else{
      toast('لا أحد أجاب صح!','error');
    }
  }else{
    const winArr=Array.isArray(winners)?winners:[parseInt(winners)];
    if(timeExpired){
      // ⏱ انتهى الوقت: الإجابة تحسب نقاطا عادية (بدون مضاعفات)
      winArr.forEach(wi=>{
        G.scores[wi]=(G.scores[wi]||0)+pts;
      });
      const names=winArr.map(i=>esc(G.teams[i])).join(' و ');
      toast(names+' أجابوا صح! +'+pts+' نقطة','success');
      playSound(G.curIsLegend ? 'legend_cheer' : 'cheer');
      if(navigator.vibrate) navigator.vibrate([50,30,80,30,120]);
    }else{
      // الوقت لم ينته · احتساب عادي
      winArr.forEach(wi=>{
        G.scores[wi]=(G.scores[wi]||0)+finalPts;
      });
      if(armed==='hafra'){
        G.scores.forEach((_,i)=>{ if(!winArr.includes(i))G.scores[i]-=pts; });
        //  تصفيق فقط
        playSound(G.curIsLegend?'legend_cheer':'cheer');
        toast('أجابوا صح! +'+finalPts+' · خصم '+pts+' من الباقين!','success');
      }else{
        const names=winArr.map(i=>esc(G.teams[i])).join(' و ');
        //  تصفيق فقط · بدون نغمات موسيقية
        playSound(G.curIsLegend ? 'legend_cheer' : 'cheer');
        if(navigator.vibrate) navigator.vibrate([50,30,80,30,120]);
        toast(''+names+' أجابوا صح! +'+finalPts+(armed==='dagf'?' مضاعف!':''),'success');
      }
    }
  }
  updateBoardUI();
  // تعطيل زري تأكيد/لا أحد وتفعيل "التالي" (بدون تحريك · نفس المكان)
  const confirmEl = document.querySelector('#judge-actions .j-btn-confirm');
  const noneEl    = document.querySelector('#judge-actions .j-btn-none');
  const nextEl    = document.getElementById('judge-next-btn');
  if(confirmEl){ confirmEl.disabled = true; confirmEl.style.opacity = '.35'; confirmEl.style.pointerEvents = 'none'; }
  if(noneEl){    noneEl.disabled    = true; noneEl.style.opacity    = '.35'; noneEl.style.pointerEvents    = 'none'; }
  if(nextEl)     nextEl.classList.add('enabled');
  // تلميح "Enter أو النقر خارجا"
  const hintEl = document.getElementById('judge-hint');
  if(hintEl) hintEl.style.display = 'block';
  // الحفاظ على سلوك handleModalOutsideClick
  document.getElementById('qm-actions').style.display='flex';
}

function closeModal(){
  document.getElementById('q-modal').classList.remove('open');
  G.trapTarget=null;G.trapBy=null;
  const _tb=document.getElementById('qm-trap-banner'); if(_tb){_tb.style.display='none';_tb.innerHTML='';}
  // إزالة تأثير انتهاء الوقت البصري (للسؤال التالي)
  const tWrap=document.querySelector('.timer-wrap');
  if(tWrap) tWrap.classList.remove('time-expired');
  G.timeExpired=false;
  updatePUDisplay();
  clearInterval(G.timer);
  const cell=document.getElementById('cell_'+G.curKey);
  if(cell)cell.classList.add('used');
  PU.armed=null;
  G.turn=(G.turn+1)%G.teams.length;
  updateBoardUI();checkDone();
}

// ═══════════════════════════════════════════════════════════════════
//  وضع الاختبار (Assessment Mode) · للبحث التربوي
// ═══════════════════════════════════════════════════════════════════
var _testModeActive = false;
var _testStudents = []; // [{code,name}]
var _testAnswers  = []; // [{studentIdx, qText, qAnswer, response, correct, ts}]
var _testCurrentQ = null;
var _testQueueIdx = 0;
var _testQueue    = [];

function hhStartTestMode(){
  const overlay=document.createElement('div');
  overlay.id='hh-test-setup'; overlay.style.cssText='position:fixed;inset:0;background:rgba(30,6,15,.7);z-index:999990;display:flex;align-items:center;justify-content:center;padding:16px;direction:rtl;';
  overlay.innerHTML='<div style="background:#fff;border:2px solid #B8924A;border-radius:20px;max-width:480px;width:100%;overflow:hidden;font-family:Cairo,Tajawal,sans-serif;">' +'<div style="background:linear-gradient(135deg,#1F4E79,#12304d);color:#fff;padding:13px 18px;font-weight:900;font-size:.95rem;display:flex;align-items:center;gap:8px;"> وضع الاختبار التربوي</div>' +'<div style="padding:16px 18px;">' +'<div style="font-size:.8rem;font-weight:800;color:#1F4E79;margin-bottom:5px;">الفئات (نفس اللعبة الحالية)</div>' +'<div style="font-size:.78rem;color:#555;background:#E9EEF8;border-radius:8px;padding:8px 12px;margin-bottom:12px;">'+((G.selectedCats||[]).join(' · ')||'اختر فئات أولاً')+'</div>' +'<div style="font-size:.8rem;font-weight:800;color:#1F4E79;margin-bottom:5px;">عدد الأسئلة لكل طالب</div>' +'<input id="hh-test-qcount" type="number" min="5" max="30" value="10" style="width:100%;border:1.5px solid #C9B37E;border-radius:10px;padding:8px 12px;font-family:Cairo;font-size:.9rem;margin-bottom:12px;box-sizing:border-box;">' +'<div style="font-size:.8rem;font-weight:800;color:#1F4E79;margin-bottom:5px;">أكواد الطلاب (سطر لكل طالب · كود أو رقم)</div>' +'<textarea id="hh-test-students" rows="5" style="width:100%;border:1.5px solid #C9B37E;border-radius:10px;padding:8px 12px;font-family:Cairo;font-size:.84rem;box-sizing:border-box;" placeholder="مثال: 1 أو أحمد"></textarea>' +'<div style="display:flex;gap:9px;margin-top:10px;">' +'<button onclick="hhInitTest()" style="background:linear-gradient(135deg,#1F4E79,#12304d);color:#fff;border:none;border-radius:11px;padding:10px 22px;font-weight:900;font-size:.84rem;cursor:pointer;flex:1;">ابدأ الاختبار</button>' +'<button onclick=\"hhCloseTestSetup()\" style="background:#F3F0F1;color:#666;border:none;border-radius:11px;padding:10px 16px;font-weight:900;font-size:.84rem;cursor:pointer;">إلغاء</button>' +'</div></div></div>';
  document.body.appendChild(overlay);
}

function hhInitTest(){
  const qcount=parseInt((document.getElementById('hh-test-qcount')||{}).value||10);
  const raw=((document.getElementById('hh-test-students')||{}).value||'').split('\n').map(s=>s.trim()).filter(Boolean);
  if(!raw.length){ toast('أدخل أكواد الطلاب','warn'); return; }
  if(!(G.selectedCats||[]).length){ toast('ابدأ لعبة أولاً لاختيار الفئات','warn'); return; }
  _testStudents=raw.map((s,i)=>({code:s,name:s,idx:i}));
  _testAnswers=[]; _testQueueIdx=0; _testModeActive=true;
  // بناء طابور الأسئلة: qcount لكل طالب، مختلطة عشوائياً من الفئات المختارة
  const pool=[];
  (G.selectedCats||[]).forEach(cat=>{ (QDB[cat]||[]).forEach(q=>pool.push(Object.assign({},q,{_cat:cat}))); });
  _testQueue=[];
  _testStudents.forEach(st=>{
    const sh=pool.slice().sort(()=>Math.random()-.5).slice(0,qcount);
    sh.forEach(q=>_testQueue.push({student:st,q}));
  });
  document.getElementById('hh-test-setup').remove();
  hhNextTestQ();
}

function hhNextTestQ(){
  if(_testQueueIdx>=_testQueue.length){ hhEndTest(); return; }
  const item=_testQueue[_testQueueIdx]; _testCurrentQ=item;
  const st=item.student; const q=item.q;
  const total=_testStudents.length*(_testQueue.length/_testStudents.length);
  const ov=document.createElement('div'); ov.id='hh-test-q';
  ov.style.cssText='position:fixed;inset:0;background:#fff;z-index:999985;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:24px;direction:rtl;font-family:Cairo,Tajawal,sans-serif;';
  const pct=Math.round(_testQueueIdx/(_testQueue.length||1)*100);
  ov.innerHTML='<div style="max-width:540px;width:100%;">' +'<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;">' +'<span style="background:#1F4E79;color:#fff;border-radius:8px;padding:4px 12px;font-weight:900;font-size:.78rem;">طالب: '+esc(st.name)+'</span>' +'<span style="font-size:.76rem;color:#999;">'+(_testQueueIdx+1)+' / '+_testQueue.length+'</span>' +'</div>' +'<div style="background:#e9eef8;border-radius:99px;height:8px;margin-bottom:18px;"><div style="background:#1F4E79;border-radius:99px;height:8px;width:'+pct+'%"></div></div>' +'<div style="background:#F7FBFF;border:2px solid #1F4E79;border-radius:16px;padding:22px;margin-bottom:16px;">' +'<div style="font-size:.7rem;color:#8A6D2E;font-weight:800;margin-bottom:8px;">'+esc(q._cat||'')+' •  '+({easy:'سهل',med:'متوسط',hard:'صعب'}[q.diff]||q.diff||'')+'</div>' +'<div style="font-size:1.15rem;font-weight:900;color:#1F4E79;line-height:1.7;">'+esc(q.q||'')+'</div>' +(q.img?'<img src="'+q.img+'" style="max-height:140px;margin-top:10px;border-radius:10px;display:block;">':'')
    +'</div>' +'<div style="display:flex;gap:9px;flex-wrap:wrap;">' +'<button onclick="hhRecordTest(true)" style="flex:1;background:linear-gradient(135deg,#3D6B53,#274a38);color:#fff;border:none;border-radius:11px;padding:12px;font-weight:900;font-size:.9rem;cursor:pointer;"> صحيحة</button>' +'<button onclick="hhRecordTest(false)" style="flex:1;background:linear-gradient(135deg,#8A1538,#5E0E26);color:#fff;border:none;border-radius:11px;padding:12px;font-weight:900;font-size:.9rem;cursor:pointer;"> خاطئة</button>' +'</div>' +'<button onclick="hhRevealTestAnswer()" id="hh-test-show-ans" style="width:100%;margin-top:9px;background:#E9EEF8;color:#1F4E79;border:1.5px solid #1F4E79;border-radius:11px;padding:9px;font-weight:900;font-size:.82rem;cursor:pointer;"> اعرض الجواب</button>' +'<div id="hh-test-ans-box" style="display:none;background:#EBF2EE;border:2px solid #3D6B53;border-radius:10px;padding:11px;margin-top:8px;font-weight:900;color:#3D6B53;text-align:center;font-size:.95rem;">'+esc(q.a||'')+'</div>' +'</div>';
  document.body.appendChild(ov);
}
function hhRevealTestAnswer(){
  const ab=document.getElementById('hh-test-ans-box'); if(ab) ab.style.display='block';
  const sb=document.getElementById('hh-test-show-ans'); if(sb) sb.style.display='none';
}
function hhRecordTest(correct){
  const item=_testCurrentQ;
  _testAnswers.push({ student:item.student.name, q:item.q.q, a:item.q.a, correct, cat:item.q._cat||'', diff:item.q.diff||'' });
  _testQueueIdx++;
  const old=document.getElementById('hh-test-q'); if(old) old.remove();
  hhNextTestQ();
}
function hhEndTest(){
  _testModeActive=false;
  hhShowTestReport();
}
function hhShowTestReport(){
  hhShowSessionReport(_testAnswers, true);
}


