//  تقرير الجلسة التربوية · قابل للطباعة والتصدير
// ═══════════════════════════════════════════════════════════════════
function hhOfferSessionReport(){
  try{
    var old=document.getElementById('hh-sr-offer'); if(old) old.remove();
    var bar=document.createElement('div'); bar.id='hh-sr-offer';
    bar.style.cssText='position:fixed;bottom:96px;left:50%;transform:translateX(-50%);z-index:999979;background:linear-gradient(175deg,#4A0B1E,#5E0E26);border:1.5px solid #B8924A;border-radius:14px;padding:10px 14px;display:flex;align-items:center;gap:10px;box-shadow:0 10px 30px rgba(30,6,15,.4);direction:rtl;';
    bar.innerHTML='<span style="color:#F5E6C4;font-weight:800;font-size:.85rem;">انتهت الجلسة · تقرير الأداء جاهز</span>'
      +'<button onclick="hhCloseOfferSR();hhShowSessionReport(null,false)" style="background:linear-gradient(135deg,#EAD9B0,#B8924A);color:#3D0918;border:1px solid #FDF3DD;border-radius:9px;padding:7px 14px;font-weight:800;font-size:.8rem;cursor:pointer;">عرض التقرير</button>'
      +'<button onclick="hhCloseOfferSR()" aria-label="إخفاء" style="background:rgba(255,255,255,.1);color:#EAD9B0;border:1px solid rgba(212,188,133,.5);border-radius:9px;width:30px;height:30px;font-weight:800;cursor:pointer;">✕</button>';
    document.body.appendChild(bar);
    setTimeout(hhCloseOfferSR, 12000);
  }catch(e){}
}
function hhCloseOfferSR(){ var b=document.getElementById('hh-sr-offer'); if(b) b.remove(); }
function hhCloseSessionReport(){
  var e=document.getElementById('hh-session-report');
  if(e) e.remove();
}
function hhShowSessionReport(testData, isTest){
  const log = isTest ? testData : (G.sessionLog||[]);
  if(!log || !log.length){ toast('لا توجد بيانات جلسة بعد','info'); return; }
  const ov=document.createElement('div'); ov.id='hh-session-report';
  ov.style.cssText='position:fixed;inset:0;background:rgba(30,6,15,.6);z-index:999980;display:flex;align-items:flex-start;justify-content:center;padding:16px;overflow-y:auto;direction:rtl;';
  ov.addEventListener('click', function(e){ if(e.target===ov) hhCloseSessionReport(); });
  // إحصاءات
  const total=log.length;
  const correct=log.filter(r=>r.correct).length;
  const pct=Math.round(correct/total*100);
  // تجميع حسب الفئة
  const byCat={};
  log.forEach(r=>{
    const c=r.cat||r._cat||'متنوع';
    if(!byCat[c]) byCat[c]={total:0,correct:0};
    byCat[c].total++;
    if(r.correct) byCat[c].correct++;
  });
  // تجميع حسب الطالب (في وضع الاختبار)
  let studentTable='';
  if(isTest){
    const bySt={};
    log.forEach(r=>{ if(!bySt[r.student]) bySt[r.student]={total:0,correct:0};
      bySt[r.student].total++; if(r.correct) bySt[r.student].correct++; });
    studentTable='<div style="margin-top:16px;">' +'<div style="font-weight:900;font-size:.88rem;color:#1F4E79;margin-bottom:8px;"> نتائج الطلاب</div>' +'<table style="width:100%;border-collapse:collapse;font-size:.8rem;">' +'<thead><tr style="background:#1F4E79;color:#fff;">' +'<th style="padding:7px 10px;text-align:right;">الطالب</th>' +'<th style="padding:7px;text-align:center;">الصحيح</th>' +'<th style="padding:7px;text-align:center;">الإجمالي</th>' +'<th style="padding:7px;text-align:center;">النسبة</th></tr></thead><tbody>' +Object.entries(bySt).map(([st,d],i)=>{
        const p=Math.round(d.correct/d.total*100);
        const bg=i%2?'#E9EEF8':'#fff';
        const cl=p>=70?'#3D6B53':p>=50?'#b5801f':'#c0392b';
        return '<tr style="background:'+bg+';">' +'<td style="padding:7px 10px;font-weight:800;">'+esc(st)+'</td>' +'<td style="padding:7px;text-align:center;color:#3D6B53;font-weight:900;">'+d.correct+'</td>' +'<td style="padding:7px;text-align:center;">'+d.total+'</td>' +'<td style="padding:7px;text-align:center;font-weight:900;color:'+cl+';">'+p+'%</td></tr>';
      }).join('')
      +'</tbody></table></div>';
  }
  // جدول الأسئلة
  const _sid = G.startTime || Date.now();
  const qRows=log.map((r,i)=>{
    const bg=i%2?'#F7FBFF':'#fff';
    const icon=r.correct?'':'';
    const winner=r.winners&&r.winners.length?r.winners.join('/'):(r.student||r.team||'·');
    return '<tr style="background:'+bg+';">' +'<td style="padding:6px 8px;text-align:center;font-weight:900;">'+icon+'</td>' +'<td style="padding:6px 8px;font-weight:700;max-width:190px;">'+esc(r.q||'').slice(0,55)+(r.q&&r.q.length>55?'…':'')+'</td>' +'<td style="padding:6px 8px;color:#3D6B53;font-weight:800;">'+esc(r.a||'').slice(0,25)+'</td>' +'<td style="padding:6px 8px;text-align:center;font-size:.7rem;color:#8A6D2E;">' +esc(r.cat||r._cat||'')
        +(r.subCat?'<br><span style="color:#1F4E79;font-size:.65rem;font-weight:900;">'+esc(r.subCat)+'</span>':'')+'</td>' +'<td style="padding:6px 8px;text-align:center;font-size:.7rem;">'+esc(winner)+'</td>' +'<td style="padding:4px 6px;min-width:110px;"><input type="text" id="hh-note-'+_sid+'-'+i+'" value="'+esc(r.note||'')+'" placeholder="ملاحظة..." onchange="hhSaveNote(this,'+i+','+(!isTest)+')" style="width:100%;border:1px solid #E3D9C6;border-radius:6px;padding:4px 6px;font-family:Cairo,Tajawal,sans-serif;font-size:.72rem;"></td>' +'</tr>';
  }).join('');
  const catRows=Object.entries(byCat).map(([c,d],i)=>{
    const p=Math.round(d.correct/d.total*100);
    const cl=p>=70?'#3D6B53':p>=50?'#b5801f':'#c0392b';
    return '<tr style="background:'+(i%2?'#E9EEF8':'#fff')+';">' +'<td style="padding:7px 10px;font-weight:800;">'+esc(c)+'</td>' +'<td style="padding:7px;text-align:center;color:#3D6B53;font-weight:900;">'+d.correct+'</td>' +'<td style="padding:7px;text-align:center;">'+d.total+'</td>' +'<td style="padding:7px;text-align:center;font-weight:900;color:'+cl+';">'+p+'%</td></tr>';
  }).join('');
  const dateStr=new Date().toLocaleDateString('ar-QA',{weekday:'short',year:'numeric',month:'short',day:'numeric'});
  const pctCl=pct>=70?'#3D6B53':pct>=50?'#b5801f':'#c0392b';
  ov.innerHTML='<div id="hh-report-inner" style="background:#fff;border:2px solid #B8924A;border-radius:20px;max-width:680px;width:100%;overflow:hidden;margin-bottom:24px;">' +'<div style="background:linear-gradient(135deg,#1F4E79,#12304d);color:#fff;padding:14px 18px;display:flex;justify-content:space-between;align-items:center;">' +'<div style="font-weight:900;font-size:.95rem;"> '+(isTest?'تقرير الاختبار التربوي':'تقرير جلسة المُلهِم')+'</div>' +'<div style="font-size:.72rem;opacity:.8;">'+dateStr+'</div></div>' +'<div style="padding:16px 18px;">' +'<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:16px;">' +'<div style="background:#E9EEF8;border-radius:12px;padding:10px;text-align:center;">' +'<div style="font-size:1.5rem;font-weight:900;color:#1F4E79;">'+total+'</div>' +'<div style="font-size:.72rem;color:#555;font-weight:800;">أسئلة</div></div>' +'<div style="background:#EBF2EE;border-radius:12px;padding:10px;text-align:center;">' +'<div style="font-size:1.5rem;font-weight:900;color:#3D6B53;">'+correct+'</div>' +'<div style="font-size:.72rem;color:#555;font-weight:800;">صحيحة</div></div>' +'<div style="background:'+(pct>=70?'#EBF2EE':pct>=50?'#FDF3DD':'#F7ECEF')+';border-radius:12px;padding:10px;text-align:center;">' +'<div style="font-size:1.5rem;font-weight:900;color:'+pctCl+';">'+pct+'%</div>' +'<div style="font-size:.72rem;color:#555;font-weight:800;">النسبة</div></div></div>' +'<div style="font-weight:900;font-size:.88rem;color:#1F4E79;margin-bottom:8px;"> الأداء حسب الفئة</div>' +'<table style="width:100%;border-collapse:collapse;font-size:.8rem;margin-bottom:14px;">' +'<thead><tr style="background:#1F4E79;color:#fff;"><th style="padding:7px 10px;text-align:right;">الفئة</th><th style="padding:7px;text-align:center;">صحيح</th><th style="padding:7px;text-align:center;">إجمالي</th><th style="padding:7px;text-align:center;">نسبة</th></tr></thead>' +'<tbody>'+catRows+'</tbody></table>' +studentTable
    +'<div style="font-weight:900;font-size:.88rem;color:#1F4E79;margin:14px 0 8px;"> تفاصيل الأسئلة</div>' +'<div style="overflow-x:auto;"><table style="width:100%;border-collapse:collapse;font-size:.78rem;">' +'<thead><tr style="background:#E9EEF8;color:#1F4E79;font-weight:900;">' +'<th style="padding:6px 8px;text-align:center;">النتيجة</th>' +'<th style="padding:6px 8px;text-align:right;">السؤال</th>' +'<th style="padding:6px 8px;text-align:right;">الجواب</th>' +'<th style="padding:6px 8px;text-align:center;">الفئة / الفئة الفرعية</th>' +'<th style="padding:6px 8px;text-align:center;">'+(isTest?'الطالب':'الفريق')+'</th>' +'<th style="padding:6px 8px;text-align:center;">ملاحظة المعلم</th></tr></thead>' +'<tbody>'+qRows+'</tbody></table></div>' +'<div style="display:flex;gap:9px;margin-top:14px;flex-wrap:wrap;">' +'<button onclick="hhShowInsight(null)" style="background:linear-gradient(135deg,#5E0E26,#3D0918);color:#fff;border:none;border-radius:11px;padding:10px 20px;font-weight:900;font-size:.84rem;cursor:pointer;box-shadow:0 4px 12px rgba(94,14,38,.25);"> التقرير التربوي الذكي</button>' +'<button onclick="hhPrintReport()" style="background:linear-gradient(135deg,#1F4E79,#12304d);color:#fff;border:none;border-radius:11px;padding:10px 20px;font-weight:900;font-size:.84rem;cursor:pointer;"> طباعة</button>' +'<button onclick="hhExportCSV('+(isTest?'true':'false')+')" style="background:#EBF2EE;color:#3D6B53;border:1.5px solid #3D6B53;border-radius:11px;padding:10px 20px;font-weight:900;font-size:.84rem;cursor:pointer;"> تصدير CSV</button>' +(!isTest?'<button onclick=\"hhSaveSessionDialog()\" style=\"background:#E9EEF8;color:#1F4E79;border:1.5px solid #1F4E79;border-radius:11px;padding:10px 16px;font-weight:900;font-size:.84rem;cursor:pointer;\"> احفظ للبحث</button>':'')
    +(!isTest?'<button onclick=\"hhShowAnalytics()\" style=\"background:#F5E9EE;color:#8A1538;border:1.5px solid #8A1538;border-radius:11px;padding:10px 16px;font-weight:900;font-size:.84rem;cursor:pointer;\"> التحليلات التراكمية</button>':'')
    +'<button onclick="hhCloseSessionReport()" style="background:#F3F0F1;color:#666;border:none;border-radius:11px;padding:10px 16px;font-weight:900;font-size:.84rem;cursor:pointer;">إغلاق</button>' +'</div></div></div>';
  document.body.appendChild(ov);
}
function hhPrintReport(){
  const html=document.getElementById('hh-report-inner');
  if(!html) return;
  const w=window.open('','_blank');
  w.document.write('<html dir="rtl"><head><meta charset="utf-8"><title>تقرير المُلهِم</title>' +'<style>body{font-family:Cairo,Tajawal,Arial,sans-serif;padding:20px;direction:rtl;}table{border-collapse:collapse;width:100%;}th,td{border:1px solid #ddd;padding:6px 10px;}th{background:#1F4E79;color:#fff;}@media print{button{display:none}}</style></head><body>');
  w.document.write(html.innerHTML);
  w.document.write('<script>window.print();setTimeout(()=>window.close(),1000);</script></body></html>');
  w.document.close();
}
// ═══ حفظ الملاحظة ═══
function hhSaveNote(input, idx, isGame){
  try{
    if(isGame && G.sessionLog && G.sessionLog[idx]) G.sessionLog[idx].note=input.value;
    else if(!isGame && window._testAnswers && window._testAnswers[idx]) window._testAnswers[idx].note=input.value;
    var key='hh_session_notes_'+(G.startTime||0);
    var notes=JSON.parse(localStorage.getItem(key)||'{}');
    notes[idx]=input.value; localStorage.setItem(key,JSON.stringify(notes));
  }catch(e){}
}

// ═══ التحليلات التراكمية ═══
var _savedSessions=[];
try{ var _ss=localStorage.getItem('hh_saved_sessions'); if(_ss) _savedSessions=JSON.parse(_ss)||[]; }catch(e){}

function hhSaveCurrentSession(phase, groupName){
  if(!G.sessionLog||!G.sessionLog.length){ if(typeof toast==='function') toast('لا توجد بيانات جلسة للحفظ','warn'); return; }
  var snap={ id:G.startTime||Date.now(), date:new Date().toLocaleDateString('ar-QA',{month:'short',day:'numeric'}),
    iso:new Date().toISOString().slice(0,10),
    gameName:G.gameName||'جلسة', cats:(G.selectedCats||[]).join(' · '),
    phase: phase||'تجريبي', group: groupName||'المجموعة التجريبية',
    log:JSON.parse(JSON.stringify(G.sessionLog)) };
  _savedSessions.push(snap);
  try{ localStorage.setItem('hh_saved_sessions',JSON.stringify(_savedSessions.slice(-30))); }catch(e){}
  if(typeof toast==='function') toast(' حُفظت الجلسة ('+snap.gameName+') للمقارنة','success');
}

function hhShowCompare(){
  if(_savedSessions.length<2){ if(typeof toast==='function') toast('احفظ جلستين على الأقل للمقارنة','warn'); return; }
  var ov=document.createElement('div'); ov.id='hh-compare-overlay';
  ov.style.cssText='position:fixed;inset:0;background:rgba(30,6,15,.65);z-index:999979;display:flex;align-items:flex-start;justify-content:center;padding:16px;overflow-y:auto;direction:rtl;';
  var sessions=_savedSessions.slice(-4);
  var rows=sessions.map(function(sess){
    var tot=sess.log.length; var cor=sess.log.filter(function(r){return r.correct;}).length;
    var pct=tot?Math.round(cor/tot*100):0;
    var cl=pct>=70?'#3D6B53':pct>=50?'#b5801f':'#c0392b';
    var byCat={};
    sess.log.forEach(function(r){ var c=r.cat||'متنوع'; if(!byCat[c])byCat[c]={t:0,c:0}; byCat[c].t++; if(r.correct)byCat[c].c++; });
    var catBars=Object.entries(byCat).map(function(e){
      var c=e[0]; var d=e[1]; var p=Math.round(d.c/d.t*100);
      var bc=p>=70?'#3D6B53':p>=50?'#b5801f':'#c0392b';
      return '<div style="margin-bottom:4px;"><div style="display:flex;justify-content:space-between;font-size:.7rem;font-weight:800;"><span>'+esc(c)+'</span><span style="color:'+bc+';">'+p+'%</span></div>' +'<div style="background:#eee;border-radius:4px;height:7px;"><div style="background:'+bc+';border-radius:4px;height:7px;width:'+p+'%;"></div></div></div>';
    }).join('');
    return '<div style="background:#fff;border:2px solid #B8924A;border-radius:14px;padding:14px;flex:1;min-width:180px;">' +'<div style="font-weight:900;font-size:.8rem;color:#1F4E79;margin-bottom:3px;">'+esc(sess.gameName)+'</div>' +'<div style="font-size:.7rem;color:#999;margin-bottom:10px;">'+esc(sess.date)+' · '+esc(sess.cats)+'</div>' +'<div style="display:flex;gap:8px;margin-bottom:12px;">' +'<div style="text-align:center;flex:1;background:#E9EEF8;border-radius:10px;padding:8px;">' +'<div style="font-size:1.3rem;font-weight:900;color:'+cl+';">'+pct+'%</div>' +'<div style="font-size:.65rem;color:#555;">النسبة</div></div>' +'<div style="text-align:center;flex:1;background:#EBF2EE;border-radius:10px;padding:8px;">' +'<div style="font-size:1.3rem;font-weight:900;color:#3D6B53;">'+cor+'/'+tot+'</div>' +'<div style="font-size:.65rem;color:#555;">الصحيح</div></div></div>' +catBars+'</div>';
  }).join('');
  ov.innerHTML='<div style="background:#fff;border:2px solid #B8924A;border-radius:20px;max-width:860px;width:100%;overflow:hidden;">' +'<div style="background:linear-gradient(135deg,#1F4E79,#12304d);color:#fff;padding:14px 18px;display:flex;justify-content:space-between;align-items:center;">' +'<div style="font-weight:900;font-size:.95rem;"> التحليلات التراكمية ('+sessions.length+')</div>' +'<button onclick="document.getElementById(&quot;hh-compare-overlay&quot;).remove()" style="background:none;border:none;color:#fff;font-size:1.1rem;cursor:pointer;">✕</button></div>' +'<div style="padding:16px 18px;display:flex;gap:12px;flex-wrap:wrap;">'+rows+'</div>' +'<div style="padding:0 18px 16px;display:flex;gap:9px;">' +'<button onclick="hhExportCompareCSV()" style="background:#EBF2EE;color:#3D6B53;border:1.5px solid #3D6B53;border-radius:11px;padding:9px 18px;font-weight:900;font-size:.82rem;cursor:pointer;"> تصدير مقارنة CSV</button>' +'<button onclick="hhClearSessions()" style="background:#F3F0F1;color:#c0392b;border:1.5px solid #e0c0c0;border-radius:11px;padding:9px 16px;font-weight:900;font-size:.82rem;cursor:pointer;"> مسح</button>' +'</div></div>';
  document.body.appendChild(ov);
}
function hhClearSessions(){_savedSessions=[];try{localStorage.removeItem('hh_saved_sessions');}catch(e){}var ov=document.getElementById('hh-compare-overlay');if(ov)ov.remove();if(typeof toast==='function')toast('مُسحت الجلسات المحفوظة','info');}
function hhExportCompareCSV(){
  var rows=[['الجلسة','التاريخ','الفئات','عدد الأسئلة','الصحيح','النسبة%']];
  _savedSessions.slice(-4).forEach(function(sess){
    var tot=sess.log.length; var cor=sess.log.filter(function(r){return r.correct;}).length;
    rows.push([sess.gameName,sess.date,sess.cats,tot,cor,tot?Math.round(cor/tot*100):0]);
  });
  var csv=rows.map(function(r){return r.map(function(c){return '"'+String(c).replace(/"/g,'""')+'"';}).join(',');}).join('\n');
  var bl=new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'});
  var a=document.createElement('a'); a.href=URL.createObjectURL(bl);
  a.download='compare_'+new Date().toISOString().slice(0,10)+'.csv'; a.click();
}

// ═══════════════════════════════════════════════════════════════════
//  لوحة التحليلات التراكمية · تطور الأداء عبر الجلسات (للبحث التربوي)
// ═══════════════════════════════════════════════════════════════════
function hhSaveSessionDialog(){
  if(!G.sessionLog||!G.sessionLog.length){ if(typeof toast==='function') toast('لا توجد بيانات جلسة','warn'); return; }
  var old=document.getElementById('hh-savesess'); if(old) old.remove();
  var ov=document.createElement('div'); ov.id='hh-savesess';
  ov.style.cssText='position:fixed;inset:0;background:rgba(30,6,15,.65);z-index:999992;display:flex;align-items:center;justify-content:center;padding:16px;direction:rtl;';
  ov.innerHTML='<div style="background:#fff;border:2px solid #B8924A;border-radius:18px;max-width:420px;width:100%;overflow:hidden;font-family:Cairo,Tajawal,sans-serif;">' +'<div style="background:linear-gradient(135deg,#1F4E79,#12304d);color:#fff;padding:13px 18px;font-weight:900;font-size:.92rem;"> حفظ الجلسة للتحليل البحثي</div>' +'<div style="padding:16px 18px;">' +'<div style="font-size:.78rem;font-weight:800;color:#1F4E79;margin-bottom:5px;">مرحلة البحث</div>' +'<select id="ss-phase" style="width:100%;border:1.5px solid #C9B37E;border-radius:10px;padding:9px 12px;font-family:Cairo;font-size:.85rem;margin-bottom:12px;box-sizing:border-box;">' +'<option value="قبلي">اختبار قبلي (قبل التدخل)</option>' +'<option value="تجريبي" selected>جلسة تجريبية (أثناء التدخل)</option>' +'<option value="بعدي">اختبار بعدي (بعد التدخل)</option>' +'<option value="تذكّر">اختبار تذكّر (بعد أسبوعين)</option>' +'</select>' +'<div style="font-size:.78rem;font-weight:800;color:#1F4E79;margin-bottom:5px;">المجموعة</div>' +'<select id="ss-group" style="width:100%;border:1.5px solid #C9B37E;border-radius:10px;padding:9px 12px;font-family:Cairo;font-size:.85rem;margin-bottom:14px;box-sizing:border-box;">' +'<option value="المجموعة التجريبية" selected>المجموعة التجريبية</option>' +'<option value="المجموعة الضابطة">المجموعة الضابطة</option>' +'</select>' +'<div style="display:flex;gap:9px;">' +'<button onclick="hhConfirmSaveSession()" style="flex:1;background:linear-gradient(135deg,#1F4E79,#12304d);color:#fff;border:none;border-radius:11px;padding:10px;font-weight:900;font-size:.85rem;cursor:pointer;">حفظ</button>' +'<button onclick="hhCloseSaveDialog()" style="background:#F3F0F1;color:#666;border:none;border-radius:11px;padding:10px 16px;font-weight:900;font-size:.85rem;cursor:pointer;">إلغاء</button>' +'</div></div></div>';
  document.body.appendChild(ov);
}
function hhCloseSaveDialog(){ var e=document.getElementById('hh-savesess'); if(e) e.remove(); }
function hhConfirmSaveSession(){
  var ph=(document.getElementById('ss-phase')||{}).value||'تجريبي';
  var gr=(document.getElementById('ss-group')||{}).value||'المجموعة التجريبية';
  hhSaveCurrentSession(ph, gr);
  hhCloseSaveDialog();
}
function hhShowAnalytics(){
  if(!_savedSessions.length){ if(typeof toast==='function') toast('لا جلسات محفوظة بعد · احفظ جلسة أولاً','warn'); return; }
  var old=document.getElementById('hh-analytics'); if(old) old.remove();
  var ov=document.createElement('div'); ov.id='hh-analytics';
  ov.style.cssText='position:fixed;inset:0;background:rgba(30,6,15,.65);z-index:999978;display:flex;align-items:flex-start;justify-content:center;padding:16px;overflow-y:auto;direction:rtl;';
  var S=_savedSessions.slice();
  var totQ=0, totC=0;
  S.forEach(function(x){ totQ+=x.log.length; totC+=x.log.filter(function(r){return r.correct;}).length; });
  var overall=totQ?Math.round(totC/totQ*100):0;
  var pts=S.map(function(x,i){
    var t=x.log.length, c=x.log.filter(function(r){return r.correct;}).length;
    return {i:i+1, pct:t?Math.round(c/t*100):0, name:x.gameName, phase:x.phase||'·'};
  });
  var W=Math.max(280, pts.length*70), H=150;
  var poly=pts.map(function(p,i){
    var x=(pts.length>1)?(i/(pts.length-1))*(W-40)+20:W/2;
    var y=H-20-(p.pct/100)*(H-45);
    return x.toFixed(1)+','+y.toFixed(1);
  }).join(' ');
  var dots=pts.map(function(p,i){
    var x=(pts.length>1)?(i/(pts.length-1))*(W-40)+20:W/2;
    var y=H-20-(p.pct/100)*(H-45);
    var col=p.phase==='قبلي'?'#c0392b':p.phase==='بعدي'?'#3D6B53':p.phase==='تذكّر'?'#1F4E79':'#B8924A';
    return '<circle cx="'+x.toFixed(1)+'" cy="'+y.toFixed(1)+'" r="5" fill="'+col+'" stroke="#fff" stroke-width="2"/>' +'<text x="'+x.toFixed(1)+'" y="'+(y-11).toFixed(1)+'" text-anchor="middle" font-size="10" font-weight="900" fill="'+col+'" font-family="Cairo">'+p.pct+'%</text>';
  }).join('');
  var chart='<svg viewBox="0 0 '+W+' '+H+'" style="width:100%;height:auto;max-height:190px;">' +'<line x1="20" y1="'+(H-20)+'" x2="'+(W-20)+'" y2="'+(H-20)+'" stroke="#ddd" stroke-width="1.5"/>' +'<line x1="20" y1="20" x2="20" y2="'+(H-20)+'" stroke="#ddd" stroke-width="1.5"/>' +'<line x1="20" y1="'+(H-20-0.7*(H-45)).toFixed(1)+'" x2="'+(W-20)+'" y2="'+(H-20-0.7*(H-45)).toFixed(1)+'" stroke="#3D6B53" stroke-dasharray="4 4" stroke-width="1" opacity=".5"/>' +'<polyline points="'+poly+'" fill="none" stroke="#B8924A" stroke-width="2.5" stroke-linejoin="round"/>' + dots + '</svg>';
  var byPhase={};
  S.forEach(function(x){
    var ph=x.phase||'تجريبي';
    if(!byPhase[ph]) byPhase[ph]={t:0,c:0,n:0};
    byPhase[ph].t+=x.log.length;
    byPhase[ph].c+=x.log.filter(function(r){return r.correct;}).length;
    byPhase[ph].n++;
  });
  var phaseCards=['قبلي','تجريبي','بعدي','تذكّر'].filter(function(p){return byPhase[p];}).map(function(p){
    var d=byPhase[p]; var pc=d.t?Math.round(d.c/d.t*100):0;
    var col=p==='قبلي'?'#c0392b':p==='بعدي'?'#3D6B53':p==='تذكّر'?'#1F4E79':'#B8924A';
    var bg=p==='قبلي'?'#F7ECEF':p==='بعدي'?'#EBF2EE':p==='تذكّر'?'#E9EEF8':'#FDF3DD';
    return '<div style="background:'+bg+';border:1.5px solid '+col+';border-radius:12px;padding:11px;text-align:center;flex:1;min-width:98px;">' +'<div style="font-size:1.5rem;font-weight:900;color:'+col+';">'+pc+'%</div>' +'<div style="font-size:.72rem;font-weight:900;color:'+col+';">'+esc(p)+'</div>' +'<div style="font-size:.64rem;color:#888;margin-top:2px;">'+d.n+' جلسة · '+d.t+' سؤال</div></div>';
  }).join('');
  var gainBox='';
  if(byPhase['قبلي'] && byPhase['بعدي']){
    var pre=Math.round(byPhase['قبلي'].c/byPhase['قبلي'].t*100);
    var post=Math.round(byPhase['بعدي'].c/byPhase['بعدي'].t*100);
    var gain=post-pre;
    var gcol=gain>0?'#3D6B53':gain<0?'#c0392b':'#B8924A';
    gainBox='<div style="background:'+(gain>0?'#EBF2EE':'#F7ECEF')+';border:2px solid '+gcol+';border-radius:14px;padding:13px;margin:12px 0;text-align:center;">' +'<div style="font-size:.78rem;font-weight:800;color:#555;">أثر التدخل (البعدي − القبلي)</div>' +'<div style="font-size:2rem;font-weight:900;color:'+gcol+';line-height:1.2;">'+(gain>0?'+':'')+gain+'%</div>' +'<div style="font-size:.72rem;color:#666;">من '+pre+'% إلى '+post+'%</div></div>';
  }
  var byGroup={};
  S.forEach(function(x){
    var g=x.group||'·';
    if(!byGroup[g]) byGroup[g]={t:0,c:0,n:0};
    byGroup[g].t+=x.log.length; byGroup[g].c+=x.log.filter(function(r){return r.correct;}).length; byGroup[g].n++;
  });
  var groupRows=Object.keys(byGroup).map(function(g,i){
    var d=byGroup[g]; var pc=d.t?Math.round(d.c/d.t*100):0;
    var col=pc>=70?'#3D6B53':pc>=50?'#b5801f':'#c0392b';
    return '<tr style="background:'+(i%2?'#E9EEF8':'#fff')+';">' +'<td style="padding:7px 10px;font-weight:800;">'+esc(g)+'</td>' +'<td style="padding:7px;text-align:center;">'+d.n+'</td>' +'<td style="padding:7px;text-align:center;">'+d.t+'</td>' +'<td style="padding:7px;text-align:center;font-weight:900;color:'+col+';">'+pc+'%</td></tr>';
  }).join('');
  var catAgg={};
  S.forEach(function(x){ x.log.forEach(function(r){
    var c=r.cat||'متنوع'; if(!catAgg[c]) catAgg[c]={t:0,c:0};
    catAgg[c].t++; if(r.correct) catAgg[c].c++;
  }); });
  var weakest=Object.keys(catAgg).map(function(c){
    return {c:c, pct:Math.round(catAgg[c].c/catAgg[c].t*100), t:catAgg[c].t};
  }).filter(function(x){return x.t>=2;}).sort(function(a,b){return a.pct-b.pct;});
  var weakRows=weakest.slice(0,6).map(function(x){
    var col=x.pct>=70?'#3D6B53':x.pct>=50?'#b5801f':'#c0392b';
    return '<div style="margin-bottom:6px;">' +'<div style="display:flex;justify-content:space-between;font-size:.74rem;font-weight:800;margin-bottom:2px;">' +'<span>'+esc(x.c)+' <span style="color:#aaa;font-weight:700;">('+x.t+')</span></span><span style="color:'+col+';">'+x.pct+'%</span></div>' +'<div style="background:#eee;border-radius:5px;height:8px;"><div style="background:'+col+';border-radius:5px;height:8px;width:'+x.pct+'%;"></div></div></div>';
  }).join('');
  var sessRows=S.map(function(x,i){
    var t=x.log.length, c=x.log.filter(function(r){return r.correct;}).length;
    var pc=t?Math.round(c/t*100):0;
    var col=pc>=70?'#3D6B53':pc>=50?'#b5801f':'#c0392b';
    var phCol=x.phase==='قبلي'?'#c0392b':x.phase==='بعدي'?'#3D6B53':x.phase==='تذكّر'?'#1F4E79':'#B8924A';
    return '<tr style="background:'+(i%2?'#F7FBFF':'#fff')+';">' +'<td style="padding:6px 8px;text-align:center;font-weight:900;color:#999;">'+(i+1)+'</td>' +'<td style="padding:6px 8px;font-weight:800;">'+esc(x.gameName)+'</td>' +'<td style="padding:6px 8px;text-align:center;"><span style="background:'+phCol+';color:#fff;border-radius:7px;padding:1px 8px;font-size:.66rem;font-weight:900;">'+esc(x.phase||'·')+'</span></td>' +'<td style="padding:6px 8px;text-align:center;font-size:.7rem;">'+esc(x.group||'·')+'</td>' +'<td style="padding:6px 8px;text-align:center;font-size:.7rem;color:#888;">'+esc(x.date)+'</td>' +'<td style="padding:6px 8px;text-align:center;">'+t+'</td>' +'<td style="padding:6px 8px;text-align:center;font-weight:900;color:'+col+';">'+pc+'%</td></tr>';
  }).join('');
  ov.innerHTML='<div id="hh-analytics-inner" style="background:#fff;border:2px solid #B8924A;border-radius:20px;max-width:760px;width:100%;overflow:hidden;margin-bottom:24px;font-family:Cairo,Tajawal,sans-serif;">' +'<div style="background:linear-gradient(135deg,#1F4E79,#12304d);color:#fff;padding:14px 18px;display:flex;justify-content:space-between;align-items:center;">' +'<div style="font-weight:900;font-size:.98rem;"> لوحة التحليلات التراكمية</div>' +'<button onclick="hhCloseAnalytics()" style="background:none;border:none;color:#fff;font-size:1.15rem;cursor:pointer;">✕</button></div>' +'<div style="padding:16px 18px;">' +'<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:14px;">' +'<div style="background:#E9EEF8;border-radius:12px;padding:10px;text-align:center;"><div style="font-size:1.5rem;font-weight:900;color:#1F4E79;">'+S.length+'</div><div style="font-size:.7rem;color:#555;font-weight:800;">جلسة</div></div>' +'<div style="background:#FDF3DD;border-radius:12px;padding:10px;text-align:center;"><div style="font-size:1.5rem;font-weight:900;color:#B8924A;">'+totQ+'</div><div style="font-size:.7rem;color:#555;font-weight:800;">سؤال</div></div>' +'<div style="background:#EBF2EE;border-radius:12px;padding:10px;text-align:center;"><div style="font-size:1.5rem;font-weight:900;color:#3D6B53;">'+overall+'%</div><div style="font-size:.7rem;color:#555;font-weight:800;">المعدل العام</div></div>' +'</div>' +'<div style="font-weight:900;font-size:.86rem;color:#1F4E79;margin-bottom:6px;"> منحنى التطور عبر الجلسات</div>' +'<div style="background:#FAFBFD;border:1.5px solid #E3D9C6;border-radius:12px;padding:8px;margin-bottom:14px;">'+chart
    +'<div style="text-align:center;font-size:.64rem;color:#999;margin-top:2px;">الخط المتقطع = عتبة الإتقان 70%</div></div>' +(phaseCards?'<div style="font-weight:900;font-size:.86rem;color:#1F4E79;margin-bottom:6px;"> الأداء حسب مرحلة البحث</div><div style="display:flex;gap:9px;flex-wrap:wrap;">'+phaseCards+'</div>':'')
    + gainBox
    +'<div style="font-weight:900;font-size:.86rem;color:#1F4E79;margin:12px 0 6px;"> مقارنة المجموعات</div>' +'<table style="width:100%;border-collapse:collapse;font-size:.8rem;margin-bottom:14px;">' +'<thead><tr style="background:#1F4E79;color:#fff;"><th style="padding:7px 10px;text-align:right;">المجموعة</th><th style="padding:7px;text-align:center;">جلسات</th><th style="padding:7px;text-align:center;">أسئلة</th><th style="padding:7px;text-align:center;">النسبة</th></tr></thead>' +'<tbody>'+groupRows+'</tbody></table>' +(weakRows?'<div style="font-weight:900;font-size:.86rem;color:#1F4E79;margin-bottom:6px;"> الفئات الأضعف (تحتاج تعزيزاً)</div><div style="background:#FDF8EC;border:1.5px solid #E3D9C6;border-radius:12px;padding:11px;margin-bottom:14px;">'+weakRows+'</div>':'')
    +'<div style="font-weight:900;font-size:.86rem;color:#1F4E79;margin-bottom:6px;"> سجل الجلسات</div>' +'<div style="overflow-x:auto;"><table style="width:100%;border-collapse:collapse;font-size:.78rem;">' +'<thead><tr style="background:#E9EEF8;color:#1F4E79;font-weight:900;">' +'<th style="padding:6px 8px;">#</th><th style="padding:6px 8px;text-align:right;">الجلسة</th><th style="padding:6px 8px;">المرحلة</th><th style="padding:6px 8px;">المجموعة</th><th style="padding:6px 8px;">التاريخ</th><th style="padding:6px 8px;">أسئلة</th><th style="padding:6px 8px;">النسبة</th></tr></thead>' +'<tbody>'+sessRows+'</tbody></table></div>' +'<div style="display:flex;gap:9px;margin-top:14px;flex-wrap:wrap;">' +'<button onclick="hhPrintAnalytics()" style="background:linear-gradient(135deg,#1F4E79,#12304d);color:#fff;border:none;border-radius:11px;padding:10px 20px;font-weight:900;font-size:.84rem;cursor:pointer;"> طباعة التقرير</button>' +'<button onclick="hhExportAnalyticsCSV()" style="background:#EBF2EE;color:#3D6B53;border:1.5px solid #3D6B53;border-radius:11px;padding:10px 18px;font-weight:900;font-size:.84rem;cursor:pointer;"> تصدير بيانات البحث</button>' +'<button onclick="hhCloseAnalytics()" style="background:#F3F0F1;color:#666;border:none;border-radius:11px;padding:10px 16px;font-weight:900;font-size:.84rem;cursor:pointer;">إغلاق</button>' +'</div></div></div>';
  document.body.appendChild(ov);
}
function hhCloseAnalytics(){ var e=document.getElementById('hh-analytics'); if(e) e.remove(); }
function hhPrintAnalytics(){
  var el=document.getElementById('hh-analytics-inner'); if(!el) return;
  var w=window.open('','_blank');
  w.document.write('<html dir="rtl"><head><meta charset="utf-8"><title>تقرير التحليلات</title>' +'<style>body{font-family:Cairo,Tajawal,Arial,sans-serif;padding:20px;direction:rtl;}table{border-collapse:collapse;width:100%;}th,td{border:1px solid #ddd;padding:6px 10px;}th{background:#1F4E79;color:#fff;}button{display:none}</style></head><body>');
  w.document.write(el.innerHTML);
  w.document.write('</body></html>');
  w.document.close();
  setTimeout(function(){ try{ w.print(); }catch(e){} }, 600);
}
function hhExportAnalyticsCSV(){
  if(!_savedSessions.length){ if(typeof toast==='function') toast('لا بيانات','info'); return; }
  var rows=[['رقم الجلسة','اسم الجلسة','التاريخ','المرحلة','المجموعة','الفئات','عدد الأسئلة','الصحيح','النسبة%']];
  _savedSessions.forEach(function(x,i){
    var t=x.log.length, c=x.log.filter(function(r){return r.correct;}).length;
    rows.push([i+1,x.gameName,x.iso||x.date,x.phase||'',x.group||'',x.cats,t,c,t?Math.round(c/t*100):0]);
  });
  rows.push([]);
  rows.push(['تفصيل الأسئلة']);
  rows.push(['الجلسة','المرحلة','المجموعة','السؤال','الجواب','الفئة','الفئة الفرعية','المستوى','النتيجة','ملاحظة المعلم']);
  _savedSessions.forEach(function(x){
    x.log.forEach(function(r){
      rows.push([x.gameName,x.phase||'',x.group||'',r.q||'',r.a||'',r.cat||'',r.subCat||'',r.diff||'',r.correct?'صحيح':'خطأ',r.note||'']);
    });
  });
  var csv=rows.map(function(r){return r.map(function(c){return '"'+String(c==null?'':c).replace(/"/g,'""')+'"';}).join(',');}).join('\n');
  var bl=new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'});
  var a=document.createElement('a'); a.href=URL.createObjectURL(bl);
  a.download='almulhim_research_'+new Date().toISOString().slice(0,10)+'.csv'; a.click();
  if(typeof toast==='function') toast('✓ صُدّرت بيانات البحث كاملة','success');
}

// ═══════════════════════════════════════════════════════════════════
//  محرك التوصيات التربوية · تحليل أنماط الخطأ وتوليد خطة الحصة القادمة
// ═══════════════════════════════════════════════════════════════════
function hhAnalyzeSession(log){
  if(!log || !log.length) return null;
  var total=log.length;
  var correct=log.filter(function(r){return r.correct;}).length;
  var pct=Math.round(correct/total*100);
  var wrong=log.filter(function(r){return !r.correct;});

  // ── 1) الأداء حسب المستوى (يكشف: هل المشكلة في الحفظ أم الفهم؟) ──
  var byDiff={easy:{t:0,c:0},med:{t:0,c:0},hard:{t:0,c:0}};
  log.forEach(function(r){
    var d=r.diff||'med';
    if(!byDiff[d]) byDiff[d]={t:0,c:0};
    byDiff[d].t++; if(r.correct) byDiff[d].c++;
  });
  var pE=byDiff.easy.t?Math.round(byDiff.easy.c/byDiff.easy.t*100):null;
  var pM=byDiff.med.t?Math.round(byDiff.med.c/byDiff.med.t*100):null;
  var pH=byDiff.hard.t?Math.round(byDiff.hard.c/byDiff.hard.t*100):null;

  // ── 2) الأداء حسب الفئة والفئة الفرعية ──
  var byCat={}, bySub={};
  log.forEach(function(r){
    var c=r.cat||'متنوع';
    if(!byCat[c]) byCat[c]={t:0,c:0};
    byCat[c].t++; if(r.correct) byCat[c].c++;
    if(r.subCat){
      if(!bySub[r.subCat]) bySub[r.subCat]={t:0,c:0};
      bySub[r.subCat].t++; if(r.correct) bySub[r.subCat].c++;
    }
  });
  var catArr=Object.keys(byCat).map(function(c){
    return {name:c, pct:Math.round(byCat[c].c/byCat[c].t*100), t:byCat[c].t};
  }).sort(function(a,b){return a.pct-b.pct;});
  var subArr=Object.keys(bySub).map(function(c){
    return {name:c, pct:Math.round(bySub[c].c/bySub[c].t*100), t:bySub[c].t};
  }).sort(function(a,b){return a.pct-b.pct;});

  // ── 3) تصنيف نمط السؤال (يكشف نوع الصعوبة المعرفية) ──
  function qType(q){
    var t=String(q||'');
    if(/^(متى|في أي عام|في أي سنة|كم عام|أي عام)/.test(t) || /\bعام\b|\bسنة\b|\bتاريخ\b/.test(t)) return 'التواريخ والتسلسل الزمني';
    if(/^(كم)\b/.test(t) || /\bعدد\b/.test(t)) return 'الأعداد والإحصاءات';
    if(/^(أين|ما عاصمة|في أي دولة|في أي قارة|أي مدينة)/.test(t)) return 'المواقع والجغرافيا';
    if(/^(من|مَن)\b/.test(t)) return 'الأعلام والشخصيات';
    if(/^(لماذا|ما سبب|علل|ما الفرق|ما المقصود)/.test(t)) return 'التعليل والفهم العميق';
    if(/^(ما|ماذا)\b/.test(t)) return 'المفاهيم والتعريفات';
    return 'أنماط أخرى';
  }
  var typeAgg={};
  log.forEach(function(r){
    var ty=qType(r.q);
    if(!typeAgg[ty]) typeAgg[ty]={t:0,c:0};
    typeAgg[ty].t++; if(r.correct) typeAgg[ty].c++;
  });
  var typeArr=Object.keys(typeAgg).filter(function(k){return typeAgg[k].t>=2;})
    .map(function(k){ return {name:k, pct:Math.round(typeAgg[k].c/typeAgg[k].t*100), t:typeAgg[k].t}; })
    .sort(function(a,b){return a.pct-b.pct;});

  // ── 4) توليد التشخيص والتوصيات ──
  var diagnosis='', recs=[], level='';
  if(pct>=85){ level='ممتاز';
    diagnosis='أداء متميز · الطلاب أتقنوا محتوى هذه الجلسة بدرجة عالية.'; }
  else if(pct>=70){ level='جيد';
    diagnosis='أداء جيد تجاوز عتبة الإتقان (70%)، مع وجود فجوات محددة تستحق المعالجة.'; }
  else if(pct>=50){ level='متوسط';
    diagnosis='أداء متوسط دون عتبة الإتقان · يحتاج المحتوى إلى إعادة تقديم بأسلوب مختلف.'; }
  else { level='ضعيف';
    diagnosis='أداء دون المتوقع · يُرجّح أن المحتوى قُدّم قبل ترسيخ الأساسيات، أو أن مستوى الأسئلة أعلى من جاهزية الطلاب.'; }

  // تحليل تدرّج المستويات
  if(pE!==null && pE<60){
    recs.push({icon:'', t:'ضعف في الأساسيات', d:'نسبة الإجابة على الأسئلة السهلة '+pE+'% فقط · هذا مؤشر على أن المفاهيم الأساسية لم تترسخ بعد. ابدأ الحصة القادمة بمراجعة سريعة للأساسيات قبل أي محتوى جديد.'});
  } else if(pE!==null && pH!==null && pE>=80 && pH<40){
    recs.push({icon:'', t:'إتقان سطحي', d:'الطلاب أتقنوا السهل ('+pE+'%) وتعثّروا في الصعب ('+pH+'%) · الحفظ حاضر والفهم العميق ناقص. استخدم أسئلة "لماذا" و"ما الفرق" في الحصة القادمة.'});
  } else if(pH!==null && pH>=70){
    recs.push({icon:'', t:'جاهزية للتعميق', d:'أداء قوي في الأسئلة الصعبة ('+pH+'%) · الطلاب مستعدون لمحتوى أكثر تحدياً أو لمشروع بحثي قصير.'});
  }

  // أضعف فئة
  if(catArr.length && catArr[0].pct<60 && catArr[0].t>=2){
    recs.push({icon:'', t:'فئة تحتاج تعزيزاً: '+catArr[0].name,
      d:'نسبة الإتقان فيها '+catArr[0].pct+'% من أصل '+catArr[0].t+' أسئلة. خصّص لها 10 دقائق في بداية الحصة القادمة قبل الانتقال لموضوع جديد.'});
  }
  // أقوى فئة (تعزيز إيجابي)
  if(catArr.length>1 && catArr[catArr.length-1].pct>=80){
    recs.push({icon:'', t:'نقطة قوة: '+catArr[catArr.length-1].name,
      d:'أتقنها الطلاب بنسبة '+catArr[catArr.length-1].pct+'%. يمكنك البناء عليها كمدخل لربط المحتوى الجديد.'});
  }
  // أضعف فئة فرعية
  if(subArr.length && subArr[0].pct<60 && subArr[0].t>=2){
    recs.push({icon:'', t:'محور فرعي متعثّر: '+subArr[0].name,
      d:'الإتقان فيه '+subArr[0].pct+'% · راجعه بنشاط قصير أو خريطة ذهنية.'});
  }
  // نمط السؤال الأضعف
  if(typeArr.length && typeArr[0].pct<55){
    var tp=typeArr[0];
    var tips={
      'التواريخ والتسلسل الزمني':'استخدم خطاً زمنياً بصرياً على السبورة، واربط كل تاريخ بحدث مصوّر.',
      'الأعداد والإحصاءات':'حوّل الأرقام إلى مقارنات محسوسة (مثال: يعادل عدد طلاب المدرسة).',
      'المواقع والجغرافيا':'اعرض خريطة تفاعلية واطلب من الطلاب تحديد المواقع بأنفسهم.',
      'الأعلام والشخصيات':'اربط كل شخصية بقصة قصيرة أو صورة · السرد يثبّت الأسماء.',
      'التعليل والفهم العميق':'استخدم أسلوب السؤال السقراطي: اسأل "لماذا؟" ثلاث مرات متتالية.',
      'المفاهيم والتعريفات':'اطلب من الطلاب صياغة التعريف بكلماتهم قبل عرض التعريف الرسمي.',
      'أنماط أخرى':'نوّع أساليب طرح السؤال لتغطية أنماط تفكير مختلفة.' };
    recs.push({icon:'', t:'نمط الصعوبة: '+tp.name,
      d:'الإتقان في هذا النمط '+tp.pct+'% من أصل '+tp.t+' أسئلة. '+(tips[tp.name]||'')});
  }
  // توصية عامة عند الضعف الشامل
  if(pct<50){
    recs.push({icon:'⏸', t:'أعد التقديم قبل التقدّم',
      d:'لا تنتقل لوحدة جديدة قبل إعادة تقديم هذا المحتوى بأسلوب مختلف (نشاط جماعي، فيديو قصير، أو تعلّم بالأقران).'});
  }
  if(!recs.length){
    recs.push({icon:'', t:'واصل بنفس النهج',
      d:'الأداء متوازن عبر المستويات والفئات · استمر في الأسلوب الحالي مع رفع مستوى التحدي تدريجياً.'});
  }

  // ── 5) أسئلة تستحق إعادة الطرح ──
  var retry=wrong.slice(0,6).map(function(r){ return {q:r.q, a:r.a, cat:r.cat||'', diff:r.diff||''}; });

  return { total:total, correct:correct, pct:pct, level:level, diagnosis:diagnosis,
    recs:recs, retry:retry, byDiff:{easy:pE, med:pM, hard:pH},
    catArr:catArr, typeArr:typeArr };
}


// ═══════════════════════════════════════════════════════════════════
//  دعوة الجولة التعريفية · شريط لطيف بدل نافذة تُفرض على المستخدم
// ═══════════════════════════════════════════════════════════════════
function hhShowTourInvite(){
  try{
    if(localStorage.getItem('hh_onboarding_seen') === '1') return;
    if(localStorage.getItem('hh_tour_invite_dismissed') === '1') return;
  }catch(e){ return; }
  if(document.getElementById('hh-tour-invite')) return;

  var bar = document.createElement('div');
  bar.id = 'hh-tour-invite';
  bar.style.cssText = 'position:fixed;bottom:18px;left:50%;transform:translateX(-50%) translateY(120%);' + 'background:#fff;border:1.5px solid #B8924A;border-radius:16px;' + 'box-shadow:0 12px 34px rgba(94,14,38,.18);z-index:99990;' + 'padding:11px 14px;display:flex;align-items:center;gap:12px;' + 'font-family:Cairo,Tajawal,sans-serif;direction:rtl;max-width:min(420px,92vw);' + 'transition:transform .45s cubic-bezier(.2,.9,.3,1.2);';
  bar.innerHTML =
      '<div style="font-size:1.3rem;line-height:1;"></div>' + '<div style="flex:1;min-width:0;">' +   '<div style="font-weight:900;font-size:.83rem;color:#5E0E26;">أول مرة معنا؟</div>' +   '<div style="font-size:.72rem;color:#777;font-weight:700;">جولة سريعة في 30 ثانية · أو تصفّح بحرية</div>' + '</div>' + '<button onclick="hhAcceptTourInvite()" style="background:linear-gradient(135deg,#8A1538,#5E0E26);color:#fff;border:none;border-radius:10px;padding:8px 15px;font-family:Cairo;font-weight:900;font-size:.78rem;cursor:pointer;white-space:nowrap;">ابدأ الجولة</button>' + '<button onclick="hhDismissTourInvite()" title="إخفاء" style="background:none;border:none;color:#bbb;font-size:1.05rem;cursor:pointer;padding:2px 4px;line-height:1;">✕</button>';
  document.body.appendChild(bar);
  requestAnimationFrame(function(){
    setTimeout(function(){ bar.style.transform = 'translateX(-50%) translateY(0)'; }, 40);
  });
  // يختفي وحده بعد 12 ثانية دون إزعاج
  window._hhTourInviteTimer = setTimeout(function(){ hhDismissTourInvite(true); }, 12000);
}
function hhDismissTourInvite(soft){
  var bar = document.getElementById('hh-tour-invite');
  if(bar){
    bar.style.transform = 'translateX(-50%) translateY(120%)';
    setTimeout(function(){ if(bar && bar.parentNode) bar.remove(); }, 450);
  }
  try{ clearTimeout(window._hhTourInviteTimer); }catch(e){}
  // الإخفاء اليدوي = لا تُعرض ثانية؛ الاختفاء التلقائي = قد تظهر بزيارة لاحقة
  if(!soft){ try{ localStorage.setItem('hh_tour_invite_dismissed','1'); }catch(e){} }
}
function hhAcceptTourInvite(){
  hhDismissTourInvite();
  try{ localStorage.setItem('hh_tour_invite_dismissed','1'); }catch(e){}
  setTimeout(function(){ try{ if(typeof hhOnboardingShow==='function') hhOnboardingShow(); }catch(e){} }, 300);
}

// ═══════════════════════════════════════════════════════════════════
//  مركز المنهج · مكتبة الدروس وتوليد المحتوى (المرحلة الأولى)
// البنية: مادة ← صف ← وحدة ← درس  |  تخزين محلي + مزامنة سحابية
// ═══════════════════════════════════════════════════════════════════
var _HH_CURR_KEY = 'hh_curriculum_lessons';
var _hhLessons = [];

function hhLoadLessons(){
  try{
    var raw = localStorage.getItem(_HH_CURR_KEY);
    _hhLessons = raw ? (JSON.parse(raw) || []) : [];
  }catch(e){ _hhLessons = []; }
  return _hhLessons;
}
function hhSaveLessons(){
  try{
    var payload = JSON.stringify(_hhLessons);
    if(payload.length > 3.5*1024*1024){
      if(typeof toast==='function') toast(' مكتبة الدروس امتلأت · احذف دروساً قديمة','error');
      return false;
    }
    localStorage.setItem(_HH_CURR_KEY, payload);
    // مزامنة سحابية صامتة (إن توفرت)
    try{
      if(typeof firebase!=='undefined' && firebase.firestore && typeof currentUser!=='undefined' && currentUser){
        firebase.firestore().collection('curriculum_lessons').doc(currentUser.uid)
          .set({ lessons:_hhLessons, updatedAt:new Date().toISOString(), owner:currentUser.email||'' })
          .catch(function(){});
      }
    }catch(e){}
    return true;
  }catch(e){ return false; }
}
hhLoadLessons();

// ── سجل النشاط (رقابة المنصة) ──
var _HH_LOG_KEY = 'hh_activity_log';
function hhLogActivity(type, detail){
  try{
    var log = JSON.parse(localStorage.getItem(_HH_LOG_KEY) || '[]');
    log.push({
      t: type, d: String(detail||'').slice(0,120),
      u: (typeof currentUser!=='undefined' && currentUser) ? (currentUser.email||currentUser.uid||'زائر') : 'زائر',
      ts: Date.now()
    });
    if(log.length > 400) log = log.slice(-400);
    localStorage.setItem(_HH_LOG_KEY, JSON.stringify(log));
    // إرسال سحابي صامت للأحداث المهمة فقط
    if(['lesson_add','generate','game_start'].indexOf(type) >= 0){
      try{
        if(typeof firebase!=='undefined' && firebase.firestore){
          firebase.firestore().collection('platform_activity').add({
            type:type, detail:String(detail||'').slice(0,120),
            user:(typeof currentUser!=='undefined'&&currentUser)?(currentUser.email||'مجهول'):'زائر',
            createdAt: firebase.firestore.FieldValue.serverTimestamp()
          }).catch(function(){});
        }
      }catch(e){}
    }
  }catch(e){}
}

// ── استخراج النص من ملف ──
function hhExtractText(file, cb){
  var name = (file.name||'').toLowerCase();
  if(name.endsWith('.txt') || file.type === 'text/plain'){
    var r = new FileReader();
    r.onload = function(e){ cb(null, String(e.target.result||'')); };
    r.onerror = function(){ cb('تعذر قراءة الملف'); };
    r.readAsText(file, 'utf-8');
    return;
  }
  if(name.endsWith('.pdf') || file.type === 'application/pdf'){
    if(typeof pdfjsLib === 'undefined'){
      cb('لقراءة PDF أضف مكتبة pdf.js · أو الصق نص الدرس مباشرة');
      return;
    }
    var fr = new FileReader();
    fr.onload = function(e){
      pdfjsLib.getDocument({data:e.target.result}).promise.then(function(pdf){
        var pages = [], n = Math.min(pdf.numPages, 30);
        var seq = Promise.resolve();
        for(var i=1;i<=n;i++){
          (function(pi){
            seq = seq.then(function(){
              return pdf.getPage(pi).then(function(pg){
                return pg.getTextContent().then(function(tc){
                  pages.push(tc.items.map(function(it){return it.str;}).join(' '));
                });
              });
            });
          })(i);
        }
        seq.then(function(){ cb(null, pages.join('\n\n')); })
           .catch(function(){ cb('تعذر استخراج النص من الملف'); });
      }).catch(function(){ cb('الملف غير مقروء · تأكد أنه نصي وليس صورة ممسوحة'); });
    };
    fr.onerror = function(){ cb('تعذر قراءة الملف'); };
    fr.readAsArrayBuffer(file);
    return;
  }
  cb('صيغة غير مدعومة · استخدم PDF نصي أو TXT، أو الصق النص مباشرة');
}

// ── واجهة مركز المنهج ──
// ═══════════════════════════════════════════════════════════════════
//  التوليد الذكي · الاتصال بالوسيط السحابي الآمن
// ═══════════════════════════════════════════════════════════════════
var _HH_AI_URL_KEY = 'hh_ai_endpoint';
function hhGetAIEndpoint(){
  try{ return localStorage.getItem(_HH_AI_URL_KEY) || ''; }catch(e){ return ''; }
}
function hhSetAIEndpoint(url){
  try{
    if(url) localStorage.setItem(_HH_AI_URL_KEY, url.trim());
    else localStorage.removeItem(_HH_AI_URL_KEY);
    // مزامنة للأدمن حتى تعمل على كل الأجهزة
    if(typeof firebase!=='undefined' && firebase.firestore && typeof isAdminUser==='function' && isAdminUser(currentUser)){
      firebase.firestore().collection('platform_settings').doc('ai_config')
        .set({ endpoint: url||'', updatedAt: new Date().toISOString() }, {merge:true}).catch(function(){});
    }
    return true;
  }catch(e){ return false; }
}
// جلب الرابط من السحابة عند الإقلاع (فيعمل التوليد لكل المستخدمين)
(function(){
  try{
    setTimeout(function(){
      if(typeof firebase==='undefined' || !firebase.firestore) return;
      firebase.firestore().collection('platform_settings').doc('ai_config').get()
        .then(function(d){
          if(d.exists && d.data().endpoint && !hhGetAIEndpoint()){
            try{ localStorage.setItem(_HH_AI_URL_KEY, d.data().endpoint); }catch(e){}
          }
        }).catch(function(){});
    }, 3000);
  }catch(e){}
})();

// ── الاستدعاء الفعلي ──
async function hhCurrAIGenerate(kind, lesson){
  var url = hhGetAIEndpoint();
  if(!url) throw new Error('NO_ENDPOINT');
  var res = await fetch(url, {
    method:'POST',
    headers:{'Content-Type':'application/json'},
    body: JSON.stringify({
      kind: kind,
      text: lesson.text || '',
      meta: { subject:lesson.subject||'', grade:lesson.grade||'', unit:lesson.unit||'', lesson:lesson.lesson||'' },
      uid: (typeof currentUser!=='undefined'&&currentUser)?currentUser.uid:null,
      email: (typeof currentUser!=='undefined'&&currentUser)?currentUser.email:null
    })
  });
  var j = await res.json().catch(function(){ return null; });
  if(!res.ok || !j || !j.ok) throw new Error((j&&j.error) || 'تعذر التوليد');
  return j;
}

// ── عرض النتائج المولّدة ──
function hhRenderAI(kind, d, lesson){
  if(kind==='questions'){
    var qs = d.questions||[];
    if(!qs.length) return '<div style="color:#c0392b;font-weight:800;">لم تُولَّد أسئلة</div>';
    window._hhGenQs = qs; window._hhGenLesson = lesson;
    var dl={easy:'سهل',med:'متوسط',hard:'صعب'};
    return '<div style="background:#fff;border:1.5px solid #E3D9C6;border-radius:10px;padding:12px;">' + '<div style="font-weight:900;color:#1F4E79;margin-bottom:9px;"> '+qs.length+' سؤالاً مولّداً · '+esc(lesson.lesson)+'</div>' + qs.map(function(q,i){
          var col=q.diff==='hard'?'#c0392b':q.diff==='med'?'#b5801f':'#3D6B53';
          return '<div style="margin-bottom:10px;padding-bottom:9px;border-bottom:1px dashed #eee;">' + '<div style="display:flex;gap:6px;align-items:center;flex-wrap:wrap;margin-bottom:3px;">' +   '<span style="background:'+col+';color:#fff;border-radius:6px;padding:1px 7px;font-size:.62rem;font-weight:900;">'+(dl[q.diff]||q.diff||'')+'</span>' +   (q.bloom?'<span style="background:#E9EEF8;color:#1F4E79;border-radius:6px;padding:1px 7px;font-size:.62rem;font-weight:900;">'+esc(q.bloom)+'</span>':'')
            + '</div>' + '<div style="font-weight:800;color:#333;font-size:.8rem;">'+(i+1)+'. '+esc(q.q||'')+'</div>' + '<div style="font-size:.73rem;color:#3D6B53;font-weight:800;margin-top:3px;">✓ '+esc(q.a||'')+'</div>' + (q.opts&&q.opts.length?'<div style="font-size:.68rem;color:#999;margin-top:2px;">خيارات: '+q.opts.map(function(o){return esc(o);}).join(' · ')+'</div>':'')
            + '</div>';
        }).join('')
      + '<button onclick="hhAddGenToBoard()" style="background:linear-gradient(135deg,#8A1538,#5E0E26);color:#fff;border:none;border-radius:10px;padding:9px 18px;font-family:Cairo;font-weight:900;font-size:.8rem;cursor:pointer;margin-top:8px;"> أضفها كفئة قابلة للعب</button>' + '</div>';
  }
  if(kind==='quiz'){
    var it=d.items||[];
    return '<div style="background:#fff;border:1.5px solid #E3D9C6;border-radius:10px;padding:12px;">' + '<div style="font-weight:900;color:#3D6B53;margin-bottom:4px;"> '+esc(d.title||'اختبار')+'</div>' + '<div style="font-size:.7rem;color:#888;margin-bottom:9px;">الدرجة الكلية: '+(d.total||20)+'</div>' + it.map(function(x){
          return '<div style="margin-bottom:9px;padding-bottom:8px;border-bottom:1px dashed #eee;">' + '<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:3px;">' +   '<span style="background:#EBF2EE;color:#3D6B53;border-radius:6px;padding:1px 7px;font-size:.62rem;font-weight:900;">'+esc(x.type||'')+'</span>' +   '<span style="background:#FDF3DD;color:#8A6D2E;border-radius:6px;padding:1px 7px;font-size:.62rem;font-weight:900;">'+esc(x.bloom||'')+'</span>' +   '<span style="color:#aaa;font-size:.62rem;font-weight:900;">('+(x.marks||2)+' درجة)</span>' + '</div>' + '<div style="font-weight:800;color:#333;font-size:.8rem;">'+(x.n||'')+'. '+esc(x.q||'')+'</div>' + (x.opts&&x.opts.length?'<div style="font-size:.72rem;color:#666;margin-top:3px;">'+x.opts.map(function(o){return '◻ '+esc(o);}).join(' ')+'</div>':'')
            + '<div style="font-size:.72rem;color:#3D6B53;font-weight:800;margin-top:3px;">✓ '+esc(x.a||'')+'</div></div>';
        }).join('')
      + '<button onclick="hhPrintGen()" style="background:linear-gradient(135deg,#3D6B53,#274a38);color:#fff;border:none;border-radius:10px;padding:9px 18px;font-family:Cairo;font-weight:900;font-size:.8rem;cursor:pointer;margin-top:6px;"> طباعة الاختبار</button>' + '</div>';
  }
  if(kind==='summary'){
    return '<div style="background:#FDF8EC;border:1.5px solid #E3D9C6;border-radius:10px;padding:13px;">' + '<div style="font-weight:900;color:#8A6D2E;margin-bottom:6px;"> '+esc(d.title||lesson.lesson)+'</div>' + (d.idea?'<div style="background:#fff;border-right:3px solid #B8924A;border-radius:8px;padding:9px 11px;margin-bottom:9px;font-weight:800;color:#5E0E26;font-size:.82rem;"> '+esc(d.idea)+'</div>':'')
      + ((d.points||[]).length?'<div style="font-weight:900;font-size:.78rem;color:#8A6D2E;margin-bottom:4px;">النقاط الرئيسة</div>' + (d.points||[]).map(function(p){return '<div style="font-size:.79rem;margin-bottom:4px;color:#444;">• '+esc(p)+'</div>';}).join(''):'')
      + ((d.terms||[]).length?'<div style="font-weight:900;font-size:.78rem;color:#8A6D2E;margin:9px 0 4px;">المصطلحات</div>' + (d.terms||[]).map(function(t){return '<div style="font-size:.76rem;margin-bottom:3px;"><b style="color:#1F4E79;">'+esc(t.term)+':</b> '+esc(t.def)+'</div>';}).join(''):'')
      + (d.conclusion?'<div style="margin-top:9px;padding-top:8px;border-top:1px solid #eee2c8;font-size:.79rem;color:#555;font-weight:700;">'+esc(d.conclusion)+'</div>':'')
      + '</div>';
  }
  if(kind==='strategies'){
    var st=d.strategies||[];
    return '<div style="background:#F5E9EE;border:1.5px solid #E3D9C6;border-radius:10px;padding:13px;">' + '<div style="font-weight:900;color:#8A1538;margin-bottom:8px;"> استراتيجيات لهذا الدرس</div>' + st.map(function(s,i){
          return '<div style="background:#fff;border-radius:9px;padding:10px 12px;margin-bottom:8px;">' + '<div style="display:flex;justify-content:space-between;gap:8px;align-items:center;">' +   '<div style="font-weight:900;font-size:.82rem;color:#8A1538;">'+(i+1)+'. '+esc(s.name||'')+'</div>' +   '<span style="font-size:.65rem;color:#999;font-weight:800;white-space:nowrap;">⏱ '+esc(s.time||'')+'</span></div>' + (s.why?'<div style="font-size:.74rem;color:#777;margin:3px 0 5px;">'+esc(s.why)+'</div>':'')
            + ((s.steps||[]).map(function(x,j){return '<div style="font-size:.75rem;color:#444;margin-bottom:2px;">'+(j+1)+') '+esc(x)+'</div>';}).join(''))
            + '</div>';
        }).join('')
      + (d.activity?'<div style="background:#EBF2EE;border:1.5px solid #3D6B53;border-radius:9px;padding:10px 12px;">' + '<div style="font-weight:900;font-size:.8rem;color:#3D6B53;"> '+esc(d.activity.name||'نشاط ختامي')+'</div>' + '<div style="font-size:.76rem;color:#444;margin-top:3px;">'+esc(d.activity.desc||'')+'</div>' + (d.activity.materials?'<div style="font-size:.7rem;color:#888;margin-top:3px;">المواد: '+esc(d.activity.materials)+'</div>':'')
          + '</div>':'')
      + '</div>';
  }
  if(kind==='challenge'){
    return '<div style="background:linear-gradient(135deg,#FDF3DD,#f7e9c9);border:2px solid #B8924A;border-radius:12px;padding:14px;">' + '<div style="font-weight:900;color:#8A6D2E;margin-bottom:6px;"> تحدي الدرس ('+(d.points||600)+' نقطة)</div>' + '<div style="font-size:.88rem;font-weight:800;color:#5E0E26;line-height:1.9;margin-bottom:8px;">'+esc(d.challenge||'')+'</div>' + ((d.hints||[]).length?'<div style="font-size:.74rem;color:#777;margin-bottom:6px;"> تلميحات: '+(d.hints||[]).map(function(h){return esc(h);}).join(' · ')+'</div>':'')
      + '<div style="background:#fff;border-radius:8px;padding:9px 11px;font-size:.78rem;color:#3D6B53;font-weight:800;">✓ '+esc(d.answer||'')+'</div>' + (d.skill?'<div style="font-size:.7rem;color:#999;margin-top:5px;">المهارة: '+esc(d.skill)+'</div>':'')
      + '</div>';
  }
  return '<pre style="font-size:.7rem;white-space:pre-wrap;">'+esc(JSON.stringify(d,null,1))+'</pre>';
}

// ── إضافة الأسئلة المولّدة كفئة قابلة للعب ──
function hhAddGenToBoard(){
  var qs = window._hhGenQs, L = window._hhGenLesson;
  if(!qs || !qs.length || !L){ if(typeof toast==='function') toast('لا أسئلة للإضافة','warn'); return; }
  var catName = ' ' + (L.lesson||'درس');
  try{
    var arr = qs.map(function(q){
      var o = { q:q.q, a:q.a, diff:(q.diff==='hard'?'hard':q.diff==='med'?'med':'easy') };
      if(q.opts && q.opts.length>=4) o.opts = q.opts;
      return o;
    });
    if(typeof QDB!=='undefined') QDB[catName] = arr;
    if(typeof window.QDB_ORIGINAL!=='undefined' && window.QDB_ORIGINAL) window.QDB_ORIGINAL[catName] = JSON.parse(JSON.stringify(arr));
    if(typeof CAT_INFO!=='undefined') CAT_INFO[catName] = {emoji:'', label:catName, color:'#1F4E79', bg:'#E9EEF8'};
    // حفظ دائم
    try{
      var saved = JSON.parse(localStorage.getItem('hh_generated_cats')||'{}');
      saved[catName] = arr;
      localStorage.setItem('hh_generated_cats', JSON.stringify(saved));
    }catch(e){}
    if(typeof hhLogActivity==='function') hhLogActivity('generate', 'فئة قابلة للعب: '+catName);
    if(typeof toast==='function') toast('✓ أُضيفت «'+catName+'» · اختَرها عند بدء لعبة جديدة','success');
  }catch(e){
    if(typeof toast==='function') toast('تعذرت الإضافة','error');
  }
}
// استعادة الفئات المولّدة عند الإقلاع
(function(){
  try{
    setTimeout(function(){
      var saved = JSON.parse(localStorage.getItem('hh_generated_cats')||'{}');
      Object.keys(saved).forEach(function(c){
        if(typeof QDB!=='undefined' && !QDB[c]) QDB[c] = saved[c];
        if(typeof CAT_INFO!=='undefined' && !CAT_INFO[c]) CAT_INFO[c] = {emoji:'', label:c, color:'#1F4E79', bg:'#E9EEF8'};
      });
    }, 2500);
  }catch(e){}
})();

function hhPrintGen(){
  var out=document.getElementById('hh-gen-out'); if(!out) return;
  var w=window.open('','_blank');
  w.document.write('<html dir="rtl"><head><meta charset="utf-8"><title>مخرجات المُلهِم</title>' +'<style>body{font-family:Cairo,Tajawal,Arial,sans-serif;padding:22px;direction:rtl;line-height:1.9;}button{display:none}</style></head><body>');
  w.document.write(out.innerHTML);
  w.document.write('</body></html>');
  w.document.close();
  setTimeout(function(){ try{ w.print(); }catch(e){} },600);
}

// ── إعدادات التوليد ──
function hhAISettings(){
  var cur = hhGetAIEndpoint();
  var ov=document.createElement('div'); ov.id='hh-aiset';
  ov.style.cssText='position:fixed;inset:0;background:rgba(30,6,15,.7);z-index:999996;display:flex;align-items:center;justify-content:center;padding:18px;direction:rtl;';
  ov.innerHTML='<div style="background:#fff;border:2px solid #B8924A;border-radius:18px;max-width:520px;width:100%;overflow:hidden;font-family:Cairo,Tajawal,sans-serif;">' +'<div style="background:linear-gradient(135deg,#3D6B53,#274a38);color:#fff;padding:13px 18px;font-weight:900;font-size:.92rem;"> إعدادات التوليد الذكي</div>' +'<div style="padding:16px 18px;">' +'<div style="font-size:.78rem;color:#555;line-height:1.9;margin-bottom:10px;">الصق رابط الوسيط السحابي (Cloud Function). بعد حفظه سيعمل التوليد الذكي لك ولكل من يستخدم المنصة.</div>' +'<input id="ai-url" type="text" value="'+esc(cur)+'" placeholder="https://us-central1-اسم-مشروعك.cloudfunctions.net/generateContent" style="width:100%;border:1.5px solid #C9B37E;border-radius:10px;padding:9px 12px;font-family:monospace;font-size:.76rem;box-sizing:border-box;margin-bottom:10px;direction:ltr;text-align:left;">' +'<div id="ai-set-status" style="font-size:.74rem;font-weight:800;min-height:16px;margin-bottom:8px;"></div>' +'<div style="display:flex;gap:9px;flex-wrap:wrap;">' +'<button onclick="hhSaveAIEndpoint()" style="background:linear-gradient(135deg,#3D6B53,#274a38);color:#fff;border:none;border-radius:11px;padding:10px 20px;font-weight:900;font-size:.83rem;cursor:pointer;">حفظ</button>' +'<button onclick="hhTestAIEndpoint()" style="background:#E9EEF8;color:#1F4E79;border:1.5px solid #1F4E79;border-radius:11px;padding:10px 16px;font-weight:900;font-size:.83rem;cursor:pointer;">اختبار الاتصال</button>' +'<button onclick="document.getElementById(\'hh-aiset\').remove()" style="background:#F3F0F1;color:#666;border:none;border-radius:11px;padding:10px 16px;font-weight:900;font-size:.83rem;cursor:pointer;">إغلاق</button>' +'</div>' +'<div style="font-size:.7rem;color:#999;margin-top:10px;line-height:1.7;">لم تنشئ الوسيط بعد؟ راجع ملف firebase-functions-index.js · التركيب لا يتجاوز 10 دقائق.</div>' +'</div></div>';
  document.body.appendChild(ov);
}
function hhSaveAIEndpoint(){
  var v=(document.getElementById('ai-url')||{}).value||'';
  var st=document.getElementById('ai-set-status');
  if(v && !/^https:\/\//.test(v.trim())){ if(st){st.textContent=' الرابط يجب أن يبدأ بـ https://'; st.style.color='#c0392b';} return; }
  hhSetAIEndpoint(v.trim());
  if(st){ st.textContent = v ? '✓ حُفظ الرابط · التوليد الذكي مفعّل' : '✓ أُلغي الرابط · التوليد المحلي فقط'; st.style.color='#3D6B53'; }
  if(typeof toast==='function') toast(v?'✓ فُعّل التوليد الذكي':'أُلغي التوليد الذكي','success');
}
async function hhTestAIEndpoint(){
  var st=document.getElementById('ai-set-status');
  var v=(document.getElementById('ai-url')||{}).value||'';
  if(!v){ if(st){st.textContent=' الصق الرابط أولاً'; st.style.color='#c0392b';} return; }
  if(st){ st.textContent='⏳ جاري الاختبار...'; st.style.color='#8A6D2E'; }
  try{
    var r = await fetch(v.trim(), {
      method:'POST', headers:{'Content-Type':'application/json'},
      body: JSON.stringify({ kind:'summary', text:'هذا نص تجريبي للتحقق من عمل الوسيط السحابي بشكل صحيح ويحتوي على معلومات كافية للاختبار.', meta:{lesson:'اختبار'} })
    });
    var j = await r.json().catch(function(){return null;});
    if(r.ok && j && j.ok){ if(st){ st.textContent=' الاتصال ناجح · الوسيط يعمل'; st.style.color='#3D6B53'; } }
    else { if(st){ st.textContent=' '+((j&&j.error)||'استجابة غير متوقعة'); st.style.color='#c0392b'; } }
  }catch(e){
    if(st){ st.textContent=' تعذر الوصول للرابط'; st.style.color='#c0392b'; }
  }
}


// ── استيراد حزمة المنهج الرسمي ──
function hhImportPack(){
  var pack = window._HH_CURRICULUM_PACK;
  if(!pack || !pack.lessons || !pack.lessons.length){
    if(typeof toast==='function') toast('لم تُحمّل حزمة المنهج','warn'); return;
  }
  var existing = {};
  _hhLessons.forEach(function(L){ existing[L.unit+'|'+L.lesson] = true; });
  var added = 0;
  pack.lessons.forEach(function(L){
    var key = L.unit+'|'+L.lesson;
    if(existing[key]) return;
    _hhLessons.push({
      subject:L.subject, grade:L.grade, unit:L.unit, lesson:L.lesson,
      text:L.text, date:L.date || 'المنهج الرسمي', ts:Date.now()
    });
    added++;
  });
  if(added === 0){ if(typeof toast==='function') toast('كل دروس المنهج مضافة مسبقاً','info'); return; }
  if(hhSaveLessons()){
    if(typeof hhLogActivity==='function') hhLogActivity('lesson_add', 'استيراد المنهج: '+added+' درساً');
    if(typeof toast==='function') toast('✓ استُورد '+added+' درساً من المنهج الرسمي','success');
    hhOpenCurriculum();
  }
}

