function hhGuideRender(role){
  var G = (role==='teacher') ? HH_GUIDE_TEACHER : HH_GUIDE_STUDENT;
  var other = (role==='teacher') ? 'student' : 'teacher';
  var otherLbl = (role==='teacher') ? 'دليل الطالب' : 'دليل المعلم';
  var old=document.getElementById('hh-guide'); if(old) old.remove();
  var ov=document.createElement('div'); ov.id='hh-guide';
  ov.style.cssText='position:fixed;inset:0;background:rgba(30,6,15,.72);z-index:999976;display:flex;align-items:flex-start;justify-content:center;padding:16px;overflow-y:auto;direction:rtl;font-family:Cairo,Tajawal,sans-serif;';

  var steps=G.steps.map(function(s,i){
    return '<div style="background:#fff;border:1.5px solid #E3D9C6;border-radius:14px;padding:14px 16px;margin-bottom:9px;">'
      +'<div style="display:flex;gap:11px;align-items:flex-start;">'
      +'<span style="background:'+G.color+';color:#fff;border-radius:50%;width:28px;height:28px;display:flex;align-items:center;justify-content:center;font-weight:900;font-size:.83rem;flex-shrink:0;">'+(i+1)+'</span>'
      +'<div style="flex:1;min-width:0;">'
      +'<div style="font-weight:900;font-size:.9rem;color:'+G.dark+';margin-bottom:4px;">'+esc(s.t)+'</div>'
      +'<div style="font-size:.81rem;color:#555;line-height:1.95;">'+esc(s.d)+'</div>'
      + (s.act ? '<button onclick="hhGuideAct(\''+s.act.fn+'\')" style="background:'+G.color+';color:#fff;border:none;border-radius:9px;padding:6px 15px;font-family:Cairo;font-weight:900;font-size:.74rem;cursor:pointer;margin-top:8px;">'+esc(s.act.label)+'</button>' : '')
      +'</div></div></div>';
  }).join('');

  var tips=G.tips.map(function(t){
    return '<div style="font-size:.79rem;color:#555;line-height:1.9;margin-bottom:5px;">• '+esc(t)+'</div>';
  }).join('');

  ov.innerHTML='<div style="background:#FAFBFD;border:2px solid '+G.color+';border-radius:20px;max-width:640px;width:100%;overflow:hidden;margin-bottom:24px;">'
    +'<div style="background:linear-gradient(135deg,'+G.color+','+G.dark+');color:#fff;padding:16px 18px;display:flex;justify-content:space-between;align-items:center;">'
    +'<div><div style="font-weight:900;font-size:1.05rem;">'+esc(G.title)+'</div>'
    +'<div style="font-size:.76rem;opacity:.88;margin-top:3px;">'+esc(G.intro)+'</div></div>'
    +'<button onclick="hhCloseGuide()" style="background:none;border:none;color:#fff;font-size:1.15rem;cursor:pointer;">✕</button></div>'
    +'<div style="padding:16px 18px;">'
    + steps
    +'<div style="background:#FDF8EC;border:1.5px solid #E3D9C6;border-radius:13px;padding:13px;margin-top:13px;">'
    +'<div style="font-weight:900;font-size:.85rem;color:#8A6D2E;margin-bottom:7px;">نصائح تختصر عليك الطريق</div>'+tips+'</div>'
    +'<button onclick="hhGuidePick(\''+other+'\')" style="width:100%;background:#fff;color:'+G.dark+';border:1.5px solid '+G.color+';border-radius:12px;padding:10px;font-family:Cairo;font-weight:900;font-size:.82rem;cursor:pointer;margin-top:12px;">عرض '+esc(otherLbl)+' بدلاً منه</button>'
    +'</div></div>';
  document.body.appendChild(ov);
}
function hhGuideAct(fn){
  hhCloseGuide();
  setTimeout(function(){
    try{ if(typeof window[fn]==='function') window[fn](); }
    catch(e){ if(typeof toast==='function') toast('افتح القسم من شريط التنقل','info'); }
  }, 300);
}

