// ضمان تحميل الخطوط قبل الرسم (يمنع تشوّه العربية على Canvas)
async function hhEnsureFonts(){
  try{
    if(document.fonts && document.fonts.load){
      await Promise.all([
        document.fonts.load('900 60px Cairo'),
        document.fonts.load('800 30px Cairo'),
        document.fonts.load('700 24px Tajawal')
      ]);
      await document.fonts.ready;
    }
  }catch(e){}
}

// رسم زخرفة قطرية (نمط المثلثات المتعرجة · من العلم القطري)
function hhDrawQatarZigzag(x, cx, cy, w, h, teeth, color, alpha){
  x.save(); x.globalAlpha = alpha || 1; x.fillStyle = color;
  var step = h / teeth;
  x.beginPath();
  x.moveTo(cx, cy);
  for(var i=0;i<teeth;i++){
    x.lineTo(cx + w, cy + step*i + step/2);
    x.lineTo(cx, cy + step*(i+1));
  }
  x.lineTo(cx, cy); x.closePath(); x.fill();
  x.restore();
}

// نجمة ثمانية (زخرفة إسلامية)
function hhDrawStar8(x, cx, cy, rOuter, rInner, color, alpha){
  x.save(); x.globalAlpha = alpha||1; x.fillStyle = color;
  x.beginPath();
  for(var i=0;i<16;i++){
    var r = (i%2===0)? rOuter : rInner;
    var a = (Math.PI/8)*i - Math.PI/2;
    var px = cx + Math.cos(a)*r, py = cy + Math.sin(a)*r;
    i===0 ? x.moveTo(px,py) : x.lineTo(px,py);
  }
  x.closePath(); x.fill(); x.restore();
}

function hhRoundRect(x, rx, ry, rw, rh, rad){
  x.beginPath();
  if(x.roundRect){ x.roundRect(rx,ry,rw,rh,rad); return; }
  x.moveTo(rx+rad,ry);
  x.lineTo(rx+rw-rad,ry); x.quadraticCurveTo(rx+rw,ry,rx+rw,ry+rad);
  x.lineTo(rx+rw,ry+rh-rad); x.quadraticCurveTo(rx+rw,ry+rh,rx+rw-rad,ry+rh);
  x.lineTo(rx+rad,ry+rh); x.quadraticCurveTo(rx,ry+rh,rx,ry+rh-rad);
  x.lineTo(rx,ry+rad); x.quadraticCurveTo(rx,ry,rx+rad,ry);
  x.closePath();
}

async function hhShareCard(i){
  var s = hhGBStudents()[i]; if(!s) return;
  var D = hhDiagnoseStudent(s.name);
  await hhEnsureFonts();

  // دقة عالية: 2x للطباعة والشاشات الحادة
  var SC = 2, W = 1080, H = 1440;
  var c = document.createElement('canvas');
  c.width = W*SC; c.height = H*SC;
  var x = c.getContext('2d');
  x.scale(SC, SC);
  x.textBaseline = 'alphabetic';
  x.direction = 'rtl';

  var GOLD='#B8924A', GOLD_LT='#EAD9A8', MAROON='#5E0E26', DARK='#2B0912';
  var F = function(w,sz,fam){ return w+' '+sz+'px '+(fam||"'Cairo','Tajawal','Segoe UI',Arial,sans-serif"); };

  // ── الخلفية ──
  var g = x.createLinearGradient(0,0,W,H);
  g.addColorStop(0,'#6B1230'); g.addColorStop(.55,MAROON); g.addColorStop(1,DARK);
  x.fillStyle=g; x.fillRect(0,0,W,H);

  // زخرفة النجوم الثمانية الخافتة
  hhDrawStar8(x, 130, 200, 90, 40, GOLD, .05);
  hhDrawStar8(x, W-130, 340, 70, 32, GOLD, .05);
  hhDrawStar8(x, 150, H-260, 78, 35, GOLD, .05);
  hhDrawStar8(x, W-120, H-180, 60, 28, GOLD, .05);

  // شريط الزجزاج القطري (يمين ويسار)
  hhDrawQatarZigzag(x, 0, 0, 26, H, 9, GOLD, .22);
  x.save(); x.translate(W,0); x.scale(-1,1);
  hhDrawQatarZigzag(x, 0, 0, 26, H, 9, GOLD, .22);
  x.restore();

  // ── الإطار المزدوج ──
  x.strokeStyle=GOLD; x.lineWidth=5;
  hhRoundRect(x, 46, 46, W-92, H-92, 28); x.stroke();
  x.strokeStyle='rgba(234,217,168,.42)'; x.lineWidth=2;
  hhRoundRect(x, 62, 62, W-124, H-124, 20); x.stroke();

  x.textAlign='center';

  // ── الترويسة ──
  x.fillStyle=GOLD_LT; x.font=F(900,42);
  x.fillText('منصة المُلهِم', W/2, 146);
  x.fillStyle='rgba(234,217,168,.62)'; x.font=F(700,23);
  x.fillText('حيث يبدأ الإلهام', W/2, 184);

  // فاصل بنجمة
  x.strokeStyle='rgba(184,146,74,.6)'; x.lineWidth=2;
  x.beginPath(); x.moveTo(W/2-190,208); x.lineTo(W/2-34,208); x.stroke();
  x.beginPath(); x.moveTo(W/2+34,208); x.lineTo(W/2+190,208); x.stroke();
  hhDrawStar8(x, W/2, 208, 15, 6.5, GOLD, .95);

  // ── اسم الطالب ──
  x.fillStyle='#fff'; x.font=F(900,60);
  var nm = s.name.length>22 ? s.name.slice(0,22)+'…' : s.name;
  x.fillText(nm, W/2, 300);
  if(s.cls){
    x.fillStyle='rgba(255,255,255,.66)'; x.font=F(700,26);
    x.fillText(s.cls, W/2, 342);
  }

  // ── حلقة المؤشر ──
  var cy=520, r=132;
  x.save();
  x.shadowColor='rgba(0,0,0,.35)'; x.shadowBlur=24;
  x.beginPath(); x.arc(W/2, cy, r+16, 0, Math.PI*2);
  x.fillStyle='rgba(255,255,255,.05)'; x.fill();
  x.restore();

  x.beginPath(); x.arc(W/2, cy, r, 0, Math.PI*2);
  x.strokeStyle='rgba(255,255,255,.13)'; x.lineWidth=17; x.stroke();

  if(D.leadership!==null){
    var grad=x.createLinearGradient(W/2-r, cy-r, W/2+r, cy+r);
    grad.addColorStop(0, D.color); grad.addColorStop(1, GOLD);
    x.beginPath();
    x.arc(W/2, cy, r, -Math.PI/2, -Math.PI/2 + Math.PI*2*(D.leadership/100));
    x.strokeStyle=grad; x.lineWidth=17; x.lineCap='round'; x.stroke();

    x.fillStyle='#fff'; x.font=F(900,86);
    x.fillText(String(D.leadership), W/2, cy+22);
    x.fillStyle='rgba(255,255,255,.6)'; x.font=F(700,21);
    x.fillText('المؤشر القيادي', W/2, cy+58);
  } else {
    x.fillStyle='rgba(255,255,255,.45)'; x.font=F(900,42);
    x.fillText('·', W/2, cy+16);
  }

  // ── شارة اللقب ──
  x.font=F(900,40);
  var lvlW = x.measureText(D.level).width + 78;
  var lvlY = cy + r + 62;
  x.save();
  x.shadowColor='rgba(0,0,0,.3)'; x.shadowBlur=16;
  hhRoundRect(x, W/2-lvlW/2, lvlY-42, lvlW, 62, 31);
  var lg=x.createLinearGradient(W/2-lvlW/2, 0, W/2+lvlW/2, 0);
  lg.addColorStop(0, D.color); lg.addColorStop(1, hhShade(D.color,-18));
  x.fillStyle=lg; x.fill();
  x.restore();
  x.strokeStyle='rgba(234,217,168,.55)'; x.lineWidth=2;
  hhRoundRect(x, W/2-lvlW/2, lvlY-42, lvlW, 62, 31); x.stroke();
  x.fillStyle='#fff'; x.font=F(900,34);
  x.fillText(D.level, W/2, lvlY);

  // ── بطاقات الإحصاء ──
  var stats=[
    ['التحصيل', D.achieve!==null? D.achieve+'%':'·'],
    ['الانتظام', D.attendance!==null? D.attendance+'%':'·'],
    ['نقاط التميّز', String(D.strengths.length)]
  ];
  var bw=272, gp=26, sx=(W-(bw*3+gp*2))/2, by=lvlY+72;
  stats.forEach(function(st,idx){
    var bx=sx+idx*(bw+gp);
    hhRoundRect(x, bx, by, bw, 152, 22);
    x.fillStyle='rgba(255,255,255,.085)'; x.fill();
    x.strokeStyle='rgba(184,146,74,.42)'; x.lineWidth=2;
    hhRoundRect(x, bx, by, bw, 152, 22); x.stroke();
    x.fillStyle=GOLD_LT; x.font=F(900,50);
    x.fillText(st[1], bx+bw/2, by+82);
    x.fillStyle='rgba(255,255,255,.68)'; x.font=F(700,22);
    x.fillText(st[0], bx+bw/2, by+120);
  });

  // ── نقاط التميّز ──
  var ty = by + 216;
  if(D.strengths.length){
    x.strokeStyle='rgba(184,146,74,.35)'; x.lineWidth=1.5;
    x.beginPath(); x.moveTo(W/2-210, ty-42); x.lineTo(W/2+210, ty-42); x.stroke();
    x.fillStyle=GOLD; x.font=F(900,27);
    x.fillText('نقاط التميّز', W/2, ty);
    x.fillStyle='rgba(255,255,255,.9)'; x.font=F(700,25);
    var line = D.strengths.slice(0,3).join('   ·   ');
    x.fillText(line, W/2, ty+44);
  }

  // ── التذييل ──
  var fy = H - 150;
  x.strokeStyle='rgba(184,146,74,.45)'; x.lineWidth=2;
  x.beginPath(); x.moveTo(W/2-160, fy-46); x.lineTo(W/2-26, fy-46); x.stroke();
  x.beginPath(); x.moveTo(W/2+26, fy-46); x.lineTo(W/2+160, fy-46); x.stroke();
  hhDrawStar8(x, W/2, fy-46, 12, 5, GOLD, .9);

  x.fillStyle=GOLD_LT; x.font=F(800,26);
  x.fillText('almulhimedu.org', W/2, fy);
  x.fillStyle='rgba(255,255,255,.45)'; x.font=F(700,19);
  x.fillText(new Date().toLocaleDateString('ar-QA',{year:'numeric',month:'long',day:'numeric'}), W/2, fy+36);

  var url=c.toDataURL('image/png');
  window._hhCardURL=url; window._hhCardName=s.name;

  var html='<img src="'+url+'" style="width:100%;border-radius:14px;box-shadow:0 12px 34px rgba(0,0,0,.22);display:block;">'
    +'<div style="display:flex;gap:8px;margin-top:12px;flex-wrap:wrap;">'
    +'<button onclick="hhDownloadCard()" style="flex:1;min-width:120px;background:linear-gradient(135deg,#B8924A,#8A6D2E);color:#fff;border:none;border-radius:11px;padding:11px;font-family:Cairo;font-weight:900;font-size:.84rem;cursor:pointer;">تنزيل بدقة عالية</button>'
    +'<button onclick="hhShareCardNative()" style="background:#25d366;color:#fff;border:none;border-radius:11px;padding:11px 18px;font-family:Cairo;font-weight:900;font-size:.84rem;cursor:pointer;">مشاركة</button>'
    +'</div>'
    +'<div style="font-size:.72rem;color:#999;margin-top:9px;line-height:1.7;text-align:center;">دقة 2160×2880 · صالحة للطباعة والعرض · بالهوية القطرية</div>';
  if(typeof hhSchModal==='function') hhSchModal('بطاقة ' + s.name, html, '#B8924A');
}

function hhShade(hex, pct){
  try{
    var n=parseInt(hex.slice(1),16);
    var r=Math.max(0,Math.min(255,(n>>16)+pct));
    var gg=Math.max(0,Math.min(255,((n>>8)&255)+pct));
    var b=Math.max(0,Math.min(255,(n&255)+pct));
    return '#'+((1<<24)+(r<<16)+(gg<<8)+b).toString(16).slice(1);
  }catch(e){ return hex; }
}

function hhDownloadCard(){
  if(!window._hhCardURL) return;
  var a=document.createElement('a');
  a.href=window._hhCardURL;
  a.download='almulhim_'+(window._hhCardName||'card').replace(/\s+/g,'_')+'.png';
  a.click();
  if(typeof toast==='function') toast('نُزّلت البطاقة','success');
}
async function hhShareCardNative(){
  if(!window._hhCardURL) return;
  try{
    var res=await fetch(window._hhCardURL);
    var blob=await res.blob();
    var file=new File([blob], 'almulhim.png', {type:'image/png'});
    if(navigator.canShare && navigator.canShare({files:[file]})){
      await navigator.share({ files:[file], title:'بطاقة '+(window._hhCardName||''), text:'من منصة المُلهِم' });
      return;
    }
  }catch(e){}
  hhDownloadCard();
}

// ═══════════════════════════════════════════════════════════════════
// القصة التعليمية التفاعلية · تعلّم بالسرد واتخاذ القرار
// ═══════════════════════════════════════════════════════════════════
var HH_SEAL_KEY = 'hh_platform_seal';
var _hhSeal = 'classic';   // classic | star | pearl | wave

function hhSealLoad(){
  try{ var v=localStorage.getItem(HH_SEAL_KEY); if(v) _hhSeal=v; }catch(e){}
  try{
    if(typeof firebase!=='undefined' && firebase.firestore){
      firebase.firestore().collection('platform_settings').doc('cert_issuer').get()
        .then(function(d){ if(d.exists && d.data().seal){ _hhSeal=d.data().seal;
          try{ localStorage.setItem(HH_SEAL_KEY,_hhSeal); }catch(e){} } }).catch(function(){});
    }
  }catch(e){}
  return _hhSeal;
}
hhSealLoad();

// نص منحنٍ حول دائرة
function hhArcText(x, text, cx, cy, radius, startAngle, endAngle, font, color, flip){
  // العربية متصلة الحروف · تقطيعها يفسدها. نرسم النص كوحدة على قوس مائل بسيط.
  x.save();
  x.fillStyle=color; x.font=font; x.textAlign='center'; x.textBaseline='middle';
  x.direction='rtl';
  var mid = (startAngle + endAngle) / 2;
  x.translate(cx + Math.cos(mid)*radius, cy + Math.sin(mid)*radius);
  x.rotate(flip ? mid - Math.PI/2 : mid + Math.PI/2);
  x.fillText(text, 0, 0);
  x.restore();
}

/**
 * يرسم ختم المنصة
 * @param design classic | star | pearl | wave
 */
// ═══════════════════════════════════════════════════════════════════
// ختم المنصة الأزرق · تطريز إسلامي + نص عربي وإنجليزي
// ═══════════════════════════════════════════════════════════════════
var HH_SEAL_BLUE  = '#1F4E79';
var HH_SEAL_BLUE2 = '#12304d';
var HH_SEAL_LT    = '#5b8fc7';

// وردة إسلامية ثمانية البتلات (تطريز)
function hhDrawIslamicRosette(x, cx, cy, r, color, lw, petals){
  petals = petals || 8;
  x.save();
  x.strokeStyle = color; x.lineWidth = lw || Math.max(1, r*0.045);
  x.lineJoin='round';
  for(var i=0;i<petals;i++){
    var a = (Math.PI*2/petals)*i;
    x.beginPath();
    // بتلة: قوسان متقابلان
    var x0 = cx + Math.cos(a)*r*0.16, y0 = cy + Math.sin(a)*r*0.16;
    var x1 = cx + Math.cos(a)*r,      y1 = cy + Math.sin(a)*r;
    var pa = a + Math.PI/petals, pb = a - Math.PI/petals;
    var cx1 = cx + Math.cos(pa)*r*0.72, cy1 = cy + Math.sin(pa)*r*0.72;
    var cx2 = cx + Math.cos(pb)*r*0.72, cy2 = cy + Math.sin(pb)*r*0.72;
    x.moveTo(x0,y0); x.quadraticCurveTo(cx1,cy1,x1,y1);
    x.quadraticCurveTo(cx2,cy2,x0,y0);
    x.stroke();
  }
  x.restore();
}

// شريط تطريز: نقاط ومعينات متناوبة حول الحلقة
function hhDrawEmbroideryBand(x, cx, cy, r, count, color, size){
  x.save(); x.fillStyle=color;
  for(var i=0;i<count;i++){
    var a=(Math.PI*2/count)*i;
    var px=cx+Math.cos(a)*r, py=cy+Math.sin(a)*r;
    x.save(); x.translate(px,py); x.rotate(a+Math.PI/4);
    if(i%2===0){
      x.fillRect(-size/2,-size/2,size,size);           // معيّن
    } else {
      x.beginPath(); x.arc(0,0,size*0.42,0,Math.PI*2); x.fill();  // نقطة
    }
    x.restore();
  }
  x.restore();
}

// تعرّجات دقيقة (نمط الجدائل الإسلامي)
function hhDrawInterlace(x, cx, cy, r, teeth, color, lw){
  x.save(); x.strokeStyle=color; x.lineWidth=lw; x.beginPath();
  for(var i=0;i<=teeth*2;i++){
    var a=(Math.PI*2/(teeth*2))*i;
    var rr = (i%2===0) ? r : r*0.90;
    var px=cx+Math.cos(a)*rr, py=cy+Math.sin(a)*rr;
    i===0 ? x.moveTo(px,py) : x.lineTo(px,py);
  }
  x.closePath(); x.stroke(); x.restore();
}

/**
 * الختم الرسمي الأزرق
 */
/**
 * ختم المنصة · نسخة شفافة راقية
 * لا خلفيات مصمتة · زخرفة خفيفة · خطوط نظيفة
 */
function hhDrawSeal(x, cx, cy, R, color, dark, design){
  var B  = HH_SEAL_BLUE;    // #1F4E79
  var B2 = HH_SEAL_BLUE2;   // #12304d
  var LT = HH_SEAL_LT;      // #5b8fc7
  var F  = function(w,sz){ return w+' '+sz+"px 'Cairo','Tajawal',Arial,sans-serif"; };
  var FE = function(w,sz){ return w+' '+sz+"px 'Cairo',Georgia,'Times New Roman',serif"; };
  x.save();
  x.textAlign='center'; x.textBaseline='alphabetic';
  x.lineJoin='round'; x.lineCap='round';

  // ══ لا خلفية مصمتة · الختم شفاف تماماً ══

  // ── 1) الحلقة الخارجية: خطان رفيعان أنيقان ──
  x.beginPath(); x.arc(cx,cy,R*0.992,0,Math.PI*2);
  x.strokeStyle=B2; x.lineWidth=R*0.042; x.stroke();

  x.beginPath(); x.arc(cx,cy,R*0.925,0,Math.PI*2);
  x.strokeStyle=B; x.lineWidth=R*0.016; x.stroke();

  // ── 2) زخرفة خفيفة: نقاط صغيرة متباعدة (بلا ثِقل) ──
  (function(){
    var n=36;
    for(var i=0;i<n;i++){
      var a=(Math.PI*2/n)*i;
      x.beginPath();
      x.arc(cx+Math.cos(a)*R*0.958, cy+Math.sin(a)*R*0.958, R*0.014, 0, Math.PI*2);
      x.fillStyle= (i%3===0) ? B2 : B;
      x.globalAlpha = (i%3===0) ? 1 : .7;
      x.fill();
    }
    x.globalAlpha=1;
  })();

  // ── 3) حلقة النص: حدّان رفيعان فقط (بلا تعبئة) ──
  x.beginPath(); x.arc(cx,cy,R*0.810,0,Math.PI*2);
  x.strokeStyle=B; x.lineWidth=R*0.019; x.stroke();
  x.beginPath(); x.arc(cx,cy,R*0.555,0,Math.PI*2);
  x.strokeStyle=B; x.lineWidth=R*0.019; x.stroke();

  // ── 4) النصوص الدائرية ──
  var rText = R*0.685;
  function _arcTxt(txt, startA, endA, fontSize, reverse){
    var chars = txt.split('');
    var step = (endA - startA) / chars.length;
    x.save();
    x.fillStyle=B2; x.font=FE(800, fontSize);
    x.textAlign='center'; x.textBaseline='middle'; x.direction='ltr';
    for(var k=0;k<chars.length;k++){
      var ch = reverse ? chars[chars.length-1-k] : chars[k];
      var a = startA + step*k + step/2;
      x.save();
      x.translate(cx + Math.cos(a)*rText, cy + Math.sin(a)*rText);
      x.rotate(reverse ? a - Math.PI/2 : a + Math.PI/2);
      x.fillText(ch, 0, 0);
      x.restore();
    }
    x.restore();
  }
  _arcTxt('A L - M U L H I M   E D U C A T I O N A L', Math.PI*0.14, Math.PI*0.86, R*0.098, true);
  _arcTxt('T H E   B E S T', Math.PI*1.31, Math.PI*1.69, R*0.120, false);

  // ── 5) فواصل جانبية: معيّنان صغيران أنيقان ──
  [-1,1].forEach(function(sgn){
    var px=cx+sgn*rText, py=cy;
    x.save(); x.translate(px,py); x.rotate(Math.PI/4);
    x.beginPath(); x.rect(-R*0.026,-R*0.026, R*0.052, R*0.052);
    x.fillStyle=B2; x.globalAlpha=1; x.fill();
    x.restore();
  });
  x.globalAlpha=1;

  // ── 6) القلب: حلقة رفيعة بلا تعبئة ──
  x.beginPath(); x.arc(cx,cy,R*0.520,0,Math.PI*2);
  x.strokeStyle=B2; x.lineWidth=R*0.034; x.stroke();

  // (لا زخرفة خلف الاسم · الجوهر وحده)

  // ── 8) الاسم في المركز ──
  x.fillStyle=B2; x.font=F(900, R*0.33); x.direction='rtl';
  x.textAlign='center'; x.textBaseline='alphabetic';
  x.fillText('المُلهِم', cx, cy + R*0.025);

  // فاصل رفيع
  x.strokeStyle=B; x.globalAlpha=.85; x.lineWidth=R*0.014;
  x.beginPath(); x.moveTo(cx-R*0.165, cy+R*0.115); x.lineTo(cx+R*0.165, cy+R*0.115); x.stroke();
  x.globalAlpha=1;

  x.fillStyle=B2; x.font=FE(800, R*0.112); x.direction='ltr';
  x.fillText('AL-MULHIM', cx, cy + R*0.255);

  x.restore();
}

// ── معاينة الأختام واختيارها ──
function hhSealPicker(){
  if(!(typeof hhIsAdmin==='function' && hhIsAdmin())){
    if(typeof toast==='function') toast('اختيار ختم المنصة صلاحية إدارية','error'); return;
  }
  hhSealLoad();
  var designs=[
    ['classic','الكلاسيكي','حلقتان ونص دائري ونجمة ثمانية'],
    ['star','النجمة','نجمة ثمانية إسلامية محيطة'],
    ['pearl','اللؤلؤة','حلقة لؤلؤية · رمز قطر البحري'],
    ['wave','الموج','زجزاج العلم القطري داخل الحلقة']
  ];
  var old=document.getElementById('hh-seal'); if(old) old.remove();
  var ov=document.createElement('div'); ov.id='hh-seal';
  ov.style.cssText='position:fixed;inset:0;background:rgba(30,6,15,.76);z-index:999996;display:flex;align-items:flex-start;justify-content:center;padding:16px;overflow-y:auto;direction:rtl;font-family:Cairo,Tajawal,sans-serif;';
  ov.innerHTML='<div style="background:#FAFBFD;border:2px solid #B8924A;border-radius:20px;max-width:620px;width:100%;overflow:hidden;margin-bottom:22px;">'
    +'<div style="background:linear-gradient(135deg,#8A6D2E,#B8924A);color:#fff;padding:15px 18px;display:flex;justify-content:space-between;align-items:center;">'
    +'<div><div style="font-weight:900;font-size:1rem;">ختم المنصة</div>'
    +'<div style="font-size:.73rem;opacity:.87;margin-top:2px;">اختر التصميم · يظهر على كل الشهادات</div></div>'
    +'<button onclick="hhCloseSeal()" style="background:none;border:none;color:#fff;font-size:1.15rem;cursor:pointer;">✕</button></div>'
    +'<div style="padding:16px 18px;">'
    +'<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:12px;" id="seal-grid">'
    + designs.map(function(d){
        var on = (_hhSeal===d[0]);
        return '<div onclick="hhPickSeal(\''+d[0]+'\')" style="background:#fff;border:2.5px solid '+(on?'#B8924A':'#E3D9C6')+';border-radius:16px;padding:14px;text-align:center;cursor:pointer;transition:all .15s;'+(on?'box-shadow:0 6px 20px rgba(184,146,74,.28);':'')+'">'
          +'<canvas id="seal-cv-'+d[0]+'" width="340" height="340" style="width:150px;height:150px;"></canvas>'
          +'<div style="font-weight:900;font-size:.86rem;color:'+(on?'#8A6D2E':'#5E0E26')+';margin-top:6px;">'+esc(d[1])
          + (on?' <span style="background:#3D6B53;color:#fff;border-radius:6px;padding:1px 8px;font-size:.6rem;">مُفعّل</span>':'')+'</div>'
          +'<div style="font-size:.7rem;color:#999;font-weight:700;margin-top:3px;line-height:1.6;">'+esc(d[2])+'</div>'
          +'</div>';
      }).join('')
    +'</div>'
    +'<div id="seal-status" style="font-size:.76rem;font-weight:800;min-height:18px;margin-top:10px;text-align:center;"></div>'
    +'</div></div>';
  document.body.appendChild(ov);
  // رسم المعاينات
  setTimeout(function(){
    designs.forEach(function(d){
      var cv=document.getElementById('seal-cv-'+d[0]); if(!cv) return;
      var x=cv.getContext('2d'); x.clearRect(0,0,340,340);
      var bg=x.createLinearGradient(0,0,340,340);
      bg.addColorStop(0,'#FFFDF9'); bg.addColorStop(1,'#F8F1E2');
      x.fillStyle=bg; x.fillRect(0,0,340,340);
      hhDrawSeal(x, 170, 170, 130, '#B8924A', '#8A6D2E', d[0]);
    });
  }, 60);
}
function hhCloseSeal(){ var e=document.getElementById('hh-seal'); if(e) e.remove(); }
async function hhPickSeal(id){
  if(!(typeof hhIsAdmin==='function' && hhIsAdmin())) return;
  _hhSeal=id;
  try{ localStorage.setItem(HH_SEAL_KEY,id); }catch(e){}
  var st=document.getElementById('seal-status');
  if(st){ st.textContent='جاري الحفظ...'; st.style.color='#8A6D2E'; }
  try{
    await firebase.firestore().collection('platform_settings').doc('cert_issuer')
      .set({ seal:id, updatedBy:currentUser.email, updatedAt:new Date().toISOString() }, {merge:true});
    if(st){ st.textContent='حُفظ الختم وسرى على كل الشهادات'; st.style.color='#3D6B53'; }
  }catch(e){
    if(st){ st.textContent='حُفظ محلياً · تعذرت المزامنة السحابية'; st.style.color='#b5801f'; }
  }
  if(typeof toast==='function') toast('فُعّل الختم','success');
  hhSealPicker();
}

// ═══════════════════════════════════════════════════════════════════
// تصدير PDF · نموذج شهادة مخصص · الختم إلزامي على كل الشهادات
// ═══════════════════════════════════════════════════════════════════
// ═══════════════════════════════════════════════════════════════════
// مكتبة نماذج الشهادات · نماذج متعددة · PDF وصور · الختم إلزامي
// ═══════════════════════════════════════════════════════════════════
var _HH_TPL_LIB_KEY = 'hh_cert_templates';
var _hhCertTemplates = [];   // [{id,name,img,w,h,sealX,sealY,sealR,fields}]

function hhTplLibLoad(){
  try{
    var raw=localStorage.getItem(_HH_TPL_LIB_KEY);
    if(raw) _hhCertTemplates=JSON.parse(raw)||[];
  }catch(e){ _hhCertTemplates=[]; }
  try{
    if(typeof firebase!=='undefined' && firebase.firestore){
      firebase.firestore().collection('cert_templates').limit(20).get()
        .then(function(snap){
          var arr=[]; snap.forEach(function(d){ arr.push(Object.assign({id:d.id}, d.data())); });
          if(arr.length){
            arr.sort(function(a,b){ return String(a.name||'').localeCompare(String(b.name||'')); });
            _hhCertTemplates=arr;
            try{ localStorage.setItem(_HH_TPL_LIB_KEY, JSON.stringify(arr)); }catch(e){}
          }
        }).catch(function(){});
    }
  }catch(e){}
  return _hhCertTemplates;
}
hhTplLibLoad();

function hhTplById(id){
  for(var i=0;i<_hhCertTemplates.length;i++){ if(_hhCertTemplates[i].id===id) return _hhCertTemplates[i]; }
  return null;
}

// ── تحويل PDF إلى صورة (الصفحة الأولى) ──
function hhEnsurePdfJs(){
  return new Promise(function(resolve){
    if(window.pdfjsLib){ resolve(true); return; }
    var s=document.createElement('script');
    s.src='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js';
    s.onload=function(){
      try{ window.pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js'; }catch(e){}
      resolve(!!window.pdfjsLib);
    };
    s.onerror=function(){ resolve(false); };
    document.head.appendChild(s);
  });
}
async function hhPdfToImage(file){
  var loaded=await hhEnsurePdfJs();
  if(!loaded) throw new Error('PDF_LIB');
  var buf=await file.arrayBuffer();
  var pdf=await window.pdfjsLib.getDocument({data:buf}).promise;
  var page=await pdf.getPage(1);
  var vp=page.getViewport({scale:2});
  var c=document.createElement('canvas');
  c.width=vp.width; c.height=vp.height;
  await page.render({canvasContext:c.getContext('2d'), viewport:vp}).promise;
  return c;
}

// ── مدير المكتبة ──
function hhCertTemplateManager(){
  if(!(typeof hhIsAdmin==='function' && hhIsAdmin())){
    if(typeof toast==='function') toast('إدارة النماذج صلاحية إدارية','error'); return;
  }
  hhTplLibLoad();
  var cards = _hhCertTemplates.length ? _hhCertTemplates.map(function(T,i){
    return '<div style="background:#fff;border:1.5px solid #E3D9C6;border-right:4px solid #8A6D2E;border-radius:12px;padding:11px 13px;margin-bottom:8px;">'
      +'<div style="display:flex;gap:10px;align-items:center;flex-wrap:wrap;">'
      +'<img src="'+T.img+'" style="width:90px;height:64px;object-fit:cover;border-radius:8px;border:1px solid #eee;">'
      +'<div style="flex:1;min-width:0;">'
      +'<div style="font-weight:900;font-size:.83rem;color:#5E0E26;">'+esc(T.name||('نموذج '+(i+1)))+'</div>'
      +'<div style="font-size:.69rem;color:#999;margin-top:2px;">'+T.w+'×'+T.h+' · ختم '+Math.round(T.sealR*100)+'%</div></div>'
      +'<div style="display:flex;gap:5px;flex-wrap:wrap;">'
      +'<button onclick="hhTplEdit(\''+T.id+'\')" style="background:#1F4E79;color:#fff;border:none;border-radius:8px;padding:5px 11px;font-family:Cairo;font-weight:900;font-size:.67rem;cursor:pointer;">ضبط</button>'
      +'<button onclick="hhTplPreview(\''+T.id+'\')" style="background:#EBF2EE;color:#3D6B53;border:1px solid #3D6B53;border-radius:8px;padding:5px 11px;font-family:Cairo;font-weight:900;font-size:.67rem;cursor:pointer;">معاينة</button>'
      +'<button onclick="hhTplDelete(\''+T.id+'\')" style="background:#fff;color:#c0392b;border:1px solid #e0c0c0;border-radius:8px;padding:5px 10px;font-family:Cairo;font-weight:900;font-size:.67rem;cursor:pointer;">حذف</button>'
      +'</div></div></div>';
  }).join('') : '<div style="text-align:center;color:#999;padding:18px;font-weight:700;font-size:.81rem;line-height:1.9;">لا نماذج بعد · ارفع نموذجك الأول.<br><span style="font-size:.73rem;color:#bbb;">تُستخدم شهادة المنصة الافتراضية حالياً.</span></div>';

  var html='<div style="font-size:.78rem;color:#666;line-height:1.9;margin-bottom:12px;">'
    +'ارفع نماذج شهاداتك (PDF أو صورة). تُحفظ في المكتبة باسم «نموذج 1، 2...» وتختار منها عند الإصدار. '
    +'<b style="color:#8A1538;">ختم المنصة يُضاف إلزامياً على كل نموذج.</b></div>'
    +'<div style="background:#fff;border:1.5px solid #C9B37E;border-radius:12px;padding:12px;margin-bottom:13px;">'
    +'<div style="font-weight:900;font-size:.82rem;color:#8A6D2E;margin-bottom:8px;">رفع نموذج جديد</div>'
    +'<input id="tpl-name" placeholder="اسم النموذج (اختياري)" style="width:100%;border:1.5px solid #E3D9C6;border-radius:9px;padding:8px 11px;font-family:Cairo;font-size:.8rem;box-sizing:border-box;margin-bottom:8px;">'
    +'<input type="file" id="tpl-file" accept="image/png,image/jpeg,application/pdf,.pdf,.png,.jpg,.jpeg" onchange="hhTplUpload(this)" style="width:100%;font-family:Cairo;font-size:.77rem;">'
    +'<div style="font-size:.68rem;color:#aaa;margin-top:5px;line-height:1.7;">PDF أو PNG أو JPG · تُحوَّل الصفحة الأولى تلقائياً</div>'
    +'<div id="tpl-status" style="font-size:.74rem;font-weight:800;min-height:16px;margin-top:6px;"></div>'
    +'</div>'
    +'<div style="font-weight:900;font-size:.85rem;color:#5E0E26;margin-bottom:8px;">مكتبة النماذج ('+_hhCertTemplates.length+')</div>'
    + cards;
  if(typeof hhSchModal==='function') hhSchModal('نماذج الشهادات', html, '#8A6D2E');
}

async function hhTplUpload(input){
  var f=input.files&&input.files[0]; if(!f) return;
  var st=document.getElementById('tpl-status');
  var nameVal=((document.getElementById('tpl-name')||{}).value||'').trim();
  if(st){ st.textContent='جاري المعالجة...'; st.style.color='#8A6D2E'; }
  try{
    var canvas;
    var isPdf = /\.pdf$/i.test(f.name) || f.type==='application/pdf';
    if(isPdf){
      if(st) st.textContent='جاري تحويل PDF...';
      canvas = await hhPdfToImage(f);
    } else {
      canvas = await new Promise(function(res,rej){
        var r=new FileReader();
        r.onload=function(e){
          var img=new Image();
          img.onload=function(){
            var c=document.createElement('canvas');
            c.width=img.width; c.height=img.height;
            c.getContext('2d').drawImage(img,0,0);
            res(c);
          };
          img.onerror=rej; img.src=String(e.target.result);
        };
        r.onerror=rej; r.readAsDataURL(f);
      });
    }
    // تصغير للحد الآمن
    var maxW=1700;
    var out=canvas;
    if(canvas.width>maxW){
      var sc=maxW/canvas.width;
      var c2=document.createElement('canvas');
      c2.width=Math.round(canvas.width*sc); c2.height=Math.round(canvas.height*sc);
      c2.getContext('2d').drawImage(canvas,0,0,c2.width,c2.height);
      out=c2;
    }
    var url=out.toDataURL('image/jpeg',0.86);
    if(url.length>820*1024) url=out.toDataURL('image/jpeg',0.70);
    if(url.length>900*1024){
      if(st){ st.textContent='الملف كبير جداً · استخدم نسخة أصغر'; st.style.color='#c0392b'; }
      return;
    }
    var n=_hhCertTemplates.length+1;
    var tpl={
      id:'tpl_'+Date.now().toString(36),
      name: nameVal || ('نموذج '+n),
      img:url, w:out.width, h:out.height,
      sealX:0.30, sealY:0.78, sealR:0.075
    };
    _hhCertTemplates.push(tpl);
    await hhTplSaveOne(tpl);
    if(st){ st.textContent='أُضيف «'+tpl.name+'» ('+Math.round(url.length/1024)+'KB)'; st.style.color='#3D6B53'; }
    if(typeof hhLogActivity==='function') hhLogActivity('generate','نموذج شهادة: '+tpl.name);
    setTimeout(hhCertTemplateManager, 800);
  }catch(e){
    if(st){
      st.textContent = (String(e.message)==='PDF_LIB')
        ? 'تعذر تحميل قارئ PDF · حوّل الملف لصورة أو تحقق من الاتصال'
        : 'تعذرت المعالجة · جرّب ملفاً آخر';
      st.style.color='#c0392b';
    }
  }
}
async function hhTplSaveOne(tpl){
  try{ localStorage.setItem(_HH_TPL_LIB_KEY, JSON.stringify(_hhCertTemplates)); }catch(e){}
  try{
    await firebase.firestore().collection('cert_templates').doc(tpl.id).set({
      name:tpl.name, img:tpl.img, w:tpl.w, h:tpl.h,
      sealX:tpl.sealX, sealY:tpl.sealY, sealR:tpl.sealR,
      updatedBy:currentUser.email, updatedAt:new Date().toISOString()
    });
  }catch(e){ if(typeof toast==='function') toast('حُفظ محلياً · تعذرت المزامنة','warn'); }
}
async function hhTplDelete(id){
  if(!confirm('حذف هذا النموذج؟')) return;
  _hhCertTemplates=_hhCertTemplates.filter(function(t){ return t.id!==id; });
  try{ localStorage.setItem(_HH_TPL_LIB_KEY, JSON.stringify(_hhCertTemplates)); }catch(e){}
  try{ await firebase.firestore().collection('cert_templates').doc(id).delete(); }catch(e){}
  hhCertTemplateManager();
}
function hhTplEdit(id){
  var T=hhTplById(id); if(!T) return;
  var html='<img src="'+T.img+'" style="width:100%;border-radius:10px;border:1.5px solid #E3D9C6;margin-bottom:11px;">'
    +'<div style="font-size:.75rem;font-weight:800;color:#8A6D2E;margin-bottom:4px;">اسم النموذج</div>'
    +'<input id="te-name" value="'+esc(T.name||'')+'" style="width:100%;border:1.5px solid #E3D9C6;border-radius:9px;padding:8px 11px;font-family:Cairo;font-size:.82rem;box-sizing:border-box;margin-bottom:10px;">'
    +'<div style="font-weight:900;font-size:.8rem;color:#5E0E26;margin-bottom:7px;">موضع الختم</div>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;margin-bottom:10px;">'
    +'<div><div style="font-size:.7rem;color:#888;margin-bottom:3px;">أفقياً %</div>'
    +'<input id="te-x" type="number" min="0" max="100" value="'+Math.round(T.sealX*100)+'" style="width:100%;border:1.5px solid #E3D9C6;border-radius:8px;padding:6px 9px;font-family:Cairo;font-size:.8rem;box-sizing:border-box;"></div>'
    +'<div><div style="font-size:.7rem;color:#888;margin-bottom:3px;">رأسياً %</div>'
    +'<input id="te-y" type="number" min="0" max="100" value="'+Math.round(T.sealY*100)+'" style="width:100%;border:1.5px solid #E3D9C6;border-radius:8px;padding:6px 9px;font-family:Cairo;font-size:.8rem;box-sizing:border-box;"></div>'
    +'<div><div style="font-size:.7rem;color:#888;margin-bottom:3px;">الحجم %</div>'
    +'<input id="te-r" type="number" min="3" max="25" value="'+Math.round(T.sealR*100)+'" style="width:100%;border:1.5px solid #E3D9C6;border-radius:8px;padding:6px 9px;font-family:Cairo;font-size:.8rem;box-sizing:border-box;"></div>'
    +'</div>'
    +'<div style="display:flex;gap:8px;flex-wrap:wrap;">'
    +'<button onclick="hhTplSavePos(\''+id+'\')" style="flex:1;background:linear-gradient(135deg,#1F4E79,#12304d);color:#fff;border:none;border-radius:10px;padding:9px;font-family:Cairo;font-weight:900;font-size:.8rem;cursor:pointer;">حفظ</button>'
    +'<button onclick="hhTplPreview(\''+id+'\')" style="background:#EBF2EE;color:#3D6B53;border:1.5px solid #3D6B53;border-radius:10px;padding:9px 16px;font-family:Cairo;font-weight:900;font-size:.8rem;cursor:pointer;">معاينة</button>'
    +'</div>';
  if(typeof hhSchModal==='function') hhSchModal('ضبط: '+(T.name||''), html, '#1F4E79');
}
async function hhTplSavePos(id){
  var T=hhTplById(id); if(!T) return;
  var g=function(i){ var e=document.getElementById(i); return e? parseFloat(e.value):null; };
  var nm=(document.getElementById('te-name')||{}).value;
  if(nm && nm.trim()) T.name=nm.trim();
  var xx=g('te-x'), yy=g('te-y'), rr=g('te-r');
  if(xx!=null) T.sealX=Math.max(0,Math.min(100,xx))/100;
  if(yy!=null) T.sealY=Math.max(0,Math.min(100,yy))/100;
  if(rr!=null) T.sealR=Math.max(3,Math.min(25,rr))/100;
  await hhTplSaveOne(T);
  if(typeof toast==='function') toast('حُفظ النموذج','success');
  hhCertTemplateManager();
}
async function hhTplPreview(id){
  var T=hhTplById(id); if(!T) return;
  var url=await hhRenderTemplateCert({name:'اسم الطالب', reason:'المادة الدراسية', score:'95', teacher:'المعلّم', serial:'ALM-XXXXXX'}, T);
  if(!url) return;
  var html='<img src="'+url+'" style="width:100%;border-radius:11px;border:1.5px solid #E3D9C6;">'
    +'<div style="font-size:.73rem;color:#999;margin-top:8px;text-align:center;line-height:1.7;">ختم المنصة مضاف إلزامياً في الموضع المحدد.</div>';
  if(typeof hhSchModal==='function') hhSchModal('معاينة: '+(T.name||''), html, '#3D6B53');
}

// ── الرسم على نموذج محدد (الختم إلزامي) ──
function hhRenderTemplateCert(o, T){
  return new Promise(function(resolve){
    T = T || (o && o._tpl) || null;
    if(!T){ resolve(null); return; }
    var img=new Image();
    img.onload=function(){
      var SC=2, W=T.w, H=T.h;
      var c=document.createElement('canvas'); c.width=W*SC; c.height=H*SC;
      var x=c.getContext('2d'); x.scale(SC,SC);
      x.drawImage(img,0,0,W,H);
      x.direction='rtl'; x.textAlign='center';
      var F=function(w,sz){ return w+' '+sz+"px 'Cairo','Tajawal',Arial,sans-serif"; };
      var fs=Math.round(H*0.062);
      x.font=F(900,fs); x.fillStyle='#3D0918';
      while(x.measureText(o.name).width > W*0.72 && fs>18){ fs-=2; x.font=F(900,fs); }
      x.fillText(o.name, W/2, H*0.47);
      if(o.reason){ x.fillStyle='#5E0E26'; x.font=F(800,Math.round(H*0.028)); x.fillText(o.reason, W/2, H*0.56); }
      if(o.score){ x.fillStyle='#8A6D2E'; x.font=F(900,Math.round(H*0.034)); x.fillText(o.score+'%', W/2, H*0.635); }
      if(o.teacher){ x.fillStyle='#5E0E26'; x.font=F(800,Math.round(H*0.021)); x.fillText(o.teacher, W*0.76, H*0.855); }
      x.fillStyle='rgba(94,14,38,.75)'; x.font=F(700,Math.round(H*0.019));
      x.fillText(new Date().toLocaleDateString('ar-QA',{year:'numeric',month:'long',day:'numeric'}), W*0.30, H*0.855);
      // ═══ الختم إلزامي · لا يمكن تعطيله ═══
      if(typeof hhDrawSeal==='function'){
        hhDrawSeal(x, W*T.sealX, H*T.sealY, Math.round(Math.min(W,H)*T.sealR), '#B8924A','#8A6D2E','classic');
      }
      if(o.serial){
        x.fillStyle='rgba(94,14,38,.4)'; x.font=F(700,Math.round(H*0.014));

      }
      resolve(c.toDataURL('image/png'));
    };
    img.onerror=function(){ resolve(null); };
    img.src=T.img;
  });
}

// ── تصدير PDF ──
function hhEnsureJsPDF(){
  return new Promise(function(resolve){
    if(window.jspdf && window.jspdf.jsPDF){ resolve(true); return; }
    var s=document.createElement('script');
    s.src='https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js';
    s.onload=function(){ resolve(!!(window.jspdf && window.jspdf.jsPDF)); };
    s.onerror=function(){ resolve(false); };
    document.head.appendChild(s);
  });
}
// احتياط: طباعة إلى PDF عبر نافذة الطباعة (يعمل دون إنترنت)
function hhCertPDFFallback(){
  if(!window._hhCertURL) return;
  var img=new Image();
  img.onload=function(){
    var landscape = img.width >= img.height;
    var w=window.open('','_blank');
    w.document.write('<html><head><meta charset="utf-8"><title>شهادة</title>'
      +'<style>@page{size:A4 '+(landscape?'landscape':'portrait')+';margin:0}'
      +'html,body{margin:0;padding:0;height:100%}'
      +'img{width:100%;height:100%;object-fit:contain;display:block}</style></head><body>'
      +'<img src="'+window._hhCertURL+'"></body></html>');
    w.document.close();
    setTimeout(function(){ try{ w.print(); }catch(e){} }, 800);
    if(typeof toast==='function') toast('اختر «حفظ كـ PDF» من نافذة الطباعة','info');
  };
  img.src=window._hhCertURL;
}

async function hhCertPDF(){
  if(!window._hhCertURL){ if(typeof toast==='function') toast('أصدر الشهادة أولاً','warn'); return; }
  if(typeof toast==='function') toast('جاري تجهيز PDF...','info');
  var loaded=await hhEnsureJsPDF();
  if(!loaded){
    // احتياط تلقائي · لا تفشل أبداً
    hhCertPDFFallback();
    return;
  }
  try{
    var img=new Image();
    await new Promise(function(res,rej){ img.onload=res; img.onerror=rej; img.src=window._hhCertURL; });
    var landscape = img.width >= img.height;
    var jsPDF=window.jspdf.jsPDF;
    var pdf=new jsPDF({ orientation: landscape?'landscape':'portrait', unit:'mm', format:'a4' });
    var pw=pdf.internal.pageSize.getWidth();
    var ph=pdf.internal.pageSize.getHeight();
    // ملء الصفحة مع الحفاظ على النسبة
    var ratio=img.width/img.height;
    var w=pw, h=pw/ratio;
    if(h>ph){ h=ph; w=ph*ratio; }
    var ox=(pw-w)/2, oy=(ph-h)/2;
    pdf.addImage(window._hhCertURL, 'PNG', ox, oy, w, h, undefined, 'FAST');
    pdf.save('certificate_'+String(window._hhCertName||'student').replace(/\s+/g,'_')+'.pdf');
    if(typeof toast==='function') toast('نُزّلت الشهادة PDF','success');
    if(typeof hhLogActivity==='function') hhLogActivity('generate','شهادة PDF: '+(window._hhCertName||''));
  }catch(e){
    hhCertPDFFallback();
  }
}

