// ── إعدادات الجهة المُصدِرة: يملكها الأدمن فقط ──
var _HH_CERT_ISSUER_KEY = 'hh_cert_issuer';
var _hhCertIssuer = { org:'منصة المُلهِم', sub:'منصة تربوية قطرية', locked:true };

function hhCertLoadIssuer(){
  // المصدر الموثوق: السحابة (يكتبها الأدمن فقط عبر قواعد Firestore)
  try{
    var raw=localStorage.getItem(_HH_CERT_ISSUER_KEY);
    if(raw){ var d=JSON.parse(raw); if(d && d.org) _hhCertIssuer=d; }
  }catch(e){}
  try{
    if(typeof firebase!=='undefined' && firebase.firestore){
      firebase.firestore().collection('platform_settings').doc('cert_issuer').get()
        .then(function(doc){
          if(doc.exists && doc.data().org){
            _hhCertIssuer={ org:doc.data().org, sub:doc.data().sub||'', locked:true };
            try{ localStorage.setItem(_HH_CERT_ISSUER_KEY, JSON.stringify(_hhCertIssuer)); }catch(e){}
          }
        }).catch(function(){});
    }
  }catch(e){}
  return _hhCertIssuer;
}
hhCertLoadIssuer();

