function launchConfetti(){
  const canvas=document.getElementById('confetti-canvas');
  if(!canvas)return;
  canvas.style.display='block';
  canvas.width=window.innerWidth;
  canvas.height=window.innerHeight;
  const ctx=canvas.getContext('2d');
  const pieces=[];
  const colors=['#ffd700','#ff4444','#44ff44','#4444ff','#ff44ff','#44ffff','#ff8800','#ffffff'];
  for(let i=0;i<160;i++){
    pieces.push({
      x:Math.random()*canvas.width,
      y:-20-Math.random()*200,
      w:8+Math.random()*8,
      h:4+Math.random()*6,
      color:colors[Math.floor(Math.random()*colors.length)],
      vx:(Math.random()-0.5)*4,
      vy:3+Math.random()*4,
      angle:Math.random()*360,
      va:(Math.random()-0.5)*8,
      opacity:1
    });
  }
  let frame=0;
  function draw(){
    ctx.clearRect(0,0,canvas.width,canvas.height);
    pieces.forEach(p=>{
      ctx.save();
      ctx.globalAlpha=p.opacity;
      ctx.translate(p.x,p.y);
      ctx.rotate(p.angle*Math.PI/180);
      ctx.fillStyle=p.color;
      ctx.fillRect(-p.w/2,-p.h/2,p.w,p.h);
      ctx.restore();
      p.x+=p.vx; p.y+=p.vy;
      p.angle+=p.va;
      if(frame>120) p.opacity-=0.008;
    });
    frame++;
    if(frame<220) requestAnimationFrame(draw);
    else{ctx.clearRect(0,0,canvas.width,canvas.height);canvas.style.display='none';}
  }
  draw();
}

function toggleGameStats(){
  const panel=document.getElementById('game-stats-panel');
  const btn=document.getElementById('stats-toggle-btn');
  if(panel.style.display==='none'){
    buildGameStats();
    panel.style.display='block';
    if(btn)btn.style.display='none';
  } else {
    panel.style.display='none';
    if(btn)btn.style.display='block';
  }
}

// تصدير نتائج اللعبة إلى CSV (يفتح في Excel)
function hhExportGameResults(){
  try{
    const date = new Date();
    const dateStr = date.toLocaleDateString('ar-QA');
    const timeStr = date.toLocaleTimeString('ar-QA');
    
    // 1) معلومات اللعبة العامة
    let csv = '\uFEFF'; // BOM لدعم UTF-8 في Excel
    csv += 'منصة الملهم · تقرير نتائج اللعبة\n';
    csv += 'اسم اللعبة,' + (G.gameName || 'بدون اسم') + '\n';
    csv += 'التاريخ,' + dateStr + '\n';
    csv += 'الوقت,' + timeStr + '\n\n';
    
    // 2) جدول الفرق والنتائج
    csv += 'الترتيب,اسم الفريق,النقاط\n';
    const sorted = G.teams.map((t,i) => ({name:t, score:G.scores[i]}))
      .sort((a,b) => b.score - a.score);
    sorted.forEach((t,i) => {
      const rank = i === 0 ? 'الأول' : (i+1) + '';
      csv += rank + ',' + t.name + ',' + t.score + '\n';
    });
    
    // 3) الفئات المختارة
    csv += '\nالفئات المختارة\n';
    (G.selectedCats || []).forEach(c => {
      csv += c + '\n';
    });
    
    // 4) إحصائيات الأسئلة
    let totalQ = 0, answeredQ = 0;
    if(G.boardData){
      Object.entries(G.boardData).forEach(([cat,diffs])=>{
        Object.entries(diffs).forEach(([diff,qs])=>{
          qs.forEach(q=>{
            const key = cat + '__' + diff + '__' + qs.indexOf(q);
            const cell = document.getElementById('cell_'+key);
            const used = cell && cell.classList.contains('used');
            totalQ++;
            if(used) answeredQ++;
          });
        });
      });
    }
    csv += '\nإحصائيات الأسئلة\n';
    csv += 'إجمالي الأسئلة,' + totalQ + '\n';
    csv += 'الأسئلة المُجاب عليها,' + answeredQ + '\n';
    csv += 'النسبة,' + (totalQ ? Math.round(answeredQ/totalQ*100) : 0) + '%\n';
    
    // إنشاء وتحميل الملف
    const blob = new Blob([csv], {type: 'text/csv;charset=utf-8;'});
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    const fileName = 'نتائج_' + (G.gameName||'لعبة') + '_' + date.toISOString().slice(0,10) + '.csv';
    link.download = fileName;
    link.click();
    URL.revokeObjectURL(link.href);
    
    if(typeof toast === 'function') toast('تم تصدير النتائج بنجاح', 'success');
  }catch(e){
    console.error('خطأ في التصدير:', e);
    if(typeof toast === 'function') toast('تعذر التصدير: ' + e.message, 'error');
  }
}

function buildGameStats(){
  const el=document.getElementById('game-stats-content');
  if(!el)return;
  // حساب الإحصائيات من بيانات اللوح
  let totalQ=0, answeredQ=0;
  const catStats={};
  Object.entries(G.boardData).forEach(([cat,diffs])=>{
    let catTotal=0, catAnswered=0;
    Object.entries(diffs).forEach(([diff,qs])=>{
      qs.forEach(q=>{
        const key=cat+'__'+diff+'__'+qs.indexOf(q);
        const cell=document.getElementById('cell_'+key);
        const used=cell&&cell.classList.contains('used');
        totalQ++; catTotal++;
        if(used){answeredQ++;catAnswered++;}
      });
    });
    catStats[cat]={total:catTotal,answered:catAnswered};
  });
  const pct=totalQ?Math.round(answeredQ/totalQ*100):0;
  // بناء HTML
  let html='';
  // نسبة الأسئلة المجاب عنها · بطاقة زجاجية
  html+=`<div style="background:rgba(255,255,255,.07);backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px);border:1px solid rgba(255,255,255,.12);border-radius:12px;padding:12px;margin-bottom:12px;">
    <div style="display:flex;justify-content:space-between;font-size:.85rem;font-weight:800;margin-bottom:7px;">
      <span style="color:#fff;">الأسئلة المجاب عنها</span>
      <span style="color:#ffd700;font-variant-numeric:tabular-nums;">${answeredQ} / ${totalQ} <span style="color:#8ab4e0;font-size:.78rem;">(${pct}%)</span></span>
    </div>
    <div style="background:rgba(255,255,255,.08);border-radius:999px;height:9px;overflow:hidden;box-shadow:inset 0 1px 2px rgba(0,0,0,.3);">
      <div style="background:linear-gradient(90deg,#e8c968 0%,#B8924A 100%);height:100%;width:${pct}%;border-radius:999px;transition:width .6s;box-shadow:0 0 10px rgba(184,146,74,.5);"></div>
    </div>
  </div>`;
  // إحصاء كل فريق
  const sorted=[...G.teams.map((t,i)=>({name:t,pts:G.scores[i],idx:i}))].sort((a,b)=>b.pts-a.pts);
  html+='<div style="margin-bottom:8px;font-size:.82rem;font-weight:900;color:#ffd700;display:flex;align-items:center;gap:6px;"><span style="display:inline-block;width:3px;height:13px;background:#B8924A;border-radius:2px;"></span>النتائج النهائية</div>';
  sorted.forEach((t,rank)=>{
    const medal=rank===0?'':rank===1?'':rank===2?'':'▪';
    const isWinner=rank===0;
    const bg = isWinner
      ? 'linear-gradient(135deg,rgba(184,146,74,.22),rgba(184,146,74,.08))' : 'rgba(255,255,255,.06)';
    const border = isWinner
      ? '1.5px solid rgba(184,146,74,.5)' : '1px solid rgba(255,255,255,.12)';
    const ptsColor = isWinner ? '#ffd700' : '#fff';
    html+=`<div style="display:flex;justify-content:space-between;align-items:center;padding:9px 12px;border-radius:10px;margin-bottom:6px;background:${bg};border:${border};backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px);${isWinner?'box-shadow:0 3px 12px rgba(184,146,74,.15);':''}">
      <span style="font-weight:800;font-size:.88rem;color:#fff;">${medal} ${esc(t.name)}</span>
      <span style="font-weight:900;font-size:.95rem;color:${ptsColor};font-variant-numeric:tabular-nums;${isWinner?'text-shadow:0 2px 4px rgba(184,146,74,.3);':''}">${(t.pts||0).toLocaleString('en-US')} نقطة</span>
    </div>`;
  });
  // توزيع الأسئلة على الفئات
  html+='<div style="margin-top:12px;margin-bottom:6px;font-size:.82rem;font-weight:900;color:#ffd700;display:flex;align-items:center;gap:6px;"><span style="display:inline-block;width:3px;height:13px;background:#B8924A;border-radius:2px;"></span>تغطية الفئات</div>';
  Object.entries(catStats).forEach(([cat,s])=>{
    const ci=CAT_INFO[cat]||{emoji:'<svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M21 5c-1.11-.35-2.33-.5-3.5-.5-1.95 0-4.05.4-5.5 1.5-1.45-1.1-3.55-1.5-5.5-1.5S2.45 4.9 1 6v14.65c0 .25.25.5.5.5.1 0 .15-.05.25-.05C3.1 20.45 5.05 20 6.5 20c1.95 0 4.05.4 5.5 1.5 1.35-.85 3.8-1.5 5.5-1.5 1.65 0 3.35.3 4.75 1.05.1.05.15.05.25.05.25 0 .5-.25.5-.5V6c-.6-.45-1.25-.75-2-1z"/></svg>',label:cat};
    const p=s.total?Math.round(s.answered/s.total*100):0;
    html+=`<div style="display:flex;align-items:center;gap:8px;padding:6px 10px;margin-bottom:4px;border-radius:8px;background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.08);">
      <span style="font-size:.78rem;min-width:110px;color:#fff;font-weight:700;">${ci.emoji} ${ci.label}</span>
      <div style="flex:1;background:rgba(255,255,255,.08);border-radius:999px;height:6px;overflow:hidden;box-shadow:inset 0 1px 2px rgba(0,0,0,.3);">
        <div style="background:linear-gradient(90deg,#7ab3e0,#B8924A);height:100%;width:${p}%;border-radius:999px;transition:width .6s;"></div>
      </div>
      <span style="font-size:.72rem;color:#8ab4e0;min-width:34px;font-weight:800;font-variant-numeric:tabular-nums;text-align:left;">${s.answered}/${s.total}</span>
    </div>`;
  });
  el.innerHTML=html;
}


function shareResult(){
  const sorted=[...G.teams.map((t,i)=>({name:t,pts:G.scores[i]}))].sort((a,b)=>b.pts-a.pts);
  const winner=sorted[0];
  let text='<svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M19 5h-2V3H7v2H5c-1.1 0-2 .9-2 2v1c0 2.55 1.92 4.63 4.39 4.94A5.01 5.01 0 0011 15.9V19H7v2h10v-2h-4v-3.1A5.01 5.01 0 0016.61 12.94C19.08 12.63 21 10.55 21 8V7c0-1.1-.9-2-2-2zM5 8V7h2v3.82C5.84 10.4 5 9.3 5 8zm14 0c0 1.3-.84 2.4-2 2.82V7h2v1z"/></svg> نتيجة منصة الملهم\n';
  text+=' '+(G.gameName||'لعبة')+'\n\n';
  sorted.forEach((t,i)=>{
    const medal=i===0?'':i===1?'':i===2?'':'▪';
    text+=medal+' '+t.name+': '+t.pts+' نقطة\n';
  });
  text+='\n<svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M21 6H3a2 2 0 00-2 2v8a2 2 0 002 2h18a2 2 0 002-2V8a2 2 0 00-2-2zM11 13H8v3H6v-3H3v-2h3V8h2v3h3v2zm4.5 2a1.5 1.5 0 110-3 1.5 1.5 0 010 3zm4-3a1.5 1.5 0 110-3 1.5 1.5 0 010 3z"/></svg> العب معنا على: alhalhali.com';
  // محاولة مشاركة عبر Web Share API أو نسخ النص
  if(navigator.share){
    navigator.share({title:'نتيجة الملهم',text}).catch(()=>copyShareText(text));
  } else {
    copyShareText(text);
  }
}

function copyShareText(text){
  if(navigator.clipboard){
    navigator.clipboard.writeText(text).then(()=>toast('تم نسخ النتيجة - الصقها في واتساب','success'));
  } else {
    const ta=document.createElement('textarea');
    ta.value=text;document.body.appendChild(ta);ta.select();
    document.execCommand('copy');document.body.removeChild(ta);
    toast('تم نسخ النتيجة - الصقها في واتساب','success');
  }
}

function confirmQuit(){
  // إنشاء modal مخصص بدل confirm العادي
  showQuitModal();}

function showQuitModal(){
  const modal=document.getElementById('quit-modal');
  if(modal){modal.classList.add('open');return;}
  const div=document.createElement('div');
  div.id='quit-modal';
  div.style.cssText='position:fixed;inset:0;z-index:9999;background:rgba(0,0,0,.6);display:flex;align-items:center;justify-content:center;padding:20px;';
  div.innerHTML=`
    <div style="background:#fff;border:2px solid #8A1538;border-radius:16px;padding:28px;max-width:360px;width:100%;box-shadow:6px 6px 0 #8A1538;text-align:center;">
      <div style="font-size:2rem;margin-bottom:8px;"></div>
      <div style="font-weight:900;font-size:1.1rem;margin-bottom:10px;">إنهاء اللعبة؟</div>
      <div style="font-size:.88rem;color:#555;margin-bottom:20px;line-height:1.7;">سيتم إعلان النتيجة الحالية وحفظ اللعبة في سجل ألعابك</div>
      <div style="display:flex;gap:10px;">
        <button onclick="doQuitGame()" style="flex:1;padding:12px;background:#8A1538;color:#fff;border:2px solid #8A1538;border-radius:10px;font-family:Cairo,sans-serif;font-weight:900;cursor:pointer;font-size:.9rem;">إنهاء وعرض النتيجة</button>
        <button onclick="closeQuitModal()" style="flex:1;padding:12px;background:#fff;color:#8A1538;border:2px solid #8A1538;border-radius:10px;font-family:Cairo,sans-serif;font-weight:900;cursor:pointer;font-size:.9rem;">تراجع</button>
      </div>
    </div>`;
  document.body.appendChild(div);
}

function closeQuitModal(){
  const m=document.getElementById('quit-modal');
  if(m)m.remove();
}

function doQuitGame(){
  closeQuitModal();
  clearInterval(G.timer);
  document.getElementById('q-modal').classList.remove('open');
  endGame();
}

// ════ قائمة الصدارة ════

// ════ قائمة الصدارة · real-time ════
var currentLBTab = 'solo';
var _lbUnsubSolo  = null;
var _lbUnsubTeams = null;
var _lbUnsubRole  = null;

function switchLBTab(tab){
  currentLBTab = tab;
  // تحديث الأزرار الأربعة
  ['teachers','students','solo','teams'].forEach(function(t){
    var b = document.getElementById('lb-tab-'+t);
    if(!b) return;
    var active = (t===tab);
    b.style.background = active ? '#8A1538' : '#fff';
    b.style.color      = active ? '#fff' : '#8A1538';
  });
  if(tab==='teachers') startRoleLB('teacher');
  else if(tab==='students') startRoleLB('student');
  else if(tab==='solo') startSoloLB();
  else startTeamsLB();
}

// ═══ تحميل متصدرين حسب الدور (معلم أو طالب) ═══
// نجلب كل المستخدمين ونفلتر في JS · يضمن الدقة ولا يحتاج فهرس مركب
function startRoleLB(role){
  // أوقف الاشتراكات الأخرى
  if(_lbUnsubSolo){ _lbUnsubSolo(); _lbUnsubSolo=null; }
  if(_lbUnsubTeams){ _lbUnsubTeams(); _lbUnsubTeams=null; }
  if(_lbUnsubRole){ _lbUnsubRole(); _lbUnsubRole=null; }

  var el = document.getElementById('lb-list');
  var title = document.getElementById('lb-list-title');
  var label = role==='teacher' ? '<svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M5 13.18v4L12 21l7-3.82v-4L12 17l-7-3.82zM12 3L1 9l11 6 9-4.91V17h2V9L12 3z"/></svg> أفضل المعلمين' : '<svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M21 5c-1.11-.35-2.33-.5-3.5-.5-1.95 0-4.05.4-5.5 1.5-1.45-1.1-3.55-1.5-5.5-1.5S2.45 4.9 1 6v14.65c0 .25.25.5.5.5.1 0 .15-.05.25-.05C3.1 20.45 5.05 20 6.5 20c1.95 0 4.05.4 5.5 1.5 1.35-.85 3.8-1.5 5.5-1.5 1.65 0 3.35.3 4.75 1.05.1.05.15.05.25.05.25 0 .5-.25.5-.5V6c-.6-.45-1.25-.75-2-1z"/></svg> أفضل الطلاب';
  if(title) title.innerHTML = label + ' <span style="display:inline-flex;align-items:center;gap:4px;background:#fdeceb;border:1px solid #e74c3c;color:#c0392b;border-radius:10px;padding:1px 8px;font-size:.62rem;font-weight:900;margin-right:6px;vertical-align:middle;"><span style="display:inline-block;width:6px;height:6px;border-radius:50%;background:#e74c3c;animation:pulse 1.2s infinite;"></span>مباشر</span>';

  if(OFFLINE_MODE){
    if(el) el.innerHTML = '<p style="text-align:center;color:#888;padding:20px;font-size:.85rem;">الترتيب حسب الدور يحتاج اتصال بالإنترنت</p>';
    return;
  }

  if(el) el.innerHTML = '<div style="text-align:center;padding:16px;color:#aaa;font-size:.85rem;"><svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M6 2v6h.01L6 8.01 10 12l-4 4 .01.01H6V22h12v-5.99h-.01L18 16l-4-4 4-3.99-.01-.01H18V2H6z"/></svg> جاري الاتصال...</div>';

  // جلب كل المستخدمين (مرتبين بالنقاط) والفلترة في JS
  _lbUnsubRole = db.collection('leaderboard')
    .orderBy('points','desc')
    .limit(200)
    .onSnapshot(function(snap){
      // فلترة صارمة: الدور المطلوب تحديدا + نقاط > 0
      var arr = snap.docs
        .map(function(d){
          var data = d.data();
          return {
            name:data.name, pts:data.points||0, uid:d.id, role:data.role||null,
            // بيانات إضافية لاحتساب اللقب
            gamesPlayed:data.gamesPlayed||0, points:data.points||0,
            createdAt:data.createdAt||null, hasReviewed:false
          };
        })
        .filter(function(u){ return u.role === role && (u.pts||0) > 0; })
        .slice(0, 50);
      if(arr.length === 0){
        var icon = role==='teacher' ? '<svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M5 13.18v4L12 21l7-3.82v-4L12 17l-7-3.82zM12 3L1 9l11 6 9-4.91V17h2V9L12 3z"/></svg>' : '<svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M21 5c-1.11-.35-2.33-.5-3.5-.5-1.95 0-4.05.4-5.5 1.5-1.45-1.1-3.55-1.5-5.5-1.5S2.45 4.9 1 6v14.65c0 .25.25.5.5.5.1 0 .15-.05.25-.05C3.1 20.45 5.05 20 6.5 20c1.95 0 4.05.4 5.5 1.5 1.35-.85 3.8-1.5 5.5-1.5 1.65 0 3.35.3 4.75 1.05.1.05.15.05.25.05.25 0 .5-.25.5-.5V6c-.6-.45-1.25-.75-2-1z"/></svg>';
        var who  = role==='teacher' ? 'معلم' : 'طالب';
        if(el) el.innerHTML =
          '<div style="text-align:center;padding:30px 16px;line-height:1.9;">'+
            '<div style="font-size:2.4rem;margin-bottom:8px;">'+icon+'</div>'+
            '<div style="font-weight:900;color:#8A1538;font-size:1rem;margin-bottom:4px;">لم يشارك أي '+who+' بعد</div>'+
            '<div style="font-size:.82rem;color:#777;">كن أول '+who+' يتصدر القائمة · ابدأ لعبة واكسب النقاط! </div>'+
          '</div>';
        var hero=document.getElementById('lb-hero'); if(hero) hero.style.display='none';
        var p23=document.getElementById('lb-podium-23'); if(p23) p23.style.display='none';
        var myR=document.getElementById('lb-my-rank'); if(myR) myR.style.display='none';
        return;
      }
      renderLBData(arr, 'solo');
    }, function(err){
      console.error('Role LB error:', err);
      if(err.code === 'permission-denied'){
        if(el) el.innerHTML = '<p style="text-align:center;color:#888;padding:20px;font-size:.85rem;">سجل دخولك لعرض المتصدرين</p>';
      } else {
        if(el) el.innerHTML = '<p style="text-align:center;color:#888;padding:20px;font-size:.85rem;">تعذر الاتصال · تحقق من الإنترنت</p>';
      }
    });
}

// ═══ فردي · real-time ═══
function startSoloLB(){
  // أوقف اشتراك الفرق إن كان نشطا
  if(_lbUnsubTeams){ _lbUnsubTeams(); _lbUnsubTeams=null; }

  var el = document.getElementById('lb-list');
  var title = document.getElementById('lb-list-title');
  if(title) title.innerHTML = ' أفضل اللاعبين <span style="display:inline-flex;align-items:center;gap:4px;background:#fdeceb;border:1px solid #e74c3c;color:#c0392b;border-radius:10px;padding:1px 8px;font-size:.62rem;font-weight:900;margin-right:6px;vertical-align:middle;"><span style="display:inline-block;width:6px;height:6px;border-radius:50%;background:#e74c3c;animation:pulse 1.2s infinite;"></span>مباشر</span>';

  if(OFFLINE_MODE){
    // وضع offline · تحميل مرة واحدة
    renderLB();
    return;
  }

  el.innerHTML = '<div style="text-align:center;padding:16px;color:#aaa;font-size:.85rem;"><svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M6 2v6h.01L6 8.01 10 12l-4 4 .01.01H6V22h12v-5.99h-.01L18 16l-4-4 4-3.99-.01-.01H18V2H6z"/></svg> جاري الاتصال...</div>';

  // إلغاء الاشتراك القديم إن وجد
  if(_lbUnsubSolo){ _lbUnsubSolo(); }

  // onSnapshot · يتحدث تلقائيا عند أي تغيير
  _lbUnsubSolo = db.collection('leaderboard')
    .orderBy('points','desc')
    .limit(200)
    .onSnapshot(function(snap){
      // تبويب "عام": فقط غير المصنفين (role مفقود) أو role === 'other' // المعلمون والطلاب لهم تبويباتهم الخاصة
      var arr = snap.docs
        .map(function(d){
          var data = d.data();
          return {
            name:data.name, pts:data.points||0, uid:d.id, role:data.role||null,
            gamesPlayed:data.gamesPlayed||0, points:data.points||0,
            createdAt:data.createdAt||null, hasReviewed:false
          };
        })
        .filter(function(u){
          if((u.pts||0) <= 0) return false;
          return (u.role === 'other' || u.role === null);
        })
        .slice(0, 50);
      if(!arr.length){
        el.innerHTML =
          '<div style="text-align:center;padding:30px 16px;line-height:1.9;">'+
            '<div style="font-size:2.4rem;margin-bottom:8px;"></div>'+
            '<div style="font-weight:900;color:#8A1538;font-size:1rem;margin-bottom:4px;">لا يوجد لاعبون متصدرون بعد</div>'+
            '<div style="font-size:.82rem;color:#777;">ابدأ مشاركتك الأولى واكسب النقاط لتظهر هنا! <svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M9.19 6.35a4.5 4.5 0 010 6.36L7 14.9l-2.5-2.5 2.19-2.19a4.5 4.5 0 016.5-3.86zM12 18l3-3 6.5 6.5-3 3L12 18zM6 15a3 3 0 00-3 3v3h3v-3h3a3 3 0 00-3-3z"/></svg></div>'+
          '</div>';
        var hero=document.getElementById('lb-hero'); if(hero) hero.style.display='none';
        var p23=document.getElementById('lb-podium-23'); if(p23) p23.style.display='none';
        var myR=document.getElementById('lb-my-rank'); if(myR) myR.style.display='none';
        return;
      }
      renderLBData(arr, 'solo');
    }, function(err){
      console.error('LB error:', err);
      if(err.code === 'permission-denied'){
        el.innerHTML = '<p style="text-align:center;color:#888;padding:20px;font-size:.85rem;">سجل دخولك لعرض المتصدرين</p>';
      } else {
        el.innerHTML = '<p style="text-align:center;color:#888;padding:20px;font-size:.85rem;">تعذر الاتصال · تحقق من الإنترنت</p>';
      }
    });
}

// ═══ فرق · real-time ═══
function startTeamsLB(){
  if(_lbUnsubSolo){ _lbUnsubSolo(); _lbUnsubSolo=null; }

  var el = document.getElementById('lb-list');
  var title = document.getElementById('lb-list-title');
  if(title) title.innerHTML = ' أفضل الفرق <span style="display:inline-flex;align-items:center;gap:4px;background:#fdeceb;border:1px solid #e74c3c;color:#c0392b;border-radius:10px;padding:1px 8px;font-size:.62rem;font-weight:900;margin-right:6px;vertical-align:middle;"><span style="display:inline-block;width:6px;height:6px;border-radius:50%;background:#e74c3c;animation:pulse 1.2s infinite;"></span>مباشر</span>';

  if(OFFLINE_MODE){
    renderTeamsLBLocal();
    return;
  }

  el.innerHTML = '<div style="text-align:center;padding:16px;color:#aaa;font-size:.85rem;"><svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M6 2v6h.01L6 8.01 10 12l-4 4 .01.01H6V22h12v-5.99h-.01L18 16l-4-4 4-3.99-.01-.01H18V2H6z"/></svg> جاري الاتصال...</div>';

  if(_lbUnsubTeams){ _lbUnsubTeams(); }

  _lbUnsubTeams = db.collection('team_scores')
    .orderBy('pts','desc')
    .limit(50)
    .onSnapshot(function(snap){
      // فلترة: فقط الفرق التي لها نقاط محققة (pts > 0)
      var arr = snap.docs
        .map(function(d){ return {name:d.data().name, pts:d.data().pts||0}; })
        .filter(function(t){ return (t.pts||0) > 0; });
      if(!arr.length){
        // لا توجد فرق في Firestore · جرب سجل الجهاز
        renderTeamsLBLocal();
        return;
      }
      renderLBData(arr, 'teams');
    }, function(err){
      renderTeamsLBLocal();
    });
}

// ═══ عرض البيانات · أول 5 فقط ═══
function renderLBData(arr, mode){
  var el = document.getElementById('lb-list');
  var myRankSection = document.getElementById('lb-my-rank');
  var heroEl  = document.getElementById('lb-hero');
  var pod23El = document.getElementById('lb-podium-23');
  if(myRankSection) myRankSection.style.display='none';
  if(heroEl) heroEl.style.display='none';
  if(pod23El) pod23El.style.display='none';

  // أول 5 فقط
  var top5 = arr.slice(0,5);

  if(!top5.length){
    el.innerHTML='<p style="text-align:center;color:#555;padding:24px;line-height:2;"><svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M19 5h-2V3H7v2H5c-1.1 0-2 .9-2 2v1c0 2.55 1.92 4.63 4.39 4.94A5.01 5.01 0 0011 15.9V19H7v2h10v-2h-4v-3.1A5.01 5.01 0 0016.61 12.94C19.08 12.63 21 10.55 21 8V7c0-1.1-.9-2-2-2zM5 8V7h2v3.82C5.84 10.4 5 9.3 5 8zm14 0c0 1.3-.84 2.4-2 2.82V7h2v1z"/></svg><br>لا توجد بيانات بعد<br><small style="color:#aaa;">العب واكسب نقاط لتظهر هنا!</small></p>';
    return;
  }

  var myUid = currentUser ? (currentUser.uid||currentUser.id) : null;

  // ── المركز الأول: بطاقة حماسية ──
  var p1 = top5[0];
  if(p1 && heroEl){
    heroEl.style.display='block';
    var isMe1 = mode==='solo' && myUid && p1.uid===myUid;
    document.getElementById('lb-hero-avatar').textContent=(p1.name||'؟').charAt(0);
    //  احتساب لقب المتصدر
    var heroBadge = '';
    try{
      if(typeof getUserBadge === 'function' && p1.role){
        var b1 = getUserBadge(p1);
        if(b1) heroBadge = '<div style="margin-top:8px;display:flex;justify-content:center;">' + renderBadgeHTML(b1, {size:'sm'}) + '</div>';
      }
    }catch(e){}
    document.getElementById('lb-hero-name').innerHTML=esc(p1.name)+(isMe1?' <span style="font-size:.65rem;background:#d4b740;color:#8A1538;border-radius:10px;padding:1px 7px;font-weight:900;">أنت </span>':'') + heroBadge;
    const heropts=document.getElementById('lb-hero-pts');
    if(heropts){
      const span=heropts.querySelector('span');
      if(span) span.textContent=(p1.pts||0).toLocaleString('en-US')+' نقطة';
    }
  }

  // ── المركزان 2 و3 ──
  if(pod23El){
    pod23El.style.display='flex';
    [[2,'pod-2'],[3,'pod-3']].forEach(function(pair){
      var rank=pair[0], id=pair[1];
      var p=top5[rank-1];
      var col=document.getElementById(id);
      if(col) col.style.visibility=p?'visible':'hidden';
      var av=document.getElementById(id+'-avatar');
      var nm=document.getElementById(id+'-name');
      var pt=document.getElementById(id+'-pts');
      var isMe=mode==='solo'&&myUid&&p&&p.uid===myUid;
      if(av) av.textContent=p?((p.name||'؟').charAt(0).toUpperCase()||'؟'):'';
      if(nm) nm.innerHTML=p?esc(p.name)+(isMe?' <span style="font-size:.55rem;background:#8A1538;color:#fff;border-radius:8px;padding:1px 5px;">أنت</span>':''):'';
      if(pt) pt.textContent=p?(p.pts||0).toLocaleString('en-US')+' نقطة':'';
    });
  }

  // ── المراكز 4 و5 ──
  var list45 = top5.slice(3);
  var medals = ['4','5'];
  if(list45.length){
    el.innerHTML = list45.map(function(p,i){
      var pts=(p.pts||0).toLocaleString('en-US');
      var isMe=mode==='solo'&&myUid&&p.uid===myUid;
      //  شارة اللقب (مصغرة)
      var badgeChip = '';
      try{
        if(typeof getUserBadge === 'function' && p.role){
          var bb = getUserBadge(p);
          if(bb) badgeChip = ' ' + renderBadgeHTML(bb, {size:'sm', withIcon:false});
        }
      }catch(e){}
      return '<div class="lb-row" style="'+(isMe?'border-color:#8A1538;background:#e8f2ec;font-weight:900;':'')+'">' +
        '<div class="lb-rank" style="font-weight:900;font-size:.9rem;color:#8A1538;">'+medals[i]+'</div>' +
        '<div class="lb-name">'+esc(p.name)+(isMe?' <span style="font-size:.62rem;background:#8A1538;color:#fff;border-radius:8px;padding:1px 6px;">أنت</span>':'')+badgeChip+'</div>' +
        '<div class="lb-pts">'+pts+' نقطة</div>' +
      '</div>';
    }).join('');
  } else {
    el.innerHTML='';
  }

  // ── مركز المستخدم إن كان خارج الـ5 (فردي) ──
  if(mode==='solo' && myUid && myRankSection){
    var myIdx=arr.findIndex(function(p){return p.uid===myUid;});
    if(myIdx>=5){
      var me=arr[myIdx];
      var card=document.getElementById('lb-my-rank-card');
      myRankSection.style.display='block';
      card.innerHTML=
        '<div style="font-size:1.1rem;font-weight:900;color:#8A1538;min-width:36px;">#'+(myIdx+1)+'</div>'+
        '<div style="flex:1;font-weight:900;">'+esc(me.name)+' <span style="font-size:.62rem;background:#8A1538;color:#fff;border-radius:8px;padding:1px 6px;">أنت</span></div>'+
        '<div style="font-weight:900;color:#8A1538;">'+(me.pts||0).toLocaleString('en-US')+' نقطة</div>'+
        (top5[4]?'<div style="font-size:.7rem;color:#888;width:100%;text-align:center;margin-top:4px;">تحتاج '+Math.max(0,(top5[4].pts||0)-(me.pts||0)).toLocaleString('en-US')+' نقطة إضافية للمركز الخامس</div>':'');
    }
  }
}

// ═══ فرق من localStorage (fallback) ═══
function renderTeamsLBLocal(){
  var teamMap = {};
  var hist = JSON.parse(localStorage.getItem('hh_game_history')||'[]');
  hist.forEach(function(game){
    var parts = (game.teams||'').split(' | ');
    parts.forEach(function(part){
      var m = part.match(/^(.+):\s*(\d+)$/);
      if(m){ var n=m[1].trim(), p=parseInt(m[2]); teamMap[n]=(teamMap[n]||0)+p; }
    });
  });
  var arr = Object.entries(teamMap)
                  .map(function(e){return {name:e[0],pts:e[1]};})
                  .filter(function(t){ return (t.pts||0) > 0; })
                  .sort(function(a,b){return b.pts-a.pts;})
                  .slice(0,5);
  if(!arr.length){
    var el = document.getElementById('lb-list');
    if(el) el.innerHTML =
      '<div style="text-align:center;padding:30px 16px;line-height:1.9;">'+
        '<div style="font-size:2.4rem;margin-bottom:8px;"><svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M19 5h-2V3H7v2H5c-1.1 0-2 .9-2 2v1c0 2.55 1.92 4.63 4.39 4.94A5.01 5.01 0 0011 15.9V19H7v2h10v-2h-4v-3.1A5.01 5.01 0 0016.61 12.94C19.08 12.63 21 10.55 21 8V7c0-1.1-.9-2-2-2zM5 8V7h2v3.82C5.84 10.4 5 9.3 5 8zm14 0c0 1.3-.84 2.4-2 2.82V7h2v1z"/></svg></div>'+
        '<div style="font-weight:900;color:#8A1538;font-size:1rem;margin-bottom:4px;">لا توجد فرق متصدرة بعد</div>'+
        '<div style="font-size:.82rem;color:#777;">ابدأ مشاركتك الجماعية الأولى وكن أول فريق يحجز مكانه! </div>'+
      '</div>';
    var hero=document.getElementById('lb-hero'); if(hero) hero.style.display='none';
    var p23=document.getElementById('lb-podium-23'); if(p23) p23.style.display='none';
    var myR=document.getElementById('lb-my-rank'); if(myR) myR.style.display='none';
    return;
  }
  renderLBData(arr,'teams');
}

