/**
 * تعريف خدمات المسارات (المعلم + الطالب).
 * كل خدمة لها 3 حالات يديرها الأدمن:
 *   - 'available' (متاحة) → الزر يعمل
 *   - 'soon' (قريبا) → الزر يظهر مع شارة "قريبا" ولا يعمل
 *   - 'hidden' (مخفية) → لا تظهر للمستخدمين العاديين (تظهر للأدمن فقط برمز)
 */
const PATH_SERVICES_DEFAULTS = {
  // مسار المعلم
  teacher: {
    'tch-games':      { defaultStatus:'available' },
    'tch-quizzes':    { defaultStatus:'soon' },
    'tch-certs':      { defaultStatus:'soon' },
    'tch-questions':  { defaultStatus:'available' },
    'tch-timeline':   { defaultStatus:'soon' },
    'tch-lesson':     { defaultStatus:'hidden' },     // مخفي بالافتراض
    'tch-flashcards': { defaultStatus:'hidden' },
    'tch-classes':    { defaultStatus:'hidden' }
  },
  // مسار الطالب
  student: {
    'std-games':      { defaultStatus:'available' },
    'std-quizzes':    { defaultStatus:'soon' },
    'std-certs':      { defaultStatus:'soon' },
    'std-join-class': { defaultStatus:'available' },
    'std-timeline':   { defaultStatus:'soon' },
    'std-lesson':     { defaultStatus:'hidden' },
    'std-flashcards': { defaultStatus:'hidden' }
  }
};

// كاش للحالات المحملة
let _pathServicesCache = null;

/**
 * جلب حالات الخدمات (من Firestore أو localStorage).
 * تدمج القيم المخزنة مع القيم الافتراضية.
 */
async function loadPathServicesStatuses(){
  let data = {};
  try{
    if(typeof db !== 'undefined' && db && !OFFLINE_MODE){
      const doc = await db.collection('platform_settings').doc('path_services').get();
      if(doc.exists){
        data = doc.data() || {};
      }
    } else {
      const cached = localStorage.getItem('hh_path_services');
      if(cached){
        try{ data = JSON.parse(cached) || {}; }catch(e){}
      }
    }
  }catch(e){
    console.warn('Failed to load path services', e);
    try{
      const cached = localStorage.getItem('hh_path_services');
      if(cached) data = JSON.parse(cached) || {};
    }catch(_){}
  }
  _pathServicesCache = data;
  return data;
}

/**
 * احتساب حالة خدمة معينة (مع fallback للقيمة الافتراضية).
 * الحالات: 'available' | 'soon' | 'hidden' */
function getServiceStatus(pathType, serviceId){
  // ابحث في الكاش أولا
  if(_pathServicesCache && _pathServicesCache[serviceId]){
    return _pathServicesCache[serviceId];
  }
  // افتراض: الحالة الأصلية من PATH_SERVICES_DEFAULTS
  const def = (PATH_SERVICES_DEFAULTS[pathType] || {})[serviceId];
  return def ? def.defaultStatus : 'available';
}

/**
 * تحديث حالة خدمة (للأدمن فقط).
 */
async function updateServiceStatus(serviceId, newStatus){
  if(typeof isAdminUser === 'function' && !isAdminUser(currentUser)){
    if(typeof toast === 'function') toast('هذه الميزة للأدمن فقط', 'error');
    return false;
  }
  if(!['available','soon','hidden'].includes(newStatus)) return false;

  // حدث الكاش محليا
  if(!_pathServicesCache) _pathServicesCache = {};
  _pathServicesCache[serviceId] = newStatus;

  // احفظ في Firestore
  try{
    if(typeof db !== 'undefined' && db && !OFFLINE_MODE){
      await db.collection('platform_settings').doc('path_services').set({
        [serviceId]: newStatus,
        _lastUpdated: firebase.firestore.FieldValue.serverTimestamp()
      }, { merge:true });
    } else {
      // وضع offline → localStorage
      localStorage.setItem('hh_path_services', JSON.stringify(_pathServicesCache));
      if(typeof _hh_saveCustomizationsToCloud === 'function') _hh_saveCustomizationsToCloud();
    }
    if(typeof toast === 'function') toast('تم التحديث', 'success');
    return true;
  }catch(e){
    console.error('Failed to save service status', e);
    if(typeof toast === 'function') toast('فشل الحفظ', 'error');
    return false;
  }
}

window.getServiceStatus = getServiceStatus;
window.updateServiceStatus = updateServiceStatus;
window.loadPathServicesStatuses = loadPathServicesStatuses;


