/**
 * بناء HTML لخدمة واحدة (للمسارين).
 */
function _renderPathService(svc, pathType){
  const status = getServiceStatus(pathType, svc.id);
  const isAdmin = (typeof isAdminUser === 'function') && isAdminUser(currentUser);

  // مخفية → لا تظهر للمستخدمين العاديين
  if(status === 'hidden' && !isAdmin) return '';

  // تكوينات حسب الحالة
  let badgeHTML = '';
  let opacity = '';
  let onClick = svc.onClick;

  if(status === 'soon'){
    badgeHTML = '<span class="path-svc-badge soon">قريبا</span>';
    opacity = 'opacity:.85;';
    onClick = svc.soonAction || `showSoonToast('${svc.title.replace(/'/g, "\\'")}');`;
  } else if(status === 'hidden'){
    badgeHTML = '<span class="path-svc-badge hidden-badge">مخفية</span>';
    opacity = 'opacity:.6;';
  }

  // زر التحكم للأدمن
  const adminCtrlHTML = isAdmin ? `
    <button class="path-svc-admin-ctrl" onclick="event.stopPropagation();openServiceStatusMenu(event,'${svc.id}');"
            title="تحكم الأدمن" type="button">
      <svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor">
        <circle cx="12" cy="6" r="2"/><circle cx="12" cy="12" r="2"/><circle cx="12" cy="18" r="2"/>
      </svg>
    </button> ` : '';

  return `
    <div class="path-svc-wrap">
      <button class="path-modal-option" style="${opacity}" onclick="${onClick}">
        <div class="path-modal-option-icon" style="${svc.iconBg}"> ${svc.icon}
        </div>
        <div class="path-modal-option-info">
          <div class="path-modal-option-title">${svc.title} ${badgeHTML}</div>
          <div class="path-modal-option-desc">${svc.desc}</div>
        </div>
        <svg class="path-modal-option-arrow" width="20" height="20" viewBox="0 0 24 24" fill="currentColor"><path d="M15.41 7.41L14 6l-6 6 6 6 1.41-1.41L10.83 12z"/></svg>
      </button> ${adminCtrlHTML}
    </div> `;
}

