/**
 * قائمة تحكم الأدمن لخدمة معينة (تفتح عند الضغط على ⋮)
 */
function openServiceStatusMenu(event, serviceId){
  if(typeof isAdminUser === 'function' && !isAdminUser(currentUser)) return;
  event.stopPropagation();

  // أزل أي قائمة مفتوحة سابقا
  const existing = document.getElementById('path-svc-menu');
  if(existing) existing.remove();

  const btn = event.currentTarget;
  const rect = btn.getBoundingClientRect();

  // اكتشف pathType
  const pathType = serviceId.startsWith('tch-') ? 'teacher' : 'student';
  const currentStatus = getServiceStatus(pathType, serviceId);

  const menu = document.createElement('div');
  menu.id = 'path-svc-menu';
  menu.style.cssText = `
    position:fixed; z-index:11000;
    top:${rect.bottom + 4}px; right:${window.innerWidth - rect.right}px;
    background:#fff; border:1.5px solid #8A1538;
    border-radius:12px; box-shadow:0 12px 32px rgba(0,0,0,.25);
    padding:6px; min-width:180px;
    font-family:Cairo,sans-serif; direction:rtl;
    animation:svcMenuFadeIn .15s ease;
  `;

  const opts = [
    { val:'available', label:'متاحة', emoji:'<svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-2 15l-5-5 1.41-1.41L10 14.17l7.59-7.59L19 8l-9 9z"/></svg>', color:'#3D6B53' },
    { val:'soon',      label:'قريبا', emoji:'<svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M6 2v6h.01L6 8.01 10 12l-4 4 .01.01H6V22h12v-5.99h-.01L18 16l-4-4 4-3.99-.01-.01H18V2H6z"/></svg>', color:'#B8924A' },
    { val:'hidden',    label:'مخفية', emoji:'', color:'#c0392b' }
  ];

  menu.innerHTML = `
    <div style="font-size:.7rem;color:#888;font-weight:800;padding:6px 10px 4px;border-bottom:1px solid #eee;margin-bottom:4px;"> تغيير الحالة:
    </div> ${opts.map(o => `
      <button onclick="event.stopPropagation();_setServiceStatus('${serviceId}','${o.val}');"
              style="display:flex;align-items:center;gap:8px;width:100%;padding:9px 10px;
                     background:${currentStatus === o.val ? '#f0f7f3' : 'transparent'};
                     border:none;border-radius:8px;cursor:pointer;
                     font-family:Cairo;font-weight:${currentStatus === o.val ? '900' : '700'};
                     font-size:.82rem;color:${o.color};
                     transition:background .15s;text-align:right;"
              onmouseover="this.style.background='${currentStatus === o.val ? '#e8f2ec' : '#f5f5f5'}'"
              onmouseout="this.style.background='${currentStatus === o.val ? '#f0f7f3' : 'transparent'}'">
        <span style="font-size:1rem;">${o.emoji}</span>
        <span style="flex:1;">${o.label}</span> ${currentStatus === o.val ? '<svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor"><path d="M9 16.17L4.83 12l-1.42 1.41L9 19 21 7l-1.41-1.41L9 16.17z"/></svg>' : ''}
      </button> `).join('')}
  `;

  document.body.appendChild(menu);

  // إغلاق عند النقر في أي مكان آخر
  setTimeout(() => {
    const closeMenu = (e) => {
      if(!menu.contains(e.target)){
        menu.remove();
        document.removeEventListener('click', closeMenu);
      }
    };
    document.addEventListener('click', closeMenu);
  }, 50);
}

/**
 * تطبيق تغيير الحالة (يستدعى من القائمة)
 */
async function _setServiceStatus(serviceId, newStatus){
  const menu = document.getElementById('path-svc-menu');
  if(menu) menu.remove();

  const ok = await updateServiceStatus(serviceId, newStatus);
  if(!ok) return;

  // أعد رسم المسار المفتوح حاليا (إن وجد)
  const pathModal = document.getElementById('path-modal');
  if(pathModal && pathModal.classList.contains('active')){
    const isTeacher = serviceId.startsWith('tch-');
    if(isTeacher) openTeacherPath();
    else openStudentPath();
  }

  // أعد رسم لوحة إدارة المسارات (إن كانت مفتوحة)
  try{
    if(typeof renderPathsAdminPanel === 'function') renderPathsAdminPanel();
  }catch(e){}
}

window.openServiceStatusMenu = openServiceStatusMenu;
window._setServiceStatus = _setServiceStatus;

function closePathModal(){
  document.getElementById('path-modal').classList.remove('active');
  document.body.style.overflow = '';
}

function goToCustomQuestions(){
  // يذهب مباشرة لشاشة إضافة الأسئلة المخصصة
  const btn = document.getElementById('editor-menu-btn');
  if(btn) btn.click();
  else showScreen('screen-custom-q');
}

// ESC يغلق المودال
document.addEventListener('keydown', function(e){
  if(e.key === 'Escape'){
    const modal = document.getElementById('path-modal');
    if(modal && modal.classList.contains('active')) closePathModal();
  }
});
