let _currentBadgeFilter = 'all';

// ═══════════════════════════════════════════════════════════════════
// تبديل علامة تبويب الدليل (معلم / طالب)
// ═══════════════════════════════════════════════════════════════════
function switchGuideTab(role){
  // تحديث الأزرار
  document.querySelectorAll('.guide-tab').forEach(t=>{
    t.classList.toggle('active', t.dataset.guide === role);
  });
  // تحديث المحتوى
  document.querySelectorAll('.guide-content').forEach(c=>{
    c.classList.remove('active');
  });
  const target = document.getElementById('guide-'+role);
  if(target) target.classList.add('active');
  // التمرير لأعلى الدليل
  try{ window.scrollTo({top:150, behavior:'smooth'}); }catch(e){}
}

function openAchievements(){
  showScreen('screen-achievements');
  renderAchievements();
}

function renderAchievements(){
  const stats = getUserStats();
  const earned = new Set(stats.earnedBadges);

  // تحديث الملخص
  document.getElementById('ah-earned-count').textContent = earned.size;
  document.getElementById('ah-skills-count').textContent = (stats.earnedSkills||[]).length;
  document.getElementById('ah-activities-count').textContent = stats.totalActivities || 0;

  // بناء شبكة الشارات
  const grid = document.getElementById('badges-grid');
  if(!grid) return;

  grid.innerHTML = Object.entries(BADGES).filter(([id, b])=>{
    if(_currentBadgeFilter === 'all') return true;
    if(_currentBadgeFilter === 'earned') return earned.has(id);
    return b.category === _currentBadgeFilter;
  }).map(([id, b])=>{
    const isEarned = earned.has(id);
    return `
      <div class="badge-item ${isEarned?'earned':'locked'}" onclick="showBadgeDetails('${id}')">
        <div class="badge-icon-wrap" style="background:${isEarned?`linear-gradient(135deg,${BADGE_TIERS[b.tier].gradient[0]},${BADGE_TIERS[b.tier].gradient[1]})`:'#cfd8dc'};color:${isEarned?b.color:'#9e9e9e'};"> ${isEarned ? '<div class="badge-tier-ring"></div>' : ''}
          <svg viewBox="0 0 24 24">${getBadgeIcon(b.icon)}</svg>
        </div>
        <div class="badge-name">${b.name}</div>
        <div class="badge-tier ${b.tier}">${BADGE_TIERS[b.tier].label}</div>
      </div> `;
  }).join('') || '<p style="grid-column:1/-1;text-align:center;color:#888;padding:20px;font-weight:700;">لا توجد شارات في هذه الفئة</p>';

  // مسارات المهارات
  renderSkillTracks();
}

function renderSkillTracks(){
  const stats = getUserStats();
  const skillsGrid = document.getElementById('skills-grid');
  if(!skillsGrid) return;

  skillsGrid.innerHTML = Object.entries(SKILL_TRACKS).map(([id, track])=>{
    // حساب التقدم
    let completed = 0;
    const reqsHtml = track.requirements.map(req=>{
      const done = evaluateSkillReq(req, stats);
      if(done) completed++;
      return `
        <div class="skill-req ${done?'done':''}">
          <svg viewBox="0 0 24 24" fill="currentColor">${done?'<path d="M9 16.17L4.83 12l-1.42 1.41L9 19 21 7l-1.41-1.41L9 16.17z"/>':'<circle cx="12" cy="12" r="10" fill="none" stroke="currentColor" stroke-width="2"/>'}</svg>
          <span>${req.label}</span>
        </div> `;
    }).join('');

    const total = track.requirements.length;
    const pct = Math.round((completed/total) * 100);
    const isEarned = completed === total;

    return `
      <div class="skill-track-card ${isEarned?'earned':''}">
        <div class="skill-track-header">
          <div class="skill-track-icon" style="background:linear-gradient(135deg,${track.gradient[0]},${track.gradient[1]});">
            <svg viewBox="0 0 24 24">${getBadgeIcon(track.icon)}</svg>
          </div>
          <div class="skill-track-info">
            <div class="skill-track-name">${track.name}</div>
            <div class="skill-track-desc">${track.desc}</div>
          </div>
          <div class="skill-track-progress">${completed}/${total}</div>
        </div>
        <div class="skill-requirements">${reqsHtml}</div>
      </div> `;
  }).join('');
}

function evaluateSkillReq(req, stats){
  switch(req.type){
    case 'quizzes_above_80': return (stats.quizzesAbove90||0) >= req.count || (stats.bestQuizScore||0) >= 80 && (stats.quizzesTaken||0) >= req.count;
    case 'activities_done': return (stats.totalActivities||0) >= req.count;
    case 'categories_mastered': return (stats.masteriesCount||0) >= req.count;
    case 'history_mastery': return ((stats.categoryMastery||{}).history||0) >= req.count;
    case 'qatar_mastery': return ((stats.categoryMastery||{}).qatar||0) >= req.count;
    case 'legend_plays': return (stats.legendPlays||0) >= req.count;
    case 'quizzes_taken': return (stats.quizzesTaken||0) >= req.count;
    case 'badges': return (stats.earnedBadges||[]).length >= req.count;
    case 'best_score': return (stats.bestQuizScore||0) >= req.count;
    case 'max_streak': return (stats.maxStreak||0) >= req.count;
    case 'skills_earned': return (stats.earnedSkills||[]).length >= req.count;
    default: return false;
  }
}

// فلتر الشارات
document.addEventListener('click', (e)=>{
  if(e.target.matches('.filter-btn')){
    document.querySelectorAll('.filter-btn').forEach(b=>b.classList.remove('active'));
    e.target.classList.add('active');
    _currentBadgeFilter = e.target.dataset.filter;
    renderAchievements();
  }
});

// عرض تفاصيل الشارة
function showBadgeDetails(badgeId){
  const badge = BADGES[badgeId];
  if(!badge) return;
  const stats = getUserStats();
  const isEarned = (stats.earnedBadges||[]).includes(badgeId);

  const header = document.getElementById('badge-modal-header');
  const icon = document.getElementById('badge-modal-icon');
  const status = document.getElementById('badge-modal-status');
  const name = document.getElementById('badge-modal-name');
  const desc = document.getElementById('badge-modal-desc');
  const shareBtn = document.getElementById('badge-share-btn');

  header.style.background = isEarned 
    ? `linear-gradient(135deg,${BADGE_TIERS[badge.tier].gradient[0]},${BADGE_TIERS[badge.tier].gradient[1]})`
    : 'linear-gradient(135deg,#757575,#424242)';

  icon.style.background = isEarned
    ? `linear-gradient(135deg,${BADGE_TIERS[badge.tier].gradient[0]},${BADGE_TIERS[badge.tier].gradient[1]})`
    : '#9e9e9e';
  icon.innerHTML = `<svg viewBox="0 0 24 24">${getBadgeIcon(badge.icon)}</svg>`;

  status.innerHTML = isEarned ? `✓ ${BADGE_TIERS[badge.tier].label} · محققة` : '<svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M18 8h-1V6c0-2.76-2.24-5-5-5S7 3.24 7 6v2H6c-1.1 0-2 .9-2 2v10c0 1.1.9 2 2 2h12c1.1 0 2-.9 2-2V10c0-1.1-.9-2-2-2zM12 17a2 2 0 010-4 2 2 0 010 4zM9 8V6c0-1.66 1.34-3 3-3s3 1.34 3 3v2H9z"/></svg> مقفلة';
  name.textContent = badge.name;
  desc.textContent = badge.desc;
  shareBtn.style.display = isEarned ? 'inline-flex' : 'none';
  shareBtn.dataset.badgeId = badgeId;

  document.getElementById('badge-modal-overlay').classList.add('active');
  document.body.style.overflow = 'hidden';
}

function closeBadgeModal(){
  document.getElementById('badge-modal-overlay').classList.remove('active');
  document.body.style.overflow = '';
}

// مشاركة شارة
function shareBadge(){
  const btn = document.getElementById('badge-share-btn');
  const badgeId = btn.dataset.badgeId;
  const badge = BADGES[badgeId];
  if(!badge) return;

  const text = `<svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M19 5h-2V3H7v2H5c-1.1 0-2 .9-2 2v1c0 2.55 1.92 4.63 4.39 4.94A5.01 5.01 0 0011 15.9V19H7v2h10v-2h-4v-3.1A5.01 5.01 0 0016.61 12.94C19.08 12.63 21 10.55 21 8V7c0-1.1-.9-2-2-2zM5 8V7h2v3.82C5.84 10.4 5 9.3 5 8zm14 0c0 1.3-.84 2.4-2 2.82V7h2v1z"/></svg> حصلت على شارة "${badge.name}" في منصة الملهم التعليمية!\n\n${badge.desc}\n\nانضم إلي: https://almulhimedu.org`;

  if(navigator.share){
    navigator.share({title: 'شارة الملهم', text: text, url: 'https://almulhimedu.org'})
      .catch(e=>{});
  } else {
    // نسخ للحافظة
    navigator.clipboard.writeText(text).then(()=>{
      toast('تم نسخ النص · الصقه في واتساب/تويتر','success');
    }).catch(()=>{
      toast('تعذر النسخ','error');
    });
  }
}

// إشعار فتح شارة جديدة
function showBadgeUnlockModal(badge){
  const overlay = document.getElementById('unlock-overlay');
  const icon = document.getElementById('unlock-big-icon');
  const name = document.getElementById('unlock-name');
  const desc = document.getElementById('unlock-desc');

  icon.style.background = `linear-gradient(135deg,${BADGE_TIERS[badge.tier].gradient[0]},${BADGE_TIERS[badge.tier].gradient[1]})`;
  icon.innerHTML = `<svg viewBox="0 0 24 24">${getBadgeIcon(badge.icon)}</svg>`;
  name.textContent = badge.name;
  desc.textContent = badge.desc;

  overlay.classList.add('active');
  document.body.style.overflow = 'hidden';

  // صوت تأثير (اختياري)
  try{
    const audioContext = new (window.AudioContext || window.webkitAudioContext)();
    const osc = audioContext.createOscillator();
    const gain = audioContext.createGain();
    osc.connect(gain);
    gain.connect(audioContext.destination);
    osc.frequency.setValueAtTime(523.25, audioContext.currentTime);
    osc.frequency.exponentialRampToValueAtTime(1046.50, audioContext.currentTime + 0.3);
    gain.gain.setValueAtTime(0.1, audioContext.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, audioContext.currentTime + 0.5);
    osc.start();
    osc.stop(audioContext.currentTime + 0.5);
  }catch(e){}
}

function closeUnlockModal(){
  document.getElementById('unlock-overlay').classList.remove('active');
  document.body.style.overflow = '';
}

// مشاركة/طباعة ملف الإنجازات PDF
async function sharePDFAchievements(){
  // تحميل html2pdf ديناميكيا لو مش محمل
  if(typeof html2pdf === 'undefined'){
    toast('جاري تحضير المكتبة...','info');
    await loadScript('https://cdnjs.cloudflare.com/ajax/libs/html2pdf.js/0.10.1/html2pdf.bundle.min.js');
  }

  const stats = getUserStats();
  const earned = new Set(stats.earnedBadges);
  const earnedBadges = Object.entries(BADGES).filter(([id])=>earned.has(id));

  // بناء HTML للـ PDF
  const pdfContent = document.createElement('div');
  pdfContent.style.cssText = 'font-family:Cairo,Arial,sans-serif;direction:rtl;padding:40px;background:#fff;width:210mm;color:#5E0E26;';
  pdfContent.innerHTML = `
    <div style="text-align:center;border-bottom:3px solid #B8924A;padding-bottom:20px;margin-bottom:30px;">
      <div style="font-size:28px;font-weight:900;color:#8A1538;margin-bottom:6px;">منصة الملهم التعليمية</div>
      <div style="font-size:14px;color:#6b7c8e;font-weight:600;">ملف الإنجازات الشخصي</div>
    </div>
    <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-bottom:30px;">
      <div style="background:#F8F8F6;border:1.5px solid #B8924A;padding:16px;border-radius:12px;text-align:center;">
        <div style="font-size:32px;font-weight:900;color:#8A6D2E;">${earned.size}</div>
        <div style="font-size:12px;color:#6b7c8e;font-weight:700;margin-top:4px;">شارة محققة</div>
      </div>
      <div style="background:#e8f2ec;border:1.5px solid #8A1538;padding:16px;border-radius:12px;text-align:center;">
        <div style="font-size:32px;font-weight:900;color:#5E0E26;">${(stats.earnedSkills||[]).length}</div>
        <div style="font-size:12px;color:#6b7c8e;font-weight:700;margin-top:4px;">مهارة متقنة</div>
      </div>
      <div style="background:#fce8ee;border:1.5px solid #8A1538;padding:16px;border-radius:12px;text-align:center;">
        <div style="font-size:32px;font-weight:900;color:#8A1538;">${stats.totalActivities||0}</div>
        <div style="font-size:12px;color:#6b7c8e;font-weight:700;margin-top:4px;">نشاط مكمل</div>
      </div>
    </div>
    <h3 style="font-size:18px;font-weight:900;color:#8A1538;margin-bottom:14px;border-right:4px solid #B8924A;padding-right:10px;">الشارات المحققة</h3>
    <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:30px;"> ${earnedBadges.length === 0 ? '<div style="grid-column:1/-1;text-align:center;color:#6b7c8e;padding:20px;">لم يتم تحقيق شارات بعد</div>' : earnedBadges.map(([id,b])=>`
        <div style="background:#fff;border:1.5px solid ${b.color};border-radius:10px;padding:10px;text-align:center;">
          <div style="font-weight:900;font-size:13px;color:#5E0E26;margin-bottom:3px;">${b.name}</div>
          <div style="font-size:10px;color:#6b7c8e;line-height:1.4;">${b.desc}</div>
          <div style="font-size:9px;font-weight:800;color:${b.color};margin-top:4px;">${BADGE_TIERS[b.tier].label}</div>
        </div> `).join('')}
    </div>
    <div style="margin-top:40px;padding-top:20px;border-top:2px solid #e8f2ec;display:flex;justify-content:space-between;align-items:center;font-size:11px;color:#6b7c8e;">
      <div>تاريخ الإصدار: ${new Date().toLocaleDateString('ar-QA',{year:'numeric',month:'long',day:'numeric'})}</div>
      <div>alhalhali.com</div>
    </div> `;

  try{
    document.body.appendChild(pdfContent);
    pdfContent.style.position = 'fixed';
    pdfContent.style.left = '-9999px';
    await html2pdf().set({
      margin:0, filename:'ملف_إنجازاتي_الملهم.pdf',
      image:{type:'jpeg', quality:0.98},
      html2canvas:{scale:2, useCORS:true, backgroundColor:'#ffffff'},
      jsPDF:{unit:'mm', format:'a4', orientation:'portrait'}
    }).from(pdfContent).save();
    document.body.removeChild(pdfContent);
    toast('تم تحميل ملف الإنجازات','success');
  }catch(e){
    console.error(e);
    toast('تعذر إنشاء الملف','error');
  }
}

function loadScript(src){
  return new Promise((res,rej)=>{
    const s = document.createElement('script');
    s.src = src; s.onload = res; s.onerror = rej;
    document.head.appendChild(s);
  });
}
// ═══════════════════════════════════════════════════════════════════

//  سجل التنقل (للرجوع الذكي)
window._screenHistory = window._screenHistory || [];

var HH_IMMERSIVE_SCREENS = ['screen-board'];
function showScreen(id){
  // اللعب الغامر: شاشات اللعب تُخفي أشرطة المنصة وإطارها
  try{ document.body.classList.toggle('hh-immersive', HH_IMMERSIVE_SCREENS.indexOf(id)!==-1); }catch(e){}
  // أضف الشاشة الحالية للسجل قبل الانتقال
  const currentActive = document.querySelector('.screen.active');
  if(currentActive && currentActive.id && currentActive.id !== id){
    // لا نضيف نفس الشاشة مرتين متتاليتين
    if(window._screenHistory[window._screenHistory.length - 1] !== currentActive.id){
      window._screenHistory.push(currentActive.id);
    }
    // حد أقصى للسجل (لا نريد ذاكرة لا نهائية)
    if(window._screenHistory.length > 20) window._screenHistory.shift();
  }
  document.querySelectorAll('.screen').forEach(s=>s.classList.remove('active'));
  document.getElementById(id).classList.add('active');
  //  العودة لأعلى الصفحة عند الدخول لأي شاشة (حل مشكلة التمرير التلقائي)
  window.scrollTo(0, 0);
  //  تحديث شريط التنقل السفلي
  try{ hh_updateBottomNav(id); }catch(e){}
  // إظهار أزرار الإدارة السريعة للأدمن
  try{
    const isAdm = (typeof isAdminUser==='function' && isAdminUser(currentUser));
    const tbxAdm = document.getElementById('tbx-admin-quick');
    if(tbxAdm) tbxAdm.style.display = (isAdm && id==='screen-toolbox') ? 'inline-flex' : 'none';
    const tbxBar = document.getElementById('tbx-admin-quickbar');
    if(tbxBar) tbxBar.style.display = (isAdm && id==='screen-toolbox') ? 'block' : 'none';
  }catch(e){}
  //  تطبيق حالة المحبرة (إخفاء/إظهار/متاح/قريبا) عند فتحها
  if(id==='screen-toolbox'){
    try{ if(typeof applyToolboxStates==='function') applyToolboxStates(); }catch(e){}
  }
  if(id==='screen-reviews') loadHomeReviews();
  // إيقاف real-time listeners عند مغادرة المتصدرين
  if(id!=='screen-lb') stopLBListeners();
  if(id==='screen-setup'){
    buildCatSelect();
    //  اقتراح تلقائي لاسم اللعبة إذا فارغ
    try{
      const gn = document.getElementById('game-name');
      if(gn && !gn.value.trim()){
        setTimeout(()=>autoGameName(), 150);
      }
    }catch(e){}
    //  اقتراح تلقائي لأسماء الفرق
    try{ autoSuggestTeamNames(); }catch(e){}
  }
  if(id==='screen-custom-q'){
    if(!isAllowedEditor()){
      showScreen('screen-menu');
      toast('ليس لديك صلاحية هذه الميزة','error');
      return;
    }
    renderCustomQList();
  }
  // تحديث التصميم الملكي عند الدخول للقائمة
  if(id==='screen-menu') updateRoyalGreeting();
  //  تشغيل العدّ التصاعدي لشريط الإحصائيات التعريفي
  if(id==='screen-menu'){ try{ hh_initHeroStatsObserver(); }catch(e){} }
  //  تحميل شخصيات الرعاة عند فتح صفحة الشخصيات
  if(id==='screen-influencers' || id==='screen-sponsors'){
    try{ loadInfluencers(); }catch(e){ console.error('loadInfluencers error:', e); }
  }
}

//  الرجوع الذكي للشاشة السابقة (يحفظ سياق المستخدم)
function goBack(fallback){
  const fb = fallback || 'screen-menu';
  if(window._screenHistory && window._screenHistory.length > 0){
    const previous = window._screenHistory.pop();
    if(previous && document.getElementById(previous)){
      // عرض مباشر بدون إضافة للسجل (لأنه رجوع، ليس انتقال جديد)
      document.querySelectorAll('.screen').forEach(s=>s.classList.remove('active'));
      document.getElementById(previous).classList.add('active');
      window.scrollTo(0, 0);
      // تحديث التحية إذا رجع للقائمة
      if(previous==='screen-menu') updateRoyalGreeting();
      return;
    }
  }
  // لا يوجد سجل → اذهب للوجهة الافتراضية
  showScreen(fb);
}

// تحديث التحية الديناميكية في التصميم الملكي
function updateRoyalGreeting(){
  try{
    const greetEl=document.getElementById('royal-greeting-time');
    const nameEl=document.getElementById('royal-username-text');
    if(greetEl){
      const h=new Date().getHours();
      let greeting='مرحبا';
      if(h>=4 && h<12)       greeting='صباح الخير';
      else if(h>=12 && h<17) greeting='مساء النور';
      else if(h>=17 && h<21) greeting='مساء الخير';
      else                    greeting='أهلا بك';
      greetEl.textContent=greeting;
    }
    if(nameEl){
      const userNameEl=document.getElementById('ub-name');
      let name=userNameEl ? userNameEl.textContent.trim() : '';
      
      // إذا الاسم إنجليزي، نستخدم لقب عربي أنيق
      const hasArabic = /[\u0600-\u06FF]/.test(name);
      if(!name || name==='مستخدم' || !hasArabic){
        // نحاول استخراج الاسم العربي من displayName
        const display = currentUser?.displayName || '';
        if(/[\u0600-\u06FF]/.test(display)){
          name = display.trim().split(/\s+/)[0];
        } else {
          name = 'أيها الملهم';
        }
      } else {
        // نأخذ الاسم الأول فقط لو كان كاملا
        const parts = name.split(/\s+/);
        if(parts.length > 1) name = parts[0];
      }
      nameEl.textContent = name;
    }
  }catch(e){}
}
function shuffle(a){const r=[...a];for(let i=r.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[r[i],r[j]]=[r[j],r[i]];}return r;}
function deleteGameHistory(idx){
  if(!confirm('حذف هذه اللعبة من السجل؟')) return;
  try{
    const hist=JSON.parse(localStorage.getItem('hh_game_history')||'[]');
    const removed = hist[idx];
    hist.splice(idx,1);
    localStorage.setItem('hh_game_history',JSON.stringify(hist));
    
    // حذف سحابي إن وجد _docId
    if(removed && removed._docId && !OFFLINE_MODE && db && currentUser){
      db.collection('user_games').doc(removed._docId).delete().catch(err=>{
        console.warn('cloud delete game:', err);
      });
    }
    
    renderMyGames();
    toast('تم حذف اللعبة','info');
  }catch(e){}
}

//  بناء أيقونة فئة مصغّرة فاخرة لبطاقات ألعابي السابقة
function _hhCatThumb(cat){
  var ci = (typeof CAT_INFO !== 'undefined' && CAT_INFO[cat]) ? CAT_INFO[cat] : null;
  var label = ci && ci.label ? ci.label : cat;
  var color = ci && ci.color ? ci.color : '#8A1538';
  var bg = ci && ci.bg ? ci.bg : '#F7EBEE';
  var inner;
  if(ci && ci.img){
    inner = '<img src="'+ci.img+'" alt="" style="width:100%;height:100%;object-fit:contain;padding:4px;box-sizing:border-box;">';
  } else if(ci && ci.emoji && ci.emoji.indexOf('<svg') !== -1){
    inner = '<span style="font-size:20px;color:'+color+';display:flex;align-items:center;justify-content:center;width:100%;height:100%;">'+ci.emoji+'</span>';
  } else if(ci && ci.emoji && ci.emoji.trim()){
    inner = '<span style="font-size:22px;line-height:1;">'+ci.emoji+'</span>';
  } else {
    // حرف أول الفئة على خلفية ملوّنة
    inner = '<span style="font-family:Cairo,sans-serif;font-weight:900;font-size:20px;color:#fff;">'+esc((label||'؟').charAt(0))+'</span>';
  }
  var iconBg = (ci && ci.img) ? '#fff' : ((ci && ci.emoji && ci.emoji.trim() && ci.emoji.indexOf('<svg')===-1) ? bg : color);
  return '<div style="position:relative;border-radius:11px;overflow:hidden;aspect-ratio:1;background:'+iconBg+';display:flex;flex-direction:column;align-items:center;justify-content:center;box-shadow:0 2px 6px rgba(0,0,0,.1);">' + '<div style="flex:1;display:flex;align-items:center;justify-content:center;width:100%;min-height:0;">'+inner+'</div>' + '<div style="width:100%;background:'+color+';color:#fff;font-family:Cairo,sans-serif;font-weight:800;font-size:8.5px;text-align:center;padding:2px 3px;line-height:1.15;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">'+esc(label)+'</div>' + '</div>';
}

function renderMyGames(){
  const el=document.getElementById('my-games-list');
  const countEl=document.getElementById('my-games-count');
  if(!el)return;
  try{
    const hist=JSON.parse(localStorage.getItem('hh_game_history')||'[]');
    if(countEl){
      const n = hist.length;
      countEl.textContent = (n === 0 ? 'لا توجد' : n.toLocaleString('en-US')) + ' ' + (n === 1 ? 'لعبة' : (n === 2 ? 'لعبتان' : (n >= 3 && n <= 10 ? 'ألعاب' : 'لعبة')));
    }
    if(!hist.length){
      el.innerHTML=`<div style="text-align:center;padding:32px 20px;background:#fff;border:1.5px dashed #d0d8d0;border-radius:14px;">
        <svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="#B8924A" stroke-width="1.5" style="margin:0 auto 12px;display:block;opacity:.6;"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>
        <div style="color:#8A1538;font-size:.92rem;font-weight:900;">لا توجد ألعاب محفوظة بعد</div>
        <div style="color:#888;font-size:.78rem;margin-top:6px;line-height:1.6;">العب لعبة جديدة وستظهر هنا تلقائيا<br>مع كل التفاصيل والنتائج</div>
      </div>`;
      return;
    }
    el.innerHTML=hist.map((g,idx)=>{
      // تحليل النقاط للتلوين
      const teamsRaw = (g.teams||'').split(' | ');
      const teamsHTML = teamsRaw.slice(0,3).map(t=>{
        const m = t.match(/^(.+):\s*(-?\d+)$/);
        if(!m) return `<span style="font-size:.72rem;color:#555;">${esc(t)}</span>`;
        const pts = parseInt(m[2]);
        const color = pts > 0 ? '#3D6B53' : pts < 0 ? '#c0392b' : '#888';
        const bg = pts > 0 ? '#EBF2EE' : pts < 0 ? '#fdecea' : '#f5f5f5';
        return `<span style="font-size:.7rem;font-weight:800;color:${color};background:${bg};padding:2px 8px;border-radius:6px;">${esc(m[1])}: ${pts.toLocaleString('en-US')}</span>`;
      }).join('') + (teamsRaw.length > 3 ? `<span style="font-size:.7rem;color:#888;font-weight:700;">+${teamsRaw.length - 3}</span>` : '');

      return `<div onclick="openGameOptionsModal(${idx})"
        style="background:#fff;border:1.5px solid #e0e6e0;border-right:4px solid #B8924A;border-radius:14px;padding:14px;margin-bottom:10px;box-shadow:0 2px 8px rgba(138,21,56,.06);cursor:pointer;transition:all .2s;"
        onmouseover="this.style.borderRightColor='#8A1538';this.style.transform='translateY(-1px)';this.style.boxShadow='0 6px 16px rgba(138,21,56,.12)'"
        onmouseout="this.style.borderRightColor='#B8924A';this.style.transform='';this.style.boxShadow='0 2px 8px rgba(138,21,56,.06)'">
        <!-- رأس البطاقة -->
        <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:10px;margin-bottom:10px;">
          <div style="flex:1;min-width:0;">
            <div style="font-family:Cairo,sans-serif;font-weight:900;font-size:.95rem;color:#5E0E26;margin-bottom:3px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${esc(g.name||'لعبة بدون اسم')}</div>
            <div style="font-size:.7rem;color:#888;display:flex;align-items:center;gap:5px;font-weight:700;">
              <svg width="11" height="11" viewBox="0 0 24 24" fill="currentColor"><path d="M19 4h-1V2h-2v2H8V2H6v2H5c-1.11 0-1.99.9-1.99 2L3 20a2 2 0 002 2h14c1.1 0 2-.9 2-2V6c0-1.1-.9-2-2-2zm0 16H5V10h14v10zM5 8V6h14v2H5z"/></svg> ${esc(g.date||'')}
            </div>
          </div>
          <!-- الفائز -->
          <div style="display:flex;align-items:center;gap:5px;background:linear-gradient(135deg,#fffbea,#fef3d6);border:1.5px solid #d4b740;border-radius:9px;padding:4px 10px;flex-shrink:0;">
            <svg width="13" height="13" viewBox="0 0 24 24" fill="#d4b740" stroke="#8A6D2E" stroke-width="0.5"><polygon points="12,2 15,9 22,9 17,14 19,21 12,17 5,21 7,14 2,9 9,9"/></svg>
            <span style="font-size:.72rem;font-weight:900;color:#8A1538;">${esc(g.winner||'·')}</span>
          </div>
        </div>
        <!-- الفئات: شبكة أيقونات فاخرة -->
        <div style="margin-bottom:8px;background:linear-gradient(135deg,#f8fbf9,#f3f9f5);padding:10px;border-radius:12px;border:1px solid #e3efe8;">
          <div style="display:flex;align-items:center;gap:5px;margin-bottom:8px;">
            <svg width="12" height="12" viewBox="0 0 24 24" fill="#3D6B53" style="vertical-align:middle;"><rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/></svg>
            <span style="font-size:.68rem;color:#3D6B53;font-weight:900;font-family:Cairo,sans-serif;">الفئات الملعوبة</span>
          </div> ${(function(){
            var arr = Array.isArray(g.catsArr) ? g.catsArr : (g.cats||'').split(/[،,]/).map(function(c){return c.trim();}).filter(Boolean);
            if(!arr.length) return '<span style="font-size:.7rem;color:#999;">·</span>';
            var maxShow = 6;
            var shown = arr.slice(0, maxShow);
            var rest = arr.length - maxShow;
            var thumbs = shown.map(function(c){ return _hhCatThumb(c); }).join('');
            if(rest > 0){
              thumbs += '<div style="border-radius:11px;aspect-ratio:1;background:linear-gradient(135deg,#8A1538,#5E0E26);display:flex;align-items:center;justify-content:center;color:#f0d784;font-family:Cairo,sans-serif;font-weight:900;font-size:14px;box-shadow:0 2px 6px rgba(138,21,56,.2);">+'+rest+'</div>';
            }
            return '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(64px,1fr));gap:7px;">'+thumbs+'</div>';
          })()}
        </div>
        <!-- النقاط (ملخصة) -->
        <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;">
          <div style="display:flex;flex-wrap:wrap;gap:5px;flex:1;">${teamsHTML}</div>
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#B8924A" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" style="flex-shrink:0;">
            <polyline points="15 18 9 12 15 6"/>
          </svg>
        </div>
      </div>`;
    }).join('');
  }catch(e){
    el.innerHTML='<p style="text-align:center;color:#c00;padding:20px">حدث خطأ في التحميل</p>';
  }
}

// ═══ نظام مودال خيارات اللعبة + إعادة اللعب ═══

let _currentGameOptionsIdx = -1;

/**
 * فتح مودال خيارات لعبة من السجل
 */
function openGameOptionsModal(idx){
  try{
    const hist = JSON.parse(localStorage.getItem('hh_game_history')||'[]');
    const g = hist[idx];
    if(!g) return;
    _currentGameOptionsIdx = idx;

    document.getElementById('gom-game-name').textContent = g.name || 'لعبة بدون اسم';
    document.getElementById('gom-game-date').textContent = g.date || '';
    (function(){
      var catsEl = document.getElementById('gom-cats');
      if(!catsEl) return;
      var cats = (g.cats||'').split(/[،,]/).map(function(c){return c.trim();}).filter(Boolean);
      if(!cats.length){ catsEl.innerHTML = '<span style="color:#999;">·</span>'; return; }
      catsEl.innerHTML = '<div style="display:flex;flex-wrap:wrap;gap:5px;">' + cats.map(function(c){
        return '<span style="display:inline-block;font-size:.75rem;font-weight:700;color:#3D6B53;background:#f5fbf7;border:1px solid #cfe5d8;padding:4px 11px;border-radius:20px;font-family:Tajawal,sans-serif;">' + esc(c) + '</span>';
      }).join('') + '</div>';
    })();

    // الفرق
    const teamsRaw = (g.teams||'').split(' | ');
    const teamsHTML = teamsRaw.map(t => {
      const m = t.match(/^(.+):\s*(-?\d+)$/);
      if(!m) return `<span style="font-size:.78rem;color:#555;background:#f0f0f0;padding:4px 10px;border-radius:8px;">${esc(t)}</span>`;
      const pts = parseInt(m[2]);
      const color = pts > 0 ? '#3D6B53' : pts < 0 ? '#c0392b' : '#666';
      const bg = pts > 0 ? '#EBF2EE' : pts < 0 ? '#fdecea' : '#f5f5f5';
      return `<span style="font-size:.78rem;font-weight:900;color:${color};background:${bg};padding:5px 11px;border-radius:9px;border:1px solid ${color}30;">${esc(m[1])}: ${pts.toLocaleString('en-US')}</span>`;
    }).join('');
    document.getElementById('gom-teams').innerHTML = teamsHTML;

    document.getElementById('game-options-modal').style.display = 'flex';
  }catch(e){
    if(typeof toast === 'function') toast('حدث خطأ', 'error');
  }
}

function closeGameOptionsModal(){
  document.getElementById('game-options-modal').style.display = 'none';
  _currentGameOptionsIdx = -1;
}

function deleteGameFromModal(){
  if(_currentGameOptionsIdx < 0) return;
  if(!confirm('هل تريد حذف هذه اللعبة من السجل؟')) return;
  try{
    const hist = JSON.parse(localStorage.getItem('hh_game_history')||'[]');
    hist.splice(_currentGameOptionsIdx, 1);
    localStorage.setItem('hh_game_history', JSON.stringify(hist));
    closeGameOptionsModal();
    renderMyGames();
    if(typeof toast === 'function') toast('تم حذف اللعبة', 'success');
  }catch(e){
    if(typeof toast === 'function') toast('حدث خطأ', 'error');
  }
}

/**
 * فتح مودال إعادة اللعب (من داخل مودال الخيارات)
 */
function openReplayModal(){
  if(_currentGameOptionsIdx < 0) return;
  try{
    const hist = JSON.parse(localStorage.getItem('hh_game_history')||'[]');
    const g = hist[_currentGameOptionsIdx];
    if(!g || !g.catsArr || !g.teamsArr){
      if(typeof toast === 'function') toast('لا يمكن إعادة هذه اللعبة (بيانات قديمة)', 'error');
      return;
    }

    // اسم اللعبة
    const gameNameInput = document.getElementById('replay-game-name');
    gameNameInput.value = g.name || '';

    // الفئات (للعرض)
    const catsList = document.getElementById('replay-cats-list');
    if(catsList){
      const catsArr = Array.isArray(g.catsArr) ? g.catsArr : [];
      catsList.innerHTML = catsArr.map(c => `<span style="display:inline-block;background:#fff;border:1px solid #d0e0d4;border-radius:7px;padding:3px 9px;margin:2px 3px;font-size:.74rem;color:#8A1538;font-weight:700;">${esc(c)}</span>`).join('');
    }

    // الفرق (قابلة للتعديل)
    const teamsContainer = document.getElementById('replay-teams-inputs');
    if(teamsContainer){
      const teams = Array.isArray(g.teamsArr) ? g.teamsArr : [];
      teamsContainer.innerHTML = teams.map((team, i) => {
        // teamsArr يحوي إما أسماء (strings) أو كائنات {name, ...}
        const name = typeof team === 'string' ? team : (team && team.name) || ('الفريق ' + (i+1));
        const colors = ['#8A1538','#1E3A5F','#B8924A','#8A1538','#922b21','#3D4A7A','#3D6B53','#8A6D2E'];
        const color = colors[i % colors.length];
        return `
          <div style="display:flex;align-items:center;gap:8px;background:#fafaf5;border:1.5px solid #e0e6e0;border-right:3px solid ${color};border-radius:9px;padding:8px 10px;">
            <div style="width:26px;height:26px;background:${color};color:#fff;border-radius:50%;display:flex;align-items:center;justify-content:center;font-family:Cairo;font-weight:900;font-size:.75rem;flex-shrink:0;">${(i+1).toLocaleString('en-US')}</div>
            <input type="text" class="replay-team-input" data-team-idx="${i}" value="${esc(name)}"
                   style="flex:1;border:none;background:transparent;outline:none;font-family:Cairo;font-weight:800;color:#1a1a2e;font-size:.88rem;padding:4px 0;">
          </div> `;
      }).join('');
    }

    // إغلاق مودال الخيارات وفتح مودال الإعادة
    document.getElementById('game-options-modal').style.display = 'none';
    document.getElementById('replay-modal').style.display = 'flex';
  }catch(e){
    console.error(e);
    if(typeof toast === 'function') toast('حدث خطأ', 'error');
  }
}

function closeReplayModal(){
  document.getElementById('replay-modal').style.display = 'none';
  // أعد فتح مودال الخيارات إن أراد المستخدم العودة
  if(_currentGameOptionsIdx >= 0){
    document.getElementById('game-options-modal').style.display = 'flex';
  }
}

/**
 * بدء لعبة معادة بنفس الفئات + أسماء فرق محدثة
 */
function startReplayGame(){
  if(_currentGameOptionsIdx < 0) return;
  try{
    const hist = JSON.parse(localStorage.getItem('hh_game_history')||'[]');
    const g = hist[_currentGameOptionsIdx];
    if(!g || !g.catsArr) return;

    // اسم اللعبة الجديدة
    const newName = (document.getElementById('replay-game-name').value || '').trim()
      || (g.name + ' (إعادة)');

    // أسماء الفرق الجديدة
    const teamInputs = document.querySelectorAll('.replay-team-input');
    const newTeamNames = [];
    teamInputs.forEach(inp => {
      const name = (inp.value || '').trim();
      if(name) newTeamNames.push(name);
    });

    if(newTeamNames.length < 2){
      if(typeof toast === 'function') toast('يلزم فريقان على الأقل', 'error');
      return;
    }

    // إغلاق المودالات
    document.getElementById('replay-modal').style.display = 'none';
    document.getElementById('game-options-modal').style.display = 'none';
    _currentGameOptionsIdx = -1;

    // بدء اللعبة بنفس الفئات (الأسئلة ستختار عشوائيا تلقائيا عند البدء)
    if(typeof startGame === 'function'){
      startGame([...newTeamNames], [...g.catsArr], newName);
      if(typeof toast === 'function') toast('بدأت اللعبة بأسئلة جديدة!', 'success');
    } else {
      if(typeof toast === 'function') toast('تعذر بدء اللعبة', 'error');
    }
  }catch(e){
    console.error(e);
    if(typeof toast === 'function') toast('حدث خطأ', 'error');
  }
}

window.openGameOptionsModal = openGameOptionsModal;
window.closeGameOptionsModal = closeGameOptionsModal;
window.deleteGameFromModal = deleteGameFromModal;
window.openReplayModal = openReplayModal;
window.closeReplayModal = closeReplayModal;
window.startReplayGame = startReplayGame;

// حفظ اللعبة فور بدئها · تبقى في السجل حتى لو لم تكتمل
function hhSaveGameStart(){
  try{
    const gameData = {
      localId: G.gameLocalId,
      date:new Date().toLocaleDateString('ar-QA'),
      timestamp: Date.now(),
      name:G.gameName||'لعبة بدون اسم',
      cats:(G.selectedCats||[]).slice(0,3).join('، ')+((G.selectedCats||[]).length>3?'...':''),
      catsArr:G.selectedCats||[],
      teamsArr:G.teams||[],
      teamCount:(G.teams||[]).length,
      teams:(G.teams||[]).map(t=>t+': 0').join(' | '),
      winner:'·',
      status:'incomplete',      // تُحدَّث إلى complete عند الإنهاء
      isComp: !!G.isComp
    };
    // محلي
    const hist=JSON.parse(localStorage.getItem('hh_game_history')||'[]');
    hist.unshift(gameData);
    if(hist.length>50)hist.length=50;
    localStorage.setItem('hh_game_history',JSON.stringify(hist));
    // سحابي · نحفظ بمعرّف ثابت (localId) لنحدّثه لاحقاً بدل التكرار
    if(!OFFLINE_MODE && db && currentUser && currentUser.uid){
      db.collection('user_games').doc(G.gameLocalId).set({
        userId: currentUser.uid,
        userEmail: currentUser.email || '',
        ...gameData,
        createdAt: firebase.firestore.FieldValue.serverTimestamp()
      }).catch(()=>{});
    }
  }catch(e){ console.warn('hhSaveGameStart:', e); }
}

function saveGameHistory(sorted){
  try{
    const patch = {
      teams:sorted.map(t=>t.name+': '+t.pts).join(' | '),
      winner:sorted[0].name,
      status:'complete',
      completedAt: Date.now()
    };
    // 1) تحديث السجل المحلي (نبحث عن نفس localId)
    const hist=JSON.parse(localStorage.getItem('hh_game_history')||'[]');
    let found=false;
    for(let i=0;i<hist.length;i++){
      if(hist[i].localId && G.gameLocalId && hist[i].localId===G.gameLocalId){
        hist[i]=Object.assign({}, hist[i], patch); found=true; break;
      }
    }
    if(!found){
      // احتياط: لو لم يُحفظ عند البدء لأي سبب، ننشئه الآن كاملاً
      hist.unshift({
        localId:G.gameLocalId||('g'+Date.now()),
        date:new Date().toLocaleDateString('ar-QA'), timestamp:Date.now(),
        name:G.gameName||'لعبة', cats:(G.selectedCats||[]).slice(0,3).join('، '),
        catsArr:G.selectedCats||[], teamsArr:G.teams||[], teamCount:(G.teams||[]).length,
        isComp:!!G.isComp, ...patch
      });
    }
    if(hist.length>50)hist.length=50;
    localStorage.setItem('hh_game_history',JSON.stringify(hist));

    // 2) تحديث السحابة (نفس المستند بمعرّف localId)
    if(!OFFLINE_MODE && db && currentUser && currentUser.uid && G.gameLocalId){
      db.collection('user_games').doc(G.gameLocalId).set(patch, {merge:true}).catch(err=>{
        console.warn('cloud game update:', err);
      });
    }
  }catch(e){
    console.error('saveGameHistory:', e);
  }
}

// تحميل ألعاب المستخدم من السحابة
async function loadUserGamesFromCloud(){
  if(OFFLINE_MODE||!db||!currentUser||!currentUser.uid) return false;
  try{
    const snap = await db.collection('user_games')
      .where('userId','==',currentUser.uid)
      .orderBy('createdAt','desc')
      .limit(50)
      .get();
    
    if(snap.empty) return false;
    
    const cloudGames = [];
    snap.forEach(doc => {
      const data = doc.data();
      cloudGames.push({
        _docId: doc.id, // للحذف لاحقا
        date: data.date || '',
        timestamp: data.timestamp || 0,
        name: data.name || 'لعبة بدون اسم',
        cats: data.cats || '',
        catsArr: data.catsArr || [],
        teamsArr: data.teamsArr || [],
        teamCount: data.teamCount || 0,
        teams: data.teams || '',
        winner: data.winner || '' });
    });
    
    // ندمج مع المحلية ونزيل المكررات (بناء على timestamp)
    const localHist = JSON.parse(localStorage.getItem('hh_game_history')||'[]');
    const allGames = [...cloudGames];
    const seenTimestamps = new Set(cloudGames.map(g=>g.timestamp).filter(Boolean));
    localHist.forEach(g => {
      if(!g.timestamp || !seenTimestamps.has(g.timestamp)){
        allGames.push(g);
      }
    });
    
    // ترتيب حسب timestamp
    allGames.sort((a,b)=>(b.timestamp||0)-(a.timestamp||0));
    
    // حفظ النتيجة المدمجة
    localStorage.setItem('hh_game_history', JSON.stringify(allGames.slice(0,50)));
    
    return true;
  }catch(e){
    console.warn('loadUserGames:', e.message);
    return false;
  }
}

function replayFromHistory(idx){
  try{
    const hist=JSON.parse(localStorage.getItem('hh_game_history')||'[]');
    const g=hist[idx];
    if(!g||!g.catsArr||!g.teamsArr)return;
    startGame([...g.teamsArr], [...g.catsArr], g.name);
    toast('يبدأ اللعب!','success');
  }catch(e){toast('حدث خطأ','error');}
}

function clearMyGames(){
  if(confirm('هل تريد مسح سجل الألعاب؟')){
    localStorage.removeItem('hh_game_history');
    renderMyGames();
    toast('تم مسح السجل','info');
  }
}

// ════ البدء من جديد · يمسح كل البيانات المحلية ويعيد المنصة لحالة أول مرة ════
function resetEverything(){
  const confirmed = confirm(
    'البدء من جديد\n\n' +
    'سيتم حذف:\n' +
    '• سجل الألعاب السابقة\n' +
    '• الفئات المحفوظة\n' +
    '• إعدادات المنصة المحلية\n' +
    '• التقدم في الحصة التفاعلية\n\n' +
    'لن يتم حذف حسابك أو بياناتك الشخصية.\n\n' +
    'هل أنت متأكد؟' );
  if(!confirmed) return;
  
  // تأكيد نهائي
  const finalConfirm = confirm('تأكيد أخير: هل تريد فعلا البدء من جديد؟ لا يمكن التراجع.');
  if(!finalConfirm) return;
  
  try{
    // قائمة المفاتيح التي يمكن حذفها (مفاتيح hh_ باستثناء بيانات الجلسة الأساسية)
    const keysToDelete = [];
    const keepKeys = ['hh_dark']; // احتفظ بتفضيل Dark Mode فقط
    
    for(let i = 0; i < localStorage.length; i++){
      const key = localStorage.key(i);
      if(key && key.startsWith('hh_') && !keepKeys.includes(key)){
        keysToDelete.push(key);
      }
    }
    
    // حذف المفاتيح
    keysToDelete.forEach(key => localStorage.removeItem(key));
    
    // حذف sessionStorage (للحصة التفاعلية)
    try{ sessionStorage.clear(); }catch(e){}
    
    toast('تم البدء من جديد! المنصة الآن كأنك تستخدمها لأول مرة','success');
    
    // إعادة التوجيه للقائمة الرئيسية بعد ثانية
    setTimeout(()=>{
      showScreen('screen-menu');
      // إعادة تحميل الصفحة لضمان تحديث كل شيء
      setTimeout(()=>window.location.reload(), 800);
    }, 1200);
    
  }catch(e){
    console.error('Reset error:',e);
    toast('حدث خطأ أثناء البدء من جديد','error');
  }
}

function esc(s){const d=document.createElement('div');d.textContent=s;return d.innerHTML;}
// تنظيف القيم داخل سمات HTML (مثل onclick='...${id}...')
// تمنع XSS عبر الـ id أو الـ name
function escAttr(s){
  if (s == null) return '';
  return String(s).replace(/['"\\<>&]/g, function(c){
    return {"'":'&#39;','"':'&quot;','\\':'&#92;','<':'&lt;','>':'&gt;','&':'&amp;'}[c];
  });
}

// ═══════════════════════════════════════════════════════════════════
//  حارس التهريب العام · يُطبَّق على أي نص من السحابة/الأدمن
// ═══════════════════════════════════════════════════════════════════
function escSafe(v){
  if(v === null || v === undefined) return '';
  const t = String(v);
  return t.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
          .replace(/"/g,'&quot;').replace(/'/g,'&#39;');
}
// تعقيم عميق لكائن كامل (نصوصه فقط)
function sanitizeDeep(obj, depth){
  depth = depth || 0;
  if(depth > 6) return obj;
  if(typeof obj === 'string') return escSafe(obj);
  if(Array.isArray(obj)) return obj.map(function(x){ return sanitizeDeep(x, depth+1); });
  if(obj && typeof obj === 'object'){
    const out = {};
    Object.keys(obj).forEach(function(k){
      // نستثني حقول الصور (data:) من التهريب لأنها تُستخدم في src وليس innerHTML
      if(k === 'img' || k === 'image' || k === 'logo' || k === 'icon' || k === 'src'){ out[k] = obj[k]; }
      else out[k] = sanitizeDeep(obj[k], depth+1);
    });
    return out;
  }
  return obj;
}

let tt;function toast(msg,type='info'){const t=document.getElementById('toast');t.textContent=msg;t.className='show '+type;clearTimeout(tt);tt=setTimeout(()=>t.classList.remove('show'),3200);}

