//  عدّ تصاعدي + ظهور انسيابي لشريط الإحصائيات التعريفي
function hh_animateHeroStats(){
  const bar = document.getElementById('hero-stats-bar');
  if(!bar || bar.dataset.animated === '1') return;
  bar.dataset.animated = '1';
  const counters = bar.querySelectorAll('.hero-stat-count');
  counters.forEach((el, i) => {
    const target = parseInt(el.dataset.target, 10) || 0;
    const suffix = el.dataset.suffix || '';
    const duration = 1400;
    const startDelay = i * 120;
    setTimeout(() => {
      const startTime = performance.now();
      function tick(now){
        const elapsed = now - startTime;
        const progress = Math.min(elapsed / duration, 1);
        // easing انسيابي (easeOutexpo) يبطئ قرب النهاية
        const eased = progress === 1 ? 1 : 1 - Math.pow(2, -10 * progress);
        const current = Math.round(target * eased);
        el.textContent = current.toLocaleString('en-US') + suffix;
        if(progress < 1){
          requestAnimationFrame(tick);
        } else {
          el.textContent = target.toLocaleString('en-US') + suffix;
        }
      }
      requestAnimationFrame(tick);
    }, startDelay);
  });
}

// مراقبة ظهور الشريط لتشغيل العدّ عند رؤيته فقط (أداء أفضل)
function hh_initHeroStatsObserver(){
  const bar = document.getElementById('hero-stats-bar');
  if(!bar) return;
  if(!('IntersectionObserver' in window)){
    hh_animateHeroStats();
    return;
  }
  const obs = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if(entry.isIntersecting){
        hh_animateHeroStats();
        obs.disconnect();
      }
    });
  }, { threshold: 0.4 });
  obs.observe(bar);
}
// استدعاء احتياطي عند التحميل إن كانت الرئيسية ظاهرة فوراً
document.addEventListener('DOMContentLoaded', function(){
  setTimeout(function(){
    const menu = document.getElementById('screen-menu');
    if(menu && menu.classList.contains('active')){
      try{ hh_initHeroStatsObserver(); }catch(e){}
    }
  }, 600);
});

//  تحميل الإحصائيات الشخصية في الشريط العلوي
async function loadRoyalStatsStrip(){
  // تحديث شارة اللقب أيضا
  try{ refreshHomeUserBadge(); }catch(e){}
  const stripEl = document.getElementById('royal-stats-strip');
  if(!stripEl) return;
  try{
    if(currentUser && db && !OFFLINE_MODE){
      const doc = await db.collection('users').doc(currentUser.uid).get();
      if(doc.exists){
        const d = doc.data();
        const points = d.points || 0;
        const games = d.gamesPlayed || 0;
        // حساب الـ streak (أيام متتالية - مبسط حاليا)
        const lastSeen = d.lastSeen;
        let streak = 1;
        if(lastSeen && lastSeen.toMillis){
          const diff = Math.floor((Date.now() - lastSeen.toMillis()) / (1000*60*60*24));
          streak = diff <= 1 ? (d.streak || 1) : 0;
        }
        const pEl = document.getElementById('rss-points');
        const gEl = document.getElementById('rss-games');
        const sEl = document.getElementById('rss-streak');
        const tEl = document.getElementById('rss-time');
        if(pEl) pEl.textContent = points.toLocaleString('en-US');
        if(gEl) gEl.textContent = games.toLocaleString('en-US');
        if(sEl) sEl.textContent = streak;
        // ⏱ عرض الوقت في المنصة (مختصر للشريط الضيق)
        if(tEl){
          const total = d.totalMinutes || 0;
          if(total < 60)        tEl.textContent = total + 'د';
          else if(total < 1440) tEl.textContent = Math.floor(total/60) + 'س ' + (total%60) + 'د';
          else                  tEl.textContent = Math.floor(total/1440) + 'ي ' + Math.floor((total%1440)/60) + 'س';
        }
      }
    }
  }catch(e){ console.warn('stats strip load failed', e); }
}

