function loadRoleQuickStart(){
  const container = document.getElementById('role-quick-start');
  const btnsEl = document.getElementById('rqs-buttons');
  const titleEl = document.getElementById('rqs-title');
  const subtitleEl = document.getElementById('rqs-subtitle');
  if(!container || !btnsEl) return;

  const role = (typeof _currentUserRole !== 'undefined' && _currentUserRole) || 'guest';
  let buttons = [];
  let title = 'ماذا تحب أن تبدأ به؟';
  let subtitle = 'اختصر الطريق · وانطلق مباشرة';

  if(role === 'teacher'){
    title = 'كيف أساعدك اليوم أيها المعلم الملهم؟';
    subtitle = 'اختصرنا لك أهم ما تحتاجه';
    buttons = [
      { label:'الألعاب التنافسية', hint:'فرق طلابك وتنافسوا', color:'green',
        icon:'<svg viewBox="0 0 24 24" fill="currentColor"><path d="M21 6H3c-1.1 0-2 .9-2 2v8c0 1.1.9 2 2 2h18c1.1 0 2-.9 2-2V8c0-1.1-.9-2-2-2zm-10 7H8v3H6v-3H3v-2h3V8h2v3h3v2zm4.5 2c-.83 0-1.5-.67-1.5-1.5s.67-1.5 1.5-1.5 1.5.67 1.5 1.5-.67 1.5-1.5 1.5zm4-3c-.83 0-1.5-.67-1.5-1.5S18.67 9 19.5 9s1.5.67 1.5 1.5-.67 1.5-1.5 1.5z"/></svg>',
        action:"showScreen('screen-setup')" },
      { label:'شاركنا رأيك', hint:'رأيك يلهمنا', color:'gold',
        icon:'<svg viewBox="0 0 24 24" fill="currentColor"><path d="M20 2H4a2 2 0 0 0-2 2v13a2 2 0 0 0 2 2h3v3.5a.5.5 0 0 0 .8.4L13 19h7a2 2 0 0 0 2-2V4a2 2 0 0 0-2-2zM7 11.5a1.5 1.5 0 1 1 0-3 1.5 1.5 0 0 1 0 3zm5 0a1.5 1.5 0 1 1 0-3 1.5 1.5 0 0 1 0 3zm5 0a1.5 1.5 0 1 1 0-3 1.5 1.5 0 0 1 0 3z"/></svg>',
        action:"showScreen('screen-reviews')" }
    ];
  } else if(role === 'student'){
    title = 'مرحبا أيها الطالب! ماذا تحب أن تبدأ به؟';
    subtitle = 'العلم في الصغر كالنقش على الحجر';
    buttons = [
      { label:'العب الآن', hint:'تنافس مع زملائك', color:'green',
        icon:'<svg viewBox="0 0 24 24" fill="currentColor"><path d="M21 6H3c-1.1 0-2 .9-2 2v8c0 1.1.9 2 2 2h18c1.1 0 2-.9 2-2V8c0-1.1-.9-2-2-2zm-10 7H8v3H6v-3H3v-2h3V8h2v3h3v2zm4.5 2c-.83 0-1.5-.67-1.5-1.5s.67-1.5 1.5-1.5 1.5.67 1.5 1.5-.67 1.5-1.5 1.5zm4-3c-.83 0-1.5-.67-1.5-1.5S18.67 9 19.5 9s1.5.67 1.5 1.5-.67 1.5-1.5 1.5z"/></svg>',
        action:"showScreen('screen-setup')" },
      { label:'المتصدرون', hint:'شاهد أفضل اللاعبين', color:'gold',
        icon:'<svg viewBox="0 0 24 24" fill="currentColor"><path d="M7 4V2h10v2h4a1 1 0 011 1v3a5 5 0 01-4.28 4.95A6 6 0 0113 16.91V19h4v2H7v-2h4v-2.09a6 6 0 01-4.72-3.96A5 5 0 012 8V5a1 1 0 011-1h4z"/></svg>',
        action:"showScreen('screen-lb');currentLBTab='solo';switchLBTab('solo');" }
    ];
  } else {
    // المستخدم لم يسجل دخول · لا نعرض بطاقات في هذا الموضع
    // (زر "العب الآن" متوفر في القائمة العلوية بالفعل)
    if(container) container.style.display = 'none';
    return;
  }

  // تطبيق المحتوى
  titleEl.textContent = title;
  subtitleEl.textContent = subtitle;

  btnsEl.innerHTML = buttons.map(b => `
    <button class="rqs-btn" data-color="${b.color}" onclick="${b.action}"> ${b.soon ? '<span class="rqs-btn-soon">قريبا</span>' : ''}
      <div class="rqs-btn-icon">${b.icon}</div>
      <div class="rqs-btn-text">
        <span class="rqs-btn-label">${b.label}</span>
        <span class="rqs-btn-hint">${b.hint}</span>
      </div>
    </button> `).join('');

  container.style.display = 'block';
}

// ═══════════════════════════════════════════════════════
//  نظام التنقل بين الأقسام (Navigation)
// ═══════════════════════════════════════════════════════
function navGoTo(section){
  // إزالة active من كل الروابط
  document.querySelectorAll('.nav-link, .mobile-menu-link').forEach(a=>{
    a.classList.remove('nav-link-active');
    a.classList.remove('mobile-menu-active');
  });
  // تفعيل الرابط الحالي
  document.querySelectorAll(`.nav-link[data-section="${section}"]`).forEach(a=>{
    a.classList.add('nav-link-active');
  });
  document.querySelectorAll(`.mobile-menu-link[data-section="${section}"]`).forEach(a=>{
    a.classList.add('mobile-menu-active');
  });

  // التنقل حسب القسم
  switch(section){
    case 'home':
      showScreen('screen-menu');
      // التمرير للأعلى
      window.scrollTo({top:0, behavior:'smooth'});
      break;
    case 'tools':
      // التمرير لقسم "الأدوات السريعة"
      showScreen('screen-menu');
      setTimeout(()=>{
        const toolsEl = document.querySelector('.qt-master-header');
        if(toolsEl){
          toolsEl.scrollIntoView({behavior:'smooth', block:'start'});
          // فتح المجموعة الأولى المتاحة (المعلم لو ظاهر، أو شخصي)
          const teacherGroup = document.getElementById('teacher-tools-group');
          if(teacherGroup && teacherGroup.style.display !== 'none'){
            const btn = teacherGroup.querySelector('.qt-collapse-toggle');
            const body = teacherGroup.querySelector('.qt-collapse-body');
            if(btn && body && btn.getAttribute('aria-expanded') !== 'true'){
              body.style.display = 'block';
              btn.setAttribute('aria-expanded', 'true');
            }
          }
        }
      }, 100);
      break;
    case 'my':
      // فتح "منصتي" · سجل الألعاب
      showScreen('screen-mygames');
      if(typeof renderMyGames === 'function') renderMyGames();
      break;
    case 'about':
      showScreen('screen-about');
      window.scrollTo({top:0, behavior:'smooth'});
      break;
  }
}

//  قائمة الجوال
function toggleMobileMenu(){
  const menu = document.getElementById('mobile-menu');
  if(!menu) return;
  menu.style.display = (menu.style.display === 'none' || !menu.style.display) ? 'block' : 'none';
}
function closeMobileMenu(){
  const menu = document.getElementById('mobile-menu');
  if(menu) menu.style.display = 'none';
}

// طي/فتح أي مجموعة في "الأدوات السريعة" (Accordion)
function toggleQtGroup(bodyId, btn){
  const body = document.getElementById(bodyId);
  if(!body || !btn) return;
  const isOpen = btn.getAttribute('aria-expanded') === 'true';
  if(isOpen){
    body.style.display = 'none';
    btn.setAttribute('aria-expanded', 'false');
  } else {
    body.style.display = 'block';
    btn.setAttribute('aria-expanded', 'true');
  }
}

// ════ أصوات اللعبة (Web Audio API) ════
let audioCtx=null;
function getAudioCtx(){if(!audioCtx)audioCtx=new(window.AudioContext||window.webkitAudioContext)();return audioCtx;}
function playSound(type){
  try{
    const ctx=getAudioCtx();
    if(ctx.state==='suspended')ctx.resume();
    const o=ctx.createOscillator();
    const g=ctx.createGain();
    o.connect(g);g.connect(ctx.destination);
    const now=ctx.currentTime;
    if(type==='correct'){
      // نغمة إجابة صحيحة - تصاعدية + نغمة تشجيعية قصيرة
      o.frequency.setValueAtTime(440,now);
      o.frequency.setValueAtTime(550,now+0.1);
      o.frequency.setValueAtTime(660,now+0.2);
      g.gain.setValueAtTime(0.3,now);
      g.gain.exponentialRampToValueAtTime(0.001,now+0.5);
      o.start(now);o.stop(now+0.5);
      // إضافة نغمة "لمعان" خلفية للاحتفال
      const o2=ctx.createOscillator();const g2=ctx.createGain();
      o2.connect(g2);g2.connect(ctx.destination);
      o2.type='triangle';
      o2.frequency.setValueAtTime(880,now+0.3);
      o2.frequency.exponentialRampToValueAtTime(1320,now+0.5);
      g2.gain.setValueAtTime(0.15,now+0.3);
      g2.gain.exponentialRampToValueAtTime(0.001,now+0.7);
      o2.start(now+0.3);o2.stop(now+0.7);
    } else if(type==='cheer'){
      //  صوت تصفيق · يحاكي تصفيق الجمهور باستخدام ضوضاء بيضاء مشكلة
      // كل "تصفيقة" = burst قصير من الضوضاء مع filter
      const numClaps = 18; // عدد التصفيقات
      const duration = 1.6; // مدة الصوت كاملا بالثواني
      for(let i=0; i<numClaps; i++){
        // توزيع عشوائي للتصفيقات مع تكثيف في المنتصف
        const t = (i/numClaps) * duration + Math.random() * 0.04;
        const clapTime = now + t;
        // ضوضاء بيضاء (buffer صغير)
        const bufferSize = ctx.sampleRate * 0.03; // 30ms
        const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
        const data = buffer.getChannelData(0);
        for(let j=0; j<bufferSize; j++){
          data[j] = (Math.random() * 2 - 1) * Math.exp(-j/bufferSize * 8);
        }
        const noise = ctx.createBufferSource();
        noise.buffer = buffer;
        // فلتر Bandpass لمحاكاة تصفيق راحة اليد
        const filter = ctx.createBiquadFilter();
        filter.type = 'bandpass';
        filter.frequency.value = 1200 + Math.random() * 800; // 1200-2000 Hz
        filter.Q.value = 1.5;
        // Gain مع تخميم سريع
        const clapG = ctx.createGain();
        const volume = 0.15 + Math.random() * 0.12; // تنوع في القوة
        clapG.gain.setValueAtTime(0, clapTime);
        clapG.gain.linearRampToValueAtTime(volume, clapTime + 0.002);
        clapG.gain.exponentialRampToValueAtTime(0.001, clapTime + 0.08);
        noise.connect(filter);
        filter.connect(clapG);
        clapG.connect(ctx.destination);
        noise.start(clapTime);
        noise.stop(clapTime + 0.1);
      }
      return;
    } else if(type==='legend_cheer'){
      //  تصفيق حار للإجابات الأسطورية · أعنف وأطول
      const numClaps = 28;
      const duration = 2.2;
      for(let i=0; i<numClaps; i++){
        const t = (i/numClaps) * duration + Math.random() * 0.05;
        const clapTime = now + t;
        const bufferSize = ctx.sampleRate * 0.035;
        const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
        const data = buffer.getChannelData(0);
        for(let j=0; j<bufferSize; j++){
          data[j] = (Math.random() * 2 - 1) * Math.exp(-j/bufferSize * 7);
        }
        const noise = ctx.createBufferSource();
        noise.buffer = buffer;
        const filter = ctx.createBiquadFilter();
        filter.type = 'bandpass';
        filter.frequency.value = 1100 + Math.random() * 1000;
        filter.Q.value = 1.2;
        const clapG = ctx.createGain();
        const volume = 0.18 + Math.random() * 0.15;
        clapG.gain.setValueAtTime(0, clapTime);
        clapG.gain.linearRampToValueAtTime(volume, clapTime + 0.002);
        clapG.gain.exponentialRampToValueAtTime(0.001, clapTime + 0.09);
        noise.connect(filter);
        filter.connect(clapG);
        clapG.connect(ctx.destination);
        noise.start(clapTime);
        noise.stop(clapTime + 0.11);
      }
      return;
    } else if(type==='wrong'){
      // نغمة إجابة خاطئة - تنازلية
      o.frequency.setValueAtTime(300,now);
      o.frequency.setValueAtTime(200,now+0.2);
      g.gain.setValueAtTime(0.25,now);
      g.gain.exponentialRampToValueAtTime(0.001,now+0.4);
      o.start(now);o.stop(now+0.4);
    } else if(type==='tick'){
      // نقرة ساعة
      o.frequency.setValueAtTime(800,now);
      g.gain.setValueAtTime(0.05,now);
      g.gain.exponentialRampToValueAtTime(0.001,now+0.08);
      o.start(now);o.stop(now+0.08);
    } else if(type==='timeout'){
      // صفير انتهاء الوقت
      o.frequency.setValueAtTime(500,now);
      o.frequency.setValueAtTime(250,now+0.3);
      g.gain.setValueAtTime(0.3,now);
      g.gain.exponentialRampToValueAtTime(0.001,now+0.6);
      o.start(now);o.stop(now+0.6);
    } else if(type==='buzzer'){
      // صوت الخرص · صوت عميق قوي يدل على انتهاء الوقت (شبيه buzzer لعبة مسابقات)
      // نستخدم مذبذبين متزامنين لصوت أكثر قوة
      o.type='square';
      o.frequency.setValueAtTime(180,now);
      g.gain.setValueAtTime(0.35,now);
      g.gain.setValueAtTime(0.35,now+0.4);
      g.gain.exponentialRampToValueAtTime(0.001,now+0.7);
      o.start(now);o.stop(now+0.7);
      // مذبذب ثاني لإضافة طبقة
      const o2=ctx.createOscillator();const g2=ctx.createGain();
      o2.connect(g2);g2.connect(ctx.destination);
      o2.type='sawtooth';
      o2.frequency.setValueAtTime(140,now);
      g2.gain.setValueAtTime(0.2,now);
      g2.gain.setValueAtTime(0.2,now+0.4);
      g2.gain.exponentialRampToValueAtTime(0.001,now+0.7);
      o2.start(now);o2.stop(now+0.7);
    } else if(type==='win'){
      // نغمة الفوز
      [261,329,392,523].forEach((f,i)=>{
        const oi=ctx.createOscillator();const gi=ctx.createGain();
        oi.connect(gi);gi.connect(ctx.destination);
        oi.frequency.value=f;
        gi.gain.setValueAtTime(0.25,now+i*0.12);
        gi.gain.exponentialRampToValueAtTime(0.001,now+i*0.12+0.3);
        oi.start(now+i*0.12);oi.stop(now+i*0.12+0.3);
      });
      return;
    }
  }catch(e){}
}
