// ════ آخر تحديث (ديناميكي من آخر تعديل للصفحة على GitHub) ════
(function(){
  const el = document.getElementById('last-update-text');
  if(!el) return;
  
  // استخدام document.lastModified - يعطي آخر تاريخ تعديل لملف الصفحة تلقائيا
  // هذا التاريخ يتحدث تلقائيا مع كل commit على GitHub
  try{
    const lastMod = new Date(document.lastModified);
    if(isNaN(lastMod.getTime()) || lastMod.getFullYear() < 2020){
      // fallback إذا فشل: عرض تاريخ اليوم
      el.textContent = 'آخر تحديث: ' + new Date().toLocaleDateString('en-GB', {day:'2-digit', month:'2-digit', year:'numeric'});
      return;
    }
    const dateStr = lastMod.toLocaleDateString('en-GB', {day:'2-digit', month:'2-digit', year:'numeric'});
    el.textContent = 'آخر تحديث: ' + dateStr;
  }catch(e){
    el.textContent = 'آخر تحديث: ' + new Date().toLocaleDateString('en-GB', {day:'2-digit', month:'2-digit', year:'numeric'});
  }
})();

// ════════════ PROFILE ════════════
let profileOpen=false;

function toggleProfile(){
  profileOpen=!profileOpen;
  const m=document.getElementById('profile-modal');
  if(profileOpen){
    m.classList.add('open');
    loadProfileData();
    //  تحديث معلومات تغيير التصنيف
    try{ updateRoleChangeUI(); }catch(e){}
  }
  else m.classList.remove('open');
}

/**
 * فتح شاشة الإعدادات (الملف الشخصي)
 * · تستدعى من تبويبة الإعدادات في الشريط السفلي
 */
function openSettingsScreen(){
  if(!profileOpen){
    toggleProfile();
  }
  //  أبق تبويبة الإعدادات نشطة بصريا ما دام المودال مفتوحا
  try{
    document.querySelectorAll('.hh-nav-item').forEach(el => el.classList.remove('active'));
    const settingsBtn = document.querySelector('.hh-nav-item[data-target="settings"]');
    if(settingsBtn) settingsBtn.classList.add('active');
  }catch(e){}
  // عند إغلاق المودال، أعد تنشيط تبويبة الشاشة الحالية
  const profileModal = document.getElementById('profile-modal');
  if(profileModal && !profileModal._closeListenerAdded){
    profileModal._closeListenerAdded = true;
    const observer = new MutationObserver(() => {
      if(!profileModal.classList.contains('open')){
        // المودال أغلق · أعد ضبط الشريط السفلي حسب الشاشة الحالية
        try{
          const activeScreen = document.querySelector('.screen.active');
          if(activeScreen && activeScreen.id){
            hh_updateBottomNav(activeScreen.id);
          }
        }catch(e){}
      }
    });
    observer.observe(profileModal, { attributes:true, attributeFilter:['class'] });
  }
}

window.openSettingsScreen = openSettingsScreen;

/**
 * تحديث واجهة تغيير التصنيف في الملف الشخصي
 * القاعدة: التغيير مسموح مرة واحدة، أو بعد 10 أيام من آخر تغيير
 * استثناء: إذا لم يحدد دور بعد → مسموح دائما (تجاوز القفل)
 */
function updateRoleChangeUI(){
  const roleEl = document.getElementById('pf-current-role');
  const btnEl = document.getElementById('pf-change-role-btn');
  const hintEl = document.getElementById('pf-role-change-hint');
  if(!roleEl || !btnEl || !hintEl) return;

  // عرض التصنيف الحالي
  const role = _currentUserRole;
  const labels = {
    'teacher':'معلم <svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M5 13.18v4L12 21l7-3.82v-4L12 17l-7-3.82zM12 3L1 9l11 6 9-4.91V17h2V9L12 3z"/></svg>',
    'student':'طالب <svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M21 5c-1.11-.35-2.33-.5-3.5-.5-1.95 0-4.05.4-5.5 1.5-1.45-1.1-3.55-1.5-5.5-1.5S2.45 4.9 1 6v14.65c0 .25.25.5.5.5.1 0 .15-.05.25-.05C3.1 20.45 5.05 20 6.5 20c1.95 0 4.05.4 5.5 1.5 1.35-.85 3.8-1.5 5.5-1.5 1.65 0 3.35.3 4.75 1.05.1.05.15.05.25.05.25 0 .5-.25.5-.5V6c-.6-.45-1.25-.75-2-1z"/></svg>',
    'other':'عضو آخر <svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M12 12c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm0 2c-2.67 0-8 1.34-8 4v2h16v-2c0-2.66-5.33-4-8-4z"/></svg>' };
  roleEl.innerHTML = labels[role] || '· لم يحدد';

  //  استثناء: إذا لم يختر دورا فعليا → السماح دائما
  if(!role){
    btnEl.disabled = false;
    btnEl.style.opacity = '1';
    btnEl.style.cursor = 'pointer';
    hintEl.textContent = 'اختر تصنيفك الآن · مرة واحدة مجانا';
    hintEl.style.color = '#3D6B53';
    return;
  }

  // فحص حالة التغيير
  try{
    const lastChangeStr = localStorage.getItem('hh_role_last_change');
    const changeCount = parseInt(localStorage.getItem('hh_role_change_count') || '0', 10);
    const TEN_DAYS_MS = 10 * 24 * 60 * 60 * 1000;

    if(!lastChangeStr || changeCount === 0){
      // لم يتغير بعد · مسموح بتغيير مجاني واحد
      btnEl.disabled = false;
      btnEl.style.opacity = '1';
      btnEl.style.cursor = 'pointer';
      hintEl.textContent = 'يمكنك تغيير التصنيف مرة واحدة مجانا';
      hintEl.style.color = '#3D6B53';
    } else {
      const lastChange = parseInt(lastChangeStr, 10);
      const elapsed = Date.now() - lastChange;
      if(elapsed >= TEN_DAYS_MS){
        // مرت 10 أيام · مسموح بالتغيير مجددا
        btnEl.disabled = false;
        btnEl.style.opacity = '1';
        btnEl.style.cursor = 'pointer';
        hintEl.textContent = 'يمكنك التغيير الآن (متاح بعد كل 10 أيام)';
        hintEl.style.color = '#3D6B53';
      } else {
        // لم تمر 10 أيام بعد
        const remainingMs = TEN_DAYS_MS - elapsed;
        const remainingDays = Math.ceil(remainingMs / (24 * 60 * 60 * 1000));
        const arabicDays = remainingDays.toLocaleString('en-US');
        btnEl.disabled = true;
        btnEl.style.opacity = '0.5';
        btnEl.style.cursor = 'not-allowed';
        let hint = `يمكنك التغيير بعد ${arabicDays} ${remainingDays === 1 ? 'يوم' : 'يوما'}`;
        //  زر إعادة تعيين للأدمن
        if(typeof isAdminUser === 'function' && isAdminUser(currentUser)){
          hint += ' · <a href="javascript:void(0)" onclick="resetRoleChangeLock()" style="color:#c0392b;font-weight:900;text-decoration:underline;">إعادة تعيين (أدمن)</a>';
        }
        hintEl.innerHTML = hint;
        hintEl.style.color = '#8A6D2E';
        return;
      }
    }
  }catch(e){
    btnEl.disabled = false;
    hintEl.textContent = '';
  }
}

/**
 * إعادة تعيين قفل تغيير الدور (للأدمن فقط)
 */
function resetRoleChangeLock(){
  if(typeof isAdminUser === 'function' && !isAdminUser(currentUser)){
    if(typeof toast === 'function') toast('للأدمن فقط', 'error');
    return;
  }
  if(!confirm('سيتم إعادة تعيين قفل تغيير التصنيف. متابعة؟')) return;
  localStorage.removeItem('hh_role_last_change');
  localStorage.removeItem('hh_role_change_count');
  _currentRoleChangeCount = 0;
  if(typeof toast === 'function') toast('تم · يمكنك التغيير الآن', 'success');
  if(typeof updateRoleChangeUI === 'function') updateRoleChangeUI();
}
window.resetRoleChangeLock = resetRoleChangeLock;

/**
 * فتح مودال تغيير الدور من الإعدادات (تجاوز الـ "ظهر مرة")
 */
function openRoleChangeFromProfile(){
  //  إذا لم يختر دورا فعليا → افتح مباشرة (تجاوز القفل)
  if(!_currentUserRole){
    if(profileOpen) toggleProfile();
    setTimeout(() => { showRoleModal({ force: true }); }, 250);
    return;
  }

  // فحص نهائي قبل الفتح
  try{
    const lastChangeStr = localStorage.getItem('hh_role_last_change');
    const changeCount = parseInt(localStorage.getItem('hh_role_change_count') || '0', 10);
    const TEN_DAYS_MS = 10 * 24 * 60 * 60 * 1000;
    if(lastChangeStr && changeCount > 0){
      const elapsed = Date.now() - parseInt(lastChangeStr, 10);
      if(elapsed < TEN_DAYS_MS){
        const remainingDays = Math.ceil((TEN_DAYS_MS - elapsed) / (24*60*60*1000));
        toast(`لا يمكن التغيير الآن · متاح بعد ${remainingDays.toLocaleString('en-US')} ${remainingDays === 1 ? 'يوم' : 'يوما'}`, 'error');
        return;
      }
    }
  }catch(e){}
  // أغلق الإعدادات وافتح مودال الدور
  if(profileOpen) toggleProfile();
  setTimeout(() => {
    showRoleModal({ force: true });
  }, 250);
}

window.openRoleChangeFromProfile = openRoleChangeFromProfile;
window.updateRoleChangeUI = updateRoleChangeUI;

function closeProfileOutside(e){
  if(e.target===document.getElementById('profile-modal'))toggleProfile();
}

