// ════════════ RATING SYSTEM ════════════
let ratingData={stars:0,quality:0,ease:0,recommend:0};
const starLabels=['','ضعيف','مقبول','جيد','جيد جدا','ممتاز!'];

function setStar(n){
  ratingData.stars=n;
  document.querySelectorAll('.star-btn').forEach((b,i)=>{
    b.classList.toggle('on',i<n);
  });
  const lbl=document.getElementById('star-label');
  if(lbl)lbl.textContent=starLabels[n]||'';
}

function selectQ(key,val){
  ratingData[key]=val;
  const row=document.getElementById('q-'+key);
  if(row)[...row.children].forEach((b,i)=>b.classList.toggle('sel',i===val-1));
}

async function submitRating(){
  const err=document.getElementById('rate-err');
  if(!ratingData.stars){err.textContent='اختر عدد النجوم أولا';return;}
  // rate limiting: منع التقييم المتكرر (مرة واحدة كل 24 ساعة)
  const lastRated=localStorage.getItem('hh_last_rated');
  if(lastRated&&(Date.now()-parseInt(lastRated))<86400000){
    err.textContent='لقد قيمت مسبقا، يمكنك التقييم مجددا بعد 24 ساعة';return;
  }
  err.textContent='';
  const name=currentUser?(currentUser.name||currentUser.displayName||'مستخدم').split(' ')[0]:'زائر';
  // استخراج الإيميل (للأدمن فقط لاحقا)
  const userEmail = currentUser ? (currentUser.email || '') : '';
  const review={
    name,
    email: userEmail,  // ← جديد: يحفظ للعرض في لوحة التحكم فقط
    stars:ratingData.stars,
    quality:ratingData.quality,
    ease:ratingData.ease,
    recommend:ratingData.recommend,
    comment:document.getElementById('rate-comment').value.trim(),
    date:new Date().toLocaleDateString('ar-QA'),
    ts:Date.now(),
    uid:currentUser?(currentUser.uid||currentUser.id||''):('guest_'+Date.now()),
    // بصمة الجهاز · تحفظ فقط إذا وافق المستخدم
    deviceInfo: getFingerprintIfConsented()
  };
  try{
    if(!OFFLINE_MODE&&db){
      await db.collection('reviews').add(review);
      //  رفع علامة "قيم" على وثيقة المستخدم · مهم لاحتساب لقب "المعلم الملهم"
      try{
        if(currentUser){
          db.collection('users').doc(currentUser.uid).set({
            hasReviewed: true,
            reviewedAt:  firebase.firestore.FieldValue.serverTimestamp()
          }, { merge:true }).catch(()=>{});
        }
      }catch(e){}
    }else{
      const reviews=JSON.parse(localStorage.getItem('hh_reviews')||'[]');
      review.id='local_'+Date.now();
      reviews.unshift(review);
      localStorage.setItem('hh_reviews',JSON.stringify(reviews));
    }
    // علامة التقييم محليا (تستخدم كـ fallback في getCurrentUserBadge)
    try{ localStorage.setItem('hh_has_reviewed','1'); }catch(e){}
    localStorage.setItem('hh_last_rated', Date.now().toString());
    toast('شكرا على تقييمك!','success');
    showScreen('screen-menu');
    loadHomeReviews();
    // reset
    ratingData={stars:0,quality:0,ease:0,recommend:0};
    setStar(0);
    ['quality','ease','recommend'].forEach(k=>{
      const r=document.getElementById('q-'+k);
      if(r)[...r.children].forEach(b=>b.classList.remove('sel'));
    });
    const c=document.getElementById('rate-comment');
    if(c)c.value='';
  }catch(e){err.textContent='حدث خطأ، حاول مجددا';}
}

// إضافة شهادة عن المنصة يدوياً (الأدمن) · تُحفظ سحابياً وتظهر للجميع
async function openAddTestimonialModal(){
  if(!(currentUser && currentUser.email===SUPER_ADMIN_EMAIL)){ toast('فقط المدير','error'); return; }
  const name = prompt('اسم صاحب الشهادة (مثلاً: أ. محمد · معلم):');
  if(!name || !name.trim()) return;
  const comment = prompt('نص الشهادة / المقالة عن المنصة:');
  if(!comment || !comment.trim()) return;
  let stars = parseInt(prompt('عدد النجوم (1 إلى 5):','5'),10);
  if(isNaN(stars) || stars<1 || stars>5) stars = 5;

  const item = {
    id: 'testimonial_'+Date.now(),
    name: name.trim(),
    comment: comment.trim(),
    stars: stars,
    date: new Date().toLocaleDateString('ar'),
    ts: Date.now(),
    manual: true
  };
  try{
    if(OFFLINE_MODE || !db){ toast('يتطلب اتصالاً','error'); return; }
    // اقرأ الحالية وأضف
    let items = [];
    const doc = await db.collection('platform_settings').doc('testimonials').get();
    if(doc.exists && Array.isArray(doc.data().items)) items = doc.data().items;
    items.unshift(item);
    await db.collection('platform_settings').doc('testimonials').set({items: items, updated_at: Date.now()});
    toast('✓ أُضيفت الشهادة وتظهر للجميع','success');
    if(typeof loadHomeReviews === 'function') loadHomeReviews();
  }catch(e){
    if(e.code==='permission-denied') toast('الصلاحيات ترفض · راجع قواعد Firestore','error');
    else toast('فشل الحفظ: '+e.message,'error');
  }
}

// حذف شهادة يدوية (الأدمن)
async function deleteTestimonial(id){
  if(!(currentUser && currentUser.email===SUPER_ADMIN_EMAIL)) return;
  if(!confirm('حذف هذه الشهادة؟')) return;
  try{
    const doc = await db.collection('platform_settings').doc('testimonials').get();
    let items = (doc.exists && Array.isArray(doc.data().items)) ? doc.data().items : [];
    items = items.filter(it => it.id !== id);
    await db.collection('platform_settings').doc('testimonials').set({items: items, updated_at: Date.now()});
    toast('حُذفت الشهادة','info');
    if(typeof loadHomeReviews === 'function') loadHomeReviews();
  }catch(e){ toast('فشل الحذف','error'); }
}

async function loadHomeReviews(){
  let reviews=[];
  let userCount=0;
  const defaultReview={id:'founder',name:'أحمد',stars:5,comment:'منصة رائعة جدا بارك الله جهدك',date:'20/4/2026',ts:0};
  try{
    if(!OFFLINE_MODE&&db){
      const snapR = await db.collection('reviews').orderBy('ts','desc').limit(50).get();
      const snapU = await db.collection('users').get();
      reviews=snapR.docs.map(d=>({id:d.id,...d.data()}));
      userCount=snapU.size;
    }else{
      reviews=JSON.parse(localStorage.getItem('hh_reviews')||'[]');
      userCount=Object.keys(JSON.parse(localStorage.getItem('hh_users')||'{}')).length;
    }
  }catch(e){reviews=[];}
  // الشهادات اليدوية المضافة من الأدمن (محفوظة سحابياً لتظهر للجميع)
  let testimonials = [];
  try{
    if(!OFFLINE_MODE && db){
      const snapT = await db.collection('platform_settings').doc('testimonials').get();
      if(snapT.exists && Array.isArray(snapT.data().items)) testimonials = snapT.data().items;
    }
  }catch(e){}
  reviews=[...testimonials, ...reviews, defaultReview];

  // إظه_ار زر إضافة شهادة للأدمن
  const adminAddEl = document.getElementById('reviews-admin-add');
  if(adminAddEl) adminAddEl.style.display = (currentUser && currentUser.email===SUPER_ADMIN_EMAIL) ? 'block' : 'none';

  const statEl=document.getElementById('home-reviews-stats');
  const listEl=document.getElementById('home-reviews-list');
  const quickEl=document.getElementById('reviews-quick-stats');
  if(!listEl)return;

  const avg=reviews.length?(reviews.reduce((s,r)=>s+r.stars,0)/reviews.length).toFixed(1):0;
  const counts=[5,4,3,2,1].map(s=>reviews.filter(r=>r.stars===s).length);
  const total=reviews.length;
  const isAdmin=currentUser&&currentUser.email===SUPER_ADMIN_EMAIL;

  // الإحصائيات السريعة (عدد المستخدمين + الرضا + عدد التقييمات)
  if(quickEl){
    const pct=total?Math.round((reviews.filter(r=>r.stars>=4).length/total)*100):0;
    const statCard=(icon,val,label,color='#8A1538')=>`
      <div style="flex:1;min-width:120px;text-align:center;background:#fff;border:1.5px solid #e0e8f0;border-radius:14px;padding:14px 8px;box-shadow:0 2px 8px rgba(138,21,56,.08);">
        <div style="width:36px;height:36px;border-radius:50%;background:#f0f4f8;display:flex;align-items:center;justify-content:center;margin:0 auto 8px;">${icon}</div>
        <div style="font-size:1.6rem;font-weight:900;color:${color};line-height:1;">${val}</div>
        <div style="font-size:.68rem;color:#888;margin-top:4px;font-weight:600;">${label}</div>
      </div>`;
    const _isAdminView = currentUser && currentUser.email===SUPER_ADMIN_EMAIL;
    quickEl.innerHTML=
      (_isAdminView ? statCard('<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#8A1538" stroke-width="2.5"><path d="M17 21v-2a4 4 0 00-4-4H5a4 4 0 00-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 00-3-3.87"/><path d="M16 3.13a4 4 0 010 7.75"/></svg>',userCount,'مستخدم مسجل') : '')+
      statCard('<svg width="18" height="18" viewBox="0 0 24 24" fill="#d4b740" stroke="#e6ac00" stroke-width="1.5"><polygon points="12,2 15.09,8.26 22,9.27 17,14.14 18.18,21.02 12,17.77 5.82,21.02 7,14.14 2,9.27 8.91,8.26"/></svg>',avg,'متوسط التقييم','#b86a00')+
      statCard('<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#3D6B53" stroke-width="2.5"><path d="M22 11.08V12a10 10 0 11-5.93-9.14"/><polyline points="22 4 12 14.01 9 11.01"/></svg>',pct+'%','نسبة الرضا','#3D6B53');
  }

  // إحصائيات النجوم التفصيلية
  if(statEl){
    statEl.style.display='flex';
    statEl.innerHTML=`
      <div class="reviews-avg">
        <div class="avg-num">${avg}</div>
        <div class="avg-stars">${''.repeat(Math.round(avg))}${''.repeat(5-Math.round(avg))}</div>
        <div class="avg-count">${total} تقييم</div>
      </div>
      <div class="reviews-bars"> ${[5,4,3,2,1].map((s,i)=>`
          <div class="bar-row">
            <span class="bar-label">${s}</span>
            <div class="bar-track"><div class="bar-fill" style="width:${total?Math.round(counts[i]/total*100):0}%"></div></div>
            <span class="bar-pct">${counts[i]}</span>
          </div>`).join('')}
      </div>`;
  }

  // بطاقات الآراء · الأدمن يشوف الكل، الباقي 4-5 نجوم فقط
  const visible=isAdmin?reviews:reviews.filter(r=>r.stars>=4&&r.comment);
  if(!visible.length){
    listEl.innerHTML='<div style="text-align:center;padding:20px;color:#aaa;font-size:.85rem;">لا توجد تقييمات بعد، كن أول من يقيم!</div>';
    return;
  }
  listEl.innerHTML=visible.slice(0,10).map(r=>{
    const starsGold = '<span style="color:#d4b740;"></span>'.repeat(r.stars);
    const starsGray = '<span style="color:#e0e0e0;"></span>'.repeat(5-r.stars);
    // توحيد التاريخ
    const dateStr = r.date ? String(r.date).replace(/[0-9]/g, d => '0123456789'.indexOf(d)) : '';
    // خصوصية:
    // - الأدمن (أحمد): يرى اسم المستخدم الحقيقي في اللعبة + الإيميل
    // - المستخدم العادي: يرى "مستخدم" + شارة "شخص مميز ومبدع" بلا بيانات
    const displayName = r.manual ? (r.name || '') : (isAdmin ? (r.name || 'مجهول') : 'مستخدم');
    // شارة تظهر للأدمن فقط: إيميل المستخدم (إن وجد)
    const mailIcon = '<svg width="10" height="10" viewBox="0 0 24 24" fill="currentColor" style="vertical-align:-1px;flex-shrink:0;"><path d="M20 4H4c-1.1 0-1.99.9-1.99 2L2 18c0 1.1.9 2 2 2h16c1.1 0 2-.9 2-2V6c0-1.1-.9-2-2-2zm0 4l-8 5-8-5V6l8 5 8-5v2z"/></svg>';
    const userIcon = '<svg width="10" height="10" viewBox="0 0 24 24" fill="currentColor" style="vertical-align:-1px;flex-shrink:0;"><path d="M12 12c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm0 2c-2.67 0-8 1.34-8 4v2h16v-2c0-2.66-5.33-4-8-4z"/></svg>';
    const sparkIcon = '<svg width="11" height="11" viewBox="0 0 24 24" fill="currentColor" style="vertical-align:-1px;flex-shrink:0;"><path d="M12 2l1.5 5L19 8.5 14 10l-1 5-2-4-5 1 4-2.5L10 5l2 2z"/></svg>';
    const adminEmailBadge = (isAdmin && r.email) 
      ? `<div style="display:inline-flex;align-items:center;gap:5px;font-size:.68rem;color:#8A1538;font-weight:700;background:#e8f2ec;border:1px solid #c5dbcb;padding:2px 8px;border-radius:999px;margin-top:4px;direction:ltr;">${mailIcon}${esc(r.email)}</div>` 
      : '';
    // شارة "زائر بدون حساب" للأدمن فقط (إذا المستخدم ما عنده إيميل)
    const adminGuestBadge = (isAdmin && !r.email)
      ? `<div style="display:inline-flex;align-items:center;gap:5px;font-size:.65rem;color:#888;font-weight:600;background:#f5f5f5;border:1px dashed #ccc;padding:2px 8px;border-radius:999px;margin-top:4px;font-style:italic;">${userIcon}زائر (بدون حساب)</div>`
      : '';
    // شارة "شخص مميز ومبدع" تظهر للجمهور العادي فقط
    const publicSpecialBadge = (!isAdmin)
      ? `<div style="display:inline-flex;align-items:center;gap:5px;font-size:.68rem;color:#8A6D2E;font-weight:800;background:linear-gradient(135deg,#f3e8c4,#f0e5b8);border:1px solid rgba(184,146,74,.5);padding:3px 10px;border-radius:999px;margin-top:5px;box-shadow:0 2px 6px rgba(184,146,74,.12);"><span style="color:#B8924A;">${sparkIcon}</span>شخص مميز ومبدع</div>`
      : '';
    return `<div class="review-card"> ${isAdmin?`<button class="rc-delete" onclick="deleteReview('${escAttr(r.id)}')" title="حذف">حذف</button>`:''}
      <div style="display:flex;align-items:center;justify-content:space-between;gap:8px;">
        <div>
          <div class="rc-name">${esc(displayName)}</div>
          <div class="rc-stars">${starsGold}${starsGray}</div> ${adminEmailBadge}${adminGuestBadge}${publicSpecialBadge}
        </div>
        <div class="rc-date" style="text-align:left;">${dateStr}</div>
      </div> ${r.comment?`<div class="rc-text" id="rc-${r.id}" style="display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;">"${esc(r.comment)}"</div> ${r.comment.length>120?`<button onclick="expandReview('${escAttr(r.id)}')" id="rcb-${escAttr(r.id)}" style="background:none;border:none;color:#8A1538;font-family:Cairo,sans-serif;font-size:.75rem;font-weight:700;cursor:pointer;padding:2px 0;margin-top:2px;">اقرأ المزيد ▼</button>`:''}`:'' }
    </div>`;
  }).join('');
}

function expandReview(id){
  const el=document.getElementById('rc-'+id);
  const btn=document.getElementById('rcb-'+id);
  if(!el) return;
  el.style.webkitLineClamp='unset';
  el.style.overflow='visible';
  if(btn) btn.style.display='none';
}

async function deleteReview(id){
  if(!confirm('حذف هذا التقييم؟'))return;
  try{
    if(!OFFLINE_MODE&&db){
      await db.collection('reviews').doc(id).delete();
    }else{
      let reviews=JSON.parse(localStorage.getItem('hh_reviews')||'[]');
      reviews=reviews.filter(r=>r.id!==id);
      localStorage.setItem('hh_reviews',JSON.stringify(reviews));
    }
    loadHomeReviews();
    toast('تم الحذف','info');
  }catch(e){toast('خطأ في الحذف','error');}
}
