// ════════════ ADMIN PANEL ════════════
// ════ نظام الصلاحيات ════

function isAdminUser(u){
  const user = u || currentUser || (typeof auth !== 'undefined' && auth.currentUser);
  return !!(user && user.email === SUPER_ADMIN_EMAIL);
}

// فحص إذا المستخدم لديه صلاحية تعديل الأسئلة
async function isQuestionEditor(u){
  if(isAdminUser(u)) return true; // المدير دائما مصرح
  const user = u || currentUser;
  if(!user || !db) return false;
  try{
    const doc = await db.collection('users').doc(user.uid).get();
    if(doc.exists && doc.data().canEditQuestions === true) return true;
    // الشركاء: لديهم صلاحية مقيّدة على فئاتهم فقط
    return _hhGetPartnerEditableCats(user.email).length > 0;
  }catch(e){ return false; }
}

// ═══ الصلاحية المقيّدة للشركاء ═══
// يُرجع قائمة الفئات التي يحق لحساب الشريك (حسب بريده) تعديلها
function _hhGetPartnerEditableCats(email){
  if(!email) return [];
  const out = [];
  try{
    const cfg = (typeof _hh_getSponsorsConfig === 'function') ? _hh_getSponsorsConfig() : null;
    if(!cfg || !Array.isArray(cfg.tiers)) return [];
    const target = String(email).trim().toLowerCase();
    cfg.tiers.forEach(function(t){
      if(!Array.isArray(t.partners)) return;
      t.partners.forEach(function(p){
        if(!p.accountEmail) return;
        if(String(p.accountEmail).trim().toLowerCase() !== target) return;
        // نطابق فئات هذا الشريك من QDB حسب اسمه (بيرف آب / طموح / ...)
        const key = _hhPartnerCatKey(p.name);
        if(!key) return;
        try{
          Object.keys(QDB || {}).forEach(function(cat){
            if(cat.indexOf(key) !== -1) out.push(cat);
          });
        }catch(e){}
      });
    });
  }catch(e){}
  return Array.from(new Set(out));
}

// يستخرج الكلمة المفتاحية لمطابقة فئات الشريك من اسمه
function _hhPartnerCatKey(name){
  if(!name) return '';
  const n = String(name);
  if(n.indexOf('بيرف') !== -1) return 'بيرف آب';
  if(n.indexOf('طموح') !== -1) return 'طموح';
  if(n.indexOf('أجيال') !== -1 || n.indexOf('قنوان') !== -1) return 'قنوان';
  return n.trim(); // احتياطي: نطابق بالاسم الكامل
}

// هل المستخدم الحالي شريك مقيّد (وليس أدمن كامل)؟
function _hhIsRestrictedPartner(u){
  const user = u || currentUser;
  if(!user || isAdminUser(user)) return false;
  return _hhGetPartnerEditableCats(user.email).length > 0;
}

// فحص إذا المستخدم لديه صلاحية رؤية قسم شركاء النجاح
async function canViewPartners(u){
  if(isAdminUser(u)) return true; // المدير دائما يشوف
  const user = u || currentUser;
  if(!user || !db) return false;
  try{
    const doc = await db.collection('users').doc(user.uid).get();
    return !!(doc.exists && doc.data().canViewPartners === true);
  }catch(e){ return false; }
}

// تحديث ظهور قسم شركاء النجاح بناء على الصلاحية
async function updatePartnersVisibility(u){
  const section = document.getElementById('partners-section');
  if(!section) return;
  const allowed = await canViewPartners(u);
  section.style.display = allowed ? 'block' : 'none';
}

