// إنشاء فئة جديدة من لوحة التحكم
// ═══════════════════════════════════════════════════════════
function hhOpenNewCategoryModal(){
  // نبني قائمة المجموعات المتاحة + خيار إنشاء جديد
  let groupOptions = '';
  if(typeof CAT_GROUPS !== 'undefined'){
    CAT_GROUPS.forEach(g => {
      if(g.id.includes('_soon')) return;
      groupOptions += `<option value="${g.id}">${g.label}</option>`;
    });
  }
  groupOptions += `<option value="__new__" style="font-weight:900;color:#8A1538;background:#F7EBEE;">+ إنشاء مجموعة جديدة</option>`;

  // ألوان مقترحة احترافية (بدون فاقع)
  const suggestedColors = [
    {label:'عنابي',c:'#8A1538'},
    {label:'عنابي داكن',c:'#5E0E26'},
    {label:'ذهبي مطفي',c:'#B8924A'},
    {label:'كحلي',c:'#1E3A5F'},
    {label:'أخضر هادئ',c:'#3D6B53'},
    {label:'بنفسجي رصين',c:'#3D4A7A'},
    {label:'بني فاخر',c:'#A67C4A'}
  ];
  const colorBtns = suggestedColors.map(co => `<button type="button" onclick="document.getElementById('hh-newcat-color').value='${co.c}';document.getElementById('hh-newcat-color-preview').style.background='${co.c}';return false;" title="${co.label}" style="width:34px;height:34px;background:${co.c};border:2px solid #fff;border-radius:50%;cursor:pointer;box-shadow:0 2px 6px rgba(0,0,0,.15);"></button>`
  ).join('');

  const modal = document.createElement('div');
  modal.id = 'hh-newcat-modal';
  modal.style.cssText = 'position:fixed;inset:0;background:rgba(43,11,30,.65);backdrop-filter:blur(4px);z-index:99999;display:flex;align-items:center;justify-content:center;padding:16px;';
  modal.innerHTML = `
    <div style="background:#fff;border-radius:16px;max-width:520px;width:100%;max-height:90vh;overflow-y:auto;box-shadow:0 20px 60px rgba(0,0,0,.4);border:2px solid #8A1538;">
      <!-- header -->
      <div style="background:linear-gradient(135deg,#8A1538,#5E0E26);color:#fff;padding:16px 20px;border-radius:14px 14px 0 0;display:flex;justify-content:space-between;align-items:center;">
        <div style="font-family:Cairo,sans-serif;font-weight:900;font-size:1.05rem;">إنشاء فئة جديدة</div>
        <button onclick="hhCloseNewCategoryModal()" style="background:rgba(255,255,255,.15);border:none;color:#fff;width:30px;height:30px;border-radius:50%;cursor:pointer;font-size:1.1rem;font-weight:900;">✕</button>
      </div>

      <!-- body -->
      <div style="padding:20px;font-family:Tajawal,sans-serif;">
        
        <!-- اسم الفئة -->
        <div style="margin-bottom:14px;">
          <label style="font-family:Cairo;font-weight:800;font-size:.85rem;color:#8A1538;display:block;margin-bottom:6px;">اسم الفئة <span style="color:#c0392b;">*</span></label>
          <input id="hh-newcat-name" type="text" placeholder="مثال: التاريخ الإسلامي" 
            style="width:100%;padding:11px;border:1.5px solid #B8924A;border-radius:8px;font-family:Tajawal;font-size:.92rem;outline:none;" autocomplete="off">
          <div style="font-size:.7rem;color:#8A6D2E;margin-top:4px;">سيظهر هذا الاسم في قائمة الفئات</div>
        </div>

        <!-- المجموعة -->
        <div style="margin-bottom:14px;">
          <label style="font-family:Cairo;font-weight:800;font-size:.85rem;color:#8A1538;display:block;margin-bottom:6px;">المجموعة <span style="color:#c0392b;">*</span></label>
          <select id="hh-newcat-group" onchange="hhHandleGroupChange(this)" style="width:100%;padding:11px;border:1.5px solid #B8924A;border-radius:8px;font-family:Cairo,sans-serif;font-size:.9rem;background:#fff;">
            <option value="">-- اختر المجموعة --</option> ${groupOptions}
          </select>
          <div style="font-size:.7rem;color:#8A6D2E;margin-top:4px;">المجموعة تحدد أين ستظهر الفئة في القائمة</div>

          <!-- نموذج إنشاء مجموعة جديدة (يظهر عند اختيار "+ إنشاء مجموعة") -->
          <div id="hh-newgroup-form" style="display:none;margin-top:10px;padding:12px;background:#F7EBEE;border:1.5px dashed #8A1538;border-radius:10px;">
            <label style="font-family:Cairo;font-weight:800;font-size:.78rem;color:#5E0E26;display:block;margin-bottom:5px;">اسم المجموعة الجديدة</label>
            <input id="hh-newgroup-name" type="text" placeholder="مثال: التراث والفنون"
              style="width:100%;padding:9px;border:1.5px solid #8A1538;border-radius:8px;font-family:Tajawal;font-size:.9rem;outline:none;background:#fff;" autocomplete="off">
            <div style="font-size:.68rem;color:#8A1538;margin-top:5px;">ستصبح مجموعة جديدة في قائمة الفئات تحتوي على هذه الفئة وأي فئات تُنشئها لاحقاً</div>
          </div>
        </div>

        <!-- اللون -->
        <div style="margin-bottom:14px;">
          <label style="font-family:Cairo;font-weight:800;font-size:.85rem;color:#8A1538;display:block;margin-bottom:6px;">لون الفئة</label>
          <div style="display:flex;align-items:center;gap:10px;">
            <input id="hh-newcat-color" type="text" value="#8A1538" 
              style="flex:1;padding:11px;border:1.5px solid #B8924A;border-radius:8px;font-family:monospace;font-size:.92rem;outline:none;">
            <div id="hh-newcat-color-preview" style="width:44px;height:44px;background:#8A1538;border:2px solid #fff;border-radius:8px;box-shadow:0 2px 8px rgba(0,0,0,.15);"></div>
          </div>
          <div style="margin-top:8px;display:flex;flex-wrap:wrap;gap:6px;"> ${colorBtns}
          </div>
        </div>

        <!-- الوصف -->
        <div style="margin-bottom:18px;">
          <label style="font-family:Cairo;font-weight:800;font-size:.85rem;color:#8A1538;display:block;margin-bottom:6px;">وصف مختصر (اختياري)</label>
          <input id="hh-newcat-desc" type="text" placeholder="وصف يظهر تحت اسم الفئة" 
            style="width:100%;padding:11px;border:1.5px solid #B8924A;border-radius:8px;font-family:Tajawal;font-size:.88rem;outline:none;">
        </div>

        <!-- الأزرار -->
        <div style="display:flex;gap:10px;">
          <button onclick="hhCloseNewCategoryModal()" 
            style="flex:1;padding:12px;background:#fff;color:#8A1538;border:1.5px solid #8A1538;border-radius:10px;font-family:Cairo;font-weight:900;font-size:.92rem;cursor:pointer;"> إلغاء
          </button>
          <button onclick="hhCreateNewCategory()" 
            style="flex:2;padding:12px;background:linear-gradient(135deg,#8A1538,#5E0E26);color:#fff;border:none;border-radius:10px;font-family:Cairo;font-weight:900;font-size:.92rem;cursor:pointer;box-shadow:0 4px 12px rgba(138,21,56,.3);display:inline-flex;align-items:center;justify-content:center;gap:6px;">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor"><path d="M19 13h-6v6h-2v-6H5v-2h6V5h2v6h6v2z"/></svg> إنشاء الفئة
          </button>
        </div>

      </div>
    </div> `;
  document.body.appendChild(modal);

  modal.addEventListener('click', (e) => {
    if(e.target === modal) hhCloseNewCategoryModal();
  });

  setTimeout(() => {
    const nameInput = document.getElementById('hh-newcat-name');
    if(nameInput) nameInput.focus();
  }, 100);

  setTimeout(() => {
    const colorInput = document.getElementById('hh-newcat-color');
    if(colorInput){
      colorInput.oninput = () => {
        const preview = document.getElementById('hh-newcat-color-preview');
        if(preview) preview.style.background = colorInput.value;
      };
    }
  }, 100);
}

// معالجة تغيير المجموعة (إظهار نموذج إنشاء مجموعة جديدة)
function hhHandleGroupChange(sel){
  const form = document.getElementById('hh-newgroup-form');
  if(!form) return;
  if(sel.value === '__new__'){
    form.style.display = 'block';
    setTimeout(() => {
      const input = document.getElementById('hh-newgroup-name');
      if(input) input.focus();
    }, 50);
  } else {
    form.style.display = 'none';
  }
}

function hhCloseNewCategoryModal(){
  const modal = document.getElementById('hh-newcat-modal');
  if(modal) modal.remove();
}

//  حذف فئة مخصصة (للفئات التي أنشأها الأدمن فقط)
async function hhDeleteCurrentCategory(){
  const cat = _aqCurrentCat;
  if(!cat){
    if(typeof toast === 'function') toast('اختر فئة أولاً', 'error');
    return;
  }

  // التحقق: هل هذه فئة مخصصة (في hh_custom_cats)؟
  let customCats = {};
  try{ customCats = JSON.parse(localStorage.getItem('hh_custom_cats') || '{}'); }catch(e){}
  
  if(!customCats[cat]){
    if(typeof toast === 'function') toast('لا يمكن حذف الفئات الأصلية · فقط الفئات التي أنشأتها', 'error');
    return;
  }

  // تأكيد الحذف
  const confirmMsg = `هل أنت متأكد من حذف فئة "${cat}"؟\n\nسيتم حذف:\n• الفئة من القائمة\n• جميع أسئلتها (${(QDB[cat]||[]).length} سؤال)\n\nهذا الإجراء لا يمكن التراجع عنه!`;
  if(!confirm(confirmMsg)) return;

  try{
    // 1) حذف من QDB
    if(QDB[cat]) delete QDB[cat];

    // 2) حذف من CAT_INFO
    if(typeof CAT_INFO !== 'undefined' && CAT_INFO[cat]) delete CAT_INFO[cat];

    // 3) حذف من CAT_GROUPS
    if(typeof CAT_GROUPS !== 'undefined'){
      CAT_GROUPS.forEach(g => {
        if(Array.isArray(g.cats)){
          g.cats = g.cats.filter(c => c !== cat);
        }
      });
    }

    // 4) حذف من localStorage
    delete customCats[cat];
    localStorage.setItem('hh_custom_cats', JSON.stringify(customCats));
    if(typeof _hh_saveCustomizationsToCloud === 'function') _hh_saveCustomizationsToCloud();

    // 5) حذف من Firestore
    if(typeof db !== 'undefined' && db){
      try{
        await db.collection('admin_qdb').doc(cat).delete();
      }catch(e){
        console.warn('حذف السحابي تعذر:', e);
      }
    }

    // 6) إعادة بناء الواجهة
    _aqCurrentCat = '';
    if(typeof populateAQCatSelect === 'function') populateAQCatSelect();
    if(typeof buildCatSelect === 'function') buildCatSelect();
    
    // مسح قائمة الأسئلة المعروضة
    const listEl = document.getElementById('aq-questions-list');
    if(listEl) listEl.innerHTML = '';
    const filterWrap = document.getElementById('aq-filter-wrap');
    if(filterWrap) filterWrap.style.display = 'none';

    if(typeof toast === 'function') toast(' تم حذف فئة "' + cat + '"', 'success');

  }catch(e){
    console.error('خطأ في حذف الفئة:', e);
    if(typeof toast === 'function') toast('تعذر الحذف: ' + e.message, 'error');
  }
}

async function hhCreateNewCategory(){
  const name = (document.getElementById('hh-newcat-name')?.value || '').trim();
  let groupId = document.getElementById('hh-newcat-group')?.value || '';
  const color = (document.getElementById('hh-newcat-color')?.value || '#8A1538').trim();
  const desc = (document.getElementById('hh-newcat-desc')?.value || '').trim();

  // التحقق من اسم الفئة
  if(!name){
    if(typeof toast === 'function') toast('يجب إدخال اسم الفئة', 'error');
    document.getElementById('hh-newcat-name')?.focus();
    return;
  }
  if(!groupId){
    if(typeof toast === 'function') toast('يجب اختيار المجموعة', 'error');
    document.getElementById('hh-newcat-group')?.focus();
    return;
  }

  // إذا اختار "إنشاء مجموعة جديدة"
  if(groupId === '__new__'){
    const newGroupName = (document.getElementById('hh-newgroup-name')?.value || '').trim();
    if(!newGroupName){
      if(typeof toast === 'function') toast('يجب إدخال اسم المجموعة الجديدة', 'error');
      document.getElementById('hh-newgroup-name')?.focus();
      return;
    }
    // ننشئ ID للمجموعة (بسيط من الاسم)
    const newGroupId = 'custom_' + Date.now();
    
    if(typeof CAT_GROUPS !== 'undefined'){
      // التحقق من عدم وجود مجموعة بنفس الاسم
      if(CAT_GROUPS.some(g => g.label === newGroupName)){
        if(typeof toast === 'function') toast('هذه المجموعة موجودة بالفعل', 'error');
        return;
      }
      // نضيف المجموعة الجديدة
      CAT_GROUPS.push({
        id: newGroupId,
        label: newGroupName,
        icon: `<svg viewBox="0 0 100 100" width="36" height="36" xmlns="http://www.w3.org/2000/svg"><rect width="100" height="100" rx="14" fill="${color}"/><text x="50" y="62" text-anchor="middle" font-size="40" font-family="Cairo,Arial" fill="#fff" font-weight="900">${newGroupName.charAt(0)}</text></svg>`,
        cats: []
      });
      
      // نضيف المجموعة لمستوى "العامة" تلقائياً
      if(typeof CAT_LEVELS !== 'undefined'){
        const generalLevel = CAT_LEVELS.find(l => l.id === 'general');
        if(generalLevel && !generalLevel.groupIds.includes(newGroupId)){
          generalLevel.groupIds.push(newGroupId);
        }
      }
      
      // حفظ المجموعة المخصصة في localStorage
      try{
        const customGroups = JSON.parse(localStorage.getItem('hh_custom_groups') || '{}');
        customGroups[newGroupId] = { label: newGroupName, color: color };
        localStorage.setItem('hh_custom_groups', JSON.stringify(customGroups));
        if(typeof _hh_saveCustomizationsToCloud === 'function') _hh_saveCustomizationsToCloud();
      }catch(e){}
      
      // حفظ المجموعة المخصصة في Firestore (لتظهر لكل المستخدمين)
      if(typeof db !== 'undefined' && db){
        try{
          await db.collection('platform_settings').doc('custom_groups').set({
            [newGroupId]: {
              label: newGroupName,
              color: color,
              createdAt: firebase.firestore.FieldValue.serverTimestamp(),
              createdBy: currentUser ? (currentUser.email || currentUser.uid) : 'admin' }
          }, { merge: true });
        }catch(e){ console.warn('حفظ المجموعة سحابياً تعذر:', e); }
      }
      
      groupId = newGroupId;
    }
  }

  // التحقق من عدم وجود فئة بنفس الاسم
  if(QDB[name] || (typeof CAT_INFO !== 'undefined' && CAT_INFO[name])){
    if(typeof toast === 'function') toast('هذه الفئة موجودة بالفعل', 'error');
    return;
  }

  try{
    // 1) إضافة الفئة لـ QDB (فارغة)
    QDB[name] = [];

    // 2) إضافة الفئة لـ CAT_INFO (بدون إيموجي)
    if(typeof CAT_INFO !== 'undefined'){
      const bgColor = color + '15';
      CAT_INFO[name] = {
        emoji:'',
        label: name,
        color: color,
        bg: bgColor
      };
    }

    // 3) إضافة الفئة للمجموعة المختارة
    if(typeof CAT_GROUPS !== 'undefined'){
      const grp = CAT_GROUPS.find(g => g.id === groupId);
      if(grp && Array.isArray(grp.cats)){
        if(!grp.cats.includes(name)){
          grp.cats.push(name);
        }
      }
    }

    // 4) حفظ في Firestore
    if(typeof db !== 'undefined' && db && typeof currentUser !== 'undefined' && currentUser){
      try{
        await db.collection('admin_qdb').doc(name).set({
          questions: [],
          meta: {
            color: color,
            bg: color + '15',
            groupId: groupId,
            desc: desc,
            createdAt: firebase.firestore.FieldValue.serverTimestamp(),
            createdBy: currentUser.email || currentUser.uid
          }
        }, { merge: true });
      }catch(e){
        console.warn('حفظ السحابي تعذر:', e);
      }
    }

    // 5) حفظ محلي
    try{
      const customCats = JSON.parse(localStorage.getItem('hh_custom_cats') || '{}');
      customCats[name] = {
        color: color,
        bg: color + '15',
        groupId: groupId,
        desc: desc
      };
      localStorage.setItem('hh_custom_cats', JSON.stringify(customCats));
      if(typeof _hh_saveCustomizationsToCloud === 'function') _hh_saveCustomizationsToCloud();
    }catch(e){}

    // 6) إعادة بناء الواجهة (إجبار كامل)
    if(typeof populateAQCatSelect === 'function') populateAQCatSelect();
    // إعادة بناء شاشة اختيار الفئات (لو كان المستخدم فيها)
    if(typeof buildCatSelect === 'function'){
      try{ buildCatSelect(); }catch(e){ console.warn(e); }
    }
    // مسح أي كاش للفئات
    try{ localStorage.removeItem('hh_saved_cats'); }catch(e){}

    // 7) اختيار الفئة الجديدة
    setTimeout(() => {
      const sel = document.getElementById('aq-cat-select');
      if(sel){
        sel.value = name;
        if(typeof loadAdminCatQuestions === 'function') loadAdminCatQuestions();
      }
    }, 100);

    // إغلاق النموذج
    hhCloseNewCategoryModal();

    // رسالة نجاح
    if(typeof toast === 'function'){
      toast('تم إنشاء فئة "' + name + '" بنجاح! ابدأ بإضافة الأسئلة', 'success');
    }
    // تتبع الإنجازات
    if(window.hhTrackActivity) hhTrackActivity('new_category');

  }catch(e){
    console.error('خطأ في إنشاء الفئة:', e);
    if(typeof toast === 'function') toast('تعذر إنشاء الفئة: ' + e.message, 'error');
  }
}

function loadAdminCatQuestions(){
  const cat = document.getElementById('aq-cat-select').value;
  _aqCurrentCat = cat;
  const listEl = document.getElementById('aq-questions-list');
  const formEl = document.getElementById('aq-add-form');
  const filterWrap = document.getElementById('aq-filter-wrap');
  if(!cat){ listEl.innerHTML=''; formEl.style.display='none'; if(filterWrap)filterWrap.style.display='none'; return; }
  if(filterWrap){ filterWrap.style.display='block'; document.getElementById('aq-filter').value=''; }
  // نمرر مع origIdx ليعرف الزر أي سؤال يعدل
  const all = QDB[cat] || [];
  renderQuestionsList(all.map((q,idx)=>({q_obj:q, origIdx:idx})), cat);
}

// عرض قائمة الأسئلة (يستخدم من loadAdminCatQuestions و filterCurrentCategory)
function renderQuestionsList(qs, cat, highlight){
  const listEl = document.getElementById('aq-questions-list');
  const diffLabels = {easy:'سهل 200', med:'متوسط 400', hard:'صعب 600', elite:'نخبة 800'};
  const diffColors = {easy:'#1a5fa8', med:'#b86a00', hard:'#b01c1c', elite:'#5E0E26'};
  // دالة لتلوين الكلمة المبحوث عنها
  const hl = (text) => {
    if(!highlight) return esc(text);
    try{
      const safe = highlight.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
      const re = new RegExp('('+safe+')', 'gi');
      return esc(text).replace(re, '<mark style="background:#fff3a8;color:#8A6D2E;padding:0 2px;border-radius:3px;">$1</mark>');
    }catch(e){ return esc(text); }
  };
  listEl.innerHTML = qs.length ? qs.map(item=>{
    const q = item.q_obj || item;
    const i = (item.origIdx !== undefined) ? item.origIdx : item.idx;
    const imgThumb = q.img ? `<img src="${q.img}" style="width:40px;height:40px;object-fit:cover;border-radius:6px;border:1.5px solid #B8924A;flex-shrink:0;cursor:pointer;" onclick="hhPreviewImg('${q.img}')" title="انقر لعرض الصورة كاملة">` : '';
    return `
    <div style="background:#fff;border:1.5px solid #e0e8f0;border-radius:10px;padding:10px 12px;margin-bottom:8px;display:flex;align-items:flex-start;gap:8px;">
      <span style="font-size:.68rem;font-weight:900;color:${diffColors[q.diff]||'#555'};background:#f0f4f8;border-radius:6px;padding:2px 7px;flex-shrink:0;margin-top:2px;">${diffLabels[q.diff]||q.diff}</span> ${imgThumb}
      <div style="flex:1;min-width:0;">
        <div style="font-size:.82rem;font-weight:700;color:#1a1a2e;margin-bottom:3px;">${hl(q.q)} ${q.img?'<span style="font-size:.65rem;color:#B8924A;font-weight:700;"></span>':''}</div>
        <div style="font-size:.75rem;color:#3D6B53;">✓ ${hl(q.a)}</div>
      </div>
      <div style="display:flex;gap:4px;flex-shrink:0;">
        <button onclick="editAdminQuestion(${i})" style="padding:4px 8px;background:#e8f2ec;border:1.5px solid #8A1538;border-radius:6px;font-family:Cairo;font-size:.72rem;font-weight:700;color:#8A1538;cursor:pointer;">تعديل</button>
        <button onclick="deleteAdminQuestion(${i})" style="padding:4px 8px;background:#fde8e8;border:1.5px solid #c0392b;border-radius:6px;font-family:Cairo;font-size:.72rem;font-weight:700;color:#c0392b;cursor:pointer;">حذف</button>
      </div>
    </div>`;
  }).join('') : '<p style="text-align:center;color:#aaa;padding:20px;">لا توجد أسئلة مطابقة</p>';
}

// معاينة الصورة بحجم كامل
function hhPreviewImg(src){
  const overlay = document.createElement('div');
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.9);z-index:99999;display:flex;align-items:center;justify-content:center;cursor:zoom-out;padding:20px;';
  overlay.innerHTML = `<img src="${src}" style="max-width:100%;max-height:100%;border-radius:10px;box-shadow:0 10px 40px rgba(0,0,0,.5);">`;
  overlay.onclick = () => overlay.remove();
  document.body.appendChild(overlay);
}

// فلترة داخل الفئة المختارة
function filterCurrentCategory(){
  if(!_aqCurrentCat) return;
  const term = (document.getElementById('aq-filter').value||'').trim().toLowerCase();
  const all = QDB[_aqCurrentCat] || [];
  const countEl = document.getElementById('aq-filter-count');
  if(!term){
    renderQuestionsList(all.map((q,idx)=>({q_obj:q, origIdx:idx})), _aqCurrentCat);
    if(countEl) countEl.textContent = `${all.length} سؤال`;
    return;
  }
  const filtered = all.map((q,idx)=>({q_obj:q, origIdx:idx}))
    .filter(item => (item.q_obj.q||'').toLowerCase().includes(term) || (item.q_obj.a||'').toLowerCase().includes(term));
  renderQuestionsList(filtered, _aqCurrentCat, term);
  if(countEl) countEl.textContent = `${filtered.length} من ${all.length}`;
}

//  بحث شامل عبر كل الفئات
function globalSearchQuestions(){
  const term = (document.getElementById('aq-global-search').value||'').trim().toLowerCase();
  const resultsEl = document.getElementById('aq-global-results');
  if(!term){ resultsEl.innerHTML = ''; return; }
  if(term.length < 2){ resultsEl.innerHTML = '<div style="font-size:.75rem;color:#888;padding:6px;">اكتب حرفين على الأقل...</div>'; return; }
  const results = [];
  const catNames = Object.keys(QDB);
  catNames.forEach(cat=>{
    const arr = QDB[cat] || [];
    arr.forEach((q,idx)=>{
      if((q.q||'').toLowerCase().includes(term) || (q.a||'').toLowerCase().includes(term)){
        results.push({cat, idx, q});
      }
    });
  });
  const diffLabels = {easy:'س', med:'م', hard:'ص'};
  const diffColors = {easy:'#1a5fa8', med:'#b86a00', hard:'#b01c1c', elite:'#5E0E26'};
  // تمييز الكلمة
  const hl = (text) => {
    try{
      const safe = term.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
      const re = new RegExp('('+safe+')', 'gi');
      return esc(text).replace(re, '<mark style="background:#fff3a8;color:#8A6D2E;padding:0 2px;border-radius:3px;">$1</mark>');
    }catch(e){ return esc(text); }
  };
  if(!results.length){
    resultsEl.innerHTML = `<div style="font-size:.8rem;color:#888;padding:10px;text-align:center;background:#fafafa;border-radius:8px;">لا نتائج مطابقة لـ "<strong>${esc(term)}</strong>"</div>`;
    return;
  }
  // عرض عداد + النتائج
  const header = `<div style="font-size:.78rem;font-weight:900;color:#8A1538;margin-bottom:8px;background:#e8f2ec;padding:6px 10px;border-radius:6px;">
    <svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M12 2a10 10 0 100 20 10 10 0 000-20zm0 18a8 8 0 110-16 8 8 0 010 16zm0-14a6 6 0 100 12 6 6 0 000-12zm0 10a4 4 0 110-8 4 4 0 010 8zm0-6a2 2 0 100 4 2 2 0 000-4z"/></svg> ${results.length} نتيجة في ${new Set(results.map(r=>r.cat)).size} فئة
  </div>`;
  // تحديد أقصى 30 نتيجة لتجنب الإبطاء
  const maxDisplay = 30;
  const shown = results.slice(0, maxDisplay);
  const more = results.length > maxDisplay ? `<div style="text-align:center;font-size:.72rem;color:#888;padding:6px;">عرض أول ${maxDisplay} من ${results.length} · ضع كلمة أدق للتصفية</div>` : '';
  resultsEl.innerHTML = header + shown.map(r=>`
    <div style="background:#fff;border:1.5px solid #e0e8f0;border-radius:8px;padding:8px 10px;margin-bottom:6px;">
      <div style="display:flex;align-items:center;gap:6px;margin-bottom:4px;">
        <span style="font-size:.62rem;font-weight:900;color:${diffColors[r.q.diff]||'#555'};background:#f0f4f8;border-radius:4px;padding:1px 5px;">${diffLabels[r.q.diff]||r.q.diff}</span>
        <span style="font-size:.7rem;font-weight:700;color:#8A1538;background:#e8f2ec;padding:2px 7px;border-radius:10px;">${esc(r.cat)}</span>
      </div>
      <div style="font-size:.78rem;font-weight:700;color:#1a1a2e;margin-bottom:2px;">${hl(r.q.q)}</div>
      <div style="font-size:.72rem;color:#3D6B53;margin-bottom:6px;">✓ ${hl(r.q.a)}</div>
      <div style="display:flex;gap:4px;">
        <button onclick="jumpToEditQuestion('${esc(r.cat).replace(/'/g,"\\'")}',${r.idx})"
          style="flex:1;padding:4px 6px;background:#e8f2ec;border:1.5px solid #8A1538;border-radius:5px;font-family:Cairo;font-size:.7rem;font-weight:700;color:#8A1538;cursor:pointer;">تعديل</button>
        <button onclick="jumpToDeleteQuestion('${esc(r.cat).replace(/'/g,"\\'")}',${r.idx})"
          style="padding:4px 10px;background:#fde8e8;border:1.5px solid #c0392b;border-radius:5px;font-family:Cairo;font-size:.7rem;font-weight:700;color:#c0392b;cursor:pointer;">حذف</button>
      </div>
    </div> `).join('') + more;
}

// الانتقال لتعديل سؤال من نتائج البحث الشامل
function jumpToEditQuestion(cat, idx){
  document.getElementById('aq-cat-select').value = cat;
  loadAdminCatQuestions();
  setTimeout(()=>{
    editAdminQuestion(idx);
    // قم بالتمرير إلى نموذج التعديل
    const form = document.getElementById('aq-add-form');
    if(form) form.scrollIntoView({behavior:'smooth', block:'center'});
  }, 100);
}

// الحذف مباشرة من نتائج البحث الشامل
function jumpToDeleteQuestion(cat, idx){
  const q = (QDB[cat]||[])[idx];
  if(!q) return;
  if(!confirm('حذف هذا السؤال من فئة "'+cat+'"؟\n\n"'+q.q+'"')) return;
  QDB[cat].splice(idx, 1);
  saveAdminQuestion_persist(cat);
  toast('تم حذف السؤال من '+cat, 'info');
  // إعادة البحث لتحديث النتائج
  globalSearchQuestions();
  // إذا كانت الفئة المختارة حاليا، حدثها
  if(_aqCurrentCat === cat){
    loadAdminCatQuestions();
  }
}

function showAQAddForm(){
  document.getElementById('aq-edit-idx').value = '';
  document.getElementById('aq-question-text').value = '';
  document.getElementById('aq-answer-text').value = '';
  document.getElementById('aq-image-data').value = '';
  hhRemoveQuestionImage();
  setAQDiff('easy');
  document.getElementById('aq-add-form').style.display = 'block';
  document.getElementById('aq-question-text').focus();
}


// ═══ رفع صورة سؤال إلى Firebase Storage · يعيد رابط التحميل أو null ═══
async function hhUploadQImageToStorage(dataUrl){
  if(typeof firebase === 'undefined' || !firebase.storage) return null;
  if(typeof OFFLINE_MODE !== 'undefined' && OFFLINE_MODE) return null;
  const uid = (typeof currentUser !== 'undefined' && currentUser) ? currentUser.uid : 'anon';
  const path = 'question_images/' + uid + '_' + Date.now() + '.jpg';
  const ref = firebase.storage().ref(path);
  const snap = await ref.putString(dataUrl, 'data_url');
  return await snap.ref.getDownloadURL();
}

// معالجة رفع الصورة (مع ضغط تلقائي)
async function hhHandleImageUpload(event){
  const file = event.target.files[0];
  if(!file) return;
  
  // التحقق من النوع
  if(!file.type.startsWith('image/')){
    if(typeof toast === 'function') toast('يرجى اختيار ملف صورة', 'error');
    return;
  }
  
  // التحقق من الحجم (max 10MB قبل الضغط)
  if(file.size > 10 * 1024 * 1024){
    if(typeof toast === 'function') toast('حجم الصورة كبير جداً (الحد الأقصى 10MB)', 'error');
    return;
  }
  
  if(typeof toast === 'function') toast('جاري معالجة الصورة...', 'info');
  
  try{
    // ضغط الصورة وتحويلها لـ Base64
    // ضغط تكيّفي: نبدأ بجودة عالية ونشدّ إن كانت النتيجة ثقيلة (حماية حد المزامنة)
    let compressed = await hhCompressImage(file, 1000, 0.75);
    if(compressed.length > 220*1024){ compressed = await hhCompressImage(file, 800, 0.62); }
    if(compressed.length > 220*1024){ compressed = await hhCompressImage(file, 640, 0.55); }
    
    // ═══ الرفع إلى Firebase Storage أولاً (يُحفظ الرابط الصغير بدل base64) ═══
    let finalImg = compressed, viaStorage = false;
    try{
      const url = await hhUploadQImageToStorage(compressed);
      if(url){ finalImg = url; viaStorage = true; }
    }catch(eSt){ console.warn('Storage غير متاح، الإبقاء على base64:', eSt && eSt.message); }

    // عرض المعاينة
    document.getElementById('aq-image-data').value = finalImg;
    document.getElementById('aq-image-preview').src = finalImg;
    document.getElementById('aq-image-preview-wrap').style.display = 'block';
    document.getElementById('aq-image-upload-btn').style.display = 'none';
    
    // عرض الحجم
    const sizeKB = Math.round(compressed.length * 0.75 / 1024);
    document.getElementById('aq-image-size').textContent = viaStorage ? ('✓ Storage · '+sizeKB+' KB') : (sizeKB + ' KB');
    
    if(typeof toast === 'function') toast(viaStorage ? 'رُفعت الصورة إلى Storage · حُفظ الرابط فقط' : 'تم حفظ الصورة (مضغوطة محلياً — فعّل Storage للأفضل)', 'success');
  }catch(e){
    console.error('خطأ في معالجة الصورة:', e);
    if(typeof toast === 'function') toast('تعذرت معالجة الصورة: ' + e.message, 'error');
  }
  
  // مسح القيمة لإمكان رفع نفس الصورة مرة أخرى
  event.target.value = '';
}

//  ضغط الصورة لتقليل حجمها
function hhCompressImage(file, maxDim = 1000, quality = 0.75){
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        // حساب الأبعاد الجديدة (الحفاظ على النسبة)
        let width = img.width;
        let height = img.height;
        
        if(width > maxDim || height > maxDim){
          if(width > height){
            height = Math.round(height * (maxDim / width));
            width = maxDim;
          } else {
            width = Math.round(width * (maxDim / height));
            height = maxDim;
          }
        }
        
        // رسم على canvas
        const canvas = document.createElement('canvas');
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        ctx.fillStyle = '#fff';
        ctx.fillRect(0, 0, width, height);
        ctx.drawImage(img, 0, 0, width, height);
        
        // تحويل إلى JPEG (أصغر حجماً من PNG)
        const dataUrl = canvas.toDataURL('image/jpeg', quality);
        resolve(dataUrl);
      };
      img.onerror = () => reject(new Error('فشل تحميل الصورة'));
      img.src = e.target.result;
    };
    reader.onerror = () => reject(new Error('فشل قراءة الملف'));
    reader.readAsDataURL(file);
  });
}

// إزالة الصورة
function hhRemoveQuestionImage(){
  document.getElementById('aq-image-data').value = '';
  document.getElementById('aq-image-preview').src = '';
  document.getElementById('aq-image-preview-wrap').style.display = 'none';
  document.getElementById('aq-image-upload-btn').style.display = 'inline-flex';
  const sz = document.getElementById('aq-image-size');
  if(sz) sz.textContent = '';
}

// إلغاء النموذج
function hhCancelAQForm(){
  document.getElementById('aq-add-form').style.display = 'none';
  hhRemoveQuestionImage();
}

