function hhCloseBulkImport(){
  const modal = document.getElementById('hh-bulk-modal');
  if(modal) modal.remove();
}

function hhUpdateBulkCounter(){
  const text = document.getElementById('hh-bulk-text')?.value || '';
  const lines = text.split('\n').filter(l => l.trim());
  const counter = document.getElementById('hh-bulk-counter');
  if(counter){
    counter.textContent = lines.length > 0 ? `${lines.length} سطر · جاهز للاستيراد` : 'جاهز للاستيراد · اكتب أو الصق الأسئلة';
  }
}

function hhInsertBulkTemplate(type){
  const ta = document.getElementById('hh-bulk-text');
  if(!ta) return;
  if(type === 'clear'){
    ta.value = '';
    hhUpdateBulkCounter();
    document.getElementById('hh-bulk-preview').style.display = 'none';
    return;
  }
  if(type === 'sample'){
    ta.value = `easy | ما عاصمة دولة قطر؟ | الدوحة
easy | ما هو الطائر الوطني لقطر؟ | الصقر
med | متى تأسس مجلس التعاون الخليجي؟ | 1981م
med | من مؤسس قطر الحديثة؟ | الشيخ جاسم بن محمد
hard | في أي سنة سُجلت الزبارة في اليونسكو؟ | 2013م
hard | الجد الأكبر الذي تنسب إليه أسرة آل ثاني؟ | ثاني بن محمد`;
    hhUpdateBulkCounter();
  }
}

function hhParseBulkText(text){
  const lines = text.split('\n').map(l => l.trim()).filter(l => l);
  const valid = [];
  const errors = [];
  
  lines.forEach((line, idx) => {
    // نقبل | أو ، أو tab كفواصل
    const parts = line.split(/\s*[\|،\t]\s*/).map(p => p.trim());
    if(parts.length !== 3){
      errors.push({ line: idx+1, text: line, reason: 'يجب أن يحتوي السطر على 3 أجزاء (المستوى | السؤال | الجواب)' });
      return;
    }
    let [diff, q, a] = parts;
    diff = diff.toLowerCase();
    // نقبل اختصارات بالعربية
    if(diff === 'سهل' || diff === '200') diff = 'easy';
    else if(diff === 'متوسط' || diff === '400') diff = 'med';
    else if(diff === 'صعب' || diff === '600') diff = 'hard';
    
    if(!['easy','med','hard'].includes(diff)){
      errors.push({ line: idx+1, text: line, reason: 'المستوى يجب أن يكون: easy / med / hard' });
      return;
    }
    if(!q || !a){
      errors.push({ line: idx+1, text: line, reason: 'السؤال أو الجواب فارغ' });
      return;
    }
    valid.push({ diff, q, a });
  });
  
  return { valid, errors };
}

function hhBulkPreview(){
  const text = document.getElementById('hh-bulk-text')?.value || '';
  if(!text.trim()){
    if(typeof toast === 'function') toast('ما فيه أسئلة للمعاينة', 'warn');
    return;
  }
  
  const { valid, errors } = hhParseBulkText(text);
  const preview = document.getElementById('hh-bulk-preview');
  
  let stats = { easy:0, med:0, hard:0 };
  valid.forEach(q => stats[q.diff]++);
  
  let html = `
    <div style="font-family:Cairo;font-weight:900;color:#8A1538;margin-bottom:10px;border-bottom:2px solid #B8924A;padding-bottom:6px;">نتيجة المعاينة:</div>
    <div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px;">
      <div style="background:#3D6B53;color:#fff;padding:4px 12px;border-radius:8px;font-weight:900;font-size:.85rem;"> سهل: ${stats.easy}</div>
      <div style="background:#B8924A;color:#fff;padding:4px 12px;border-radius:8px;font-weight:900;font-size:.85rem;"> متوسط: ${stats.med}</div>
      <div style="background:#8A1538;color:#fff;padding:4px 12px;border-radius:8px;font-weight:900;font-size:.85rem;"> صعب: ${stats.hard}</div>
      <div style="background:#1E3A5F;color:#fff;padding:4px 12px;border-radius:8px;font-weight:900;font-size:.85rem;">المجموع: ${valid.length}</div> ${errors.length ? `<div style="background:#c0392b;color:#fff;padding:4px 12px;border-radius:8px;font-weight:900;font-size:.85rem;">أخطاء: ${errors.length}</div>` : ''}
    </div> `;
  
  if(errors.length){
    html += '<div style="font-family:Cairo;font-weight:900;color:#c0392b;margin-top:10px;margin-bottom:6px;">أسطر فيها مشاكل:</div>';
    errors.slice(0, 5).forEach(e => {
      html += `<div style="background:#fdf0f0;border-right:3px solid #c0392b;padding:6px 10px;margin-bottom:4px;border-radius:6px;font-size:.78rem;color:#5E0E26;"><strong>السطر ${e.line}:</strong> ${esc(e.reason)}<br><span style="opacity:.7;font-family:monospace;">${esc(e.text.substring(0,80))}</span></div>`;
    });
    if(errors.length > 5) html += `<div style="font-size:.78rem;color:#c0392b;margin-top:4px;">... و ${errors.length - 5} خطأ آخر</div>`;
  }
  
  if(valid.length > 0){
    html += `<div style="font-family:Cairo;font-weight:900;color:#3D6B53;margin-top:10px;margin-bottom:6px;">معاينة أول 3 أسئلة صحيحة:</div>`;
    valid.slice(0,3).forEach(q => {
      const diffLabel = q.diff === 'easy' ? ' سهل' : q.diff === 'med' ? ' متوسط' : ' صعب';
      html += `<div style="background:#fff;border-right:3px solid #B8924A;padding:6px 10px;margin-bottom:4px;border-radius:6px;font-size:.82rem;">
        <strong style="color:#8A1538;">${diffLabel}:</strong> ${esc(q.q)} <span style="color:#3D6B53;font-weight:900;">→ ${esc(q.a)}</span>
      </div>`;
    });
  }
  
  preview.innerHTML = html;
  preview.style.display = 'block';
  preview.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}

async function hhBulkImport(){
  if(!_aqCurrentCat){
    if(typeof toast === 'function') toast('اختر فئة أولاً', 'warn');
    return;
  }
  
  const text = document.getElementById('hh-bulk-text')?.value || '';
  if(!text.trim()){
    if(typeof toast === 'function') toast('ما فيه أسئلة للاستيراد', 'warn');
    return;
  }
  
  const { valid, errors } = hhParseBulkText(text);
  
  if(!valid.length){
    if(typeof toast === 'function') toast('لا توجد أسئلة صحيحة للاستيراد', 'error');
    return;
  }
  
  let confirmMsg = `سيتم استيراد ${valid.length} سؤال إلى فئة "${_aqCurrentCat}"`;
  if(errors.length) confirmMsg += `\nسيتم تجاهل ${errors.length} سطر يحتوي على أخطاء`;
  confirmMsg += '\n\nهل تريد المتابعة؟';
  
  if(!confirm(confirmMsg)) return;
  
  try{
    if(!QDB[_aqCurrentCat]) QDB[_aqCurrentCat] = [];
    
    let added = 0;
    valid.forEach(q => {
      QDB[_aqCurrentCat].push({ diff: q.diff, q: q.q, a: q.a });
      added++;
    });
    
    // حفظ
    if(typeof saveQDBToCloud === 'function'){
      await saveQDBToCloud();
    }
    
    // إعادة تحميل القائمة
    if(typeof loadAdminCatQuestions === 'function') loadAdminCatQuestions();
    
    hhCloseBulkImport();
    
    if(typeof toast === 'function'){
      toast(`تم استيراد ${added} سؤال بنجاح إلى "${_aqCurrentCat}"`, 'success');
    }
    // تتبع الإنجازات
    if(window.hhTrackActivity){
      hhTrackActivity('bulk_import');
      for(let i=0;i<added;i++) hhTrackActivity('question_added');
    }
    
  }catch(e){
    console.error('خطأ في الاستيراد:', e);
    if(typeof toast === 'function') toast('تعذر الاستيراد: ' + e.message, 'error');
  }
}

// ═══════════════════════════════════════════════════════════
//  تعديل اسم الفئة (يحدث جميع الهياكل المرتبطة)
// ═══════════════════════════════════════════════════════════
window.hhRenameCurrentCategory = function(){
  if(!_aqCurrentCat){ toast('اختر فئة أولا','warn'); return; }
  
  // فئات الخرائط لا يمكن إعادة تسميتها (مرتبطة بملفات .js منفصلة)
  const _HH_PROTECTED = new Set(['خرائط الدول','أساطير الخرائط']);
  if(_HH_PROTECTED.has(_aqCurrentCat)){
    toast('لا يمكن تعديل اسم فئات الخرائط (مرتبطة بملفات منفصلة)','warn');
    return;
  }
  
  const oldName = _aqCurrentCat;
  const newName = prompt('الاسم الجديد للفئة:\n(الاسم الحالي: "'+oldName+'")', oldName);
  
  if(newName === null) return; // المستخدم ضغط إلغاء
  const trimmed = (newName || '').trim();
  if(!trimmed){ toast('الاسم لا يمكن أن يكون فارغا','error'); return; }
  if(trimmed === oldName){ toast('لم يتغير شيء','info'); return; }
  if(QDB[trimmed]){ toast('يوجد فئة بهذا الاسم بالفعل: '+trimmed,'error'); return; }
  
  // تأكيد نهائي
  if(!confirm('سيتم تعديل اسم الفئة:\n\n"'+oldName+'"\n→\n"'+trimmed+'"\n\nهل أنت متأكد؟')) return;
  
  try{
    // 1) نقل الأسئلة في QDB
    QDB[trimmed] = QDB[oldName];
    delete QDB[oldName];
    
    // 2) نقل CAT_INFO
    if(typeof CAT_INFO !== 'undefined' && CAT_INFO[oldName]){
      CAT_INFO[trimmed] = CAT_INFO[oldName];
      // تحديث الـ label أيضا ليطابق الاسم الجديد
      if(CAT_INFO[trimmed].label === oldName){
        CAT_INFO[trimmed].label = trimmed;
      }
      delete CAT_INFO[oldName];
    }
    
    // 3) نقل CAT_SVG
    if(typeof CAT_SVG !== 'undefined' && CAT_SVG[oldName]){
      CAT_SVG[trimmed] = CAT_SVG[oldName];
      delete CAT_SVG[oldName];
    }
    
    // 4) تحديث المراجع داخل CAT_GROUPS
    if(typeof CAT_GROUPS !== 'undefined' && Array.isArray(CAT_GROUPS)){
      CAT_GROUPS.forEach(group => {
        if(Array.isArray(group.cats)){
          const idx = group.cats.indexOf(oldName);
          if(idx >= 0){
            group.cats[idx] = trimmed;
          }
        }
      });
    }
    
    // 5) تحديث الفئات المخصصة في localStorage إن كان متعلقا
    try{
      const customCats = JSON.parse(localStorage.getItem('hh_custom_cats')||'{}');
      if(customCats[oldName]){
        customCats[trimmed] = customCats[oldName];
        delete customCats[oldName];
        localStorage.setItem('hh_custom_cats', JSON.stringify(customCats));
      }
    }catch(e){ /* تجاهل */ }
    
    // 6) تحديث المتغير الحالي وإعادة تحميل القائمة
    _aqCurrentCat = trimmed;
    
    // 7) تحديث dropdown الفئات
    const sel = document.getElementById('aq-cat-select');
    if(sel){
      const opts = sel.querySelectorAll('option');
      opts.forEach(opt => {
        if(opt.value === oldName){
          opt.value = trimmed;
          opt.textContent = trimmed;
        }
      });
      sel.value = trimmed;
    }
    
    // 8) حفظ في السحابة (يصل لكل المستخدمين)
    saveQDBToCloud();
    
    // 9) إعادة تحميل القائمة
    loadAdminCatQuestions();
    
    toast('✓ تم تعديل اسم الفئة بنجاح','success');
  }catch(e){
    console.error('rename category error:', e);
    toast('حدث خطأ أثناء التعديل: '+(e.message||''),'error');
  }
};

function editAdminQuestion(idx){
  if(!_aqCurrentCat){ toast('اختر فئة أولا','warn'); return; }
  const q = QDB[_aqCurrentCat] && QDB[_aqCurrentCat][idx];
  if(!q){ toast('السؤال غير موجود','error'); return; }
  
  // ملء النموذج
  document.getElementById('aq-edit-idx').value = idx;
  document.getElementById('aq-question-text').value = q.q || '';
  document.getElementById('aq-answer-text').value = q.a || '';
  setAQDiff(q.diff);
  
  // ملء الصورة إن كانت موجودة
  if(q.img){
    document.getElementById('aq-image-data').value = q.img;
    document.getElementById('aq-image-preview').src = q.img;
    document.getElementById('aq-image-preview-wrap').style.display = 'block';
    document.getElementById('aq-image-upload-btn').style.display = 'none';
    const sizeKB = Math.round(q.img.length * 0.75 / 1024);
    document.getElementById('aq-image-size').textContent = sizeKB + ' KB';
  } else {
    hhRemoveQuestionImage();
  }
  
  // إظهار النموذج + scroll إليه + تمييز بصري
  const form = document.getElementById('aq-add-form');
  if(form){
    form.style.display = 'block';
    // scroll smooth إلى النموذج
    setTimeout(()=>{
      form.scrollIntoView({behavior:'smooth', block:'center'});
      // تأثير تمييز برتقالي مؤقت
      form.style.transition = 'box-shadow .3s ease, background .3s ease';
      form.style.boxShadow = '0 0 0 3px #B8924A, 0 8px 22px rgba(184,146,74,.4)';
      form.style.background = '#F8F8F6';
      setTimeout(()=>{
        form.style.boxShadow = '';
        form.style.background = '';
        // focus على حقل السؤال
        const qInput = document.getElementById('aq-question-text');
        if(qInput){ qInput.focus(); qInput.select(); }
      }, 1000);
    }, 80);
  }
  
  toast('عدل السؤال ثم اضغط حفظ','info');
}

function deleteAdminQuestion(idx){
  if(!_aqCurrentCat) return;
  if(typeof _hhIsRestrictedPartner === 'function' && _hhIsRestrictedPartner()){
    const allowed = _hhGetPartnerEditableCats(currentUser && currentUser.email);
    if(allowed.indexOf(_aqCurrentCat) === -1){ toast('لا تملك صلاحية تعديل هذه الفئة','error'); return; }
  }
  const q = QDB[_aqCurrentCat][idx];
  if(!confirm('حذف هذا السؤال؟\n"'+q.q+'"')) return;
  QDB[_aqCurrentCat].splice(idx, 1);
  saveAdminQuestion_persist(_aqCurrentCat);
  loadAdminCatQuestions();
  toast('تم حذف السؤال', 'info');
}

function saveAdminQuestion(){
  if(!_aqCurrentCat){ toast('اختر فئة أولا','warn'); return; }
  // حاجز أمني: الشريك المقيّد يعدّل فئاته فقط
  if(typeof _hhIsRestrictedPartner === 'function' && _hhIsRestrictedPartner()){
    const allowed = _hhGetPartnerEditableCats(currentUser && currentUser.email);
    if(allowed.indexOf(_aqCurrentCat) === -1){ toast('لا تملك صلاحية تعديل هذه الفئة','error'); return; }
  }
  const qText = document.getElementById('aq-question-text').value.trim();
  const aText = document.getElementById('aq-answer-text').value.trim();
  const imgData = document.getElementById('aq-image-data').value || '';
  if(!qText||!aText){ toast('السؤال والجواب مطلوبان','warn'); return; }
  const editIdx = document.getElementById('aq-edit-idx').value;
  const newQ = {diff:_aqCurrentDiff, q:qText, a:aText};
  // إضافة الصورة إن وجدت
  if(imgData) newQ.img = imgData;
  if(editIdx !== ''){
    QDB[_aqCurrentCat][parseInt(editIdx)] = newQ;
    toast('تم تعديل السؤال','info');
  } else {
    if(!QDB[_aqCurrentCat]) QDB[_aqCurrentCat] = [];
    QDB[_aqCurrentCat].push(newQ);
    toast('تم إضافة السؤال','info');
    // تتبع الإنجازات
    if(window.hhTrackActivity){
      hhTrackActivity('question_added');
      if(imgData) hhTrackActivity('image_question');
    }
  }
  saveAdminQuestion_persist(_aqCurrentCat);
  document.getElementById('aq-add-form').style.display = 'none';
  hhRemoveQuestionImage();
  loadAdminCatQuestions();
}

// يقرر أين تُحفظ التعديلات: الفئات الخارجية → طبقة overrides، الباقي → QDB العادية
function saveAdminQuestion_persist(cat){
  if(_hhIsExternalCat(cat)){
    _hhSaveExtCatOverride(cat);
  } else {
    saveQDBToCloud();
  }
}

// حفظ QDB محليا (localStorage) + إشارة في Firestore
async function saveQDBToCloud(){
  // 1) الحفظ المحلي · يشتغل فورا دائما (نسخة احتياطية على جهاز الأدمن)
  const savedLocally = _saveQDB();
  if(savedLocally){
    _updateQDBStatusBanner();
  }

  // 2) الحفظ في Firestore · هذا هو ما يجعل التعديلات تظهر لكل المستخدمين
  if(OFFLINE_MODE||!db||!isAdminUser()){
    if(typeof toast === 'function') toast('تم الحفظ محليا فقط (لن يصل للمستخدمين)','warn');
    return savedLocally;
  }
  
  try{
    // نستثني فئات الخرائط الكبيرة (تأتي من ملفات .js منفصلة)
    const _HH_EXTERNAL_CATS = new Set(['خرائط الدول', 'أساطير الخرائط', 'أعلام الدول', 'عواصم الدول', 'بيرف آب · ثقافة قطرية', 'بيرف آب · معلومات دينية', 'بيرف آب · رياضة', 'بيرف آب · مسابقات وألغاز', 'بيرف آب · دول وعواصم', 'بيرف آب · معلومات عامة', 'طموح · ثقافة قطرية', 'طموح · معلومات دينية', 'طموح · رياضة', 'طموح · مسابقات وألغاز', 'طموح · دول وعواصم', 'طموح · معلومات عامة', 'المهني · قنوان', 'القرآني · قنوان', 'الترفيهي · قنوان', 'الاستكشافي · قنوان', 'الهوية · قنوان', 'الأمني · قنوان', 'الرياضي · قنوان', 'ثقافة عامة · قنوان', 'مسابقة أجيال في القرآن الكريم', 'مسابقة مركز أجيال التربوي - يوم الوفاء', 'مسابقة مركز أجيال التربوي', 'مسابقة مركز أجيال التربوي - اليوم الأمني', 'مسابقة مركز أجيال التربوي - ثقافة العمل التطوعي', 'مسابقة بيرف آب - الحفل الختامي', 'مسابقة الشباب']);
    const slim = {};
    for(const cat in QDB){
      if(_HH_EXTERNAL_CATS.has(cat)) continue;
      slim[cat] = QDB[cat];
    }
    
    // نقسم الفئات على مستندات منفصلة لتجنب حد Firestore (1MB لكل مستند)
    // كل مستند يحوي مجموعة من الفئات
    const allCats = Object.keys(slim);
    const CHUNK_SIZE = 5; // 5 فئات لكل مستند
    const chunks = [];
    for(let i=0; i<allCats.length; i+=CHUNK_SIZE){
      const chunkCats = allCats.slice(i, i+CHUNK_SIZE);
      const chunkData = {};
      chunkCats.forEach(c => { chunkData[c] = slim[c]; });
      chunks.push(chunkData);
    }
    
    // حفظ كل chunk في مستند منفصل
    const batch = db.batch();
    for(let i=0; i<chunks.length; i++){
      const ref = db.collection('admin_qdb').doc('chunk_'+i);
      batch.set(ref, {
        data: JSON.stringify(chunks[i]),
        index: i,
        updatedAt: firebase.firestore.FieldValue.serverTimestamp()
      });
    }
    
    // ميتاداتا (لمعرفة عدد الـchunks وآخر تحديث)
    const metaRef = db.collection('admin_qdb').doc('meta');
    batch.set(metaRef, {
      totalChunks: chunks.length,
      totalCats: allCats.length,
      updatedAt: firebase.firestore.FieldValue.serverTimestamp(),
      updatedBy: currentUser.email
    });
    
    await batch.commit();
    
    // إشارة لإجبار العملاء الآخرين على إعادة التحميل
    await db.collection('admin').doc('qdb_version').set({
      version: Date.now(),
      updatedAt: firebase.firestore.FieldValue.serverTimestamp(),
      updatedBy: currentUser.email
    },{merge:true});
    
    if(typeof toast === 'function') toast('✓ تم الحفظ · التعديل متاح لكل المستخدمين','success');
    return true;
  }catch(e){
    console.error('saveQDB cloud error:', e);
    if(typeof toast === 'function') toast('فشل الحفظ السحابي: '+(e.message||'خطأ'),'error');
    return savedLocally;
  }
}

// تحميل QDB من Firestore · تستدعى عند فتح الموقع
async function loadQDBFromCloud(){
  if(OFFLINE_MODE||!db) return false;
  try{
    // 1) نقرأ الميتا
    const metaSnap = await db.collection('admin_qdb').doc('meta').get();
    if(!metaSnap.exists){
      return false;
    }
    const meta = metaSnap.data();
    const totalChunks = meta.totalChunks || 0;
    if(totalChunks === 0) return false;
    
    // 2) نقرأ كل الـchunks بالتوازي
    const chunkPromises = [];
    for(let i=0; i<totalChunks; i++){
      chunkPromises.push(db.collection('admin_qdb').doc('chunk_'+i).get());
    }
    const chunkSnaps = await Promise.all(chunkPromises);
    
    // 3) ندمج البيانات
    const cloudQDB = {};
    chunkSnaps.forEach(snap => {
      if(snap.exists){
        try{
          const chunkData = JSON.parse(snap.data().data || '{}');
          for(const cat in chunkData){
            cloudQDB[cat] = chunkData[cat];
          }
        }catch(e){ console.warn('chunk parse error:', e); }
      }
    });
    
    if(Object.keys(cloudQDB).length === 0) return false;
    
    // 4) ندمج مع QDB_ORIGINAL (الذي يحوي الخرائط) · بدون استبدال الخرائط/الأعلام/العواصم
    const merged = JSON.parse(JSON.stringify(QDB_ORIGINAL));
    const _EXT_CATS = new Set(['خرائط الدول','أساطير الخرائط','أعلام الدول','عواصم الدول', 'بيرف آب · ثقافة قطرية', 'بيرف آب · معلومات دينية', 'بيرف آب · رياضة', 'بيرف آب · مسابقات وألغاز', 'بيرف آب · دول وعواصم', 'بيرف آب · معلومات عامة', 'طموح · ثقافة قطرية', 'طموح · معلومات دينية', 'طموح · رياضة', 'طموح · مسابقات وألغاز', 'طموح · دول وعواصم', 'طموح · معلومات عامة', 'المهني · قنوان', 'القرآني · قنوان', 'الترفيهي · قنوان', 'الاستكشافي · قنوان', 'الهوية · قنوان', 'الأمني · قنوان', 'الرياضي · قنوان', 'ثقافة عامة · قنوان', 'مسابقة أجيال في القرآن الكريم', 'مسابقة مركز أجيال التربوي - يوم الوفاء', 'مسابقة مركز أجيال التربوي', 'مسابقة مركز أجيال التربوي - اليوم الأمني', 'مسابقة مركز أجيال التربوي - ثقافة العمل التطوعي', 'مسابقة بيرف آب - الحفل الختامي', 'مسابقة الشباب']);
    for(const cat in cloudQDB){
      if(_EXT_CATS.has(cat)) continue; // لا نسمح للسحابة بالكتابة فوق فئات الملفات الخارجية
      merged[cat] = cloudQDB[cat];
    }
    
    // نطبّق طبقة تعديلات الفئات الخارجية (الخرائط/الأعلام/...) فوق الأصل
    _hhApplyExtOverrides(merged);
    
    QDB = merged;

    //  ضمان أسئلة الشركاء (أجيال + بيرف آب + طموح) بعد المزامنة السحابية
    //   المزامنة تبني QDB من QDB_ORIGINAL الذي قد لا يحوي أسئلة الشركاء · فنحقنها من المصدر الموثوق
    try{
      if(typeof _HH_PARTNER_QUESTIONS === 'object' && _HH_PARTNER_QUESTIONS){
        for(var _pc3 in _HH_PARTNER_QUESTIONS){
          if(!Array.isArray(QDB[_pc3]) || QDB[_pc3].length === 0){
            QDB[_pc3] = JSON.parse(JSON.stringify(_HH_PARTNER_QUESTIONS[_pc3]));
          }
        }
      }
    }catch(_e3){ console.warn('partner qs inject (cloud):', _e3); }
    
    // 5) نحفظ نسخة محلية (cache)
    try{
      const _HH_EXT = new Set(['خرائط الدول','أساطير الخرائط','أعلام الدول','عواصم الدول', 'بيرف آب · ثقافة قطرية', 'بيرف آب · معلومات دينية', 'بيرف آب · رياضة', 'بيرف آب · مسابقات وألغاز', 'بيرف آب · دول وعواصم', 'بيرف آب · معلومات عامة', 'طموح · ثقافة قطرية', 'طموح · معلومات دينية', 'طموح · رياضة', 'طموح · مسابقات وألغاز', 'طموح · دول وعواصم', 'طموح · معلومات عامة', 'المهني · قنوان', 'القرآني · قنوان', 'الترفيهي · قنوان', 'الاستكشافي · قنوان', 'الهوية · قنوان', 'الأمني · قنوان', 'الرياضي · قنوان', 'ثقافة عامة · قنوان', 'مسابقة أجيال في القرآن الكريم', 'مسابقة مركز أجيال التربوي - يوم الوفاء', 'مسابقة مركز أجيال التربوي', 'مسابقة مركز أجيال التربوي - اليوم الأمني', 'مسابقة مركز أجيال التربوي - ثقافة العمل التطوعي', 'مسابقة بيرف آب - الحفل الختامي', 'مسابقة الشباب']);
      const slim = {};
      for(const c in cloudQDB){ if(!_HH_EXT.has(c)) slim[c] = cloudQDB[c]; }
      localStorage.setItem('hh_qdb_override', JSON.stringify(slim));
      localStorage.setItem('hh_qdb_modified_at', Date.now().toString());
    }catch(e){}
    
    return true;
  }catch(e){
    console.error('loadQDB cloud error:', e);
    return false;
  }
}

/**
 * تحديث شريط حالة QDB (يوضح إذا فيه تعديلات محلية)
 */
function _updateQDBStatusBanner(){
  const statusText = document.getElementById('qdb-status-text');
  const resetBtn = document.getElementById('qdb-reset-btn');
  const banner = document.getElementById('qdb-status-banner');
  if(!statusText) return;

  const modifiedAt = localStorage.getItem('hh_qdb_modified_at');
  if(modifiedAt){
    const d = new Date(parseInt(modifiedAt));
    const dateStr = d.toLocaleDateString('ar-QA',{month:'short',day:'numeric'}) + ' · ' + d.toLocaleTimeString('ar-QA',{hour:'2-digit',minute:'2-digit'});
    statusText.innerHTML = '<strong>فيه تعديلات محلية</strong> · آخر حفظ: ' + dateStr;
    if(banner){
      banner.style.background = 'linear-gradient(135deg,#f0e5b8,#fdfaf0)';
      banner.style.borderColor = '#B8924A';
      banner.style.borderRightColor = '#B8924A';
    }
    if(resetBtn) resetBtn.style.display = 'inline-flex';
  } else {
    statusText.textContent = 'لا يوجد تعديلات محلية · الأسئلة الأصلية';
    if(banner){
      banner.style.background = 'linear-gradient(135deg,#e8f2ec,#fff)';
      banner.style.borderColor = '#8A1538';
      banner.style.borderRightColor = '#8A1538';
    }
    if(resetBtn) resetBtn.style.display = 'none';
  }
}

/**
 * تأكيد وإعادة التعيين
 */
function confirmResetQDB(){
  const confirmMsg = 'إعادة تعيين الأسئلة؟\n\n' +
    'سيتم حذف جميع التعديلات المحلية على الأسئلة (إضافة/حذف/تعديل) والعودة للأسئلة الأصلية في الملف.\n\n' +
    'هذه العملية لا يمكن التراجع عنها.\n\n' +
    'هل تريد المتابعة؟';
  if(!confirm(confirmMsg)) return;
  if(!confirm('تأكيد نهائي: حذف التعديلات المحلية والعودة للأصل؟')) return;

  _resetQDB();
  _updateQDBStatusBanner();

  // إعادة تحميل قائمة الأسئلة للفئة الحالية
  loadAdminCatQuestions();
  // إعادة تعبئة القائمة المنسدلة
  populateAQCatSelect();
  toast('تمت إعادة التعيين للأسئلة الأصلية', 'success');
}

// ════ إدارة الصلاحيات ════
async function loadPermissionsPanel(){
  const listEl = document.getElementById('admin-permissions-list');
  if(!listEl||!db) return;
  listEl.innerHTML = '<div style="text-align:center;padding:20px;color:#aaa;font-family:Cairo;">جاري التحميل…</div>';
  try{
    const [snap, tSnap] = await Promise.all([
      db.collection('users').orderBy('name').get(),
      db.collection('teacher_requests').get().catch(()=>null)
    ]);
    const teachers = {};
    if(tSnap) tSnap.docs.forEach(d=>{ teachers[d.id] = (d.data()||{}).status || ''; });
    const users = snap.docs.map(d=>({id:d.id,...d.data()}));
    window._hhPermUsers = users; window._hhPermTeachers = teachers;
    const editors  = users.filter(u=>u.canEditQuestions===true).length;
    const partners = users.filter(u=>u.canViewPartners===true).length;
    const approved = users.filter(u=>teachers[u.id]==='approved').length;

    listEl.innerHTML =
      '<div style="background:linear-gradient(170deg,#4A0B1E,#5E0E26);border:2px solid #B8924A;border-radius:16px;padding:14px 16px;margin-bottom:12px;font-family:Cairo;color:#F5E6C4;">'
      + '<div style="font-weight:900;font-size:1rem;margin-bottom:8px;">الصلاحيات الفعالة في المنصة</div>'
      + '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:8px;">'
      +   '<div style="background:rgba(255,253,248,.07);border:1px solid rgba(212,188,133,.4);border-radius:10px;padding:8px;text-align:center;"><div style="font-size:1.35rem;font-weight:900;">'+users.length+'</div><div style="font-size:.7rem;color:#EAD9B0;">المستخدمون</div></div>'
      +   '<div style="background:rgba(255,253,248,.07);border:1px solid rgba(212,188,133,.4);border-radius:10px;padding:8px;text-align:center;"><div style="font-size:1.35rem;font-weight:900;">'+editors+'</div><div style="font-size:.7rem;color:#EAD9B0;">محررو الأسئلة</div></div>'
      +   '<div style="background:rgba(255,253,248,.07);border:1px solid rgba(212,188,133,.4);border-radius:10px;padding:8px;text-align:center;"><div style="font-size:1.35rem;font-weight:900;">'+partners+'</div><div style="font-size:.7rem;color:#EAD9B0;">رؤية الشركاء</div></div>'
      +   '<div style="background:rgba(255,253,248,.07);border:1px solid rgba(212,188,133,.4);border-radius:10px;padding:8px;text-align:center;"><div style="font-size:1.35rem;font-weight:900;">'+approved+'</div><div style="font-size:.7rem;color:#EAD9B0;">معلمون معتمدون</div></div>'
      + '</div>'
      + '<div style="font-size:.72rem;color:#EAD9B0;margin-top:8px;line-height:1.7;">الصلاحيتان المتاحتان: <b>تعديل الأسئلة</b> (يظهر للمستخدم زر التحرير في الفئات) و<b>رؤية شركاء النجاح</b>. اعتماد المعلمين يُدار من تبويب «المعلمون»، وإخفاء الفئات والمسابقات من «إدارة المسابقات» و«الفئات».</div>'
      + '</div>'
      + '<input id="perm-search" placeholder="ابحث بالاسم أو البريد…" oninput="renderPermList(this.value)" style="width:100%;box-sizing:border-box;padding:10px 14px;border:1.5px solid #B8924A;border-radius:12px;font-family:Cairo;font-weight:800;font-size:.85rem;margin-bottom:10px;background:#FFFDF8;">'
      + '<div id="perm-rows"></div>';
    renderPermList('');
  }catch(e){
    listEl.innerHTML = '<p style="color:#c00;text-align:center;padding:20px;font-family:Cairo;">تعذر التحميل: '+esc(e.message||'')+'</p>';
  }
}

function renderPermList(q){
  const rows = document.getElementById('perm-rows'); if(!rows) return;
  const users = window._hhPermUsers||[]; const teachers = window._hhPermTeachers||{};
  q = (q||'').trim().toLowerCase();
  const list = users.filter(u=>!q || (u.name||'').toLowerCase().includes(q) || (u.email||'').toLowerCase().includes(q));
  const permRow=(u,field,label,desc,val)=>{
    return '<div style="display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;">'
      + '<div style="flex:1;min-width:150px;"><div style="font-size:.8rem;font-weight:900;color:#3D0918;">'+label+'</div><div style="font-size:.66rem;color:#8A7A63;font-weight:700;">'+desc+'</div></div>'
      + '<div onclick="toggleUserPerm(\''+escAttr(u.id)+'\',\''+field+'\','+val+',\''+escAttr(u.name||'')+'\',\''+label+'\')" title="'+(val?'إلغاء':'منح')+'" style="width:48px;height:26px;border-radius:99px;background:'+(val?'#B8924A':'#d8cfd3')+';position:relative;cursor:pointer;flex-shrink:0;transition:background .2s;">'
      +   '<i style="position:absolute;top:3px;'+(val?'right:3px;':'right:25px;')+'width:20px;height:20px;border-radius:50%;background:#fff;box-shadow:0 1px 3px rgba(0,0,0,.25);"></i>'
      + '</div></div>';
  };
  rows.innerHTML = list.map(u=>{
    const isAdmin = u.email === SUPER_ADMIN_EMAIL;
    const tStatus = teachers[u.id];
    const chips = []
    if(isAdmin) chips.push('<span style="font-size:.68rem;background:linear-gradient(135deg,#8A1538,#5E0E26);color:#F5E6C4;border:1px solid #B8924A;border-radius:99px;padding:3px 12px;font-weight:900;">مدير عام</span>');
    if(tStatus==='approved') chips.push('<span style="font-size:.68rem;background:#EBF2EE;color:#3D6B53;border:1px solid #3D6B53;border-radius:99px;padding:3px 12px;font-weight:900;">معلم معتمد</span>');
    else if(tStatus==='pending') chips.push('<span style="font-size:.68rem;background:#FDF3DD;color:#8A6D2E;border:1px solid #B8924A;border-radius:99px;padding:3px 12px;font-weight:900;">طلب اعتماد معلق</span>');
    return '<div style="background:#FFFDF8;border:1.5px solid #B8924A;border-radius:14px;padding:12px 14px;margin-bottom:10px;font-family:Cairo;">'
      + '<div style="display:flex;align-items:center;gap:10px;'+(isAdmin?'':'margin-bottom:10px;')+'">'
      +   '<div style="width:38px;height:38px;border-radius:50%;background:linear-gradient(135deg,#8A1538,#5E0E26);border:2px solid #B8924A;color:#F5E6C4;display:flex;align-items:center;justify-content:center;font-weight:900;flex-shrink:0;">'+esc((u.name||'؟').trim().charAt(0))+'</div>'
      +   '<div style="flex:1;min-width:0;"><div style="font-weight:900;font-size:.9rem;color:#3D0918;">'+esc(u.name||'بدون اسم')+'</div><div style="font-size:.7rem;color:#8A7A63;direction:ltr;text-align:right;">'+esc(u.email||'')+'</div></div>'
      +   chips.join(' ')
      + '</div>'
      + (isAdmin ? '' :
        '<div style="display:flex;flex-direction:column;gap:9px;padding-top:9px;border-top:1px dashed #EAD9B0;">'
        + permRow(u,'canEditQuestions','تعديل الأسئلة','يرى زر التحرير ويقترح تعديلات على بنوك الفئات', u.canEditQuestions===true)
        + permRow(u,'canViewPartners','رؤية شركاء النجاح','تظهر له فئات الشركاء في شاشة الإعداد', u.canViewPartners===true)
        + '</div>')
      + '</div>';
  }).join('') || '<p style="text-align:center;color:#8A7A63;padding:20px;font-family:Cairo;font-weight:800;">لا نتائج للبحث</p>';
}

async function toggleUserPerm(uid, field, currentVal, name, label){
  const newVal = !currentVal;
  const action = newVal ? 'منح' : 'إلغاء';
  if(!confirm(action + ' صلاحية "' + label + '" لـ "' + name + '"؟')) return;
  try{
    await db.collection('users').doc(uid).update({[field]: newVal});
    toast('تم ' + action + ' الصلاحية', 'success');
    loadPermissionsPanel();
    // تحديث الواجهة فورا لو المستخدم الحالي هو نفسه
    if(currentUser && currentUser.uid === uid && field === 'canViewPartners'){
      updatePartnersVisibility(currentUser);
    }
  }catch(e){ toast('خطأ: ' + e.message, 'error'); }
}

// دالة قديمة محفوظة للتوافق العكسي
async function toggleUserPermission(uid, currentVal, name){
  return toggleUserPerm(uid, 'canEditQuestions', currentVal, name, 'تعديل الأسئلة');
}
