function _hh_saveWhatsNew(arr){
  localStorage.setItem('hh_whatsnew', JSON.stringify(arr));
}
function _hh_genWnId(){ return 'wn_'+Date.now()+'_'+Math.random().toString(36).slice(2,8); }

// ─── واجهة الأدمن ───
function renderWhatsNewAdmin(){
  const list = document.getElementById('wn-list');
  if(!list) return;
  const items = _hh_getWhatsNew();
  if(items.length === 0){
    list.innerHTML = '<div style="background:#fff;border-radius:12px;padding:24px;text-align:center;color:#888;border:1.5px dashed #dce5ea;"><div style="font-size:1.6rem;margin-bottom:6px;"></div><div style="font-family:Cairo;font-weight:900;color:#8A1538;font-size:.92rem;">لا توجد تحديثات بعد</div><div style="font-size:.78rem;margin-top:4px;">أضف أول تحديث من النموذج أعلاه</div></div>';
    return;
  }
  // الأحدث أولا
  items.sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0));
  list.innerHTML = '';
  items.forEach(it => {
    const cat = WN_CATEGORIES[it.category] || WN_CATEGORIES.feature;
    const date = new Date(it.updatedAt||it.createdAt||Date.now()).toLocaleDateString('ar-EG', {year:'numeric', month:'short', day:'numeric'});
    const card = document.createElement('div');
    card.style.cssText = 'background:#fff;border:1.5px solid #ecf0f1;border-right:4px solid '+cat.color+';border-radius:10px;padding:12px;margin-bottom:8px;'+(it.published?'':'opacity:.55;');
    card.innerHTML = '' + '<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:10px;flex-wrap:wrap;">' +   '<div style="flex:1;min-width:160px;">' +     '<div style="display:flex;align-items:center;gap:6px;margin-bottom:4px;flex-wrap:wrap;">' +       '<span style="background:'+cat.bg+';color:'+cat.color+';padding:2px 8px;border-radius:8px;font-family:Cairo;font-weight:900;font-size:.68rem;">'+cat.icon+' '+cat.label+'</span>' +       (it.published?'':'<span style="background:#fde8e8;color:#c0392b;padding:2px 8px;border-radius:8px;font-family:Cairo;font-weight:900;font-size:.65rem;"> مسودة</span>')
      +       '<span style="font-size:.7rem;color:#888;">'+date+'</span>' +     '</div>' +     '<div style="font-family:Cairo;font-weight:900;color:#3D0918;font-size:.95rem;margin-bottom:3px;">'+esc(it.title||'')+'</div>' +     '<div style="font-size:.82rem;color:#555;line-height:1.6;">'+esc(it.desc||'')+'</div>' +     (it.link?'<div style="font-size:.72rem;color:#8A6D2E;margin-top:4px;"> '+esc(it.link)+'</div>':'')
      +   '</div>' +   '<div style="display:flex;flex-direction:column;gap:5px;flex-shrink:0;">' +     '<button onclick="editWhatsNew(\''+it.id+'\')" style="padding:6px 10px;background:#fff;color:#8A1538;border:1.5px solid #8A1538;border-radius:8px;font-family:Cairo;font-weight:900;font-size:.72rem;cursor:pointer;">تعديل</button>' +     '<button onclick="deleteWhatsNew(\''+it.id+'\')" style="padding:6px 10px;background:#fff;color:#c0392b;border:1.5px solid #c0392b;border-radius:8px;font-family:Cairo;font-weight:900;font-size:.72rem;cursor:pointer;">حذف</button>' +   '</div>' + '</div>';
    list.appendChild(card);
  });
}

function resetWhatsNewForm(){
  document.getElementById('wn-edit-id').value = '';
  document.getElementById('wn-title').value = '';
  document.getElementById('wn-desc').value = '';
  document.getElementById('wn-category').value = 'feature';
  document.getElementById('wn-link').value = '';
  document.getElementById('wn-published').checked = true;
  document.getElementById('wn-form-title').textContent = 'إضافة تحديث جديد';
  document.getElementById('wn-save-btn').textContent = 'حفظ التحديث';
}

function editWhatsNew(id){
  if(typeof isAdminUser==='function' && !isAdminUser(currentUser)){ toast('فقط المدير','error'); return; }
  const it = _hh_getWhatsNew().find(x=>x.id===id);
  if(!it) return;
  document.getElementById('wn-edit-id').value = it.id;
  document.getElementById('wn-title').value = it.title || '';
  document.getElementById('wn-desc').value = it.desc || '';
  document.getElementById('wn-category').value = it.category || 'feature';
  document.getElementById('wn-link').value = it.link || '';
  document.getElementById('wn-published').checked = !!it.published;
  document.getElementById('wn-form-title').textContent = 'تعديل التحديث';
  document.getElementById('wn-save-btn').textContent = 'حفظ التعديلات';
  // التمرير للأعلى
  document.getElementById('wn-title').scrollIntoView({behavior:'smooth', block:'center'});
}

function deleteWhatsNew(id){
  if(typeof isAdminUser==='function' && !isAdminUser(currentUser)){ toast('فقط المدير','error'); return; }
  const it = _hh_getWhatsNew().find(x=>x.id===id);
  if(!it) return;
  if(!confirm('حذف تحديث "'+(it.title||'')+'"؟ لا يمكن التراجع.')) return;
  const items = _hh_getWhatsNew().filter(x=>x.id!==id);
  _hh_saveWhatsNew(items);
  toast('تم حذف التحديث','info');
  renderWhatsNewAdmin();
}

function saveWhatsNew(){
  if(typeof isAdminUser==='function' && !isAdminUser(currentUser)){ toast('فقط المدير','error'); return; }
  const id = document.getElementById('wn-edit-id').value || _hh_genWnId();
  const title = (document.getElementById('wn-title').value||'').trim();
  if(!title){ toast('عنوان التحديث مطلوب','error'); return; }
  const desc = (document.getElementById('wn-desc').value||'').trim();
  const category = document.getElementById('wn-category').value || 'feature';
  const link = (document.getElementById('wn-link').value||'').trim();
  const published = document.getElementById('wn-published').checked;

  const items = _hh_getWhatsNew();
  const idx = items.findIndex(x=>x.id===id);
  const now = Date.now();
  const obj = {id, title, desc, category, link, published, updatedAt: now, createdAt: idx>=0?items[idx].createdAt:now};
  if(idx>=0) items[idx] = obj;
  else items.unshift(obj);
  _hh_saveWhatsNew(items);
  toast(idx>=0?'تم حفظ التعديلات':'تم إضافة التحديث','success');
  resetWhatsNewForm();
  renderWhatsNewAdmin();
  // تحديث الشارة فورا + إعادة تعيين حالة "آخر مشاهدة" ليرى الجميع التحديث الجديد
  if(published){
    try{ localStorage.removeItem('hh_wn_last_seen'); }catch(e){}
    if(typeof refreshWhatsNewBadge === 'function') refreshWhatsNewBadge();
  }
}

function previewWhatsNewModal(){
  showWhatsNewModal({force:true});
}

// ─── المودال للزوار ───
function _hh_buildWhatsNewItemHTML(it){
  const cat = WN_CATEGORIES[it.category] || WN_CATEGORIES.feature;
  const linkHTML = it.link ? '<a href="'+esc(it.link)+'" style="display:inline-block;margin-top:6px;color:#8A6D2E;font-weight:900;font-size:.82rem;text-decoration:none;border-bottom:1.5px dashed #B8924A;">جرب الآن ←</a>' : '';
  return '' + '<div style="background:#fff;border:1.5px solid #ecf0f1;border-right:4px solid '+cat.color+';border-radius:12px;padding:12px 14px;margin-bottom:10px;">' +   '<div style="display:flex;align-items:center;gap:6px;margin-bottom:6px;">' +     '<span style="background:'+cat.bg+';color:'+cat.color+';padding:2px 9px;border-radius:9px;font-family:Cairo;font-weight:900;font-size:.7rem;">'+cat.icon+' '+cat.label+'</span>' +   '</div>' +   '<div style="font-family:Cairo;font-weight:900;color:#3D0918;font-size:1rem;margin-bottom:4px;">'+esc(it.title||'')+'</div>' +   (it.desc?'<div style="font-size:.85rem;color:#555;line-height:1.7;">'+esc(it.desc)+'</div>':'')
    +   linkHTML
    + '</div>';
}

function showWhatsNewModal(opts){
  opts = opts || {};
  const all = _hh_getWhatsNew().filter(it => it.published);
  if(all.length === 0 && !opts.force) return;

  // ترتيب الأحدث أولا
  all.sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0));

  // التحقق من آخر معرف رآه المستخدم
  let lastSeenId = null;
  try{ lastSeenId = localStorage.getItem('hh_wn_last_seen') || null; }catch(e){}

  //  زائر لأول مرة: التحديثات قصة العائدين لا القادمين · نعلّمها كمقروءة بصمت ولا نعرض شيئاً
  if(!lastSeenId && !opts.force){
    try{ if(all.length > 0) localStorage.setItem('hh_wn_last_seen', all[0].id); }catch(e){}
    return;
  }

  // الجديد فقط (لم يره)
  let toShow = all;
  if(lastSeenId && !opts.force){
    const lastIdx = all.findIndex(it => it.id === lastSeenId);
    if(lastIdx === 0) return; // أحدث تحديث رآه مسبقا
    if(lastIdx > 0) toShow = all.slice(0, lastIdx);
  }

  // إذا opts.force نعرض الكل
  if(opts.force) toShow = all;

  if(toShow.length === 0 && !opts.force) return;
  if(opts.force && toShow.length === 0){
    toast('لا توجد تحديثات منشورة بعد','info');
    return;
  }

  // إنشاء المودال
  const old = document.getElementById('hh-whatsnew-modal');
  if(old) old.remove();
  const modal = document.createElement('div');
  modal.id = 'hh-whatsnew-modal';
  modal.style.cssText = 'position:fixed;inset:0;z-index:99997;background:rgba(10,20,40,.82);backdrop-filter:blur(6px);display:flex;align-items:center;justify-content:center;padding:16px;font-family:Tajawal,sans-serif;direction:rtl;animation:hh-wn-in .4s ease-out;';

  const itemsHTML = toShow.map(_hh_buildWhatsNewItemHTML).join('');
  const headerSubtitle = opts.force
    ? all.length.toLocaleString('en-US') + ' تحديث في المنصة' : (toShow.length>1 ? toShow.length.toLocaleString('en-US')+' تحديث جديد لك' : 'تحديث جديد لك');

  modal.innerHTML = '' + '<div style="background:#FAFAF8;max-width:560px;width:100%;max-height:88vh;border-radius:18px;overflow:hidden;box-shadow:0 25px 70px rgba(0,0,0,.55);display:flex;flex-direction:column;">' +   '<div style="background:linear-gradient(135deg,#8A1538 0%,#3D0918 100%);color:#D4BC85;padding:20px 22px;text-align:center;position:relative;flex-shrink:0;">' +     '<button onclick="closeWhatsNewModal()" type="button" aria-label="إغلاق" style="position:absolute;top:10px;left:12px;width:30px;height:30px;border-radius:50%;background:rgba(212,188,133,.2);border:none;color:#D4BC85;cursor:pointer;font-weight:900;font-size:1.1rem;line-height:1;padding:0;display:flex;align-items:center;justify-content:center;">×</button>' +     '<div style="display:inline-flex;align-items:center;gap:6px;background:rgba(212,188,133,.15);border:1px solid rgba(212,188,133,.4);padding:4px 14px;border-radius:18px;font-size:.7rem;font-weight:900;letter-spacing:.5px;margin-bottom:8px;">' +       '<svg width="11" height="11" viewBox="0 0 24 24" fill="currentColor"><path d="M19 13.5V19c0 1.1-.9 2-2 2H5c-1.1 0-2-.9-2-2V7c0-1.1.9-2 2-2h5.5l-2 2H5v12h12v-3.5l2-2zM17.5 3l-1.41 1.41L19.17 7.5H10v2h9.17l-3.08 3.09L17.5 14l5.5-5.5L17.5 3z"/></svg>' +       'سجل التحديثات' +     '</div>' +     '<div style="font-family:Cairo;font-weight:900;font-size:1.2rem;color:#fff;margin-bottom:3px;">ماذا الجديد في الملهم؟</div>' +     '<div style="font-size:.78rem;opacity:.85;">'+esc(headerSubtitle)+'</div>' +   '</div>' +   '<div style="padding:18px 20px;overflow-y:auto;flex:1;">' +     itemsHTML
    +   '</div>' +   '<div style="padding:14px 20px;border-top:1px solid #ecf0f1;background:#fff;text-align:center;flex-shrink:0;">' +     '<button onclick="closeWhatsNewModal()" type="button" style="padding:10px 28px;background:linear-gradient(135deg,#8A1538,#5E0E26);color:#fff;border:none;border-radius:10px;font-family:Cairo;font-weight:900;font-size:.9rem;cursor:pointer;box-shadow:0 4px 12px rgba(138,21,56,.3);">'+(opts.force?'إغلاق':'فهمت، شكرا!')+'</button>' +   '</div>' + '</div>';

  document.body.appendChild(modal);
  modal.addEventListener('click', function(e){ if(e.target === modal) closeWhatsNewModal(); });

  // تعليم التحديثات كمشاهدة (إن لم يكن في وضع المعاينة)
  if(!opts.force && all.length > 0){
    try{ localStorage.setItem('hh_wn_last_seen', all[0].id); }catch(e){}
  }
}

function closeWhatsNewModal(){
  const m = document.getElementById('hh-whatsnew-modal');
  if(m) m.remove();
  if(typeof refreshWhatsNewBadge === 'function') refreshWhatsNewBadge();
}

// عرض زر "ماذا الجديد" دائم في الواجهة (يفتح كل التحديثات بدون تتبع)
window.openWhatsNew = function(){ showWhatsNewModal({force:true}); };

