// تخصيص واجهة لوحة التحكم للشريك المقيّد: محرّر الأسئلة فقط
function _hhApplyPartnerRestrictedUI(){
  // نخفي كل مجموعات القائمة الجانبية، ونبقي فقط زر الأسئلة
  document.querySelectorAll('#screen-admin .mc-group').forEach(function(g){
    g.style.display = 'none';
  });
  // نُظهر مجموعة المحتوى ونُبقي زر الأسئلة فقط داخلها
  document.querySelectorAll('#screen-admin .mc-item[data-tab]').forEach(function(b){
    const keep = (b.dataset.tab === 'questions');
    const grp = b.closest('.mc-group');
    if(keep && grp){ grp.style.display = ''; }
    b.style.display = keep ? '' : 'none';
  });
  // الشريط الجوال: نخفي كل التبويبات عدا الأسئلة (يُعاد بناؤه، فنخفيه ببساطة)
  const mbar = document.getElementById('mc-mobile-bar');
  if(mbar) mbar.style.display = 'none';
  // عنوان ترحيبي مخصص
  const greet = document.getElementById('mc-hero-greet');
  if(greet) greet.textContent = 'لوحة تعديل أسئلتك';
  const sub = document.getElementById('mc-hero-sub');
  if(sub){
    const cats = _hhGetPartnerEditableCats(currentUser && currentUser.email);
    sub.textContent = 'يمكنك تعديل وإضافة الأسئلة في فئاتك ('+cats.length+' فئة)';
  }
  // نخفي شعار «لوحة التحكم» العام ونضع اسم الشريك
  const brandTitle = document.querySelector('#screen-admin .mc-brand-title');
  if(brandTitle) brandTitle.textContent = 'أسئلتي';
}

async function loadAdminPanel(){
  const _restrictedPartner = (typeof _hhIsRestrictedPartner === 'function') && _hhIsRestrictedPartner();
  if(!isAdminUser() && !_restrictedPartner){showScreen('screen-menu');return;}
  // الشريك المقيّد: نُظهر له محرّر الأسئلة فقط ونخفي بقية أدوات الإدارة
  if(_restrictedPartner && !isAdminUser()){
    try{ _hhApplyPartnerRestrictedUI(); }catch(e){ console.warn('partner UI:', e); }
    populateAQCatSelect();
    try{ adminTab('questions'); }catch(e){}
    return;
  }
  populateAQCatSelect();
  // تحميل المستخدمين
  // (zzzb) كل مصدر في محاولة مستقلة: فشل التقييمات لا يُسقط المستخدمين، والسبب يظهر داخل التبويب لا في الصمت
  function _hhAdminShowLoadError(where, e){
    var msg = (e && e.code==='permission-denied') ? 'رُفضت القراءة بقواعد Firestore (permission-denied) · انشر القواعد المحدثة وتأكد أن بريد الدخول هو بريد الأدمن'
            : (e && /index/i.test(e.message||'')) ? 'الاستعلام يحتاج فهرساً في Firestore · افتح الرابط في Console لإنشائه'
            : ('تعذر التحميل: '+((e&&e.message)||e));
    console.error('[لوحة التحكم] '+where+':', e);
    var el=document.getElementById(where==='users'?'admin-users-list':'admin-reviews-list');
    if(el) el.innerHTML='<div style="background:#F7ECEF;border:1.5px solid #7A1330;border-radius:12px;padding:14px;color:#7A1330;font-family:Cairo;font-weight:800;font-size:.9rem;line-height:1.8;">'+msg+'<br><button onclick="loadAdminPanel()" style="margin-top:8px;background:#fff;border:1.5px solid #B8924A;border-radius:9px;padding:6px 14px;color:#8A1538;font-family:Cairo;font-weight:900;cursor:pointer;">أعد المحاولة</button></div>';
    var badge=document.getElementById('users-filter-count'); if(badge && where==='users') badge.textContent='خطأ';
  }
  try{
    if(!OFFLINE_MODE&&db){
      let users=[];
      try{
        const usersSnap=await db.collection('users').get();
        users=usersSnap.docs.map(d=>({id:d.id,...d.data()}));
      }catch(eU){ _hhAdminShowLoadError('users', eU); throw eU; }
      const _asUsers = document.getElementById('as-users');
      if(_asUsers) _asUsers.textContent=users.length;

      // تحميل التقييمات (للربط مع المستخدمين) · فشلها لا يمنع عرض المستخدمين
      let reviews=[];
      try{
        const revSnap=await db.collection('reviews').orderBy('ts','desc').get();
        reviews=revSnap.docs.map(d=>({id:d.id,...d.data()}));
      }catch(eR){ _hhAdminShowLoadError('reviews', eR); }
      const _asRev = document.getElementById('as-reviews');
      if(_asRev) _asRev.textContent=reviews.length;
      const avg=reviews.length?(reviews.reduce((s,r)=>s+r.stars,0)/reviews.length).toFixed(1):'-';
      const _asAvg = document.getElementById('as-avg');
      if(_asAvg) _asAvg.textContent=avg;
      //  حفظ القيم لاستخدامها في Dashboard الجديد
      try{ window._mcStatsCache = { users: users.length, reviews: reviews.length, avg: avg }; }catch(e){}

      //  ربط كل مستخدم بهل قيم أم لا
      const reviewedEmails = new Set(reviews.map(r=>(r.email||'').toLowerCase()).filter(Boolean));
      const reviewedNames = new Set(reviews.map(r=>(r.name||'').trim()).filter(Boolean));

      // تخصيب بيانات المستخدمين
      window._allUsers = users.map(u => {
        const emailLower = (u.email||'').toLowerCase();
        const hasReviewed = (emailLower && reviewedEmails.has(emailLower)) || reviewedNames.has((u.name||'').trim());
        // التصنيف: معلم (في القائمة المسموح لها) - طالب (له نقاط) - زائر (لا شيء)
        let userType = 'visitor';
        if(window.ALLOWED_EDITORS && window.ALLOWED_EDITORS.includes(emailLower)){
          userType = 'teacher';
        } else if((u.points || 0) > 0 || u.gamesPlayed){
          userType = 'student';
        }
        // تواريخ
        const createdAt = u.createdAt || u.ts || u.created || null;
        const lastSeen = u.lastSeen || u.lastActive || createdAt;
        return { ...u, hasReviewed, userType, createdAt, lastSeen };
      });

      // الفلتر النشط افتراضيا = الكل
      window._userFilter = { type: 'all', reviewed: 'all', activity: 'all', search: '' };
      renderUsersList();

      // التقييمات (الكود الأصلي)
      const revEl=document.getElementById('admin-reviews-list');
      if(revEl && reviews.length) revEl.innerHTML=reviews.map(r=>{
        const dev = r.deviceInfo;
        let deviceBlock = '';
        if(dev && (dev.deviceType || dev.os || dev.browser)){
          const shortId = dev.sessionId ? dev.sessionId.substr(-8) : '·';
          deviceBlock = `
            <div style="margin-top:8px;padding:8px 10px;background:#f5faf7;border:1px solid #dbe8df;border-radius:8px;font-size:.7rem;color:#8A1538;line-height:1.7;">
              <div style="display:flex;align-items:center;gap:5px;margin-bottom:4px;font-weight:800;color:#5E0E26;">
                <svg width="11" height="11" viewBox="0 0 24 24" fill="#8A1538" style="flex-shrink:0;"><path d="M4 6h18V4H4c-1.1 0-2 .9-2 2v11H0v3h14v-3H4V6zm19 2h-6c-.55 0-1 .45-1 1v10c0 .55.45 1 1 1h6c.55 0 1-.45 1-1V9c0-.55-.45-1-1-1zm-1 9h-4v-7h4v7z"/></svg> معلومات الجهاز
              </div>
              <div style="display:flex;flex-wrap:wrap;gap:4px 8px;"> ${dev.deviceType ? `<span style="background:#fff;border:1px solid #dbe8df;padding:1px 7px;border-radius:10px;font-weight:700;">${esc(dev.deviceType)}</span>` : ''}
                ${dev.os ? `<span style="background:#fff;border:1px solid #dbe8df;padding:1px 7px;border-radius:10px;">${esc(dev.os)}</span>` : ''}
                ${dev.browser ? `<span style="background:#fff;border:1px solid #dbe8df;padding:1px 7px;border-radius:10px;">${esc(dev.browser)}</span>` : ''}
                ${dev.country ? `<span style="background:#fff;border:1px solid #dbe8df;padding:1px 7px;border-radius:10px;">${esc(dev.country)}</span>` : ''}
                ${dev.language ? `<span style="background:#fff;border:1px solid #dbe8df;padding:1px 7px;border-radius:10px;direction:ltr;">${esc(dev.language)}</span>` : ''}
                ${dev.screenRes ? `<span style="background:#fff;border:1px solid #dbe8df;padding:1px 7px;border-radius:10px;direction:ltr;">${esc(dev.screenRes)}</span>` : ''}
                ${dev.timezone ? `<span style="background:#fff;border:1px solid #dbe8df;padding:1px 7px;border-radius:10px;direction:ltr;font-size:.65rem;">${esc(dev.timezone)}</span>` : ''}
              </div>
              <div style="margin-top:4px;font-size:.63rem;color:#888;direction:ltr;text-align:left;font-family:monospace;"> device: ${esc(shortId)}
              </div>
            </div>`;
        } else {
          deviceBlock = `<div style="margin-top:6px;font-size:.65rem;color:#aaa;font-style:italic;">· لم يوافق المستخدم على جمع البيانات</div>`;
        }
        return `
        <div class="admin-review-card">
          <div class="ar-info">
            <div class="ar-name">${esc(r.name||'مجهول')} <span class="ar-stars">${''.repeat(r.stars)}</span></div> ${r.email ?
              `<div class="ar-email"><svg width="11" height="11" viewBox="0 0 24 24" fill="#888" style="vertical-align:-1px;margin-left:3px;"><path d="M20 4H4c-1.1 0-1.99.9-1.99 2L2 18c0 1.1.9 2 2 2h16c1.1 0 2-.9 2-2V6c0-1.1-.9-2-2-2zm0 4l-8 5-8-5V6l8 5 8-5v2z"/></svg>${esc(r.email)}</div>` :
              `<div class="ar-email-empty"><svg width="11" height="11" viewBox="0 0 24 24" fill="#aaa" style="vertical-align:-1px;margin-left:3px;"><path d="M12 12c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm0 2c-2.67 0-8 1.34-8 4v2h16v-2c0-2.66-5.33-4-8-4z"/></svg>زائر (بدون حساب)</div>`
            }
            <div class="ar-text">${esc(r.comment||'بدون تعليق')}</div>
            <div style="font-size:.68rem;color:#aaa;margin-top:3px;">${r.date||''}</div> ${deviceBlock}
          </div>
          <button class="admin-del-btn" onclick="adminDeleteReview('${escAttr(r.id)}')">حذف</button>
        </div>`;
      }).join('');
    }
  }catch(e){console.error(e);}
}

// ═══ تصيير قائمة المستخدمين مع الفلترة ═══
function renderUsersList(){
  const listEl = document.getElementById('admin-users-list');
  if(!listEl) return;
  const users = window._allUsers || [];
  const f = window._userFilter || { type:'all', reviewed:'all', activity:'all', sort:'newest', search:'' };

  // تطبيق الفلاتر
  let filtered = users.filter(u => {
    // فلتر النوع
    if(f.type !== 'all' && u.userType !== f.type) return false;
    // فلتر التقييم
    if(f.reviewed === 'yes' && !u.hasReviewed) return false;
    if(f.reviewed === 'no' && u.hasReviewed) return false;
    // فلتر النشاط · مسميات جديدة:
    //  متفاعل = آخر نشاط خلال آخر يومين (داخل اللعبة الآن أو نشط مباشر)
    //  خامل = آخر نشاط بين 3 و 10 أيام (سجل دخولا لكن قليل التفاعل)
    //  يحتاج دعم = لم يدخل أبدا، أو لم يدخل لأكثر من 10 أيام
    if(f.activity && f.activity !== 'all'){
      const t = u.lastSeen;
      let activityKey = 'needs-help';
      if(t){
        let d;
        if(t.toMillis) d = new Date(t.toMillis());
        else if(typeof t === 'string') d = new Date(t);
        else if(typeof t === 'number') d = new Date(t);
        if(d && !isNaN(d.getTime())){
          const diffDays = Math.floor((new Date() - d) / (1000*60*60*24));
          if(diffDays <= 2)        activityKey = 'engaged';
          else if(diffDays <= 10)  activityKey = 'idle';
          else                     activityKey = 'needs-help';
        }
      }
      if(activityKey !== f.activity) return false;
    }
    // البحث
    if(f.search){
      const q = f.search.toLowerCase();
      const inName = (u.name||'').toLowerCase().includes(q);
      const inEmail = (u.email||'').toLowerCase().includes(q);
      const inPhone = (u.phone||'').toLowerCase().includes(q);
      if(!inName && !inEmail && !inPhone) return false;
    }
    return true;
  });

  //  الترتيب الديناميكي حسب اختيار المستخدم
  const sortBy = f.sort || 'newest';

  // دالة مساعدة لاحتساب زمن (millisecond)
  const getTime = (t) => t ? (t.toMillis ? t.toMillis() : new Date(t).getTime()) : 0;

  filtered.sort((a, b) => {
    if(sortBy === 'newest'){
      // الأحدث انضماما أولا
      const ta = getTime(a.createdAt) || getTime(a.lastSeen);
      const tb = getTime(b.createdAt) || getTime(b.lastSeen);
      return tb - ta;
    }
    if(sortBy === 'oldest'){
      // الأقدم انضماما أولا
      const ta = getTime(a.createdAt) || getTime(a.lastSeen) || Infinity;
      const tb = getTime(b.createdAt) || getTime(b.lastSeen) || Infinity;
      return ta - tb;
    }
    if(sortBy === 'active'){
      // الأنشط للأخمل: الأحدث آخر دخول + النقاط + عدد الألعاب
      const ta = getTime(a.lastSeen);
      const tb = getTime(b.lastSeen);
      if(tb !== ta) return tb - ta;
      const pa = (a.points || 0) + (a.gamesPlayed || 0) * 10;
      const pb = (b.points || 0) + (b.gamesPlayed || 0) * 10;
      return pb - pa;
    }
    if(sortBy === 'rated'){
      // المقيمون أولا
      if(a.hasReviewed && !b.hasReviewed) return -1;
      if(!a.hasReviewed && b.hasReviewed) return 1;
      return getTime(b.lastSeen) - getTime(a.lastSeen);
    }
    if(sortBy === 'unrated'){
      // غير المقيمين أولا
      if(!a.hasReviewed && b.hasReviewed) return -1;
      if(a.hasReviewed && !b.hasReviewed) return 1;
      return getTime(b.lastSeen) - getTime(a.lastSeen);
    }
    // افتراضي
    return getTime(b.lastSeen) - getTime(a.lastSeen);
  });

  // عرض العدد
  const countEl = document.getElementById('users-filter-count');
  if(countEl) countEl.textContent = `${filtered.length} / ${users.length}`;

  if(filtered.length === 0){
    listEl.innerHTML = `<div style="text-align:center;padding:30px;color:#aaa;font-size:.85rem;">لا يوجد مستخدمون مطابقون للفلتر</div>`;
    return;
  }

  // تحويل تاريخ Firestore لنص مفصل (تاريخ + وقت)
  function fmtDate(t){
    if(!t) return '<span style="color:#aaa;">لم يدخل بعد</span>';
    let d;
    if(t.toMillis) d = new Date(t.toMillis());
    else if(typeof t === 'string') d = new Date(t);
    else if(typeof t === 'number') d = new Date(t);
    else return '<span style="color:#aaa;">·</span>';
    if(isNaN(d.getTime())) return '<span style="color:#aaa;">·</span>';

    // التاريخ الكامل (بصيغة عربية)
    const monthNames = ['يناير','فبراير','مارس','أبريل','مايو','يونيو','يوليو','أغسطس','سبتمبر','أكتوبر','نوفمبر','ديسمبر'];
    const day = d.getDate();
    const month = monthNames[d.getMonth()];
    const year = d.getFullYear();

    // الوقت (HH:MM ص/م)
    let hours = d.getHours();
    const mins = d.getMinutes().toString().padStart(2, '0');
    const ampm = hours >= 12 ? 'م' : 'ص';
    hours = hours % 12 || 12;
    const timeStr = `${hours}:${mins} ${ampm}`;

    // المدة النسبية
    const diffMs = new Date() - d;
    const diffMins = Math.floor(diffMs / (1000*60));
    const diffHours = Math.floor(diffMs / (1000*60*60));
    const diffDays = Math.floor(diffMs / (1000*60*60*24));

    let relative;
    if(diffMins < 1) relative = 'الآن';
    else if(diffMins < 60) relative = `قبل ${diffMins} دقيقة`;
    else if(diffHours < 24) relative = `قبل ${diffHours} ساعة`;
    else if(diffDays === 1) relative = 'أمس';
    else if(diffDays < 7) relative = `قبل ${diffDays} أيام`;
    else if(diffDays < 30) relative = `قبل ${Math.floor(diffDays/7)} أسبوع`;
    else if(diffDays < 365) relative = `قبل ${Math.floor(diffDays/30)} شهر`;
    else relative = `قبل ${Math.floor(diffDays/365)} سنة`;

    return `<span style="display:inline-flex;flex-direction:column;align-items:flex-start;gap:1px;line-height:1.3;"><span style="font-weight:900;">${day} ${month} ${year}</span><span style="font-size:.85em;font-weight:600;opacity:.8;">${timeStr} • ${relative}</span></span>`;
  }

  // معلومات تصنيف المستخدم
  const typeInfo = {
    teacher:  { label:'معلم',  color:'#8A1538', bg:'#f5ede4', icon:'' },
    student:  { label:'طالب',  color:'#3D6B53', bg:'#e8f2ec', icon:'<svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M5 13.18v4L12 21l7-3.82v-4L12 17l-7-3.82zM12 3L1 9l11 6 9-4.91V17h2V9L12 3z"/></svg>' },
    visitor:  { label:'زائر',  color:'#666',    bg:'#f0f0f0', icon:'' }
  };

  //  حساب حالة النشاط بناء على lastSeen · مسميات جديدة:
  //  متفاعل = آخر نشاط خلال يومين (داخل اللعبة الآن أو نشط مباشر)
  //  خامل = آخر نشاط بين 3 و 10 أيام (سجل دخولا لكن قليل التفاعل)
  //  يحتاج دعم = لم يدخل أبدا، أو لم يدخل لأكثر من 10 أيام
  function getActivityStatus(t){
    if(!t) return { label:'يحتاج دعم', color:'#c0392b', bg:'#fdecea', icon:'<svg viewBox="0 0 24 24" style="width:1em;height:1em;vertical-align:middle;"><circle cx="12" cy="12" r="9" fill="#8A1538"/></svg>', key:'needs-help' };
    let d;
    if(t.toMillis) d = new Date(t.toMillis());
    else if(typeof t === 'string') d = new Date(t);
    else if(typeof t === 'number') d = new Date(t);
    else return { label:'يحتاج دعم', color:'#c0392b', bg:'#fdecea', icon:'<svg viewBox="0 0 24 24" style="width:1em;height:1em;vertical-align:middle;"><circle cx="12" cy="12" r="9" fill="#8A1538"/></svg>', key:'needs-help' };
    if(isNaN(d.getTime())) return { label:'يحتاج دعم', color:'#c0392b', bg:'#fdecea', icon:'<svg viewBox="0 0 24 24" style="width:1em;height:1em;vertical-align:middle;"><circle cx="12" cy="12" r="9" fill="#8A1538"/></svg>', key:'needs-help' };
    const diffDays = Math.floor((new Date() - d) / (1000*60*60*24));
    const diffHours = Math.floor((new Date() - d) / (1000*60*60));
    // داخل اللعبة الآن (آخر ساعة) → متفاعل مباشر
    if(diffHours < 1) return { label:'داخل اللعبة الآن', color:'#3D6B53', bg:'#e8f2ec', icon:'<svg viewBox="0 0 24 24" style="width:1em;height:1em;vertical-align:middle;"><circle cx="12" cy="12" r="9" fill="#3D6B53"/></svg>', key:'engaged' };
    if(diffDays <= 2) return { label:'متفاعل', color:'#3D6B53', bg:'#e8f2ec', icon:'<svg viewBox="0 0 24 24" style="width:1em;height:1em;vertical-align:middle;"><circle cx="12" cy="12" r="9" fill="#3D6B53"/></svg>', key:'engaged' };
    if(diffDays <= 10) return { label:'خامل', color:'#B8924A', bg:'#fff8e8', icon:'<svg viewBox="0 0 24 24" style="width:1em;height:1em;vertical-align:middle;"><circle cx="12" cy="12" r="9" fill="#B8924A"/></svg>', key:'idle' };
    return { label:'يحتاج دعم', color:'#c0392b', bg:'#fdecea', icon:'<svg viewBox="0 0 24 24" style="width:1em;height:1em;vertical-align:middle;"><circle cx="12" cy="12" r="9" fill="#8A1538"/></svg>', key:'needs-help' };
  }

  listEl.innerHTML = filtered.map(u => {
    const t = typeInfo[u.userType] || typeInfo.visitor;
    const act = getActivityStatus(u.lastSeen);
    //  احتساب لقب المستخدم
    let badgeHTML = '';
    try{
      // نطعم الكائن بالدور المستنبط من نوع المستخدم لتعمل الخوارزمية بشكل صحيح
      const userForBadge = { ...u, role: u.role || (u.userType==='teacher' ? 'teacher' : u.userType==='student' ? 'student' : null) };
      const userBadge = (typeof getUserBadge === 'function') ? getUserBadge(userForBadge) : null;
      if(userBadge) badgeHTML = renderBadgeHTML(userBadge, { size:'sm' });
    }catch(e){}
    const reviewBtn = !u.hasReviewed
      ? `<button onclick="requestUserReview('${escAttr(u.id)}','${esc(u.name||'')}')" title="اطلب منه التقييم" style="padding:4px 10px;background:linear-gradient(135deg,#B8924A,#8A6D2E);color:#fff;border:none;border-radius:8px;font-family:Cairo;font-weight:900;font-size:.65rem;cursor:pointer;display:inline-flex;align-items:center;gap:4px;box-shadow:0 2px 6px rgba(184,146,74,.35);">
          <svg width="10" height="10" viewBox="0 0 24 24" fill="currentColor"><path d="M12 17.27L18.18 21l-1.64-7.03L22 9.24l-7.19-.61L12 2 9.19 8.63 2 9.24l5.46 4.73L5.82 21z"/></svg> اطلب منه التقييم
        </button>`
      : '';

    return `
      <div class="admin-user-card" style="position:relative;border-right:4px solid ${t.color};">
        <div class="au-info">
          <div class="au-name" style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;"> ${esc(u.name||'بدون اسم')}
            <span style="background:${t.bg};color:${t.color};padding:2px 8px;border-radius:10px;font-family:Cairo;font-weight:900;font-size:.65rem;">${t.icon} ${t.label}</span>
            <span style="background:${act.bg};color:${act.color};padding:2px 8px;border-radius:10px;font-family:Cairo;font-weight:900;font-size:.65rem;">${act.icon} ${act.label}</span> ${badgeHTML}
            ${u.hasReviewed
              ? `<span style="background:#fff8e8;color:#8A6D2E;padding:2px 8px;border-radius:10px;font-family:Cairo;font-weight:900;font-size:.65rem;border:1px solid #B8924A;">قيم</span>`
              : `<span style="background:#fafafa;color:#aaa;padding:2px 8px;border-radius:10px;font-family:Cairo;font-weight:700;font-size:.65rem;border:1px dashed #ccc;">لم يقيم</span>`
            }
          </div>
          <div class="au-email">${esc(u.email||'')} ${u.phone?'| '+esc(u.phone):''}</div>
          <div style="display:flex;gap:10px;margin-top:4px;flex-wrap:wrap;font-size:.7rem;color:#777;">
            <span title="آخر دخول"> آخر دخول: <strong style="color:${act.color};">${fmtDate(u.lastSeen)}</strong></span> ${u.createdAt ? `<span title="تاريخ التسجيل"><svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M19 13.5V19c0 1.1-.9 2-2 2H5c-1.1 0-2-.9-2-2V7c0-1.1.9-2 2-2h5.5l-2 2H5v12h12v-3.5l2-2zM17.5 3l-1.41 1.41L19.17 7.5H10v2h9.17l-3.08 3.09L17.5 14l5.5-5.5L17.5 3z"/></svg> سجل: <strong style="color:#8A1538;">${fmtDate(u.createdAt)}</strong></span>` : ''}
          </div>
          <div class="au-pts" style="margin-top:4px;"> ${u.points||0} نقطة ${u.gamesPlayed?'• '+u.gamesPlayed+' لعبة':''}${u.totalMinutes?' • ⏱ '+(typeof formatMinutesArabic==='function'?formatMinutesArabic(u.totalMinutes):(u.totalMinutes+' دقيقة'))+(u.sessionsCount?' ('+u.sessionsCount+' جلسة)':''):''}</div> ${reviewBtn ? `<div style="margin-top:8px;">${reviewBtn}</div>` : ''}
        </div>
        <button class="admin-del-btn" onclick="adminDeleteUser('${escAttr(u.id)}','${esc(u.name||'')}')">حذف</button>
      </div>`;
  }).join('');
}

// ═══ ضوابط الفلترة ═══
function setUserFilter(key, value){
  if(!window._userFilter) window._userFilter = { type:'all', reviewed:'all', activity:'all', sort:'newest', search:'' };
  window._userFilter[key] = value;
  // تحديث UI الأزرار
  document.querySelectorAll(`.uf-btn[data-${key}]`).forEach(b => b.classList.remove('uf-active'));
  const activeBtn = document.querySelector(`.uf-btn[data-${key}="${value}"]`);
  if(activeBtn) activeBtn.classList.add('uf-active');
  renderUsersList();
}

function searchUsers(value){
  if(!window._userFilter) window._userFilter = { type:'all', reviewed:'all', activity:'all', sort:'newest', search:'' };
  window._userFilter.search = value || '';
  renderUsersList();
}

// ═══ طلب التقييم من مستخدم ═══
async function requestUserReview(uid, userName){
  if(!confirm(`سيتم إظهار رسالة طلب تقييم للمستخدم "${userName}" عند فتحه المنصة المرة القادمة.\n\nهل تريد المتابعة؟`)) return;
  try{
    if(!OFFLINE_MODE && db){
      await db.collection('users').doc(uid).set({
        reviewRequest: {
          requested: true,
          requestedAt: firebase.firestore.FieldValue.serverTimestamp(),
          requestedBy: (currentUser && currentUser.uid) || 'admin' }
      }, { merge: true });
      toast(`✓ سيرسل طلب التقييم إلى ${userName}`, 'success');
    }
  }catch(e){
    console.error(e);
    toast('تعذر إرسال طلب التقييم', 'error');
  }
}

// ═══ طلب التقييم من جميع المستخدمين الذين لم يقيموا ═══
async function requestReviewFromAllUnrated(){
  const users = window._allUsers || [];
  const unrated = users.filter(u => !u.hasReviewed);
  if(unrated.length === 0){
    toast('جميع المستخدمين قد قيموا المنصة بالفعل!', 'success');
    return;
  }
  if(!confirm(`سيتم إرسال طلب تقييم إلى ${unrated.length} مستخدم لم يقيم المنصة بعد.\n\nستظهر لهم رسالة فاخرة عند فتحهم المنصة المرة القادمة.\n\nهل تريد المتابعة؟`)) return;

  toast(`جاري إرسال طلب التقييم إلى ${unrated.length} مستخدم...`, 'info');
  let successCount = 0, failCount = 0;
  try{
    if(!OFFLINE_MODE && db){
      // batch updates
      const batch = db.batch();
      unrated.forEach(u => {
        const ref = db.collection('users').doc(u.id);
        batch.set(ref, {
          reviewRequest: {
            requested: true,
            requestedAt: firebase.firestore.FieldValue.serverTimestamp(),
            requestedBy: (currentUser && currentUser.uid) || 'admin',
            bulk: true
          }
        }, { merge: true });
      });
      await batch.commit();
      successCount = unrated.length;
    }
    toast(`✓ تم إرسال طلب التقييم إلى ${successCount} مستخدم`, 'success');
  }catch(e){
    console.error(e);
    toast('حدث خطأ · قد لا يكون كل الطلبات قد أرسلت', 'error');
  }
}

