function closeReviewRequestAndOpen(){
  const modal = document.getElementById('review-request-modal');
  if(modal) modal.remove();
  // فتح شاشة التقييم
  showScreen('screen-rate');
}

async function adminDeleteUser(uid,name){
  if(!confirm('حذف مستخدم: '+name+'؟'))return;
  try{
    await db.collection('users').doc(uid).delete();
    toast('تم حذف المستخدم','info');
    loadAdminPanel();
  }catch(e){toast('خطأ في الحذف','error');}
}

async function adminDeleteReview(id){
  if(!confirm('حذف هذا التقييم؟'))return;
  try{
    await db.collection('reviews').doc(id).delete();
    toast('تم حذف التقييم','info');
    loadAdminPanel();
    loadHomeReviews();
  }catch(e){toast('خطأ في الحذف','error');}
}



