// ════ أسئلة مخصصة ════
let cqDiff='easy';

function setCQDiff(d){
  cqDiff=d;
  ['easy','med','hard'].forEach(k=>{
    const b=document.getElementById('cq-'+k);
    if(b)b.classList.toggle('active',k===d);
  });
}

let cqImgData=null; // base64 للصورة المختارة

function handleCQImg(e){
  const file=e.target.files[0];
  if(!file)return;
  if(typeof toast==='function') toast('جار معالجة الصورة...', 'info');
  hhCompressImage(file, 350, 700).then(dataUrl => {
    cqImgData = dataUrl;
    const preview=document.getElementById('cq-img-preview');
    const name=document.getElementById('cq-img-name');
    const clear=document.getElementById('cq-img-clear');
    if(preview){preview.src=cqImgData;preview.style.display='block';}
    if(name)name.textContent=file.name;
    if(clear)clear.style.display='inline-block';
    if(typeof toast==='function') toast('تم تحميل الصورة', 'success');
  }).catch(err => {
    if(typeof toast==='function') toast('فشل معالجة الصورة', 'error');
    console.error(err);
  });
}

function clearCQImg(){
  cqImgData=null;
  const inp=document.getElementById('cq-img-input');
  const preview=document.getElementById('cq-img-preview');
  const name=document.getElementById('cq-img-name');
  const clear=document.getElementById('cq-img-clear');
  if(inp)inp.value='';
  if(preview){preview.src='';preview.style.display='none';}
  if(name)name.textContent='لم تختر صورة';
  if(clear)clear.style.display='none';
}

function addCustomQ(){
  const cat=(document.getElementById('cq-cat').value||'').trim();
  const q=(document.getElementById('cq-question').value||'').trim();
  const a=(document.getElementById('cq-answer').value||'').trim();
  const err=document.getElementById('cq-err');
  err.textContent='';
  if(!cat){err.textContent='أدخل اسم الفئة';return;}
  if(!q){err.textContent='أدخل السؤال';return;}
  if(!a){err.textContent='أدخل الجواب';return;}
  // حفظ
  const key='custom_'+cat;
  const existing=JSON.parse(localStorage.getItem('hh_custom_q')||'{}');
  if(!existing[cat])existing[cat]=[];
  const newQ={diff:cqDiff,q,a};
  if(cqImgData)newQ.img=cqImgData;
  existing[cat].push(newQ);
  localStorage.setItem('hh_custom_q',JSON.stringify(existing));
  syncCustomQsToQDB();
  // مسح الحقول
  document.getElementById('cq-question').value='';
  document.getElementById('cq-answer').value='';
  clearCQImg();
  toast('تم إضافة السؤال','success');
  renderCustomQList();
}

function syncCustomQsToQDB(){
  const custom=JSON.parse(localStorage.getItem('hh_custom_q')||'{}');
  Object.entries(custom).forEach(([cat,qs])=>{
    QDB[cat]=qs;
    if(!CAT_INFO[cat]){
      CAT_INFO[cat]={emoji:'<svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M3 17.25V21h3.75L17.81 9.94l-3.75-3.75L3 17.25zM20.71 7.04c.39-.39.39-1.02 0-1.41l-2.34-2.34c-.39-.39-1.02-.39-1.41 0l-1.83 1.83 3.75 3.75 1.83-1.83z"/></svg>',label:cat,color:'#3D6B53',bg:'#EBF2EE'};
    }
  });
}

function renderCustomQList(){
  const el=document.getElementById('cq-list');
  if(!el)return;
  const custom=JSON.parse(localStorage.getItem('hh_custom_q')||'{}');
  const cats=Object.keys(custom);

  // مؤشر حجم التخزين
  const storageEl=document.getElementById('cq-storage-info');
  if(storageEl){
    const totalQ=Object.values(custom).reduce((s,a)=>s+a.length,0);
    const hasImg=Object.values(custom).flat().some(q=>q.img);
    const kb=Math.round(JSON.stringify(custom).length/1024);
    storageEl.textContent=totalQ+' سؤال | '+(kb<1024?kb+'KB':Math.round(kb/102.4)/10+'MB')+(hasImg?' (يحتوي صور)':'');
    storageEl.style.color=kb>2048?'#c0392b':kb>800?'#b5801f':'#888';
  }

  if(!cats.length){
    el.innerHTML='<div style="text-align:center;padding:20px;color:#aaa;font-size:.85rem;">لا توجد أسئلة مخصصة بعد</div>';
    return;
  }

  // بناء القائمة بدون template literals متداخلة
  el.innerHTML='';
  cats.forEach(cat=>{
    const qs=custom[cat]||[];
    const catDiv=document.createElement('div');
    catDiv.style.cssText='border:2px solid #3D6B53;border-radius:10px;padding:12px;margin-bottom:10px;background:#f0faf5;';

    // رأس الفئة
    const header=document.createElement('div');
    header.style.cssText='display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;';
    const title=document.createElement('div');
    title.style.cssText='font-weight:900;font-size:.9rem;color:#3D6B53;';
    title.innerHTML='<svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M3 17.25V21h3.75L17.81 9.94l-3.75-3.75L3 17.25zM20.71 7.04c.39-.39.39-1.02 0-1.41l-2.34-2.34c-.39-.39-1.02-.39-1.41 0l-1.83 1.83 3.75 3.75 1.83-1.83z"/></svg> '+cat+' ('+qs.length+' سؤال)';
    const delBtn=document.createElement('button');
    delBtn.textContent='حذف الفئة';
    delBtn.style.cssText='background:none;border:1px solid #c0392b;border-radius:6px;padding:3px 8px;color:#c0392b;cursor:pointer;font-size:.72rem;';
    delBtn.onclick=()=>deleteCQCat(cat);
    header.appendChild(title);
    header.appendChild(delBtn);
    catDiv.appendChild(header);

    // أول 3 أسئلة
    const preview=qs.slice(0,3);
    preview.forEach((item,i)=>{
      const row=document.createElement('div');
      row.style.cssText='display:flex;justify-content:space-between;align-items:flex-start;padding:6px 8px;background:#fff;border-radius:6px;margin-bottom:4px;border:1px solid #c3e6ce;gap:8px;';
      
      const qDiv=document.createElement('div');
      qDiv.style.cssText='flex:1;font-size:.8rem;color:#333;';
      qDiv.innerHTML=item.q+(item.img?' <svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M12 9c-1.66 0-3 1.34-3 3s1.34 3 3 3 3-1.34 3-3-1.34-3-3-3zm9-3h-3.17L16 4h-8L6.17 6H3a2 2 0 00-2 2v12a2 2 0 002 2h18a2 2 0 002-2V8a2 2 0 00-2-2zm-9 13c-2.76 0-5-2.24-5-5s2.24-5 5-5 5 2.24 5 5-2.24 5-5 5z"/></svg>':'');
      
      const aDiv=document.createElement('div');
      aDiv.style.cssText='font-size:.72rem;color:#3D6B53;font-weight:700;white-space:nowrap;max-width:90px;overflow:hidden;text-overflow:ellipsis;';
      aDiv.textContent=item.a;
      
      const dBtn=document.createElement('button');
      dBtn.textContent='✕';
      dBtn.style.cssText='background:none;border:none;color:#ccc;cursor:pointer;font-size:.8rem;padding:0 2px;';
      dBtn.onclick=(function(c,idx){return function(){deleteCQItem(c,idx);};})(cat,i);
      
      row.appendChild(qDiv);
      row.appendChild(aDiv);
      row.appendChild(dBtn);
      catDiv.appendChild(row);
    });

    // عداد الأسئلة الإضافية
    if(qs.length>3){
      const more=document.createElement('div');
      more.style.cssText='font-size:.72rem;color:#888;text-align:center;margin-top:4px;';
      more.textContent='+'+(qs.length-3)+' أسئلة أخرى';
      catDiv.appendChild(more);
    }

    el.appendChild(catDiv);
  });
}

function deleteCQCat(cat){
  const custom=JSON.parse(localStorage.getItem('hh_custom_q')||'{}');
  delete custom[cat];
  delete QDB[cat];
  delete CAT_INFO[cat];
  localStorage.setItem('hh_custom_q',JSON.stringify(custom));
  toast('تم حذف الفئة','info');
  renderCustomQList();
}

function deleteCQItem(cat,idx){
  const custom=JSON.parse(localStorage.getItem('hh_custom_q')||'{}');
  if(custom[cat]){
    custom[cat].splice(idx,1);
    if(!custom[cat].length){delete custom[cat];delete QDB[cat];delete CAT_INFO[cat];}
    else QDB[cat]=custom[cat];
    localStorage.setItem('hh_custom_q',JSON.stringify(custom));
    renderCustomQList();
    toast('تم حذف السؤال','info');
  }
}

function clearCustomQs(){
  if(!confirm('مسح كل الأسئلة المخصصة؟'))return;
  const custom=JSON.parse(localStorage.getItem('hh_custom_q')||'{}');
  Object.keys(custom).forEach(cat=>{delete QDB[cat];delete CAT_INFO[cat];});
  localStorage.removeItem('hh_custom_q');
  toast('تم مسح الأسئلة المخصصة','info');
  renderCustomQList();
}

// تحميل الأسئلة المخصصة عند بدء التطبيق
syncCustomQsToQDB();
