// ── اختصارات لوحة المفاتيح ──
document.addEventListener('keydown', function(e){
  const modal = document.getElementById('q-modal');
  if(!modal || !modal.classList.contains('open')) return;
  // حرية الكتابة الكاملة داخل الحقول (نموذج صوّب وغيره): لا التقاط للمسافة أو الإدخال
  const _t=e.target;
  if(_t && (_t.tagName==='INPUT'||_t.tagName==='TEXTAREA'||_t.tagName==='SELECT'||_t.isContentEditable)) return;
  if(e.key === 'Enter' || e.key === ' '){
    e.preventDefault();
    const revBtn = document.getElementById('reveal-btn');
    if(revBtn && !revBtn.disabled){ revBtn.click(); return; }
    // إذا الجواب ظهر، Enter = التالي
    const actions = document.getElementById('qm-actions');
    if(actions && actions.style.display !== 'none') closeModal();
  }
  if(e.key === 'Escape' || e.key === 'n' || e.key === 'N'){
    const actions = document.getElementById('qm-actions');
    if(actions && actions.style.display !== 'none') closeModal();
  }
  // لا أحد أجاب بالضغط على X أو 0
  if(e.key === '0' || e.key === 'x' || e.key === 'X'){
    const noBtn = document.querySelector('#judge-actions .j-btn-none');
    const judgeEl = document.getElementById('team-judge');
    if(noBtn && judgeEl && judgeEl.style.display !== 'none') noBtn.click();
  }
});
