//  إظهار مقولة اليوم (تختار حسب اليوم · تتغير يوميا تلقائيا)
function loadDailyQuote(){
  const card = document.getElementById('daily-quote-card');
  if(!card) return;
  // الفهرس بناء على اليوم في السنة (تتغير يوميا)
  const now = new Date();
  const dayOfYear = Math.floor((now - new Date(now.getFullYear(), 0, 0)) / (1000*60*60*24));
  const idx = dayOfYear % QUOTES_BANK.length;
  applyQuote(QUOTES_BANK[idx]);
  card.dataset.lastIdx = idx;
}

//  تغيير المقولة (زر "مقولة أخرى")
function refreshDailyQuote(){
  const card = document.getElementById('daily-quote-card');
  if(!card) return;
  const lastIdx = parseInt(card.dataset.lastIdx || '0');
  let newIdx;
  do {
    newIdx = Math.floor(Math.random() * QUOTES_BANK.length);
  } while(newIdx === lastIdx && QUOTES_BANK.length > 1);
  applyQuote(QUOTES_BANK[newIdx]);
  card.dataset.lastIdx = newIdx;
  // حركة بسيطة عند التغيير
  card.style.transform = 'scale(.98)';
  setTimeout(()=> card.style.transform = '', 200);
}

function applyQuote(quote){
  const labelEl = document.getElementById('dq-label');
  const textEl = document.getElementById('dq-text');
  const authorEl = document.getElementById('dq-author');
  if(labelEl){
    const labels = {
      'قطر': 'من رؤية القيادة',
      'المعلم': ' في المعلم',
      'التاريخ': '<svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M14 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V8l-6-6zm4 18H6V4h7v5h5v11z"/></svg> في التاريخ',
      'العلم': '<svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M21 5c-1.11-.35-2.33-.5-3.5-.5-1.95 0-4.05.4-5.5 1.5-1.45-1.1-3.55-1.5-5.5-1.5S2.45 4.9 1 6v14.65c0 .25.25.5.5.5.1 0 .15-.05.25-.05C3.1 20.45 5.05 20 6.5 20c1.95 0 4.05.4 5.5 1.5 1.35-.85 3.8-1.5 5.5-1.5 1.65 0 3.35.3 4.75 1.05.1.05.15.05.25.05.25 0 .5-.25.5-.5V6c-.6-.45-1.25-.75-2-1z"/></svg> في طلب العلم' };
    labelEl.innerHTML = labels[quote.category] || 'مقولة اليوم';
  }
  if(textEl) textEl.textContent = `«${quote.text}»`;
  if(authorEl) authorEl.textContent = quote.author;
  var roleEl = document.getElementById('dq-role');
  if(roleEl) roleEl.textContent = quote.role || '';
}

