// ═══ تهيئة الشاشة عند الدخول ═══
function initActivityGen(){
  loadActivityTeacherData();
  selectActivityTemplate('worksheet');
  refreshDailyInspiration();
}

// ═══ فتح مولد الشهادات مباشرة (من خانة المعلم) ═══
function openCertificateDirect(){
  if(!hhCertAllowed()) return;
  showScreen('screen-activity-gen');
  // تأخير صغير حتى تتحمل الشاشة
  setTimeout(()=>{
    loadActivityTeacherData();
    selectActivityTemplate('certificate');
    refreshDailyInspiration();
    // تمرير صفحة المولد لقسم اختيار القالب
    setTimeout(()=>{
      const step3 = document.getElementById('ag-step3');
      if(step3) step3.scrollIntoView({behavior:'smooth', block:'start'});
    }, 200);
  }, 100);
}

// ═══ حفظ بيانات المعلم ═══
function saveActivityTeacherData(){
  const teacherName = document.getElementById('ag-teacher-name').value.trim();
  if(!teacherName){ toast('اكتب اسمك أولا', 'warn'); return; }
  try{
    localStorage.setItem('hh_activity_teacher', JSON.stringify({
      teacherName,
      schoolName: document.getElementById('ag-school-name').value.trim(),
      subject: document.getElementById('ag-subject').value.trim(),
      grade: document.getElementById('ag-grade').value.trim()
    }));
    if(ACTIVITY_GEN.logoDataUrl){
      localStorage.setItem('hh_activity_logo', ACTIVITY_GEN.logoDataUrl);
    }
    toast('✓ حفظت بياناتك · لن تكتبها مرة أخرى', 'success');
  }catch(e){ toast('الذاكرة ممتلئة', 'error'); }
}

function loadActivityTeacherData(){
  try{
    const saved = localStorage.getItem('hh_activity_teacher');
    if(saved){
      const data = JSON.parse(saved);
      document.getElementById('ag-teacher-name').value = data.teacherName || '';
      document.getElementById('ag-school-name').value = data.schoolName || '';
      document.getElementById('ag-subject').value = data.subject || '';
      document.getElementById('ag-grade').value = data.grade || '';
    }
    const savedLogo = localStorage.getItem('hh_activity_logo');
    if(savedLogo){
      ACTIVITY_GEN.logoDataUrl = savedLogo;
      const preview = document.getElementById('ag-logo-preview');
      if(preview) preview.innerHTML = `<img src="${savedLogo}" alt="شعار" style="max-width:60px;max-height:60px;border-radius:8px;">`;
      const label = document.getElementById('ag-logo-label');
      if(label) label.textContent = '✓ شعار المدرسة محفوظ';
      const removeBtn = document.getElementById('ag-logo-remove');
      if(removeBtn) removeBtn.style.display = 'inline-block';
    }
  }catch(e){}
}

// ═══ معاينة الشعار ═══
function previewActivityLogo(event){
  const file = event.target.files[0];
  if(!file) return;
  if(typeof toast==='function') toast('جار معالجة الشعار...', 'info');
  hhCompressImage(file, 200, 400).then(dataUrl => {
    ACTIVITY_GEN.logoDataUrl = dataUrl;
    document.getElementById('ag-logo-preview').innerHTML = `<img src="${dataUrl}" alt="معاينة الشعار" style="max-width:60px;max-height:60px;border-radius:8px;">`;
    document.getElementById('ag-logo-label').textContent = '✓ تم اختيار الشعار';
    document.getElementById('ag-logo-remove').style.display = 'inline-block';
    if(typeof toast==='function') toast('تم تحميل الشعار', 'success');
  }).catch(err => {
    if(typeof toast==='function') toast('فشل معالجة الصورة', 'error');
    console.error(err);
  });
}

function removeActivityLogo(){
  ACTIVITY_GEN.logoDataUrl = null;
  localStorage.removeItem('hh_activity_logo');
  document.getElementById('ag-logo-preview').innerHTML = `<svg width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="#3D6B53" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="18" height="18" rx="2" ry="2"/><circle cx="8.5" cy="8.5" r="1.5"/><polyline points="21 15 16 10 5 21"/></svg>`;
  document.getElementById('ag-logo-label').textContent = 'ارفع شعار المدرسة (اختياري)';
  document.getElementById('ag-logo-remove').style.display = 'none';
  document.getElementById('ag-logo-input').value = '';
}

// ═══ اختيار القالب ═══
function selectActivityTemplate(template){
  ACTIVITY_GEN.currentTemplate = template;
  document.querySelectorAll('.ag-template-btn').forEach(btn => {
    const isSelected = btn.dataset.template === template;
    if(isSelected){
      btn.style.border = '2px solid #3D6B53';
      btn.style.background = 'linear-gradient(135deg,#e8f2ec,#fff)';
      const label = btn.querySelector('div:last-child');
      if(label){ label.style.color = '#2C5340'; label.style.fontWeight = '900'; }
    } else {
      btn.style.border = '1.5px solid #e0e8f0';
      btn.style.background = '#fafafa';
      const label = btn.querySelector('div:last-child');
      if(label){ label.style.color = '#555'; label.style.fontWeight = '800'; }
    }
  });
  renderActivityDetailsForm(template);
}

// ═══ حقول التفاصيل حسب القالب ═══
