//                       نهاية نظام الألقاب
// ╚═══════════════════════════════════════════════════════════════════╝


// ╔═══════════════════════════════════════════════════════════════════╗
// ║                                                                   ║
// ║   ⏱   نظام تتبع الوقت في المنصة                                ║
// ║      session start/end + visibility + beforeunload                ║
// ║                                                                   ║
// ╚═══════════════════════════════════════════════════════════════════╝

const HH_SESSION = {
  startTs: 0,            // timestamp بداية الـ session الحالي (نشط)
  accumulated: 0,        // الدقائق المتراكمة في الـ session (للحفظ النهائي)
  isActive: false,       // هل التبويب ظاهر حاليا
  flushTimer: null,      // مؤقت الحفظ الدوري كل دقيقتين
  MIN_FLUSH_SEC: 30      // لا نحفظ session أقل من 30 ثانية
};

/** تشغيل مؤقت الجلسة · يستدعى عند تسجيل الدخول أو تحميل الصفحة */
function hh_startSession(){
  if(HH_SESSION.isActive) return;
  HH_SESSION.startTs = Date.now();
  HH_SESSION.isActive = true;
  // حفظ ضمني كل دقيقتين لتأمين الوقت في حال الإغلاق المفاجئ
  if(HH_SESSION.flushTimer) clearInterval(HH_SESSION.flushTimer);
  HH_SESSION.flushTimer = setInterval(()=> hh_flushSession(false), 120000);
}

/** إيقاف المؤقت · يستدعى عند إخفاء التبويب أو تسجيل الخروج */
function hh_pauseSession(){
  if(!HH_SESSION.isActive) return;
  hh_flushSession(true);
  HH_SESSION.isActive = false;
  HH_SESSION.startTs = 0;
}

/**
 * كتابة الوقت المتراكم إلى Firestore.
 * @param {boolean} resetAfter إعادة تصفير المؤقت بعد الحفظ
 */
async function hh_flushSession(resetAfter){
  try{
    if(!HH_SESSION.isActive || !HH_SESSION.startTs) return;
    const elapsedMs = Date.now() - HH_SESSION.startTs;
    const elapsedSec = Math.floor(elapsedMs/1000);
    if(elapsedSec < HH_SESSION.MIN_FLUSH_SEC) return;
    const elapsedMin = Math.max(1, Math.round(elapsedSec/60));
    // حفظ في Firestore (في الخلفية بدون انتظار)
    if(currentUser && db && !OFFLINE_MODE){
      try{
        const doc = await db.collection('users').doc(currentUser.uid).get();
        const cur = doc.exists ? doc.data() : {};
        const prevLongest = cur.longestSession || 0;
        const updates = {
          totalMinutes:  firebase.firestore.FieldValue.increment(elapsedMin),
          lastSessionAt: firebase.firestore.FieldValue.serverTimestamp()
        };
        // عداد الجلسات يزاد مرة واحدة عند كل بداية session · نضيفه هنا فقط أول مرة
        if(!HH_SESSION._countedThisSession){
          updates.sessionsCount = firebase.firestore.FieldValue.increment(1);
          HH_SESSION._countedThisSession = true;
        }
        if(elapsedMin > prevLongest) updates.longestSession = elapsedMin;
        db.collection('users').doc(currentUser.uid).set(updates, { merge:true }).catch(()=>{});
      }catch(e){}
    }
    // تحديث الـ baseline حتى لا نحفظ نفس الوقت مرتين
    if(resetAfter){
      HH_SESSION.startTs = 0;
    } else {
      HH_SESSION.startTs = Date.now();
    }
  }catch(e){ console.warn('flushSession failed', e); }
}

/** صياغة الوقت بصيغة عربية ذكية */
function formatMinutesArabic(totalMin){
  const m = Math.max(0, Math.floor(totalMin||0));
  if(m < 1) return 'أقل من دقيقة';
  if(m < 60) return m + ' دقيقة';
  const days = Math.floor(m / 1440);
  const hours = Math.floor((m % 1440) / 60);
  const mins = m % 60;
  if(days >= 1){
    if(days >= 7) return days + ' يوما كاملا';
    let s = days + ' يوم';
    if(hours) s += ' و ' + hours + ' ساعة';
    return s;
  }
  if(hours >= 1){
    let s = hours + ' ساعة';
    if(mins) s += ' و ' + mins + ' دقيقة';
    return s;
  }
  return m + ' دقيقة';
}

// ربط أحداث المتصفح
(function _hh_bindSessionEvents(){
  if(typeof document === 'undefined') return;
  document.addEventListener('visibilitychange', function(){
    if(document.visibilityState === 'hidden')      hh_pauseSession();
    else if(document.visibilityState === 'visible') hh_startSession();
  });
  window.addEventListener('beforeunload', function(){
    try{ hh_pauseSession(); }catch(e){}
  });
  window.addEventListener('pagehide', function(){
    try{ hh_pauseSession(); }catch(e){}
  });
})();
window.hh_startSession = hh_startSession;
window.hh_pauseSession = hh_pauseSession;
window.formatMinutesArabic = formatMinutesArabic;
