/** تحديث ظهور الشريط السفلي والتبويبات النشطة في كلا الشريطين */
function hh_updateBottomNav(currentScreenId){
  const bottomNav = document.getElementById('hh-bottom-nav');

  // الشريط السفلي
  if(bottomNav){
    // يظهر على الجوال والكمبيوتر معاً (CSS يتكفّل بالشكل المناسب لكل حجم)
    const shouldShow = HH_NAV.visibleScreens.includes(currentScreenId);
    bottomNav.style.display = shouldShow ? 'flex' : 'none';
    document.body.classList.toggle('hh-has-bottom-nav', shouldShow);
    if(shouldShow){
      const activeBottom = HH_NAV.bottomTabsMap[currentScreenId] || '';
      bottomNav.querySelectorAll('.hh-nav-item').forEach(btn => {
        btn.classList.toggle('active', btn.dataset.target === activeBottom);
      });
    }
  }

  // الشريط العلوي القديم (main-nav) · نحدث التبويبة النشطة
  try{
    const activeTopSection = HH_NAV.topTabsMap[currentScreenId] || 'home';
    document.querySelectorAll('.main-nav-links .nav-link, .mobile-menu-link').forEach(btn => {
      const sec = btn.dataset.section || '';
      btn.classList.toggle('nav-link-active', sec === activeTopSection);
      btn.classList.toggle('mobile-menu-active', sec === activeTopSection);
    });
  }catch(e){}
}

/** التنقل من الشريطين */
function hhNavigate(targetId){
  // إذا كانت تبويبة المحبرة → أخف شارة "جديد" (المستخدم رآها)
  if(targetId === 'screen-toolbox'){
    try{ hh_dismissMihbaraBadge(); }catch(e){}
  }
  showScreen(targetId);
  
  // استدعاء فوري للدوال المطلوبة عند كل شاشة (تجنب "جاري التحميل")
  if(targetId === 'screen-mygames'){
    if(typeof renderMyGames === 'function'){
      // فوري · بدون setTimeout
      renderMyGames();
    }
    // تحميل ألعاب السحابة في الخلفية ثم إعادة الرسم
    if(typeof loadUserGamesFromCloud === 'function'){
      loadUserGamesFromCloud().then(updated => {
        if(updated && typeof renderMyGames === 'function') renderMyGames();
      }).catch(()=>{});
    }
  }
}

/** فحص وعرض شارة "جديد" على المحبرة (7 أيام من أول ظهور) */
function hh_checkMihbaraBadge(){
  const badge = document.getElementById('hh-mihbara-new');
  if(!badge) return;
  try{
    let firstSeen = localStorage.getItem(HH_NAV.newBadgeKey);
    if(!firstSeen){
      firstSeen = String(Date.now());
      localStorage.setItem(HH_NAV.newBadgeKey, firstSeen);
    }
    const ageMs = Date.now() - parseInt(firstSeen, 10);
    const ageDays = ageMs / (1000 * 60 * 60 * 24);
    const dismissed = localStorage.getItem(HH_NAV.newBadgeKey + '_dismissed') === '1';
    badge.style.display = (ageDays < HH_NAV.newBadgeDays && !dismissed) ? 'inline-block' : 'none';
  }catch(e){
    badge.style.display = 'none';
  }
}

/** إخفاء شارة "جديد" بعد أول زيارة للمحبرة */
function hh_dismissMihbaraBadge(){
  try{
    localStorage.setItem(HH_NAV.newBadgeKey + '_dismissed', '1');
    const badge = document.getElementById('hh-mihbara-new');
    if(badge) badge.style.display = 'none';
  }catch(e){}
}

// تهيئة تلقائية عند تحميل الصفحة
(function _hh_initBottomNav(){
  if(typeof document === 'undefined') return;
  const init = () => {
    try{
      hh_checkMihbaraBadge();
      const active = document.querySelector('.screen.active');
      if(active && active.id) hh_updateBottomNav(active.id);
    }catch(e){}
  };
  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();

window.hh_updateBottomNav = hh_updateBottomNav;
window.hhNavigate = hhNavigate;
window.hh_dismissMihbaraBadge = hh_dismissMihbaraBadge;
