function hh_searchPlatform(query){
  const wrap = document.getElementById('nav-search-wrap');
  const resultsEl = document.getElementById('nav-search-results');
  if(!wrap || !resultsEl) return;

  const q = (query || '').trim().toLowerCase();
  wrap.classList.toggle('has-text', q.length > 0);

  if(q.length < 1){
    resultsEl.classList.remove('open');
    resultsEl.innerHTML = '';
    return;
  }

  // فلترة النتائج
  const matches = HH_SEARCH_INDEX.filter(item => {
    const haystack = (item.title + ' ' + item.desc + ' ' + (item.kw||'')).toLowerCase();
    return haystack.includes(q);
  }).slice(0, 8);

  if(matches.length === 0){
    resultsEl.innerHTML = '<div class="nav-search-empty">لا توجد نتائج مطابقة</div>';
  } else {
    resultsEl.innerHTML = matches.map(m => `
      <button class="nav-search-result" onclick="hh_handleSearchClick('${m.screen||''}','${(m.action||'').replace(/'/g,"\\'")}')">
        <span class="nav-search-result-icon">${m.icon}</span>
        <div class="nav-search-result-info">
          <div class="nav-search-result-title">${m.title}</div>
          <div class="nav-search-result-desc">${m.desc}</div>
        </div>
      </button> `).join('');
  }
  resultsEl.classList.add('open');
}

function hh_handleSearchClick(screen, action){
  hh_clearSearch();
  if(screen){
    if(typeof showScreen === 'function') showScreen(screen);
  } else if(action){
    try{ eval(action); }catch(e){ console.error(e); }
  }
}

function hh_showSearchResults(){
  const inp = document.getElementById('nav-search-input');
  if(inp && inp.value.trim()) hh_searchPlatform(inp.value);
}

function hh_clearSearch(){
  const inp = document.getElementById('nav-search-input');
  const wrap = document.getElementById('nav-search-wrap');
  const resultsEl = document.getElementById('nav-search-results');
  if(inp) inp.value = '';
  if(wrap) wrap.classList.remove('has-text');
  if(resultsEl){
    resultsEl.classList.remove('open');
    resultsEl.innerHTML = '';
  }
}

// إغلاق القائمة عند النقر خارجها
document.addEventListener('click', function(e){
  const container = document.querySelector('.nav-search-container');
  if(container && !container.contains(e.target)){
    const resultsEl = document.getElementById('nav-search-results');
    if(resultsEl) resultsEl.classList.remove('open');
  }
});

window.hh_searchPlatform = hh_searchPlatform;
window.hh_handleSearchClick = hh_handleSearchClick;
window.hh_clearSearch = hh_clearSearch;
window.hh_showSearchResults = hh_showSearchResults;
